    copyPaletteColors(A.OBJ_PLTT_ID(pal) + 8, A.OBJ_PLTT_ID(pal) + 1, 2);
    A.playSE12WithPanning('SE_M_LEER', A.battleAnimAdjustPanning(C.SOUND_PAN_TARGET));
