      A.setGpuReg('BLDCNT', C.BLDCNT_TGT2_ALL | C.BLDCNT_EFFECT_BLEND | C.BLDCNT_TGT1_BG1);
      A.setGpuReg('BLDALPHA', A.BLDALPHA_BLEND(0, 16));
