// ---- Water Pulse ring: args x, y, duration, bubble interval
// data[0] frame, data[1]/data[2] target pos, data[3] duration, data[4] bubble interval, data[5] bubble timer
CB.AnimWaterPulseRing = function (sprite) {
  if (!A.tryLoadSpriteAssets('gWaterPulseRingBubbleSpriteTemplate')) {
    A.destroyAnimSprite(sprite);
    return;
  }
  const a = args();
  A.initSpritePosToAnimAttacker(sprite, true);
  sprite.data[1] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_X_2);
  sprite.data[2] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET);
  sprite.data[3] = a[2];
  sprite.data[4] = a[3];
  sprite.callback = AnimWaterPulseRing_Step;
};
function AnimWaterPulseRing_Step(sprite) {
  const xDiff = sprite.data[1] - sprite.x;
  const yDiff = sprite.data[2] - sprite.y;

  sprite.x2 = idiv(sprite.data[0] * xDiff, sprite.data[3]);
  sprite.y2 = idiv(sprite.data[0] * yDiff, sprite.data[3]);
  if (++sprite.data[5] === sprite.data[4]) {
    sprite.data[5] = 0;
    CreateWaterPulseRingBubbles(sprite, xDiff, yDiff);
  }
  if (sprite.data[3] === sprite.data[0])
    A.destroyAnimSprite(sprite);
  sprite.data[0]++;
}
function CreateWaterPulseRingBubbles(sprite, xDiff, yDiff) {
  const something = s16(idiv(sprite.data[0], 2));
  const combinedX = s16(sprite.x + sprite.x2);
  const combinedY = s16(sprite.y + sprite.y2);
  const randomSomethingY = s16(yDiff + (A.random() % 10) - 5);
  const randomSomethingX = s16(-xDiff + (A.random() % 10) - 5);

  for (let i = 0; i <= 0; i++) {
    const s = sprAt(u8(A.createSprite('gWaterPulseRingBubbleSpriteTemplate', combinedX, s16(combinedY + something), 130)));
    s.data[0] = 20;
    s.data[1] = randomSomethingY;
    s.subpriority = u8(A.getBattlerSpriteSubpriority(A.gBattleAnimAttacker) - 1);
    if (randomSomethingX < 0)
      s.data[2] = -randomSomethingX;
    else
      s.data[2] = randomSomethingX;
  }
  for (let i = 0; i <= 0; i++) {
    const s = sprAt(u8(A.createSprite('gWaterPulseRingBubbleSpriteTemplate', combinedX, s16(combinedY - something), 130)));
    s.data[0] = 20;
    s.data[1] = randomSomethingY;
    s.subpriority = u8(A.getBattlerSpriteSubpriority(A.gBattleAnimAttacker) - 1);
    if (randomSomethingX > 0)
      s.data[2] = -randomSomethingX;
    else
      s.data[2] = randomSomethingX;
  }
}

