// ---- Megahorn: CMD_ARGS(x1, y1, x2, y2, duration)
CB.AnimMegahornHorn = function (sprite) {
  const cmd = args();   // [0] x1 [1] y1 [2] x2 [3] y2 [4] duration

  if (A.isOnPlayerSide(A.gBattleAnimTarget)) {
    A.startSpriteAffineAnim(sprite, 1);
    cmd[1] = -cmd[1];
    cmd[2] = -cmd[2];
    cmd[3] = -cmd[3];
    cmd[0] = -cmd[0];
  }

  sprite.x = A.getBattlerSpriteCoord2(A.gBattleAnimTarget, C.BATTLER_COORD_X_2) + cmd[0];
  sprite.y = A.getBattlerSpriteCoord2(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET) + cmd[1];
  sprite.data[0] = cmd[4];

  sprite.data[2] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_X_2) + cmd[2];
  sprite.data[4] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET) + cmd[3];

  sprite.callback = A.startAnimLinearTranslation;
  A.storeSpriteCallbackInData6(sprite, A.destroyAnimSprite);
};

// ---- Leech Life: CMD_ARGS(x, y, duration)
CB.AnimLeechLifeNeedle = function (sprite) {
  const cmd = args();   // [0] x [1] y [2] duration

  if (A.isOnPlayerSide(A.gBattleAnimTarget)) {
    cmd[1] = -cmd[1];
    cmd[0] = -cmd[0];
  }

  sprite.x = A.getBattlerSpriteCoord2(A.gBattleAnimTarget, C.BATTLER_COORD_X_2) + cmd[0];
  sprite.y = A.getBattlerSpriteCoord2(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET) + cmd[1];
  sprite.data[0] = cmd[2];

  sprite.data[2] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_X_2);
  sprite.data[4] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET);

  sprite.callback = A.startAnimLinearTranslation;
  A.storeSpriteCallbackInData6(sprite, A.destroyAnimSprite);
};

// ---- String Shot / Spider Web thread: CMD_ARGS(x, y, unk2 (speed), amplitude, targetsBoth)
// data[0..4] linear translation, data[5] amplitude, data[6] wave angle
CB.AnimTranslateWebThread = function (sprite) {
  const cmd = args();   // [0] x [1] y [2] unk2 [3] amplitude [4] targetsBoth

  A.initSpritePosToAnimAttacker(sprite, true);
  sprite.data[0] = cmd[2];
  sprite.data[1] = sprite.x;
  sprite.data[3] = sprite.y;

  if (!cmd[4]) {
    sprite.data[2] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_X_2);
    sprite.data[4] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET);
  } else {
    const [x, y] = A.setAverageBattlerPositions(A.gBattleAnimTarget, true);
    sprite.data[2] = x;
    sprite.data[4] = y;
  }

  A.initAnimLinearTranslationWithSpeed(sprite);
  sprite.data[5] = cmd[3];
  sprite.callback = AnimTranslateWebThread_Step;
};
function AnimTranslateWebThread_Step(sprite) {
  if (A.animTranslateLinear(sprite)) {
    A.destroyAnimSprite(sprite);
    return;
  }

  sprite.x2 += Sin(sprite.data[6], sprite.data[5]);
  sprite.data[6] = (sprite.data[6] + 13) & 0xFF;
}

// ---- String Shot wrap: CMD_ARGS(x, y). data[0] flicker delay, data[1] timer
CB.AnimStringWrap = function (sprite) {
  const cmd = args();   // [0] x [1] y

  const [x, y] = A.setAverageBattlerPositions(A.gBattleAnimTarget, false);
  sprite.x = x;
  sprite.y = y;
  if (!A.isOnPlayerSide(A.gBattleAnimAttacker))
    sprite.x -= cmd[0];
  else
    sprite.x += cmd[0];

  sprite.y += cmd[1];
  if (A.isOnPlayerSide(A.gBattleAnimTarget))
    sprite.y += 8;

  sprite.callback = AnimStringWrap_Step;
};
function AnimStringWrap_Step(sprite) {
  if (++sprite.data[0] === 3) {
    sprite.data[0] = 0;
    sprite.invisible = !sprite.invisible;
  }

  if (++sprite.data[1] === 51) {
    A.destroyAnimSprite(sprite);
  }
}
// public in C: battle_anim_new.c (batch b09) sets it as a sprite callback
CB.AnimStringWrap_Step = AnimStringWrap_Step;
FN.AnimStringWrap_Step = AnimStringWrap_Step;

// ---- Tail Glow orb: CMD_ARGS(relativeTo)
CB.AnimTailGlowOrb = function (sprite) {
  const cmd = args();   // [0] relativeTo

  if (cmd[0] === C.ANIM_ATTACKER) {
    sprite.x = A.getBattlerSpriteCoord(A.gBattleAnimAttacker, C.BATTLER_COORD_X_2);
    sprite.y = A.getBattlerSpriteCoord(A.gBattleAnimAttacker, C.BATTLER_COORD_Y_PIC_OFFSET) + 18;
  } else {
    sprite.x = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_X_2);
    sprite.y = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET) + 18;
  }

  A.storeSpriteCallbackInData6(sprite, A.destroySpriteAndMatrix);
  sprite.callback = A.runStoredCallbackWhenAffineAnimEnds;
};

// ---- Spider Web: args x, y, use average target position. data[0] blend, data[1] fade toggle, data[2] hold timer
CB.AnimSpiderWeb = function (sprite) {
  const a = args();
  A.setGpuReg('BLDCNT', C.BLDCNT_TGT2_ALL | C.BLDCNT_EFFECT_BLEND);
  A.setGpuReg('BLDALPHA', A.BLDALPHA_BLEND(16, 0));

  if (a[2]) {
    const [x, y] = A.setAverageBattlerPositions(A.gBattleAnimTarget, false);
    sprite.x = x;
    sprite.y = y;
  }

  if (!A.isOnPlayerSide(A.gBattleAnimAttacker))
    sprite.x -= a[0];
  else
    sprite.x += a[0];

  sprite.y += a[1];
  sprite.data[0] = 16;
  sprite.callback = AnimSpiderWeb_Step;
};
function AnimSpiderWeb_Step(sprite) {
  if (sprite.data[2] < 20) {
    sprite.data[2]++;
  } else if (sprite.data[1]++ & 1) {
    sprite.data[0]--;
    A.setGpuReg('BLDALPHA', A.BLDALPHA_BLEND(sprite.data[0], 16 - sprite.data[0]));

    if (sprite.data[0] === 0) {
      sprite.invisible = true;
      sprite.callback = AnimSpiderWeb_End;
    }
  }
}
function AnimSpiderWeb_End(sprite) {
  A.setGpuReg('BLDCNT', 0);
  A.setGpuReg('BLDALPHA', 0);
  A.destroyAnimSprite(sprite);
}

// ---- Poison Sting / Twineedle: CMD_ARGS(initialX, intialY, targetX, targetY, duration)
CB.AnimTranslateStinger = function (sprite) {
  const cmd = args();   // [0] initialX [1] intialY [2] targetX [3] targetY [4] duration

  if (!A.isOnPlayerSide(A.gBattleAnimAttacker)) {
    cmd[2] = -cmd[2];
    cmd[1] = -cmd[1];
    cmd[3] = -cmd[3];
  }

  if (A.isBattlerAlly(A.gBattleAnimAttacker, A.gBattleAnimTarget)) {
    if (A.getBattlerPosition(A.gBattleAnimTarget) === C.B_POSITION_PLAYER_LEFT
     || A.getBattlerPosition(A.gBattleAnimTarget) === C.B_POSITION_OPPONENT_LEFT) {
      cmd[2] *= -1;
      cmd[0] *= -1;
    }
  }

  A.initSpritePosToAnimAttacker(sprite, true);

  const lVarX = s16(A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_X_2) + cmd[2]);
  const lVarY = s16(A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET) + cmd[3]);
  let rot = A.ArcTan2Neg(s16(lVarX - sprite.x), s16(lVarY - sprite.y));
  rot = u16(rot - 0x4000);
  A.trySetSpriteRotScale(sprite, false, 0x100, 0x100, rot);

  sprite.data[0] = cmd[4];
  sprite.data[2] = lVarX;
  sprite.data[4] = lVarY;

  sprite.callback = A.startAnimLinearTranslation;
  A.storeSpriteCallbackInData6(sprite, A.destroyAnimSprite);
};

// ---- Pin Missile / Icicle Spear: CMD_ARGS(initialX, intialY, targetX, targetY, duration, waveAmplitude)
// data[0..4] linear translation, data[5] arc amplitude, data[6]/data[7] arc step and phase
CB.AnimMissileArc = function (sprite) {
  const cmd = args();   // [0] initialX [1] intialY [2] targetX [3] targetY [4] duration [5] waveAmplitude

  A.initSpritePosToAnimAttacker(sprite, true);

  if (!A.isOnPlayerSide(A.gBattleAnimAttacker))
    cmd[2] = -cmd[2];

  sprite.data[0] = cmd[4];
  sprite.data[2] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_X_2) + cmd[2];
  sprite.data[4] = A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET) + cmd[3];
  sprite.data[5] = cmd[5];
  A.initAnimArcTranslation(sprite);

  sprite.callback = AnimMissileArc_Step;
  sprite.invisible = true;
};
function AnimMissileArc_Step(sprite) {
  sprite.invisible = false;

  if (A.translateAnimHorizontalArc(sprite)) {
    A.destroyAnimSprite(sprite);
  } else {
    // look one step ahead to aim the sprite (x2/y2 keep the look-ahead position, as in the C)
    const tempData = Int16Array.from(sprite.data);
    const x2 = s16(sprite.x + sprite.x2);
    const y2 = s16(sprite.y + sprite.y2);

    if (!A.translateAnimHorizontalArc(sprite)) {
      let rotation = A.ArcTan2Neg(s16(sprite.x + sprite.x2 - x2), s16(sprite.y + sprite.y2 - y2));
      rotation = u16(rotation - 0x4000);
      A.trySetSpriteRotScale(sprite, false, 0x100, 0x100, rotation);

      for (let i = 0; i < 8; i++)
        sprite.data[i] = tempData[i];
    }
  }
}
// public in C (battle_anim_new.c reuses it)
FN.AnimMissileArc_Step = AnimMissileArc_Step;

