// ---- frozen ice cube over the target (no args)
// data[1] blend / timer, data[2] palette delay, data[3] rotations, data[4] rounds, data[15] ice cube sprite
TK.AnimTask_FrozenIceCube = function (taskId) {
  if (!A.tryLoadSpriteAssets('sFrozenIceCubeSpriteTemplate')) {
    A.destroyAnimVisualTask(taskId);
    return;
  }

  const x = s16(A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_X_2) - 32);
  const y = s16(A.getBattlerSpriteCoord(A.gBattleAnimTarget, C.BATTLER_COORD_Y_PIC_OFFSET) - 36);

  A.setGpuReg('BLDCNT', C.BLDCNT_EFFECT_BLEND | C.BLDCNT_TGT2_ALL);
  A.setGpuReg('BLDALPHA', A.BLDALPHA_BLEND(0, 16));
  const spriteId = u8(A.createSprite('sFrozenIceCubeSpriteTemplate', x, y, 4));
  const cube = sprAt(spriteId);
  if (A.getSpriteTileStartByTag('ANIM_TAG_ICE_CUBE') === 0xFFFF)
    cube.invisible = true;
  A.setSubspriteTables(cube, 'sFrozenIceCubeSubspriteTable');
  task(taskId).data[15] = spriteId;
  task(taskId).func = AnimTask_FrozenIceCube_Step1;
};
function AnimTask_FrozenIceCube_Step1(taskId) {
  const t = task(taskId);
  t.data[1]++;
  if (t.data[1] === 10) {
    t.func = AnimTask_FrozenIceCube_Step2;
    t.data[1] = 0;
  } else {
    const v = u8(t.data[1]);
    A.setGpuReg('BLDALPHA', A.BLDALPHA_BLEND(v, 16 - v));
  }
}
function AnimTask_FrozenIceCube_Step2(taskId) {
  const t = task(taskId);
  const palIndex = u8(A.indexOfSpritePaletteTag('ANIM_TAG_ICE_CUBE'));

  if (t.data[1]++ > 13) {
    t.data[2]++;
    if (t.data[2] === 3) {
      // gPlttBufferFaded colours 13, 14, 15 of the ice cube palette rotate by one
      A.palShift(A.OBJ_PLTT_ID(palIndex) >> 4, 1);

      t.data[2] = 0;
      t.data[3]++;
      if (t.data[3] === 3) {
        t.data[3] = 0;
        t.data[1] = 0;
        t.data[4]++;
        if (t.data[4] === 2) {
          t.data[1] = 9;
          t.func = AnimTask_FrozenIceCube_Step3;
        }
      }
    }
  }
}
function AnimTask_FrozenIceCube_Step3(taskId) {
  const t = task(taskId);
  t.data[1]--;
  if (t.data[1] === -1) {
    t.func = AnimTask_FrozenIceCube_Step4;
    t.data[1] = 0;
  } else {
    const v = u8(t.data[1]);
    A.setGpuReg('BLDALPHA', A.BLDALPHA_BLEND(v, 16 - v));
  }
}
function AnimTask_FrozenIceCube_Step4(taskId) {
  const t = task(taskId);
  t.data[1]++;
  if (t.data[1] === 37) {
    const cube = sprAt(u8(t.data[15]));
    A.freeSpriteOamMatrix(cube);
    A.destroySprite(cube);
  } else if (t.data[1] === 39) {
    A.setGpuReg('BLDCNT', 0);
    A.setGpuReg('BLDALPHA', 0);
    A.destroyAnimVisualTask(taskId);
  }
}

