        sprite.x += sElectricChargingParticleCoordOffsets[t.data[9]][0];
        sprite.y += sElectricChargingParticleCoordOffsets[t.data[9]][1];
        sprite.data[0] = 40 - t.data[8] * 5;
        sprite.data[1] = sprite.x;
        sprite.data[2] = t.data[14];
        sprite.data[3] = sprite.y;
