// ---------------------------------------------------------------- AnimTask_VoltTackleBolt
// args: 0 attacker -> right edge, 4 left edge -> target, other values: rows of bolts across the screen
// task data[0] state, [1] x direction, [2] delay timer, [3] x, [4] end x, [5] y, [6] bolt anim number (computed, unused),
// [7] bolts alive
function voltTackleBoltTemplate() {
  switch (A.W.moveId) {
    case 'MOVE_FAIRY_LOCK': return 'gFairyLockChainsSpriteTemplate';
    case 'MOVE_COLLISION_COURSE': return 'gCollisionCourseSpriteTemplate';
    default: return 'gVoltTackleBoltSpriteTemplate';
  }
}
TK.AnimTask_VoltTackleBolt = function (taskId) {
  const t = task(taskId);
  switch (t.data[0]) {
    case 0: {
      const template = voltTackleBoltTemplate();
      if (!A.tryLoadSpriteAssets(template)) {
        A.destroyAnimVisualTask(taskId);
        return;
      }
      const a = args();
      t.data[1] = A.isOnPlayerSide(atk()) ? 1 : -1;
      switch (a[0]) {
        case 0:
          t.data[3] = coord(atk(), C.BATTLER_COORD_X_2);
          t.data[5] = coord(atk(), C.BATTLER_COORD_Y_PIC_OFFSET);
          t.data[4] = (t.data[1] * 128) + 120;
          break;
        case 4:
          t.data[3] = 120 - (t.data[1] * 128);
          t.data[5] = coord(tgt(), C.BATTLER_COORD_Y_PIC_OFFSET);
          t.data[4] = coord(tgt(), C.BATTLER_COORD_X_2) - (t.data[1] * 32);
          break;
        default:
          if ((a[0] & 1) !== 0) {
            t.data[3] = 256;
            t.data[4] = -16;
          } else {
            t.data[3] = -16;
            t.data[4] = 256;
          }
          if (t.data[1] === 1) {
            t.data[5] = 80 - a[0] * 10;
          } else {
            t.data[5] = a[0] * 10 + 40;
            const temp = u16(t.data[3]);
            t.data[3] = t.data[4];
            t.data[4] = temp;
          }
      }
      if (t.data[3] < t.data[4]) {
        t.data[1] = 1;
        t.data[6] = 0;
      } else {
        t.data[1] = -1;
        t.data[6] = 3;
      }
      t.data[0]++;
      break;
    }
    case 1:
      if (++t.data[2] > 0) {
        t.data[2] = 0;
        if (CreateVoltTackleBolt(t, taskId) || CreateVoltTackleBolt(t, taskId)) t.data[0]++;
      }
      break;
    case 2:
      if (t.data[7] === 0) A.destroyAnimVisualTask(taskId);
      break;
  }
};
function CreateVoltTackleBolt(t, taskId) {
  let spriteId;
  switch (A.W.moveId) {
    case 'MOVE_FAIRY_LOCK':
      spriteId = A.createSpriteUnchecked('gFairyLockChainsSpriteTemplate', t.data[3], t.data[5] + 10, 35);
      break;
    case 'MOVE_COLLISION_COURSE':
      spriteId = A.createSpriteUnchecked('gCollisionCourseSpriteTemplate', t.data[3], t.data[5], 35);
      break;
    default:
      spriteId = A.createSpriteUnchecked('gVoltTackleBoltSpriteTemplate', t.data[3], t.data[5], 35);
      break;
  }
  const doDestroyOamMatrix = moveIs('MOVE_FAIRY_LOCK', 'MOVE_COLLISION_COURSE');
  if (spriteId !== C.MAX_SPRITES) {
    const s = spr(spriteId);
    s.data[6] = taskId;
    s.data[7] = 7;
    s.data[1] = moveIs('MOVE_FAIRY_LOCK') ? 25 : 12;   // how long the chains / bolts stay on screen
    s.data[2] = doDestroyOamMatrix ? 1 : 0;
    t.data[7]++;
  }
  t.data[6] += t.data[1];
  if (t.data[6] < 0) t.data[6] = 3;
  if (t.data[6] > 3) t.data[6] = 0;
  t.data[3] += t.data[1] * 16;
  return (t.data[1] === 1 && t.data[3] >= t.data[4]) || (t.data[1] === -1 && t.data[3] <= t.data[4]);
}

// ---------------------------------------------------------------- AnimGrowingShockWaveOrb
