// ---------------------------------------------------------------- AnimTask_ShockWaveProgressingBolt
// args: target battler. task data[0] state, [1] delay timer, [2] bolt columns done, [3] bolt sprites alive,
// [4] tile offset, [5] tile / y direction, [6]/[7] x/y, [8] end y, [9] x step, [10] target x, [11] pause timer,
// [12]/[13] attacker/target pan, [14] pan, [15] pan step
TK.AnimTask_ShockWaveProgressingBolt = function (taskId) {
  const t = task(taskId);
  const target = A.getAnimBattlerId(args()[0]);
  switch (t.data[0]) {
    case 0:
      if (!A.tryLoadSpriteAssets('gVoltTackleBoltSpriteTemplate')) {
        A.destroyAnimVisualTask(taskId);
        return;
      }
      t.data[6] = coord(atk(), C.BATTLER_COORD_X_2);
      t.data[7] = coord(atk(), C.BATTLER_COORD_Y_PIC_OFFSET);
      t.data[8] = 4;
      t.data[10] = coord(target, C.BATTLER_COORD_X_2);
      t.data[9] = idiv(t.data[10] - t.data[6], 5);
      t.data[4] = 7;
      t.data[5] = -1;
      t.data[11] = 12;
      t.data[12] = A.battleAnimAdjustPanning(C.SOUND_PAN_ATTACKER);
      t.data[13] = A.battleAnimAdjustPanning(C.SOUND_PAN_TARGET);
      t.data[14] = t.data[12];
      t.data[15] = idiv(t.data[13] - t.data[12], 3);
      t.data[0]++;
      break;
    case 1:
      if (++t.data[1] > 0) {
        t.data[1] = 0;
        if (CreateShockWaveBoltSprite(t, taskId)) {
          if (t.data[2] === 5) t.data[0] = 3;
          else t.data[0]++;
        }
      }
      if (t.data[11]) t.data[11]--;
      break;
    case 2:
      if (t.data[11]) t.data[11]--;
      if (++t.data[1] > 4) {
        t.data[1] = 0;
        if (t.data[2] & 1) {
          t.data[7] = 4;
          t.data[8] = 68;
          t.data[4] = 0;
          t.data[5] = 1;
        } else {
          t.data[7] = 68;
          t.data[8] = 4;
          t.data[4] = 7;
          t.data[5] = -1;
        }
        if (t.data[11]) t.data[0] = 4;
        else t.data[0] = 1;
      }
      break;
    case 3:
      if (t.data[3] === 0) A.destroyAnimVisualTask(taskId);
      break;
    case 4:
      if (t.data[11]) t.data[11]--;
      else t.data[0] = 1;
      break;
  }
};
function CreateShockWaveBoltSprite(t, taskId) {
  const spriteId = A.createSpriteUnchecked('gShockWaveProgressingBoltSpriteTemplate', t.data[6], t.data[7], 35);
  if (spriteId !== C.MAX_SPRITES) {
    const s = spr(spriteId);
    s.oam.tileNum += t.data[4];
    t.data[4] += t.data[5];
    if (t.data[4] < 0) t.data[4] = 7;
    if (t.data[4] > 7) t.data[4] = 0;
    s.data[6] = taskId;
    s.data[7] = 3;
    t.data[3]++;
  }
  if (t.data[4] === 0 && t.data[5] > 0) {
    t.data[14] += t.data[15];
    A.playSE12WithPanning('SE_M_THUNDERBOLT', s8(t.data[14]));
  }
  if ((t.data[5] < 0 && t.data[7] <= t.data[8]) || (t.data[5] > 0 && t.data[7] >= t.data[8])) {
    t.data[2]++;
    t.data[6] += t.data[9];
    return true;
  }
  t.data[7] += t.data[5] * 8;
  return false;
}

// ---------------------------------------------------------------- AnimTask_ShockWaveLightning
// args: target battler. task data[0] state, [1] delay timer, [10] lightning sprites alive, [12] subpriority,
// [13] x, [14] y of the next segment, [15] bottom y
TK.AnimTask_ShockWaveLightning = function (taskId) {
  const t = task(taskId);
  const target = A.getAnimBattlerId(args()[0]);
  switch (t.data[0]) {
    case 0:
      if (!A.tryLoadSpriteAssets('gLightningSpriteTemplate')) {
        A.destroyAnimVisualTask(taskId);
        return;
      }
      t.data[15] = coord(target, C.BATTLER_COORD_Y) + 32;
      t.data[14] = t.data[15];
      while (t.data[14] > 16) t.data[14] -= 32;
      t.data[13] = coord(target, C.BATTLER_COORD_X_2);
      t.data[12] = A.getBattlerSpriteSubpriority(target) - 2;
      t.data[0]++;
      break;
    case 1:
      if (++t.data[1] > 1) {
        t.data[1] = 0;
        if (CreateShockWaveLightningSprite(t, taskId)) t.data[0]++;
      }
      break;
    case 2:
      if (t.data[10] === 0) A.destroyAnimVisualTask(taskId);
      break;
  }
};
function CreateShockWaveLightningSprite(t, taskId) {
  const spriteId = A.createSpriteUnchecked('gLightningSpriteTemplate', t.data[13], t.data[14], t.data[12]);
  if (spriteId !== C.MAX_SPRITES) {
    const s = spr(spriteId);
    s.callback = AnimShockWaveLightning;
    s.data[6] = taskId;
    s.data[7] = 10;
    t.data[10]++;
  }
  if (t.data[14] >= t.data[15]) return true;
  t.data[14] += 32;
  return false;
}
// data[6] task id, data[7] task data slot counting live segments
function AnimShockWaveLightning(sprite) {
  if (sprite.animEnded) {
    task(sprite.data[6]).data[sprite.data[7]]--;
    A.destroySprite(sprite);
  }
}

// ---------------------------------------------------------------- AnimTask_CreateIons
// args: (unused), spawn period, duration. task data[0] timer, [1] args[0], [2] period, [3] duration
TK.AnimTask_CreateIons = function (taskId) {
  if (!A.tryLoadSpriteAssets('gIonSpriteTemplate')) {
    A.destroyAnimVisualTask(taskId);
    return;
  }
  const t = task(taskId);
  if (t.data[0] === 0) {
    const a = args();
    t.data[1] = a[0];
    t.data[2] = a[1];
    t.data[3] = a[2];
  }
  t.data[0]++;
  if (A.imod(t.data[0], t.data[2]) === 1) {
    const x = (A.random() % C.DISPLAY_WIDTH) >>> 0;
    const y = (A.random() % (C.DISPLAY_HEIGHT / 2)) >>> 0;
    A.createSprite('gIonSpriteTemplate', x, y, 4);
  }
  if (t.data[0] === t.data[3]) A.destroyAnimVisualTask(taskId);
};

// ---------------------------------------------------------------- AnimTask_VoltSwitch (a sprite callback despite its name)
// args: x, y, target x offset (mirrored on the opponent side), target y offset, duration, arc height
// data[0..4] arc translation, data[5] arc amplitude, data[6..7] arc phase
CB.AnimTask_VoltSwitch = function (sprite) {
  const a = args();
  A.initSpritePosToAnimAttacker(sprite, false);
  if (!A.isOnPlayerSide(atk())) a[2] = -a[2];
  else sprite.y += 10;   // move slightly down
  sprite.data[0] = a[4];
  sprite.data[2] = coord(tgt(), C.BATTLER_COORD_X_2) + a[2];
  sprite.data[4] = coord(tgt(), C.BATTLER_COORD_Y_PIC_OFFSET) + a[3];
  sprite.data[5] = a[5];
  A.initAnimArcTranslation(sprite);
  sprite.callback = VoltSwitch_Step;
};
function VoltSwitch_Step(sprite) {
  sprite.invisible = false;
  if (A.translateAnimHorizontalArc(sprite)) {
    // merge coords into one
    sprite.x += sprite.x2;
    sprite.y += sprite.y2;
    sprite.x2 = 0;
    sprite.y2 = 0;
    // come straight back to the attacker
    sprite.data[0] = 0x14;
    sprite.data[2] = coord(atk(), C.BATTLER_COORD_X_2);
    sprite.data[4] = coord(atk(), C.BATTLER_COORD_Y_PIC_OFFSET);
    sprite.callback = A.startAnimLinearTranslation;
    A.storeSpriteCallbackInData6(sprite, A.destroyAnimSprite);
  }
}

// ================================================================ battle_anim_fire.c

