  sprite.x += a[0]; sprite.y += a[1]; sprite.data[0] = a[2];
  if (!A.isOnPlayerSide(A.gBattleAnimAttacker)) { sprite.data[1] = -a[3]; sprite.data[4] = 1; }
  else { sprite.data[1] = a[3]; sprite.data[4] = 0; A.startSpriteAnim(sprite, 1); }
