  const sid = makeBall(id, 32, 80, 29); const s = spr(sid);
  s.data[0] = 34; s.data[1] = coord(A.gBattleAnimTarget, C.BATTLER_COORD_X); s.data[2] = coord(A.gBattleAnimTarget, C.BATTLER_COORD_Y) - 16;
