      A.prepareBattlerSpriteForRotScale(spriteId, C.ST_OAM_OBJ_NORMAL);
      t.data[10] = 256;
      const dist = (mon.y + mon.y2) - (sprite.y + sprite.y2);
      t.data[2] = idiv(u32(dist * 256), 28);
      t.data[0]++;
