    default:    // MON_SHRINK_FREE
      if (t.data[1] > 10) { A.destroyTask(sprite.data[5]); A.startSpriteAnim(sprite, 2); sprite.data[5] = 0; sprite.callback = SpriteCB_Ball_Bounce; }
