P.splash = (g, w, h, f, rnd) => { for (let k = 0; k < 7; k++) { const a = -Math.PI * (0.1 + 0.8 * k / 6), r = Math.min(w, h) * 0.4; g.line(w / 2, h * 0.8, w / 2 + Math.cos(a) * r, h * 0.8 + Math.sin(a) * r, 2, 12); g.disc(w / 2 + Math.cos(a) * r, h * 0.8 + Math.sin(a) * r, 1.5, 14); } g.outline(); };
