const COLOR_WORDS = [[/RED/, 'red'], [/BLUE|AQUA/, 'blue'], [/GREEN/, 'green'], [/YELLOW/, 'yellow'], [/PINK/, 'pink'], [/MAGENTA/, 'magenta'],
  [/PURPLE|VIO/, 'purple'], [/BLACK/, 'black'], [/WHITE/, 'white'], [/GRAY|GREY/, 'gray'], [/GOLD/, 'gold'], [/ORANGE/, 'orange'], [/BROWN/, 'brown'],
  [/TEAL/, 'teal'], [/CYAN/, 'cyan'], [/TOXIC|POISON|GAS/, 'poison'], [/RAINBOW|COLORED/, 'rainbow']];
const CACHE = Object.create(null);
SG.classify = function (tagName) {
  const n = String(tagName || '').replace(/^ANIM_TAG_/, '');
  if (CACHE[n]) return CACHE[n];
  let painter = 'generic', pal = 'blue';
  for (const [re, p, c] of RULES) if (re.test(n)) { painter = p; pal = c; break; }
  for (const [re, c] of COLOR_WORDS) if (re.test(n)) { pal = c; break; }
  const res = { painter, pal, name: n };
  CACHE[n] = res; return res;
};
// palette of a tag; generic shapes (orbs, rings, sparkles...) take the colour of the move's type
const TYPE_PAL = { TYPE_FIRE: 'fire', TYPE_WATER: 'water', TYPE_GRASS: 'leaf', TYPE_ELECTRIC: 'electric', TYPE_ICE: 'ice', TYPE_FIGHTING: 'orange',
  TYPE_POISON: 'poison', TYPE_GROUND: 'mud', TYPE_FLYING: 'wind', TYPE_PSYCHIC: 'psychic', TYPE_BUG: 'green', TYPE_ROCK: 'rock', TYPE_GHOST: 'ghost',
  TYPE_DRAGON: 'dragon', TYPE_DARK: 'shadow', TYPE_STEEL: 'steel', TYPE_FAIRY: 'pink', TYPE_NORMAL: 'white' };
SG.palette = function (tagName, moveType) {
  const c = SG.classify(tagName); const p = c.pal;
  if (p === 'ball') return ballPal(ballKind(c.name)); if (p === 'ballspark') return sparkPal(ballKind(c.name));
  return PAL[p === 'type' ? (TYPE_PAL[moveType] || 'blue') : p] || PAL.blue;
};
SG.namedPalette = (k) => PAL[k] || PAL.gray;
// index map (w*h) of a frame. `key` varies the drawing (tileNum of the frame, so offsets inside a sheet differ)
const SHEETS = Object.create(null);
SG.frame = function (tagName, w, h, key) {
  const id = tagName + '|' + w + 'x' + h + '|' + key;
  const hit = SHEETS[id]; if (hit) return hit;
  const c = SG.classify(tagName); const g = new Img(w, h);
  const r = rng(strHash(id));
  try { (P[c.painter] || P.generic)(g, w, h, key | 0, r, c.painter === 'pokeball' ? c.name : strHash(c.name)); } catch (e) { P.generic(g, w, h, 0); }
  SHEETS[id] = g.d; return g.d;
};
SG.archetype = (tagName) => SG.classify(tagName).painter;

// ------------------------------------------------------------------ original placeholder creatures (64x64, palette-indexed)
// Four species of our own design with normal and shiny palettes; never Pokémon artwork.
const CREATURES = {
  sprout: { name: 'Sproutle (stand-in)', normal: ramp([30, 70, 50], [60, 170, 120], [180, 245, 190]), shiny: ramp([90, 60, 20], [220, 170, 60], [255, 240, 160]), draw: drawSprout },
  ember: { name: 'Cindertail (stand-in)', normal: ramp([110, 40, 10], [235, 120, 40], [255, 220, 140]), shiny: ramp([40, 50, 110], [90, 130, 230], [200, 220, 255]), draw: drawEmber },
  shell: { name: 'Tidecap (stand-in)', normal: ramp([20, 60, 110], [60, 140, 220], [190, 230, 255]), shiny: ramp([90, 30, 90], [200, 90, 190], [255, 200, 245]), draw: drawShell },
  rock: { name: 'Pebblor (stand-in)', normal: ramp([60, 50, 40], [150, 125, 95], [230, 210, 175]), shiny: ramp([30, 70, 40], [90, 170, 100], [200, 250, 200]), draw: drawRock }
};
function creatureImg(kind, back) {
  const g = new Img(64, 64); CREATURES[kind].draw(g, back); g.outline(); return g;
}
function drawSprout(g, back) {
  g.blob(32, 44, 17, 14, 5, 12); g.blob(32, 30, 13, 12, 6, 13);
  g.blob(21, 14, 4, 9, 8, 14); g.blob(43, 14, 4, 9, 8, 14);
  g.blob(20, 56, 5, 3, 3, 7); g.blob(44, 56, 5, 3, 3, 7);
  if (!back) { g.blob(26, 30, 2.5, 3, 1, 2, false); g.blob(38, 30, 2.5, 3, 1, 2, false); g.disc(25, 29, 0.8, 15); g.disc(37, 29, 0.8, 15); g.line(29, 37, 35, 37, 1, 3); g.blob(32, 47, 9, 7, 10, 15); }
  else { g.blob(46, 48, 6, 5, 6, 11); g.blob(32, 38, 8, 6, 8, 12); }
}
function drawEmber(g, back) {
  g.blob(32, 42, 14, 15, 5, 12); g.blob(32, 25, 12, 11, 6, 13);
  g.poly([[22, 18], [18, 4], [28, 15]], 9); g.poly([[42, 18], [46, 4], [36, 15]], 9);
  g.blob(48, 30, 4, 6, 10, 15); g.blob(51, 22, 3, 5, 12, 15); g.blob(52, 16, 2, 3, 14, 15);
  g.blob(23, 57, 5, 3, 3, 7); g.blob(41, 57, 5, 3, 3, 7);
  if (!back) { g.blob(27, 25, 2, 3, 1, 2, false); g.blob(37, 25, 2, 3, 1, 2, false); g.disc(26.5, 24, 0.7, 15); g.disc(36.5, 24, 0.7, 15); g.poly([[30, 31], [34, 31], [32, 33]], 2); g.blob(32, 46, 8, 8, 11, 15); }
}
function drawShell(g, back) {
  g.blob(32, 40, 19, 15, 4, 11); g.blob(32, 36, 16, 12, 6, 13);
  for (let k = 0; k < 4; k++) g.ring(32, 36, 4 + k * 3.5, 1, 10);
  g.blob(32, 20, 9, 8, 7, 14); g.blob(15, 52, 5, 3, 3, 7); g.blob(49, 52, 5, 3, 3, 7);
  if (!back) { g.blob(28, 20, 2, 2.5, 1, 2, false); g.blob(36, 20, 2, 2.5, 1, 2, false); g.disc(27.5, 19, 0.7, 15); g.disc(35.5, 19, 0.7, 15); g.line(30, 25, 34, 25, 1, 3); }
}
function drawRock(g, back) {
  g.poly([[14, 56], [10, 36], [20, 18], [36, 10], [50, 20], [56, 40], [50, 56]], (x, y) => 6 + Math.round(((40 - x) + (40 - y)) / 14));
  g.poly([[22, 22], [30, 14], [38, 18], [32, 26]], 12); g.poly([[44, 34], [52, 38], [48, 46]], 9);
  g.blob(20, 58, 5, 3, 3, 6); g.blob(44, 58, 5, 3, 3, 6);
  if (!back) { g.blob(27, 34, 2.5, 2.5, 1, 2, false); g.blob(39, 34, 2.5, 2.5, 1, 2, false); g.disc(26.5, 33, 0.8, 15); g.disc(38.5, 33, 0.8, 15); g.line(29, 42, 37, 41, 1, 3); }
}
const CRE_CACHE = Object.create(null);
SG.creatures = () => Object.keys(CREATURES).map((k) => ({ id: k, name: CREATURES[k].name }));
// {w:64,h:64,idx:Uint8Array, pal:Uint16Array(16), picW, picH, yOffset}
SG.creature = function (kind, back, shiny) {
  const k = CREATURES[kind] ? kind : 'sprout'; const id = k + (back ? 'B' : 'F');
  let img = CRE_CACHE[id]; if (!img) { img = creatureImg(k, back); CRE_CACHE[id] = img; }
  const m = img.m || (img.m = measure(img.d, 64, 64));   // pictures are immutable: measure once (hot path in the palette pipeline)
  return { w: 64, h: 64, idx: img.d, pal: shiny ? CREATURES[k].shiny : CREATURES[k].normal, picW: m.w, picH: m.h, yOffset: m.yOffset };
};
// visible box of a 64x64 picture, as the game's species data would give (MON_COORDS_SIZE, y offset)
function measure(idx, w, h) {
  let x0 = w, y0 = h, x1 = -1, y1 = -1;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (idx[y * w + x]) { if (x < x0) x0 = x; if (y < y0) y0 = y; if (x > x1) x1 = x; if (y > y1) y1 = y; }
  if (x1 < 0) return { w: 48, h: 48, yOffset: 8 };
  return { w: Math.min(64, Math.ceil((x1 - x0 + 1) / 8) * 8), h: Math.min(64, Math.ceil((y1 - y0 + 1) / 8) * 8), yOffset: Math.max(0, h - 1 - y1) };
}
SG.measure = measure;
// the substitute doll (drawn, not copied)
SG.doll = function (back) {
  const id = 'doll' + (back ? 'B' : 'F'); let img = CRE_CACHE[id];
  if (!img) { img = new Img(64, 64); img.blob(32, 44, 13, 13, 6, 13); img.blob(32, 26, 11, 10, 7, 14); img.poly([[24, 20], [22, 8], [29, 17]], 10); img.poly([[40, 20], [42, 8], [35, 17]], 10);
    if (!back) { img.disc(28, 26, 1.3, 1); img.disc(36, 26, 1.3, 1); img.line(30, 31, 34, 31, 1, 3); } img.outline(); CRE_CACHE[id] = img; }
  return { w: 64, h: 64, idx: img.d, pal: ramp([120, 90, 50], [225, 195, 140], [255, 240, 210]), picW: 32, picH: 48, yOffset: 6 };
};

