// ------------------------------------------------------------------ helpers
function pxSize(d, it, k) { return (Math.max(it.rec.w, it.rec.h)) * d.kpxAt(it.p) * (k || 1) * Math.max(it.sx || 1, it.sy || 1); }
function tintColor(base, it) {
  const c = base.slice(0, 3); const t = it.tint; if (!t) return c;
  if (t.solid) return t.solid.map((x) => x * 1.2);
  if (t.gray) { const l = (c[0] + c[1] + c[2]) / 3; c[0] = c[1] = c[2] = l; }
  if (t.c) for (let i = 0; i < 3; i++) c[i] = c[i] + (t.color[i] * 1.3 - c[i]) * t.c;
  if (t.inv) for (let i = 0; i < 3; i++) c[i] = Math.max(0, 1.1 - c[i]);
  return c;
}
function card(it, o) { const c = Object.assign({ cell: 'dot', size: [1, 1], rot: 0, color: [1, 1, 1], alpha: 1, add: 1 }, o); it.cards.push(c); return c; }
function rate(d, it, perSec) { const k = 'acc' + (it.s.k = (it.s.k || 0) + 1); return perSec / FPS; }
// fractional emission accumulator per instance & channel
function every(it, ch, perSec) { const s = it.s; s[ch] = (s[ch] || 0) + perSec * HD.settings.quality / FPS; const n = Math.floor(s[ch]); s[ch] -= n; return n; }
function velDir(it) { const l = V.len(it.v); return l > 0.01 ? V.scale([0, 0, 0], it.v, 1 / l) : null; }
function rampColor(name, t) { const c = HD.sampleRamp(name, t); return [c[0], c[1], c[2]]; }
function nearTarget(d, p, px) { const b = d.space.nearestBattler(p); return b.b >= 0 && (b.b & 1) !== (d.atkB() & 1) && b.d < d.space.battlerHeight(b.b) * (px || 0.8) ? b.b : -1; }
function typeRamp(d, cfg) { return cfg.ramp || d.style.ramp; }
// colour of an effect: explicit config, else a colour named by the sprite's template / palette (gTechnoBlastRedSpark...), else the move type
function typeColor(d, cfg, it) { return cfg.color || (it && it.hint) || d.style.color; }
// animation frame of the GBA sprite (tile offset / tiles per frame)
function frameOf(it) { const r = it.rec; const tpf = Math.max(1, (r.w >> 3) * (r.h >> 3)); return Math.floor((r.tileNum | 0) / tpf); }
// ribbon through the instance's recent positions (motion trail)
function trail(d, it, o) {
  const h = it.hist; if (!h || h.length < 2) return; const n = Math.min(h.length, o.len || 6); const pts = h.slice(h.length - n); pts.push(it.p.slice());
  it.cards.push({ layer: 'ribbons', fixed: true, pts, width: o.width, cell: o.cell || 'trail', color: o.color, intensity: o.intensity || 2, alpha: (o.alpha != null ? o.alpha : 1) * it.alpha, add: o.add != null ? o.add : 1, taper: o.taper != null ? o.taper : 0.5, scroll: it.age * (o.scroll || 2) });
}
HD.kitHelpers = { pxSize, tintColor, card, every, velDir, rampColor, nearTarget, typeRamp, typeColor, frameOf, trail };

// ------------------------------------------------------------------ impact styles (one per type; moves may override)
function stdBurst(cfg) {
  return function (d, p, st, away, b) {
    const r = cfg.ramp; const k = d.kpxAt(p) / 0.073; const rot = d.rng() * 6.28;
    // the hit spark: a spiky spark gradient-mapped through the type ramp, tinted toward the type's colour.
    // v3.1: shaped spark (impact3) in the type's colour (tint 0.25 + 0.75 x colour; v2's white comic starburst made every
    // hit look the same), small tinted core, soft glow kept under the body's size, no ring outline (an outlined ring read
    // as a UI marker): a refraction shock only. Each type adds its own debris (extra).
    const tc = rampColor(r, 0.32); const tint = [0.25 + tc[0] * 0.75, 0.25 + tc[1] * 0.75, 0.25 + tc[2] * 0.75];
    d.addFx('card', { p: p.slice(), cell: cfg.cell || 'impact3', size0: 0.8 * k * (0.6 + st * 0.5), size1: 1.75 * k * (0.6 + st * 0.6), color: tint, gmap: cfg.gmap || r, intensity: 1.25, life: 0.13 + st * 0.06, add: 1, rot });
    d.addFx('card', { p: p.slice(), cell: 'core', size0: 0.7 * k * st, size1: 0.25 * k * st, color: cfg.core ? [cfg.core[0] * 0.35 + tc[0] * 0.65, cfg.core[1] * 0.35 + tc[1] * 0.65, cfg.core[2] * 0.35 + tc[2] * 0.65] : tint, intensity: 1.05, life: 0.07, add: 1 });
    d.addFx('card', { p: p.slice(), cell: 'dot', size0: 1.0 * k * st, size1: 1.5 * k * st, color: tc, intensity: 0.35, life: 0.15, add: 1 });
    d.emit(PS.hitStreak, p, 10 + st * 12, { ramp: cfg.streakRamp || r, scale: 0.8 + st * 0.5 });
    if (d.physical) for (let i = 0; i < 2 + Math.round(st * 2); i++) { const a = rot + i * 2.1 + d.rng() * 0.6; d.addFx('card', { p: V.add([0, 0, 0], p, [Math.cos(a) * 0.5 * k, Math.sin(a) * 0.4 * k, 0.1]), cell: 'speed', size0: 1.4 * k * st, size1: 2.1 * k * st, aspect: 0.16, rot: a, color: [0.55 + tc[0] * 0.45, 0.55 + tc[1] * 0.45, 0.55 + tc[2] * 0.45], intensity: 1.0, life: 0.11, add: 1 }); }
    if (cfg.extra) cfg.extra(d, p, st, away, b);
    if (d.physical && cfg.dust !== false) { const f = d.space.feet[b] || p; d.emit(PS.dustPuff, [f[0], 0.15, f[2]], 2 + st * 4, { dir: [0, 0.25, 0], spread: 1, scale: 0.5 + st * 0.35, ramp: 'sand' }); }   // v3.2: fewer, smaller, paler puffs (big brown puffs beside the target read as a dark smudge)
    d.addFx('shockd', { p: p.slice(), r0: 0.25 * k, r1: (0.8 + st * 0.9) * k, life: 0.2, strength: 0.3 * st });
  };
}
// v3: rock / ground hits throw dirt: a dust cloud, flying stone chips and a ground-level dust ring instead of the spiky
// light burst, speed lines and screen ring of stdBurst (on stone and earth hits those read as a generic white starburst)
function earthBurst(cfg) {
  return function (d, p, st, away, b) {
    const k = d.kpxAt(p) / 0.073; const rot = d.rng() * 6.28; const f = d.space.feet[b] || p;
    d.addFx('card', { p: p.slice(), cell: 'smoke1', size0: 0.8 * k * (0.6 + st * 0.5), size1: 2.0 * k * (0.6 + st * 0.6), color: cfg.color || [0.86, 0.74, 0.58], gmap: 'dust', intensity: 1, life: 0.32 + st * 0.12, add: 0, rot });
    d.addFx('card', { p: p.slice(), cell: 'core', size0: 0.75 * k * st, size1: 0.3 * k * st, color: [1, 0.88, 0.66], intensity: 0.9, life: 0.07, add: 1 });
    d.emit(PS.chip, p, 8 + st * 10, { scale: 1.1 + st * 0.4 }); d.emit(PS.dustPuff, p, 3 + st * 4, { scale: 0.9 + st * 0.5 });
    d.emit(PS.dustPuff, [f[0], 0.15, f[2]], 4 + st * 6, { dir: [0, 0.25, 0], spread: 1, scale: 0.8 + st * 0.6 });
    d.addFx('ring', { p: [f[0], 0.06, f[2]], cell: 'ring', r0: 0.3 * k, r1: (1.1 + st * 1.1) * k, color: [0.72, 0.6, 0.44], intensity: 0.8, life: 0.32, add: 0.3, ground: true });
    if (cfg.extra) cfg.extra(d, p, st, away, b);
  };
}
