  TYPE_ELECTRIC: { light: [1, 0.95, 0.5], flash: [1, 1, 0.75], screen: [1, 0.97, 0.8], burst: stdBurst({ ramp: 'electric', core: [1, 1, 0.9], dust: false, extra: (d, p, st) => { d.emit(PS.spark, p, 12 + st * 14); d.addFx('bolt', { a: V.add([0, 0, 0], p, [d.rng.range(-0.6, 0.6), d.rng.range(-0.4, 0.4), 0]), b: V.add([0, 0, 0], p, [d.rng.range(-0.8, 0.8), d.rng.range(0.3, 0.9), d.rng.range(-0.3, 0.3)]), width: 0.05, life: 0.12, color: [1, 0.9, 0.45], branches: 0, intensity: 2, light: false }); } }) },
