  TYPE_GROUND: { light: [1, 0.85, 0.6], burst: earthBurst({ color: [0.84, 0.7, 0.5] }) },
  TYPE_ROCK: { light: [1, 0.85, 0.6], burst: earthBurst({ color: [0.8, 0.74, 0.64] }) },
  TYPE_FLYING: { light: [0.9, 0.95, 1], burst: stdBurst({ ramp: 'wind', core: [1, 1, 1], extra: (d, p, st) => { d.emit(PS.windStreak, p, 6 + st * 6); } }) },
  TYPE_PSYCHIC: { light: [1, 0.5, 0.85], flash: [1, 0.7, 0.9], burst: stdBurst({ ramp: 'psychic', cell: 'flare', dust: false, extra: (d, p, st) => { d.emit(PS.energy, p, 12 + st * 10); d.addFx('ring', { p: p.slice(), cell: 'ring', r0: 0.2, r1: 2.0, width: 0.2, color: [1, 0.45, 0.85], intensity: 1.2, life: 0.32, add: 1, distort: 1 }); } }) },
  TYPE_BUG: { light: [0.85, 1, 0.4], burst: stdBurst({ ramp: 'bug', extra: (d, p, st) => { d.emit(PS.glint, p, 6, { ramp: 'bug' }); } }) },
  TYPE_GHOST: { light: [0.65, 0.45, 1], flash: [0.7, 0.55, 1], burst: stdBurst({ ramp: 'ghost', cell: 'flare', dust: false, extra: (d, p, st) => { d.emit(PS.wisp, p, 6 + st * 6); d.emit(PS.darkSmoke, p, 4); } }) },
  TYPE_DRAGON: { light: [0.6, 0.5, 1], flash: [0.75, 0.65, 1], burst: stdBurst({ ramp: 'dragon', extra: (d, p, st) => { d.emit(PS.energy, p, 14 + st * 10, { ramp: 'dragon' }); d.emit(PS.fireBody, p, 4 + st * 6, { ramp: 'dragonfire' }); } }) },
  TYPE_DARK: { light: [0.6, 0.4, 0.75], flash: [0.6, 0.45, 0.7], burst: stdBurst({ ramp: 'dark', core: [0.9, 0.8, 1], extra: (d, p, st) => { d.emit(PS.darkSmoke, p, 6 + st * 6); d.emit(PS.energy, p, 8, { ramp: 'dark' }); } }) },
