  bolt(d, f, a, out) { const u = a / f.life; if (u < 0 || u > 1) return; const seed = f.seed + Math.floor(a * FPS / (f.reform || 2)) * 7919;
    const al = (u < 0.7 ? 1 : 1 - (u - 0.7) / 0.3) * (f.flicker ? (Math.floor(a * FPS) % 3 === 2 ? 0.45 : 1) : 1); HD.boltRibbons(f.a, f.b, seed, f.width || 0.1, f.color || [1, 0.95, 0.6], al * (f.intensity || 3), f.branches == null ? 2 : f.branches, out, f.jag);
    out.cards.push({ p: f.b, cell: 'flare', size: [f.width * 16, f.width * 16], color: f.color || [1, 0.95, 0.6], alpha: al * 0.8, add: 1, intensity: 1.6 });
    if (f.light !== false) out.lights.push({ p: f.b, color: f.color || [1, 0.95, 0.6], intensity: 8 * al, range: 12 }); },
  beam(d, f, a, out) { const u = a / f.life; if (u < 0 || u > 1) return; const w = f.width * (u < 0.15 ? u / 0.15 : u > 0.8 ? (1 - u) / 0.2 : 1) * (1 + 0.08 * Math.sin(a * 60));
    out.ribbons.push({ pts: [f.a, f.b], width: w, cell: 'beam', color: f.color, intensity: f.intensity || 3, add: 1, scroll: a * (f.scroll || 3), uvRepeat: f.repeat || 2 });
    out.ribbons.push({ pts: [f.a, f.b], width: w * 0.35, cell: 'beam', color: [1, 1, 1], intensity: (f.intensity || 3) * 1.2, add: 1, scroll: a * 5, uvRepeat: 1 }); },
  wave(d, f, a, out) { const u = a / f.life; if (u < 0 || u > 1) return; out.waves = out.waves || []; out.waves.push({ u, a, f }); },
