  const ph = (age * (f.ringRate || 2.2)) % 1; const ft = (d.space.feet && d.space.feet[f.b]) || [p[0], 0, p[2]]; const rr = (1.6 + ph * 3.4) * k * (f.size || 1);
  out.cards.push({ p: [ft[0], 0.05, ft[2]], cell: 'ring', size: [rr, rr], color: f.color, alpha: (1 - ph) * 0.6 * env, add: 1, intensity: 1.2, mode: 2 });
  if (f.distort !== false) out.distort.push({ p: [ft[0], 0.05, ft[2]], cell: 'shock', size: [rr * 1.1, rr * 1.1], strength: 0.35 * (1 - ph) * env, mode: 2 });
  out.lights.push({ p: [p[0], p[1] + 0.5, p[2] + 0.8], color: f.color, intensity: 3.5 * env, range: 8 });
  if (a && f.lift) a.lift = f.lift * HD.smooth(Math.min(1, u * 4)) * (u > 0.8 ? (1 - u) / 0.2 : 1);
  if (a) { const g = (f.glow != null ? f.glow : 0.7) * env * pul; if (g > a.glow[3]) a.glow = [f.color[0], f.color[1], f.color[2], g]; }
