const ANIM = { ATTACKER: 0, TARGET: 1, ATK_PARTNER: 2, DEF_PARTNER: 3 };
// battler id for an ANIM_* code in a task argument
function battlerOf(d, code) { const a = d.atkB(), t = d.tgtB(); return code === ANIM.TARGET ? t : code === ANIM.ATK_PARTNER ? a ^ 2 : code === ANIM.DEF_PARTNER ? t ^ 2 : a; }
// world point for a GBA point offset from a battler's picture centre, at that battler's depth
function nearBattler(d, b, dx, dy) { const g = d.space.gba[b]; return d.space.lift(g[0] + dx, g[1] + dy, d.space.depth[b]); }
HD.taskHelpers = { battlerOf, nearBattler };

// weather across the arena for `dur` seconds (rain, hail, snow, sand, sun)
