  AnimTask_ElectricBolt(d, a) {
    const b = d.tgtB(); const g = d.space.gba[b]; const x = g[0] + (a[0] | 0), y = g[1] + (a[1] | 0); const wide = !!(a[2] | 0); const dep = d.space.depth[b];
    const bot = d.space.lift(x, y + 80, dep); bot[1] = Math.max(0.05, bot[1]);
    const top = d.space.lift(x - 8, y - 70, dep); top[1] += 6;
    const col = d.cfg.boltColor || [1, 0.86, 0.3];
    d.addFx('bolt', { a: top, b: bot, width: wide ? 0.17 : 0.12, life: 11 / FPS + 0.05, color: col, intensity: wide ? 4 : 3.2, branches: wide ? 3 : 2, jag: 0.14, flicker: true });
    d.addFx('ring', { p: [bot[0], 0.06, bot[2]], r0: 0.15, r1: 1.6, width: 0.1, color: col, intensity: 1.6, life: 0.3, add: 1, ground: true });
    d.emit(HD.PS.spark, [bot[0], 0.3, bot[2]], 16, { scale: 1.1 });
    d.addFx('decal', { p: [bot[0], 0.02, bot[2]], cell: 'scorch', size: 1.4, life: 1.8, alpha: 0.5, rot: d.rng() * 6 });
    d.flash([1, 0.97, 0.8], 0.07); d.shake(0.1);
  },
  // steel moves: a bright specular sweep across the user (the GBA draws it as a BG masked by the user's sprite)
  AnimTask_MetallicShine(d, a) { d.addFx('shine', { b: d.atkB(), life: 0.85, color: [1, 1, 1] }); },
  // Surf / Muddy Water / Sludge Wave: a tidal wave rises behind the user and sweeps over the foes (the GBA scrolls a BG wave)
  AnimTask_CreateSurfWave(d, a) {
    const kind = (a[0] | 0); const ramp = kind === 1 ? 'mudwave' : kind === 2 ? 'sludgewave' : 'wave';
    d.addFx('surfwave', { life: 2.25, ramp, side: d.atkB() & 1, hit: {} });
  },
  AnimTask_CreateRaindrops(d) { HD.weather(d, 'rain', 2.4); },
  AnimTask_Hail(d) { HD.weather(d, 'hail', 2.2); },
  AnimTask_LoadSandstormBackground(d) { HD.weather(d, d.cfg.weather || 'sand', 2.6); },
