  for (let k = 0; k < 15; k++) {
    const z = -11 + k * 1.65; const curve = (z - 2) * 0.12 * w.dir; const lag = Math.sin(k * 2.3 + age * 2.2) * 0.35;
    const hk = H * (0.82 + 0.18 * Math.sin(k * 0.9 + age * 2.6)); const p = [w.x + curve - w.dir * lag, hk * 0.46, z]; const back = z < -3;
    out.cards.push({ p, cell: 'wavecrest', size: [6.2, hk], rot: 0, flip: w.dir < 0 ? 1 : 0, color: [1, 1, 1], gmap: f.ramp, alpha: 0.96, add: 0.04, intensity: 1.0, back });
  }
