HD.FX_STEP.surfwave = function (d, f, age) {
  const w = waveFront(d, f, age); if (w.rise < 0.1) return; const H = 6.2 * w.rise; const r = d.rng; const ramp = f.ramp === 'wave' ? 'spray' : f.ramp === 'mudwave' ? 'mud' : 'poison';
  for (let i = 0; i < 5; i++) { const z = r.range(-10, 12); d.emit(HD.PS.droplet, [w.x + (z - 2) * 0.12 * w.dir + r.range(-0.4, 0.4), H * r.range(0.75, 1), z], 2, { ramp, vel: [w.dir * 4, 2.5, 0], scale: 1.3 }); }
  if (d.frame % 3 === 0) { const z = r.range(-9, 11); d.emit(SPRAY, [w.x + (z - 2) * 0.12 * w.dir + w.dir * 0.6, H * 0.9, z], 1, { ramp, scale: 1.4 }); }
  for (let b = 0; b < 4; b++) {
    if (!d.space.present[b] || b === d.atkB() || f.hit[b]) continue; const ft = d.space.feet[b];
    if ((w.x + (ft[2] - 2) * 0.12 * w.dir - ft[0]) * w.dir > 0) {
      f.hit[b] = true; const foe = (b & 1) !== (d.atkB() & 1) || /FOES_AND_ALLY/.test(d.move.target);
      if (foe) { d.impact({ b, strength: d.strength, minGap: 1, style: HD.IMPACT_STYLES.TYPE_WATER }); d.emit(HD.PS.droplet, d.bpos(b), 30, { ramp, scale: 1.7, speedMul: 1.6 }); d.emit(SPRAY, d.bpos(b), 5, { ramp, scale: 1.8 }); d.shake(0.2); }
    }
  }
};
// FX: heat shimmer (distortion only), drifting
HD.FX.haze = function (d, f, age, out) { const u = age / f.life; if (u < 0 || u > 1) return; const v = f.vel || [0, 0.5, 0]; out.distort.push({ p: [f.p[0] + v[0] * age, f.p[1] + v[1] * age, f.p[2] + v[2] * age], cell: 'smoke1', size: [f.size, f.size * 0.7], strength: 0.3 * Math.sin(Math.PI * u), mode: 0 }); };
// FX: specular sweep on a battler (drives the HD sprite shader's shine band)
HD.FX.shine = function (d, f, age, out) { const u = age / f.life; const a = d.act[f.b]; if (!a) return; if (u < 0 || u > 1) { a.shine = null; return; } a.shine = [-0.7 + u * 2.4, 0.16, 0.9 * Math.sin(Math.PI * u)]; };

// weather particles, emitted per runtime frame while the weather lasts
HD.weatherStep = function (d) {
  const env = d.env; if (!env.weather) return; const u = (d.t - env.weatherT0) / env.weatherDur;
  if (u > 1) { env.weather = null; return; }
  const amt = Math.min(1, u * 5, (1 - u) * 4) * (env.weatherAmt || 1); env.weatherLevel = amt; const r = d.rng;
  const box = (n, y0, y1) => { const pts = []; for (let i = 0; i < n; i++) pts.push([r.range(-16, 18), r.range(y0, y1), r.range(-16, 12)]); return pts; };
  if (env.weather === 'rain') for (const p of box(Math.round(26 * amt), 9, 14)) d.emit(RAIN, p, 1, { vel: [2.5, -24, 0] });
  else if (env.weather === 'hail') { for (const p of box(Math.round(8 * amt), 9, 14)) d.emit(HAIL, p, 1, { vel: [3, -13, 0] }); }
  else if (env.weather === 'snow') { for (const p of box(Math.round(10 * amt), 7, 12)) d.emit(HD.PS.snow, p, 1, { vel: [0.6, -1.4, 0] }); }
  else if (env.weather === 'sand') { for (const p of box(Math.round(14 * amt), 0.2, 6)) d.emit(SAND, p, 1, { vel: [12, 0.5, 0] }); }
  else if (env.weather === 'heat') { if (d.frame % 3 === 0) for (const p of box(Math.round(4 * amt), 0.3, 3)) d.addFx('haze', { p, life: 1.2, size: 4 + r() * 3, vel: [3, 0.8, 0] }); if (d.frame % 2 === 0) for (const p of box(Math.round(3 * amt), 0.2, 3)) d.emit(HD.PS.ember, p, 2, { vel: [5, 1, 0] }); for (const p of box(Math.round(2 * amt), 0.2, 2.5)) d.emit(HEAT, p, 1, { vel: [4, 1, 0] }); }
  else if (env.weather === 'fog') { if (d.frame % 2 === 0) for (const p of box(Math.round(3 * amt), 0.3, 3)) d.emit(FOG, p, 1, { vel: [1.2, 0, 0] }); }
};
const RAIN = { sys: 'add', cell: 'streak', life: [0.45, 0.6], size: [0.09, 0.07], speed: [0, 0], ramp: 'spray', intensity: 0.9, stretch: 0.045, add: 0.6 };
const HAIL = { sys: 'alpha', add: 0.3, cell: 'shard', life: [0.8, 1.0], size: [0.22, 0.2], speed: [0, 0], ramp: 'ice', intensity: 1.2, spin: 6 };
const SAND = { sys: 'alpha', add: 0, cell: 'dust', life: [0.8, 1.4], size: [0.5, 1.2], speed: [0, 1], ramp: 'sand', spin: 0.5, turb: 0.8 };
const HEAT = { sys: 'alpha', add: 0.6, cell: 'smoke1', life: [0.8, 1.3], size: [1.2, 2.6], speed: [0, 0.4], ramp: 'ember', intensity: 0.35, spin: 0.2, turb: 0.4 };
const FOG = { sys: 'alpha', add: 0, cell: 'smoke1', life: [2.0, 3.0], size: [3, 5], speed: [0, 0.2], ramp: 'frost', spin: 0.1, turb: 0.2 };
