K.syrup = {
  update(d, it, cfg) {
    const s = pxSize(d, it, cfg.scale || 1.15); const a = it.alpha; const col = tintColor(cfg.color || [0.78, 0.07, 0.1], it); const wob = 1 + 0.03 * Math.sin(it.age * 5);
    card(it, { cell: 'orb', size: [s * 0.82 * wob, s * 0.78 / wob], color: col, alpha: 0.88 * a, add: 0, intensity: 1.1 });
    card(it, { cell: 'goo', size: [s * 0.9 * wob, s * 0.5], off: [0, -s * 0.22, 0.01], rot: Math.PI, color: col.map((x) => x * 0.8), alpha: 0.85 * a, add: 0, intensity: 1 });
    card(it, { cell: 'dot', size: [s * 1.2, s * 1.2], color: [1, 0.2, 0.2], alpha: 0.15 * a, add: 1, intensity: 1 });
    card(it, { cell: 'core', size: [s * 0.16, s * 0.1], off: [-s * 0.18, s * 0.2, 0.02], color: [1, 0.92, 0.9], alpha: 0.7 * a, add: 1, intensity: 1.2 });
    const n = every(it, 'd', cfg.drips || 3); if (n) d.emit(Object.assign({}, PS.gooDrop, { ramp: 'red', gravity: 4, speed: [0.2, 0.6], up: [0, 0.3] }), [it.p[0], it.p[1] - s * 0.35, it.p[2] + 0.1], n, { radius: s * 0.3, scale: 1.4 });
  }
};
