// ------------------------------------------------------------------ transient effects
// stat changes: arrows streaming up (raised) or down (lowered) around the battler in the stat's colour, a glow, rings
// at the feet. Colours follow the stand-in palettes (gfx_standin.js STAT_COLORS); `sharply` doubles the stream.
const STAT_COL = { 0: [1, 0.35, 0.25], 1: [0.35, 0.55, 1], 2: [1, 0.85, 0.3], 3: [0.35, 0.9, 1], 4: [0.8, 0.45, 1], 5: [1, 0.4, 0.85], 6: [0.45, 1, 0.5], 255: [0.95, 0.95, 1] };
HD.STAT_COLORS = STAT_COL;
HD.FX.statchange = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); const env = Math.min(1, u * 6, (1 - u) * 4);
  const dir = f.up ? 1 : -1; const n = f.sharply ? 7 : 4; const r = HD.rng(f.seed);
  for (let i = 0; i < n * 2; i++) {
    const ph = (age * (f.sharply ? 1.6 : 1.2) + i / (n * 2)) % 1; const a = (i / (n * 2)) * Math.PI * 2 + r() * 0.4; const rad = h * (0.35 + 0.18 * ((i * 7) % 3) / 2);
    const y = c[1] - h * 0.55 * dir + dir * ph * h * 1.2; const p = [c[0] + Math.cos(a) * rad, y, c[2] + Math.sin(a) * rad * 0.6 + 0.05];
    const fade = Math.sin(Math.PI * ph) * env; const sz = h * (f.sharply ? 0.3 : 0.24);
    out.cards.push({ p, cell: 'arrow', size: [sz, sz], rot: f.up ? 0 : Math.PI, color: f.color, alpha: 0.9 * fade, add: 1, intensity: 1.6, back: Math.sin(a) < 0 });
  }
  out.cards.push({ p: [c[0], c[1], c[2] - 0.05], back: true, cell: 'dot', size: [h * 2.6, h * 3], color: f.color, alpha: 0.4 * env, add: 1, intensity: 1.1 });
  const ft = d.space.feet[f.b]; const ph = (age * 1.8) % 1; const rr = f.up ? h * (0.4 + ph * 1.1) : h * (1.5 - ph * 1.1);
  out.cards.push({ p: [ft[0], 0.05, ft[2]], cell: 'ring', size: [rr * 2, rr * 2], color: f.color, alpha: 0.6 * env * (f.up ? 1 - ph : ph), add: 1, intensity: 1.2, mode: 2 });
  out.lights.push({ p: [c[0], c[1] + 0.5, c[2] + 0.8], color: f.color, intensity: 3.5 * env, range: 8 });
};
HD.FX_STEP.statchange = function (d, f, age) {
  const u = age / f.life; const a = d.act[f.b]; const env = Math.min(1, u * 6, (1 - u) * 4);
  if (a) { const g = 0.55 * env; if (g > a.glow[3]) a.glow = [f.color[0], f.color[1], f.color[2], g]; }
  if (d.frame % 2 === 0) { const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); d.emit(Object.assign({}, PS.energy, { life: [0.4, 0.7] }), [c[0], c[1] - (f.up ? 0.6 : -0.6) * h, c[2]], f.sharply ? 2 : 1, { ramp: f.ramp, radius: h * 0.5, vel: [0, (f.up ? 2.2 : -2.2) * h / 3, 0] }); }
};
HD.FX_STEP.recall = function (d, f, age) {   // switching out: the battler is drawn back in a beam of the ball's light
  const u = age / f.life; if (u < 0 || u > 1) return; const a = d.act[f.b]; if (a) { const g = 0.7 * Math.min(1, u * 5); if (g > a.glow[3]) a.glow = [f.color[0], f.color[1], f.color[2], g]; }
};
HD.FX.recall = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); const env = Math.min(1, u * 5, (1 - u) * 3);
  const back = (f.b & 1) ? [1, 0.25, -0.4] : [-1, 0.25, 0.6]; const end = V.madd([0, 0, 0], c, back, h * 3.5);
  out.ribbons.push({ pts: [c, end], width: h * 0.32 * env, cell: 'energy', color: f.color, intensity: 1.3, add: 1, alpha: 0.85 * env, scroll: age * 6, uvRepeat: 3 });
  out.ribbons.push({ pts: [c, end], width: h * 0.1 * env, cell: 'beam', color: [1, 1, 1], intensity: 1.1, add: 1, alpha: env });
  out.lights.push({ p: c, color: f.color, intensity: 4 * env, range: 8 });
};
HD.FX.levelup = function (d, f, age, out) {   // level up: the GBA flashes the healthbox (not drawn here); HD adds a brief golden shimmer on the battler
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); const env = HD.pulse(u);
  out.cards.push({ p: [c[0], c[1], c[2] - 0.05], back: true, cell: 'dot', size: [h * 2.2, h * 2.6], color: [1, 0.85, 0.4], alpha: 0.35 * env, add: 1, intensity: 1.1 });
  out.cards.push({ p: [c[0], c[1] + h * (0.2 + u * 0.6), c[2] + 0.1], cell: 'ring', size: [h * 1.6, h * 0.5], color: [1, 0.9, 0.5], alpha: 0.7 * env, add: 1, intensity: 1.3 });
};
HD.FX_STEP.levelup = function (d, f) { if (d.frame % 3) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); d.emit(PS.glint, [c[0], c[1] - h * 0.3, c[2]], 2, { ramp: 'gold', radius: h * 0.5, vel: [0, 1.6, 0] }); };
// a form change (Mega Evolution, Primal Reversion, Ultra Burst, Tera, Power Construct...): the moment the new form appears
HD.MOVE_FX.formburst = (d, e) => {
  const b = d.battlerRef(e.b); const c = d.bpos(b); const h = d.space.battlerHeight(b); const col = e.color || [1, 1, 1];
  d.flash([1, 1, 1], e.flash != null ? e.flash : 0.2); d.shake(0.25);
  d.addFx('card', { p: c.slice(), cell: 'lightray', size0: h * 1.2, size1: h * 4.5, color: col, intensity: 1.2, life: 0.5, add: 1, rot: d.rng() * 6 });
  d.addFx('card', { p: c.slice(), cell: 'flare', size0: h * 2.0, size1: h * 0.8, color: col, intensity: 1.2, life: 0.3, add: 1 });
  d.addFx('ring', { p: c.slice(), cell: 'ring', r0: h * 0.3, r1: h * 2.6, width: 0.12, color: col, intensity: 1.4, life: 0.45, add: 1, distort: 1.0 });
  const ft = d.space.feet[b]; d.addFx('ring', { p: [ft[0], 0.06, ft[2]], cell: 'ring', r0: 0.4, r1: h * 2.2, width: 0.1, color: col, intensity: 1, life: 0.5, add: 0.6, ground: true, distort: 0.5 });
  d.emit(PS.glint, c, 28, { ramp: e.ramp || 'rainbow', radius: h * 0.4, speedMul: 2.2 });
  d.addFx('lightpulse', { p: c.slice(), color: col, intensity: 8, range: 12, life: 0.6 });
};
HD.MOVE_FX.statchange = (d) => {
  const g = d.setup.general || {}; const P = root.BFX_RT && root.BFX_RT.FN && root.BFX_RT.FN.statsChangeParams ? root.BFX_RT.FN.statsChangeParams(g.animArg | 0) : null;
  // AnimTask_StatsChange passes isTarget = 0 and multiple = 0: the battler whose stats change is the attacker
  const pal = P ? P.pal : 0xFF; const col = STAT_COL[pal] || STAT_COL[255]; const up = P ? !P.down : true; const life = Math.max(40, ((d.plan && d.plan.frames) || 64) - 4) / FPS;
  d.addFx('statchange', { b: d.atkB(), life, color: col, up, sharply: !!(P && P.sharply), ramp: up ? 'gold' : 'water' });
};
HD.MOVE_FX.recall = (d, e) => { const g = d.setup.general || {}; const look = ballLook('GFX_TAG_' + String(g.ball || 'POKE').toUpperCase().replace(/^ITEM_|^BALL_|_BALL$/g, '') + '_BALL'); d.addFx('recall', { b: d.atkB(), life: (e.dur || 26) / FPS, color: look.glow }); };
HD.MOVE_FX.levelup = (d, e) => d.addFx('levelup', { b: d.atkB(), life: (e.dur || 36) / FPS });

