// strong winds (Delta Stream): streaks of air across the field (an extra weather kind; the others live in tasks.js)
const baseWeatherStep = HD.weatherStep;
HD.weatherStep = function (d) {
  baseWeatherStep(d); const env = d.env; if (env.weather !== 'wind') return; const amt = env.weatherLevel || 0; const r = d.rng;
  const n = Math.round(6 * amt + r()); for (let i = 0; i < n; i++) d.emit(PS.windStreak, [r.range(-14, -6), r.range(0.4, 6), r.range(-6, 6)], 1, { vel: [18, r.range(-0.5, 0.5), 0], scale: 1.6 });
};

