HD.MOVE_FX.grab = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); if (!present(d, b)) return; d.addFx('grab', { b, life: (e.dur || 16) / FPS, color: e.color || [0.5, 0.3, 0.8], reach: e.reach || 1.5 }); };
HD.FX.grab = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = battlerNow(d, f.b); const h = d.space.battlerHeight(f.b);
  const foe = d.bpos(f.b ^ 1); const dir = V.norm([0, 0, 0], V.sub([0, 0, 0], foe, c)); const reach = (u < 0.6 ? HD.easeOut(u / 0.6) : 1 - HD.easeIn((u - 0.6) / 0.4) * 0.7) * h * f.reach;
  const p = V.madd([0, 0, 0], c, dir, h * 0.35 + reach); p[1] += h * 0.12; p[2] += 0.35; const close = u < 0.55 ? 1 : 1 - Math.min(1, (u - 0.55) / 0.2) * 0.45; const k = Math.min(1, u * 8, (1 - u) * 4);
  const root0 = V.madd([0, 0, 0], c, dir, h * 0.2); root0[2] += 0.3;
  out.ribbons.push({ pts: [root0, V.lerp([0, 0, 0], root0, p, 0.5), p], width: h * 0.45, cell: 'smoke', color: [0.12, 0.05, 0.2], alpha: 0.75 * k, add: 0, taper: 0.4, scroll: age * 4 });
  out.cards.push({ p, cell: 'dot', size: [h * 1.8, h * 1.8], color: f.color, alpha: 0.35 * k, add: 1, intensity: 1 });
  const hc = close < 0.8 ? 'fist3' : 'palm3';   // v3: the open hand reaches, then closes on the snatch (was v2's flat glove icon)
  out.cards.push({ p, cell: hc, size: [h * 0.86, h * 0.86], rot: HD.alignRot(dir), color: f.color, alpha: 0.45 * k, add: 1, intensity: 1.2 });
  out.cards.push({ p, cell: hc, size: [h * 0.8, h * 0.8], rot: HD.alignRot(dir), color: [0.05, 0.02, 0.08], alpha: 0.8 * k, add: 0, hot: 0, intensity: 1 });
  out.cards.push({ p, cell: hc, size: [h * 0.74, h * 0.74], rot: HD.alignRot(dir), color: [0.34, 0.2, 0.5], alpha: k, add: 0.1, hot: 0.3, intensity: 1 });
};
HD.FX_STEP.grab = function (d, f, age) { if (!f.snap && age / f.life > 0.55) { f.snap = true; const c = battlerNow(d, f.b); const h = d.space.battlerHeight(f.b); const dir = V.norm([0, 0, 0], V.sub([0, 0, 0], d.bpos(f.b ^ 1), c)); const p = V.madd([0, 0, 0], c, dir, h * 1.8); d.emit(PS.darkSmoke, p, 8, { scale: 1.2 }); d.emit(PS.energy, p, 10, { ramp: 'dark', scale: 1.3 }); d.shake(0.08); } };

// ------------------------------------------------------------------ orbit: stars / motes circling a battler, passing behind and in front of it
HD.MOVE_FX.orbit = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); if (!present(d, b)) return; d.addFx('orbit', { b, life: (e.dur || 120) / FPS, n: e.n || 6, color: e.color || [0.85, 0.85, 1], cell: e.cell || 'star4', speed: e.speed || 2.2, radius: e.radius || 1.0, size: e.size || 1 }); };
HD.FX.orbit = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); const k = env01(u, 0.12, 0.2); const front = camSide(c);
  for (let i = 0; i < f.n; i++) {
    const a = age * f.speed + (i / f.n) * Math.PI * 2; const R = h * f.radius * (0.9 + 0.1 * Math.sin(age * 3 + i));
    const p = [c[0] + Math.cos(a) * R, c[1] + Math.sin(a * 2 + i) * h * 0.18 + (i % 2 ? h * 0.15 : -h * 0.1), c[2] + Math.sin(a) * R * 0.55];
    const fr = front(p); const tw = 0.75 + 0.25 * Math.sin(age * 20 + i * 2); const sz = h * 0.34 * tw * f.size;
    out.cards.push({ p, back: !fr, cell: f.cell, size: [sz, sz], rot: age * 2 + i, color: f.color, alpha: k * (fr ? 1 : 0.6), add: 1, intensity: 1.6 });
    out.cards.push({ p, back: !fr, cell: 'dot', size: [sz * 1.9, sz * 1.9], color: f.color, alpha: 0.25 * k, add: 1, intensity: 1 });
  }
  out.lights.push({ p: [c[0], c[1] + 0.4, c[2] + 0.8], color: f.color, intensity: 2.2 * k, range: 9 });
};

// ------------------------------------------------------------------ gravity: the field presses every battler down
// (pressure lines raining onto each battler, a dark dent in the ground, rings closing in, dust at the feet)
HD.MOVE_FX.gravity = (d, e) => d.addFx('gravity', { life: (e.dur || 50) / FPS, color: e.color || [0.72, 0.62, 1] });
HD.FX.gravity = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.15, 0.25);
  for (let b = 0; b < 4; b++) {
    if (!present(d, b)) continue; const ft = d.space.feet[b]; const h = d.space.battlerHeight(b); const r = HD.rng(f.seed + b * 31);
    for (let i = 0; i < 7; i++) { const ph = (age * 2.2 + r()) % 1; const x = ft[0] + r.range(-h * 0.85, h * 0.85), z = ft[2] + r.range(-0.3, 0.3) + 0.4; const y = h * (2.6 - ph * 2.4);
      out.cards.push({ p: [x, y, z], cell: 'speed', size: [h * 1.1, h * 0.2], rot: Math.PI / 2, color: f.color, alpha: 0.85 * k * Math.sin(Math.PI * ph), add: 1, intensity: 1.4 }); }
    const ph = (age * 1.8) % 1;
    out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 2.6, h * 1.6], rot: 0, color: [0.05, 0.02, 0.1], alpha: 0.5 * k, add: 0, intensity: 1, mode: 2 });
    out.decals.push({ p: [ft[0], 0.035, ft[2]], cell: 'ring', size: [h * (2.6 - ph * 1.8), h * (1.6 - ph * 1.1)], rot: 0, color: f.color, alpha: 0.7 * k * (0.3 + ph * 0.7), add: 1, intensity: 1.1, mode: 2 });
  }
};
HD.FX_STEP.gravity = function (d, f, age) {
  const k = env01(age / f.life, 0.15, 0.25);
  for (let b = 0; b < 4; b++) {
    if (!present(d, b)) continue; const a = d.act[b]; if (a) { a.sy *= 1 - 0.05 * k; a.sx *= 1 + 0.035 * k; }
    if (d.frame % 4 === b) { const ft = d.space.feet[b]; d.emit(PS.dustPuff, [ft[0], 0.15, ft[2]], 2, { dir: [0, 0.12, 0], spread: 1, scale: 1.3 }); }
  }
  if (d.frame % 6 === 0) d.shake(0.05);
};

// ------------------------------------------------------------------ arcs: lightning from a battler to the others it hits (Discharge)
HD.MOVE_FX.arcs = (d, e) => d.addFx('arcs', { b: d.battlerRef(e.b || 'attacker'), life: (e.dur || 30) / FPS, color: e.color || [1, 0.92, 0.45], all: e.all !== false });
HD.FX.arcs = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const a = d.bpos(f.b); const k = env01(u, 0.08, 0.3);
  for (let b = 0; b < 4; b++) {
    if (b === f.b || !present(d, b) || (!f.all && b !== d.tgtB())) continue; const p = d.bpos(b);
    HD.boltRibbons(a, p, (f.seed + b * 977 + Math.floor(age * FPS / 2) * 131) | 0, 0.1, f.color, 2.6 * k, 2, out, 0.2);
    out.lights.push({ p, color: f.color, intensity: 4 * k, range: 9 });
  }
};
HD.FX_STEP.arcs = function (d, f) { if (d.frame % 3) return; for (let b = 0; b < 4; b++) if (b !== f.b && present(d, b) && (f.all || b === d.tgtB())) d.emit(PS.spark, d.bpos(b), 6, { scale: 1.1 }); };

// ------------------------------------------------------------------ gale: a wind sweeps across the whole field and blows the haze away (Defog)
HD.MOVE_FX.gale = (d, e) => d.addFx('gale', { life: (e.dur || 100) / FPS, color: e.color || [0.9, 0.96, 1] });
HD.FX.gale = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.15, 0.25); const r = HD.rng(f.seed); const dir = (d.atkB() & 1) ? -1 : 1;
  for (let i = 0; i < 16; i++) {
    const ph = (age * (0.8 + r() * 0.6) + r()) % 1; const y = 0.4 + r() * 6.5; const z = r.range(-7, 5); const x = -12 + 26 * (dir > 0 ? ph : 1 - ph); const len = 2 + r() * 3;
    out.ribbons.push({ pts: [[x - dir * len, y, z], [x - dir * len * 0.5, y + 0.12, z], [x, y + 0.1, z]], width: 0.16 + r() * 0.16, cell: 'trail', color: f.color, intensity: 0.95, alpha: 0.55 * k * Math.sin(Math.PI * ph), add: 1, taper: 0.6 });
  }
  out.distort.push({ p: [1, 3, 0], cell: 'swirl', size: [18, 18], strength: 0.12 * k, mode: 0 });
};
HD.FX_STEP.gale = function (d) { if (d.frame % 2) return; const r = d.rng; const dir = (d.atkB() & 1) ? -1 : 1; d.emit(PS.mist, [r.range(-11, 13), r.range(0.5, 4), r.range(-7, 5)], 1, { vel: [dir * 6, 0.4, 0], scale: 1.8 }); };

// ------------------------------------------------------------------ mistcloud: soft coloured mist drifting around a battler (Aromatic Mist)
HD.MOVE_FX.mistcloud = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); if (!present(d, b)) return; d.addFx('mistcloud', { b, life: (e.dur || 120) / FPS, color: e.color || [1, 0.58, 0.8], n: e.n || 8 }); };
HD.FX.mistcloud = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); const k = env01(u, 0.2, 0.3); const r = HD.rng(f.seed); const front = camSide(c);
  for (let i = 0; i < f.n; i++) {
    const a = age * (0.5 + r() * 0.4) + r() * 6.283; const R = h * (0.6 + r() * 0.5); const p = [c[0] + Math.cos(a) * R, c[1] - h * 0.35 + r() * h * 0.9, c[2] + Math.sin(a) * R * 0.5];
    out.cards.push({ p, back: !front(p), cell: 'cloud', size: [h * (1.0 + r() * 0.6), h * (0.7 + r() * 0.4)], rot: r() * 6 + age * 0.3, color: f.color, alpha: 0.42 * k, add: 0.5, intensity: 1.15 });
  }
  out.lights.push({ p: [c[0], c[1], c[2] + 0.8], color: f.color, intensity: 1.6 * k, range: 8 });
};
HD.FX_STEP.mistcloud = function (d, f) { if (d.frame % 4) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); d.emit(PS.petalBig, [c[0], c[1] + h * 0.6, c[2]], 1, { radius: h * 0.6 }); };

// ------------------------------------------------------------------ swipe: a crescent of water (or energy) slashing across a battler
// (Aqua Tail's tail swing): the arc sweeps from the user's side over the top and down, its tail catching up
HD.MOVE_FX.swipe = (d, e) => {
  const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; const mir = (d.atkB() & 1) === 1;
  const a0 = e.a0 != null ? e.a0 : 2.4, a1 = e.a1 != null ? e.a1 : -0.6;
  d.addFx('swipe', { b, life: (e.dur || 12) / FPS, color: e.color || [0.45, 0.72, 1], cell: e.cell || 'water', a0: mir ? Math.PI - a0 : a0, a1: mir ? Math.PI - a1 : a1, radius: e.radius || 0.85, width: e.width || 0.32 });
};
HD.FX.swipe = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b);
  const head = HD.easeOut(Math.min(1, u / 0.6)); const tail = u < 0.35 ? 0 : HD.easeIn((u - 0.35) / 0.65); if (head - tail < 0.02) return;
  const n = 20; const pts = [], ws = [];
  for (let i = 0; i <= n; i++) { const t = tail + (head - tail) * (i / n); const a = f.a0 + (f.a1 - f.a0) * t; pts.push([c[0] + Math.cos(a) * h * f.radius, c[1] + Math.sin(a) * h * f.radius * 0.9, c[2] + 0.45]); ws.push(h * f.width * Math.sin(Math.PI * (0.15 + 0.85 * i / n))); }
  out.ribbons.push({ pts, widths: ws.map((w) => w * 1.6), width: 1, cell: 'boltglow', color: f.color, intensity: 0.5, add: 1 });
  out.ribbons.push({ pts, widths: ws, width: 1, cell: f.cell, color: f.color, intensity: 1.15, alpha: 0.95, add: 0.25, scroll: age * 8, uvRepeat: 2 });
  out.ribbons.push({ pts, widths: ws.map((w) => w * 0.3), width: 1, cell: 'beam', color: [0.92, 0.97, 1], intensity: 0.9, add: 0.6 });
  out.cards.push({ p: pts[n], cell: 'spray', size: [h * 0.9, h * 0.9], rot: age * 8, color: [0.85, 0.95, 1], alpha: 0.8 * (1 - tail), add: 0.4, intensity: 1.2 });
};
HD.FX_STEP.swipe = function (d, f, age) { if (!f.hit && age / f.life > 0.5) { f.hit = true; d.emit(PS.droplet, d.bpos(f.b), 22, { scale: 1.5, speedMul: 1.4 }); d.shake(0.15); } };

// ------------------------------------------------------------------ kits
// a tongue licking the target: a pink, glossy swipe with drops of saliva
K.lick = {
  update(d, it, cfg) {
    const s = pxSize(d, it, cfg.scale || 1.7); const col = tintColor(cfg.color || [1, 0.42, 0.6], it); const u = Math.min(1, it.age / 0.3);
    card(it, { cell: 'goo', size: [s * 0.55, s * (0.7 + 0.5 * u)], rot: it.rot - 0.4, color: col, alpha: it.alpha, add: 0, intensity: 1.15 });
    card(it, { cell: 'wind', size: [s * 1.1, s * 0.6], rot: it.rot - 0.4 + u * 0.6, color: [1, 0.75, 0.85], alpha: 0.55 * it.alpha * (1 - u), add: 1, intensity: 1.3 });
    const n = every(it, 'd', 14); if (n) d.emit(PS.gooDrop, it.p, n, { ramp: 'pink', scale: s / 2.6 });
  },
  init(d, it) { const b = d.space.nearestBattler(it.p).b; if (b >= 0 && b !== d.atkB()) d.impact({ b, pos: it.p.slice(), strength: d.strength * 0.8, minGap: 6 }); }
};
// clods of mud that splat on the ground where they land (Mud Sport)
K.mudsplat = {
  update(d, it, cfg) { K.mud.update(d, it, cfg); },
  end(d, it, cfg) {
    K.mud.end(d, it, cfg); if (it.rec.y < 56) return;   // flew off the top of the screen: no splat
    const s = pxSize(d, it, cfg.scale || 1.3); const g = [it.p[0], 0.02, it.p[2]];
    d.addFx('decal', { p: g, cell: 'puddle', size: s * 1.5, life: 2.6, alpha: 0.85, color: [0.3, 0.2, 0.1], rot: d.rng() * 6 }); d.emit(PS.mudDrop, [g[0], 0.2, g[2]], 5, { scale: s / 1.6 });
  }
};
// a ball of ice rolling through the air (Ice Ball): a faceted crystal mesh with a frost halo, frost trail and cold mist
K.iceball = {
  update(d, it, cfg) {
    const s = wpx(d, it.p, cfg.px || 22); const a = it.alpha;
    it.mesh = { kind: 'gem', p: it.p, size: s * 0.5, scale: [1, 0.92, 1], rot: [it.age * 7, it.age * 4 + it.uid, 0.3], color: [0.62, 0.84, 1] };
    card(it, { cell: 'bubble', size: [s * 1.25, s * 1.25], rot: 0, color: [0.75, 0.92, 1], alpha: 0.55 * a, add: 0.2, intensity: 1.1 });
    card(it, { cell: 'frost', size: [s * 1.3, s * 1.3], rot: it.age * 2, color: [0.6, 0.85, 1], alpha: 0.3 * a, add: 0.5, intensity: 1.0 });
    card(it, { cell: 'dot', size: [s * 2.0, s * 2.0], color: [0.45, 0.75, 1], alpha: 0.14 * a, add: 1, intensity: 1 });
    if (V.len(it.v) > 1.5) trail(d, it, { len: 7, width: s * 0.6, cell: 'energy', color: [0.55, 0.85, 1], intensity: 0.9, taper: 0.25, alpha: 0.55 });
    const n = every(it, 'f', 14); if (n) d.emit(PS.frost, it.p, n, { scale: s / 1.6 }); const m = every(it, 'm', 6); if (m) d.emit(PS.mist, it.p, m, { ramp: 'frost', scale: s / 2 });
    d.light(it.p, [0.6, 0.85, 1], 1.4 * a, 8, 'ice');
  },
  end(d, it) {
    d.emit(PS.iceChip, it.p, 14, { scale: 1.3, speedMul: 1.3 }); d.emit(PS.mist, it.p, 4, { ramp: 'frost', scale: 1.2 });
    const b = nearTarget(d, it.p, 1.4); if (b >= 0 && !d.status) d.impact({ b, pos: it.p.slice(), strength: d.strength, minGap: 4, style: HD.IMPACT_STYLES.TYPE_ICE });
  }
};
// ice shards flying off an impact: a crisp shard with frost, no glare
K.iceshard = {
  update(d, it, cfg) {
    const s = pxSize(d, it, cfg.scale || 1.3); const vdir = velDir(it); const rot = vdir ? HD.alignRot(vdir) : it.rot + it.age * 4;
    card(it, { cell: 'shard', size: [s * 0.7, s], rot, color: tintColor([0.78, 0.94, 1], it), alpha: it.alpha, add: 0.35, intensity: 1.35 });
    card(it, { cell: 'dot', size: [s * 1.2, s * 1.2], color: [0.5, 0.82, 1], alpha: 0.22 * it.alpha, add: 1, intensity: 1 });
    const n = every(it, 'f', 8); if (n) d.emit(PS.frost, it.p, n, { scale: s / 2.2 });
  },
  end(d, it) { d.emit(PS.iceChip, it.p, 3, { scale: 0.9 }); }
};
// a root bursting out of the ground and arching toward the target (Frenzy Plant)
K.rootburst = {
  init(d, it) { const g = [it.p[0], 0.2, it.p[2]]; d.emit(PS.chip, g, 7, { scale: 1.3 }); d.emit(PS.dustPuff, g, 5, { scale: 1.3, dir: [0, 0.6, 0], spread: 0.8 }); d.addFx('decal', { p: [it.p[0], 0.02, it.p[2]], cell: 'crack', size: 2.4, life: 2.4, alpha: 0.85, rot: d.rng() * 6 }); d.shake(0.05); },
  update(d, it, cfg) {
    const s = pxSize(d, it, cfg.scale || 1.7); const grow = HD.easeOut(Math.min(1, it.age / 0.22)); const a = it.alpha;
    const base = [it.p[0], 0, it.p[2]]; const tg = d.bpos(d.tgtB()); const dir = V.norm([0, 0, 0], [tg[0] - base[0], 0, tg[2] - base[2]]);
    const H = s * 1.15 * grow; const sway = Math.sin(it.age * 6 + it.uid) * 0.12; const pts = [], ws = []; const n = 10;
    for (let i = 0; i <= n; i++) { const t = i / n; const bend = t * t; pts.push([base[0] + dir[0] * bend * s * 0.55 + sway * t * s, t * H, base[2] + dir[2] * bend * s * 0.55 + 0.2]); ws.push(s * (0.5 - 0.4 * t)); }
    it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: ws, width: 1, cell: 'beam', color: [0.2, 0.55, 0.12], intensity: 1, alpha: a, add: 0 });
    it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: ws.map((w) => w * 0.6), width: 1, cell: 'beam', color: [0.13, 0.4, 0.08], intensity: 1, alpha: a, add: 0 });
    it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: ws.map((w) => w * 0.2), width: 1, cell: 'beam', color: [0.62, 1, 0.38], intensity: 0.7, alpha: 0.6 * a, add: 0.25 });
    it.cards.push({ fixed: true, p: pts[n], cell: 'leaf' + (it.uid & 1), size: [s * 0.42, s * 0.42], rot: it.age * 2 + it.uid, color: [0.42, 0.85, 0.3], alpha: a, add: 0, intensity: 1.1 });
    it.cards.push({ layer: 'decals', fixed: true, p: [base[0], 0.03, base[2]], cell: 'dot', size: [s * 1.2, s * 0.8], color: [0.12, 0.08, 0.04], alpha: 0.5 * a, add: 0, intensity: 1, mode: 2 });
    const m = every(it, 'l', 6); if (m) d.emit(PS.leafBit, pts[n], m, { scale: 1.2 });
  },
  end(d, it) { d.emit(PS.dustPuff, [it.p[0], 0.2, it.p[2]], 3, { scale: 1.1 }); }
};
// a thrown object (Fling: the GBA throws a black ball for the held item): a solid dark ball with a highlight and a speed trail
K.thrown = {
  update(d, it, cfg) {
    const s = wpx(d, it.p, cfg.px || 18); const a = it.alpha; const sp = V.len(it.v); const vdir = velDir(it);
    if (sp > 1.5) trail(d, it, { len: 6, width: s * 0.6, cell: 'trail', color: cfg.trailColor || [0.85, 0.82, 0.95], intensity: 0.9, alpha: 0.6, taper: 0.4 });
    card(it, { cell: 'dot', size: [s * 1.8, s * 1.8], color: [0.55, 0.4, 0.8], alpha: 0.3 * a, add: 1, intensity: 1 });
    card(it, { cell: 'orb', size: [s, s], rot: it.age * 10, color: cfg.color || [0.17, 0.14, 0.22], alpha: 0.97 * a, add: 0, intensity: 1 });
    card(it, { cell: 'core', size: [s * 0.3, s * 0.3], off: [-s * 0.15, s * 0.15, 0.02], color: [1, 1, 1], alpha: 0.6 * a, add: 1, intensity: 1.2 });
    if (sp > 3 && vdir) { const n = every(it, 'w', 18); if (n) d.emit(PS.windStreak, it.p, n, { dir: V.scale([0, 0, 0], vdir, -1), spread: 0.15, scale: s / 2.5 }); }
  },
  end(d, it) { const b = nearTarget(d, it.p, 1.4); if (b >= 0 && !d.status) { d.impact({ b, pos: it.p.slice(), strength: d.strength * 1.2, minGap: 3, force: true, style: HD.IMPACT_STYLES.TYPE_DARK }); d.shake(0.25); } }
};
// a ring of wind spreading from the user (Defog): a turning swirl, not a glaring disc; sized to the field at most
K.gustring = {
  update(d, it, cfg) {
    const h = d.space.battlerHeight(d.atkB()); const s = Math.min(pxSize(d, it, cfg.scale || 1.1), h * 4.2); const a = it.alpha; const col = cfg.color || [0.85, 0.95, 1];
    card(it, { cell: 'swirl', size: [s, s], rot: -it.age * 7, color: col, alpha: 0.5 * a, add: 1, intensity: 1.05 });
    card(it, { cell: 'ring', size: [s * 1.05, s * 1.05], color: col, alpha: 0.35 * a, add: 1, intensity: 1 });
    card(it, { layer: 'distort', cell: 'swirl', size: [s * 1.2, s * 1.2], strength: 0.45 });
    const n = every(it, 'w', 26); if (n) d.emit(PS.windStreak, it.p, n, { radius: s * 0.35, scale: Math.max(1, s / 4) });
  }
};
// a crackling dome of electricity around the user (Discharge): a soft yellow sphere, arcs over its surface, sparks
K.elecdome = {
  update(d, it, cfg) {
    const h = d.space.battlerHeight(d.atkB()); const s = Math.min(pxSize(d, it, cfg.scale || 1.0), h * 3.2); const a = it.alpha; const col = cfg.color || [1, 0.92, 0.45];
    card(it, { cell: 'dot', size: [s * 1.2, s * 1.2], color: col, alpha: 0.16 * a, add: 1, intensity: 1 });
    card(it, { cell: 'ring', size: [s, s], color: col, alpha: 0.45 * a, add: 1, intensity: 1.2 });
    if (Math.floor(it.age * FPS) % 2 === 0 || !it.s.arcs) {
      const out = { ribbons: [], cards: [] };
      for (let k = 0; k < 5; k++) { const a0 = d.rng() * 6.283, a1 = a0 + d.rng.range(0.6, 1.4); const p0 = [it.p[0] + Math.cos(a0) * s * 0.42, it.p[1] + Math.sin(a0) * s * 0.42, it.p[2] + 0.2], p1 = [it.p[0] + Math.cos(a1) * s * 0.5, it.p[1] + Math.sin(a1) * s * 0.5, it.p[2] + 0.2]; HD.boltRibbons(p0, p1, Math.floor(d.rng() * 1e9), Math.max(0.04, s * 0.012), col, 2.2 * a, 0, out, 0.3); }
      it.s.arcs = out.ribbons;
    }
    for (const r of it.s.arcs) it.cards.push({ layer: 'ribbons', fixed: true, ...r });
    const n = every(it, 'sp', 30); if (n) d.emit(PS.spark, it.p, n, { radius: s * 0.4, scale: 0.8 });
    d.light(it.p, col, 3 * a, 10, 'elec');
  }
};
// a water tail slamming down (Aqua Tail's knock-off sprite): a curling wave crest with a water trail and spray
K.watertail = {
  update(d, it, cfg) {
    const s = pxSize(d, it, cfg.scale || 1.25); const a = it.alpha; const vdir = velDir(it);
    trail(d, it, { len: 7, width: s * 0.7, cell: 'water', color: [0.4, 0.68, 1], intensity: 1.05, taper: 0.2, alpha: 0.9, add: 0.15, scroll: 5 });
    card(it, { cell: 'wavecrest', size: [s, s], rot: vdir ? HD.alignRot(vdir) + Math.PI : it.rot, color: [0.6, 0.82, 1], alpha: 0.95 * a, add: 0.2, intensity: 1.2, flip: it.flipH ? 1 : 0 });
    const n = every(it, 'd', 30); if (n) d.emit(PS.droplet, it.p, n, { scale: s / 2.4, vel: V.scale([0, 0, 0], it.v, 0.2) });
  },
  end(d, it) { const b = nearTarget(d, it.p, 1.5); if (b >= 0 && !d.status) d.impact({ b, pos: d.bpos(b), strength: d.strength * 1.1, minGap: 3, force: true, style: HD.IMPACT_STYLES.TYPE_WATER }); d.emit(PS.droplet, it.p, 18, { scale: 1.3, speedMul: 1.3 }); }
};
// chain rows (Fairy Lock): every GBA sprite of a row is one pair of interlocking links, sized to the 16-pixel step
K.chainlink = {
  update(d, it, cfg) {
    const u = wpx(d, it.p, cfg.px || 16); const a = it.alpha; const col = tintColor(cfg.color || [1, 0.66, 0.88], it);
    card(it, { cell: 'ring', size: [u * 1.0, u * 0.7], off: [-u * 0.28, 0, 0], color: col, alpha: a, add: 0.4, intensity: 1.6 });
    card(it, { cell: 'ring', size: [u * 1.0, u * 0.26], off: [u * 0.3, 0, 0.01], color: col, alpha: a, add: 0.4, intensity: 1.6 });
    card(it, { cell: 'dot', size: [u * 1.8, u * 1.0], color: col, alpha: 0.2 * a, add: 1, intensity: 1 });
    if ((it.uid + Math.floor(it.age * FPS)) % 23 === 0) d.emit(PS.glint, it.p, 1, { ramp: 'fairy', scale: 1.2 });
  }
};
// a billowing ball of steam with a scalding core (Steam Eruption): white steam that does not glare, orange heat inside
K.steamball = {
  update(d, it, cfg) {
    const s = pxSize(d, it, cfg.scale || 1.3); const a = it.alpha; const u = Math.min(1, it.age / 0.5);
    card(it, { cell: 'smoke' + (it.uid % 3), size: [s * (1.4 + u * 0.5), s * (1.4 + u * 0.5)], rot: it.uid + it.age * 0.8, color: [0.92, 0.94, 0.97], alpha: 0.78 * a, add: 0.1, intensity: 1.1 });
    card(it, { cell: 'cloud', size: [s * (1.1 + u * 0.4), s * (0.9 + u * 0.3)], rot: -it.uid - it.age * 0.5, color: [0.95, 0.96, 1], alpha: 0.5 * a, add: 0.15, intensity: 1.05 });
    card(it, { cell: 'fireball', size: [s * 0.45, s * 0.45], rot: it.age * 2, color: [1, 1, 1], gmap: 'fire', alpha: 0.55 * a * (1 - u * 0.5), add: 0.6, intensity: 1.0 });
    card(it, { cell: 'dot', size: [s * 1.6, s * 1.6], color: [1, 0.55, 0.3], alpha: 0.1 * a, add: 1, intensity: 1 });
    const n = every(it, 'm', 8); if (n) d.emit(PS.mist, it.p, n, { scale: s / 1.8 }); const m = every(it, 'd', 8); if (m) d.emit(PS.droplet, it.p, m, { scale: s / 2.6 });
    d.light(it.p, [1, 0.6, 0.35], 1.0 * a, 7, 'steam');
  },
  end(d, it) { const b = nearTarget(d, it.p, 1.2); if (b >= 0 && !d.status) d.impact({ b, pos: it.p.slice(), strength: d.strength * 0.9, minGap: 8, style: HD.IMPACT_STYLES.TYPE_WATER }); d.emit(PS.mist, it.p, 2, { scale: 1.4 }); }
};
// a glowing lava rock (Searing Shot): a dark rock mesh with fire in its cracks, a short fire trail, smoke and embers
K.lavarock = {
  update(d, it, cfg) {
    const s = pxSize(d, it, cfg.scale || 1.2); const a = it.alpha;
    it.mesh = { kind: 'rock', p: it.p, size: s * 0.36, rot: [it.age * 4 + it.uid, it.age * 3, 0], color: [0.42, 0.2, 0.12] };
    card(it, { cell: 'fireball', size: [s * 0.85, s * 0.85], rot: it.age * 3, color: [1, 1, 1], gmap: 'fire', alpha: 0.6 * a, add: 0.6, intensity: 1.0 });
    if (V.len(it.v) > 1.5) trail(d, it, { len: 6, width: s * 0.5, cell: 'fire', color: rampColor('fire', 0.3), intensity: 1.0, taper: 0.25, scroll: 3, alpha: 0.75, add: 0.7 });
    const n = every(it, 'f', 20); if (n) d.emit(PS.fireBody, it.p, n, { scale: s / 1.9 }); const m = every(it, 's', 6); if (m) d.emit(PS.smoke, it.p, m, { scale: s / 1.9 }); const e = every(it, 'e', 10); if (e) d.emit(PS.ember, it.p, e);
    d.light(it.p, [1, 0.5, 0.2], 1.3 * a, 7, 'lava');
  },
  end(d, it) { if (nearTarget(d, it.p, 1.3) >= 0) K.explosion.init(d, it, { ramp: 'fire', shake: 0.8 }); else { d.emit(PS.ember, it.p, 8); d.emit(PS.chip, it.p, 4, { scale: 1.1 }); } }
};

// the user flying up as a comet (Dragon Ascent's fly-up): the fireball look, without the explosion when it leaves the screen
K.comet = { update: K.fireball.update };

