  let gba = 0; for (let f = 1; f <= Math.min(C + 2, d.plan.atkOff.length - 1); f++) { const o = d.plan.atkOff[f]; if (o && !o[2]) gba = Math.max(gba, o[0] * ux + o[1] * uy); }
  if (d.plan.atkOff.slice(1, C + 1).some((o) => o && o[2])) return;   // the user is hidden (Fly, Dig, Bounce...): the GBA shows its own approach
  // v3.2: a script that marks the target within its first frames (contact on frames 2-4: Pound, Double Kick, Comet
