    const A = d.space.gba[d.atkB()], T = d.space.gba[d.tgtB()];
    // whose item: the side of the screen the bag settles on first (the two bags start on opposite sides of the centre)
    const k = ti ? Math.min(ti.n - 1, 24) : 0; const xs = ti ? ti.tr.x[k] : it.rec.x; const mid = (A[0] + T[0]) / 2;
    s.owner = (xs < mid) === (A[0] < T[0]) ? d.atkB() : d.tgtB(); s.dest = s.owner === d.atkB() ? d.tgtB() : d.atkB();
    if (d.atkB() === d.tgtB()) { s.owner = d.atkB(); s.dest = d.atkB(); }
