// ================================================================== ice chunks and snow (Avalanche...)
PS.snowPuff = { sys: 'alpha', cell: 'smoke0', cells: 3, life: [0.55, 1.0], size: [0.45, 1.5], speed: [0.3, 1.1], drag: 1.6, ramp: 'snowpuff', spin: 0.5, gravity: 1.2, turb: 0.4 };
