// attention: chevrons streaming in toward a battler from all sides and a pulsing ring under it (Follow Me)
HD.MOVE_FX.a_attract = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); if (!present(d, b)) return; d.addFx('a_attract', { b, life: (e.dur || 120) / FPS, color: e.color || [1, 0.88, 0.5], n: e.n || 6 }); };
HD.FX.a_attract = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); const ft = d.space.feet[f.b]; const k = env01(u, 0.1, 0.2);
  for (let i = 0; i < f.n; i++) { const a = i * 6.283 / f.n + 0.3; const v = (age * 0.9 + i * 0.37) % 1; const r = h * (1.25 - 0.75 * v); const p = scrOff([c[0], c[1], c[2] + 0.2], Math.cos(a) * r, Math.sin(a) * r * 0.8); const pa = V3.pointAlong(a + Math.PI);
    out.cards.push({ p, cell: 'arrow', size: [h * 0.24, h * 0.24], rot: pa.rot, flip: pa.flip, color: f.color, alpha: k * Math.sin(Math.PI * v), add: 0.6, intensity: 1.4 }); }
  const ph = (age * 1.4) % 1; out.cards.push({ p: [ft[0], 0.06, ft[2]], cell: 'ring', size: [h * (2.2 - 1.4 * ph), h * (2.2 - 1.4 * ph)], color: f.color, alpha: 0.5 * k * ph, add: 1, intensity: 1, mode: 2 });
};
// provocation: pulses of dark-red energy thrown from the user at the target (Taunt)
HD.MOVE_FX.a_provoke = (d, e) => d.addFx('a_provoke', { a: d.atkB(), b: d.tgtB(), life: (e.dur || 60) / FPS, color: e.color || [0.9, 0.18, 0.15], n: e.n || 3 });
HD.FX.a_provoke = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const A = nowPos(d, f.a), T = nowPos(d, f.b); const hA = d.space.battlerHeight(f.a), hT = d.space.battlerHeight(f.b);
  for (let i = 0; i < f.n; i++) { const v = u * 1.6 - i * 0.28; if (v < 0 || v > 1) continue; const p = V.lerp([0, 0, 0], A, T, HD.easeIn(v)); p[1] += Math.sin(Math.PI * v) * hA * 0.3; const s = hA * (0.55 - 0.15 * v);
    out.cards.push({ p, cell: 'smoke2', size: [s * 0.9, s * 0.9], rot: age * 6, color: [0.3, 0.03, 0.04], alpha: 0.75, add: 0, intensity: 1 }); out.cards.push({ p, cell: 'flare', size: [s * 1.1, s * 1.1], color: f.color, alpha: 0.7, add: 1, intensity: 1.4 }); out.cards.push({ p, cell: 'impact3', size: [s * 1.0, s * 1.0], rot: age * 5 + i, color: [1, 0.3, 0.2], alpha: 0.7 * (1 - v * 0.4), add: 1, intensity: 1.3 });
    if (v > 0.92) out.cards.push({ p: T, cell: 'flare', size: [hT * 1.4, hT * 1.4], color: f.color, alpha: 0.45, add: 1, intensity: 1.1 }); }
};
// a roulette spin (Metronome's random pick): coloured lights circle the user faster and faster, then burst
HD.MOVE_FX.a_roulette = (d, e) => d.addFx('a_roulette', { b: d.battlerRef(e.b || 'attacker'), life: (e.dur || 30) / FPS });
HD.FX.a_roulette = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); const k = env01(u, 0.1, 0.05); const sp = 4 + 22 * u * u;
  for (let i = 0; i < 8; i++) { const a = age * sp + i * 0.785; const p = scrOff([c[0], c[1] + h * 0.5, c[2] + 0.25], Math.cos(a) * h * 0.55, Math.sin(a) * h * 0.2); const col = HD.hsv(i / 8, 0.6, 1);
    out.cards.push({ p, cell: 'dot', size: [h * 0.26, h * 0.26], color: col, alpha: 0.6 * k, add: 1, intensity: 1.2 }); out.cards.push({ p, cell: 'core', size: [h * 0.1, h * 0.1], color: [1, 1, 1], alpha: k, add: 1, intensity: 1.3 }); }
};
HD.FX_STEP.a_roulette = function (d, f, age) { if (f.done || age < f.life - 1.5 / FPS) return; f.done = true; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); d.emit(PS.glint, [c[0], c[1] + h * 0.5, c[2]], 16, { ramp: 'rainbow', radius: h * 0.3, speedMul: 1.8 }); d.addFx('shockd', { p: [c[0], c[1] + h * 0.5, c[2] + 0.3], r0: h * 0.2, r1: h * 0.9, life: 0.22, strength: 0.5 }); d.addFx('lightpulse', { p: c, color: [1, 0.95, 0.85], intensity: 3, range: 9, life: 0.3 }); };
// a drum beat on the user's belly: a pulse ring and a thump (Belly Drum)
HD.MOVE_FX.a_beat = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); const c = nowPos(d, b); const h = d.space.battlerHeight(b); const p = [c[0], c[1] - h * 0.12, c[2] + 0.3];
  d.addFx('ring', { p, cell: 'ring', r0: h * 0.12, r1: h * 0.5, width: 0.05, color: e.color || [1, 0.6, 0.35], intensity: 1.1, life: 0.16, add: 1, distort: 0.6 }); d.emit(PS.hitStreak, p, 5, { ramp: 'fire', scale: 0.6 }); d.shake(0.04); };
// a barrier snapping into place in front of the user (Quick Guard): a hex shield that forms in a few frames, speed streaks
HD.MOVE_FX.a_guard = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); if (!present(d, b)) return; d.addFx('a_guard', { b, life: (e.dur || 34) / FPS, color: e.color || [1, 0.7, 0.35] }); };
HD.FX.a_guard = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); const T = nowPos(d, d.tgtB()); const th = sAng(c, T);
  const g = HD.easeOut(Math.min(1, age / 0.07)); const k = Math.min(1, (1 - u) / 0.3); const p = scrOff([c[0], c[1], c[2] + 0.4], Math.cos(th) * h * 0.3, 0); const fl = 0.85 + 0.15 * Math.sin(age * 25);
  out.cards.push({ p, cell: 'hex', size: [h * 1.25 * g, h * 1.35 * g], color: f.color, alpha: 0.55 * k * fl, add: 1, intensity: 1.2 });
  out.cards.push({ p, cell: 'shock', size: [h * 1.3 * g, h * 1.4 * g], color: f.color, alpha: 0.4 * k, add: 1, intensity: 1.1 });
  if (age < 0.12) { const v = age / 0.12; for (let i = 0; i < 4; i++) { const a = th + Math.PI + (i - 1.5) * 0.5; out.cards.push({ p: scrOff(p, Math.cos(a) * h * (0.9 - 0.6 * v), Math.sin(a) * h * (0.7 - 0.5 * v)), cell: 'speed', size: [h * 0.6, h * 0.1], rot: a, color: [1, 0.95, 0.85], alpha: 1 - v, add: 1, intensity: 1.2 }); } }
  out.lights.push({ p, color: f.color, intensity: 3 * k, range: 7 });
};
// a clap / high five: a starburst where the two hands meet (the clapping hand sprites' midpoint)
HD.MOVE_FX.a_clap = (d, e) => {
  const hs = [...d.inst.values()].filter((x) => x.tpl === (e.tpl || 'gHelpingHandClapSpriteTemplate') && !x.hidden); if (!hs.length) return;
  const p = hs.reduce((acc, x) => V.add(acc, acc, x.p), [0, 0, 0]); V.scale(p, p, 1 / hs.length); const h = hOf(d, d.atkB()); const col = e.color || [1, 0.88, 0.5];
  d.addFx('card', { p: p.slice(), cell: 'star4', size0: h * 0.9, size1: h * 0.15, color: col, intensity: 1.8, life: 0.2, add: 1, rot: 0.3 });
  d.addFx('ring', { p: p.slice(), cell: 'ring', r0: h * 0.1, r1: h * 0.6, width: 0.05, color: col, intensity: 1.2, life: 0.2, add: 1 }); d.emit(PS.glint, p, 10, { ramp: e.ramp || 'gold', radius: h * 0.15, speedMul: 1.6 });
  d.addFx('lightpulse', { p: p.slice(), color: col, intensity: 5, range: 8, life: 0.25 });
};
// a soft link of light between two battlers (Hold Hands): a pink ribbon arching between them, hearts drifting along it
HD.MOVE_FX.a_link = (d, e) => { const a = d.atkB(), b = d.battlerRef(e.b || 'target'); if (!present(d, b) || a === b) return; d.addFx('a_link', { a, b, life: (e.dur || 60) / FPS, color: e.color || [1, 0.5, 0.78] }); };
HD.FX.a_link = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const A = nowPos(d, f.a), B = nowPos(d, f.b); const h = d.space.battlerHeight(f.a); const k = env01(u, 0.15, 0.25);
  const pts = []; for (let i = 0; i <= 12; i++) { const v = i / 12; const q = V.lerp([0, 0, 0], A, B, v); q[1] += Math.sin(Math.PI * v) * h * 0.4; pts.push(q); }
  out.ribbons.push({ pts, width: h * 0.16, cell: 'trail', color: f.color, intensity: 1.1, alpha: 0.55 * k, add: 1, scroll: age * 2 });
  out.ribbons.push({ pts, width: h * 0.05, cell: 'beam', color: [1, 0.85, 0.92], intensity: 1, alpha: 0.6 * k, add: 1 });
};
HD.FX_STEP.a_link = function (d, f) { if (d.frame % 5) return; const A = nowPos(d, f.a), B = nowPos(d, f.b); const v = d.rng(); const q = V.lerp([0, 0, 0], A, B, v); q[1] += Math.sin(Math.PI * v) * d.space.battlerHeight(f.a) * 0.4; d.emit(PS.heart, q, 1, { scale: 0.8 }); };

