// ================================================================== wave 2 (group A): shared presentation of the group's moves
// Everything below only draws (no timing, no results). Names: a2_.
const A2_MOVES = new Set(['MOVE_GUILLOTINE', 'MOVE_HELPING_HAND', 'MOVE_ME_FIRST', 'MOVE_METRONOME', 'MOVE_HAMMER_ARM', 'MOVE_WRING_OUT', 'MOVE_CRUSH_GRIP',
  'MOVE_KARATE_CHOP', 'MOVE_DOUBLE_SLAP', 'MOVE_COMET_PUNCH', 'MOVE_VISE_GRIP', 'MOVE_DOUBLE_KICK', 'MOVE_JUMP_KICK', 'MOVE_HORN_DRILL', 'MOVE_TRIPLE_KICK',
  'MOVE_MEGAHORN', 'MOVE_ARM_THRUST', 'MOVE_SHADOW_PUNCH', 'MOVE_BULLET_PUNCH', 'MOVE_LOW_SWEEP', 'MOVE_DUAL_CHOP', 'MOVE_MEGA_PUNCH', 'MOVE_ICE_PUNCH',
  'MOVE_THUNDER_PUNCH', 'MOVE_STOMP', 'MOVE_MEGA_KICK', 'MOVE_ROLLING_KICK', 'MOVE_HORN_ATTACK', 'MOVE_FURY_ATTACK', 'MOVE_THRASH', 'MOVE_LOW_KICK',
  'MOVE_COUNTER', 'MOVE_HIGH_JUMP_KICK', 'MOVE_REVERSAL', 'MOVE_MACH_PUNCH', 'MOVE_BELLY_DRUM', 'MOVE_ENCORE', 'MOVE_BEAT_UP', 'MOVE_FOCUS_PUNCH',
  'MOVE_SMELLING_SALTS', 'MOVE_TAUNT', 'MOVE_BRICK_BREAK', 'MOVE_BLAZE_KICK', 'MOVE_NEEDLE_ARM', 'MOVE_METEOR_MASH', 'MOVE_WAKE_UP_SLAP', 'MOVE_CLOSE_COMBAT',
  'MOVE_ASSURANCE', 'MOVE_SUCKER_PUNCH', 'MOVE_QUICK_GUARD', 'MOVE_QUASH', 'MOVE_RETALIATE', 'MOVE_DRILL_RUN', 'MOVE_HEART_STAMP', 'MOVE_HORN_LEECH',
  'MOVE_HOLD_HANDS', 'MOVE_POWER_UP_PUNCH', 'MOVE_HYPERSPACE_FURY', 'MOVE_FIRE_PUNCH', 'MOVE_DIZZY_PUNCH', 'MOVE_MUD_SLAP', 'MOVE_DYNAMIC_PUNCH',
  'MOVE_CROSS_CHOP', 'MOVE_ROCK_SMASH', 'MOVE_FOLLOW_ME', 'MOVE_SKY_UPPERCUT', 'MOVE_FORCE_PALM', 'MOVE_DRAIN_PUNCH', 'MOVE_VACUUM_WAVE', 'MOVE_TAIL_SLAP']);
HD.a3.A2_MOVES = A2_MOVES;
// a limb that leaves with its sprite on the contact frame stays on the target for a moment, pushed on by the follow-through
HD.FX.a2_hold = function (d, f, age, out) {
  const u = age / f.life; if (!(u >= 0 && u <= 1)) return; const a = u < 0.3 ? 1 : 1 - HD.smooth((u - 0.3) / 0.7); const e = HD.easeOut(u);
  for (const c of f.cards) out.cards.push(Object.assign({}, c, { p: scrOff(c.p, f.dir[0] * f.push * e, f.dir[1] * f.push * e), alpha: c.alpha * a }));
};
HD.POST_STEP.push(function a2_strikes(d) {
  if (!A2_MOVES.has(d.move.id)) return;
  if (d.frame <= 1 || !d.a2) d.a2 = { last: new Map() };
  const last = d.a2.last;
  for (const it of d.inst.values()) {
    if ((it.kit !== K.strike && it.kit !== K.gesture) || it.hidden) continue; const s = it.s;
    const striking = it.kit === K.strike && s.mode && s.mode !== 'gesture';
    if (striking && it.cfg.a2_hammer) a2HammerDraw(d, it);
    else if (striking && it.cfg.a2_late != null && !s.hit && s.cf != null && s.P && s.fr) a2LateDraw(d, it, it.cfg.a2_late);
    // a travelling chop gathering energy where the hand is raised: the hand itself forms there (v3 drew a star speck)
    if (striking && s.mode === 'travel' && s.kind === 'chop' && !s.hit && it.cards.some((c) => c.cell === 'star4')) {
      const h = hOf(d, s.foe); const size = h * (it.cfg.v3size || 0.46); const f0 = s.ti ? s.ti.f0 : it.born; const prog = s.cf > f0 ? clamp((d.frame - f0) / (s.cf - f0), 0, 1) : 1; const g = HD.smooth(prog / 0.45);
      const p0 = s.ua || V3.pathPos(s.fr, s.P, 0, s.c, h); it.cards = [];   // v3.2: raised above the rushing user (s.ua) when it rushes in
      limb2(it.cards, p0, s.cell, V3.limbPose(s.kind, V3.pathAng(s.fr, s.P, 0), s.th), size * (0.75 + 0.25 * g), s.ramp, s.glow, 0.35 + 0.55 * g);
    }
    a2Restyle(it.cards, it.cfg.a2k || (striking ? 1.2 : 1.15));
    if (striking) { let b = null; for (let i = it.cards.length - 1; i >= 0; i--) if (it.cards[i].limb || (it.cards[i].a2 && it.cards[i].add === 0.12)) { b = it.cards[i]; break; }
      if (b) last.set(it.uid, { cards: it.cards.filter((c) => c.p === b.p && c.layer == null), alpha: b.alpha, f: d.frame, s }); }
  }
  for (const [uid, x] of last) {
    if (d.inst.has(uid)) continue; last.delete(uid);
    if (d.frame - x.f > 1 || x.alpha < 0.3 || !x.s.hit || !x.s.fr) continue;
    const ang = V3.pathAng(x.s.fr, x.s.P, 1); const h = hOf(d, x.s.foe);
    d.addFx('a2_hold', { cards: x.cards, life: 0.15, dir: [Math.cos(ang), Math.sin(ang)], push: 0.1 * h });
  }
  // this frame's contacts: v3's punch ring (an outlined circle over the target, read as a bubble) gives way to a refraction
  // shock; the white hit streaks take the limb's colour
  const cs = d.v3 && d.v3.contacts; if (!cs) return;
  for (const c of cs) {
    if (c.a2Done || c.f !== d.frame) continue; c.a2Done = true;
    const before = d.fx.length; d.fx = d.fx.filter((f) => !(f.kind === 'ring' && f.cell === 'ring' && !f.ground && f.t0 === d.t && V.dist(f.p, c.p) < c.h * 0.35));
    if (d.fx.length !== before) d.addFx('shockd', { p: c.p.slice(), r0: 0.12 * c.h, r1: 0.85 * c.h, life: 0.18, strength: 0.6 });
    const cfg = contactCfg(d, c); const ramp = (cfg && cfg.v3ramp) || d.style.ramp; const W = HD.rampIndex('white'); const R = HD.rampIndex(ramp);
    for (const e of d.emitted) if (e.ramp === W && e.t0 > d.t - 2 / FPS && Math.hypot(e.x - c.p[0], e.y - c.p[1], e.z - c.p[2]) < c.h * 0.3) e.ramp = R;
  }
});

// ------------------------------------------------------------------ wave 2: Hammer Arm, an overhead hammer blow
// The GBA parks the fist over the target for 16 frames, drops it on frame 21 and leaves it there while the target is
// squashed. HD shows no parked fist: the user winds up (a glow), the fist swings over in an arc from the user's side
// in the last 9 frames before contact (wide smear, afterimages) and lands on the runtime's contact frame; after a short
// follow-through it is gone, and only the crater (crack, dust, grit) stays while the target is flattened.
A_PATHS.hammer = [[-0.95, 0.62], [-0.3, 1.05], [0.02, 0.2]];
A_PATHS.chopLow = [[-0.72, 0.42], [-0.3, 0.42], [0.04, -0.07]];
// Double Slap: sideways slaps, one from the user's side, the next back from the far side (a vertical path read as a stab)
A_PATHS.slapH1 = [[-0.95, 0.28], [-0.42, 0.34], [0.1, 0.02]];
A_PATHS.slapH2 = [[0.8, 0.3], [0.36, 0.36], [-0.1, 0.02]];
function a2HammerDraw(d, it) {
  const s = it.s; const L = it.cards = []; if (!s.c || s.foe < 0) return; const h = hOf(d, s.foe); const size = h * (it.cfg.v3size || 0.66);
  const A = d.space.gba[d.atkB()], T = d.space.gba[s.foe]; const th = V3.gbaAngle(A[0], A[1], T[0], T[1]); const fr = V3.strikeFrame(th); const P = A_PATHS.hammer;
  const lead = 9, f = d.frame, cf = s.cf; if (f < cf - lead) return;
  let u, al = 1; if (f < cf) u = 0.05 + 0.95 * HD.easeIn((f - (cf - lead)) / lead); else { u = 1; al = 1 - HD.smooth((f - cf - 2) / 6); if (al <= 0.01) return; }
  const pos = (v) => V3.pathPos(fr, P, v, s.c, h); const pose = (v) => V3.pointAlong(V3.pathAng(fr, P, v));
  L.push(Object.assign({ layer: 'ribbons', fixed: true }, V3.smear(fr, P, Math.max(0, u - 0.75), u, s.c, h, size * 0.95, s.glow, 0.5 * al)));
  if (f <= cf) for (let k = 1; k <= 3; k++) { const uk = Math.max(0, u - k * 0.13); V3.ghost(L, pos(uk), s.cell, pose(uk), size * (1 - k * 0.06), s.glow, (0.4 - k * 0.1) * al); }
  limb2(L, pos(u), s.cell, pose(u), size, s.ramp, s.glow, al);
}

// ------------------------------------------------------------------ wave 2: Guillotine, two great pincer jaws
// The GBA's two blade sprites face each other across the target (one up-right, one down-left, the top one near the
// screen edge) and bite three times before the final cut. HD draws them as a pair of large lit pincer claws hinged
// left and right of the target at its middle, inside the frame: each claw closes in when its sprite closes (the bite
// follows the runtime's motion frame by frame), with an ink outline, a steel shading and a violet menace rim.
K.a2_jaw = {
  init(d, it) {
    const s = it.s; const ti = V3.trackInfo(d, it.uid); const T = d.space.gba[d.tgtB()]; const x0 = ti ? ti.x0 : it.rec.x, y0 = ti ? ti.y0 : it.rec.y;
    s.side = x0 < T[0] ? -1 : 1; s.d0 = Math.hypot(x0 - T[0], y0 - T[1]) || 30; s.dmin = s.d0;
    if (ti) for (let i = 0; i < ti.n; i++) s.dmin = Math.min(s.dmin, Math.hypot(ti.tr.x[i] - T[0], ti.tr.y[i] - T[1]));
    s.prev = 1; s.armed = false;
  },
  update(d, it, cfg) {
    const s = it.s; const b = d.tgtB(); if (!present(d, b)) return; const T = d.space.gba[b]; const h = hOf(d, b); const c = nowPos(d, b);
    const dist = Math.hypot(it.rec.x - T[0], it.rec.y - T[1]); const open = clamp((dist - s.dmin) / Math.max(1, s.d0 - s.dmin), 0, 1);
    const g = HD.smooth(Math.min(1, it.age / 0.15)); const size = h * (cfg.v3size || 0.78) * (0.75 + 0.25 * g);
    const x = s.side * h * (0.5 + 0.42 * open + 0.35 * (1 - g)); const p = scrOff([c[0], c[1], c[2] + 0.35], x, h * 0.06 * s.side * open);
    const pose = s.side < 0 ? { rot: 0.12 * open, flip: 0 } : { rot: -0.12 * open, flip: 1 }; const L = it.cards;
    const rim = cfg.a2rim || [0.6, 0.35, 1];
    L.push({ fixed: true, p, cell: 'dot', size: [size * 1.5, size * 1.5], color: rim, alpha: 0.3 * g, add: 1, intensity: 1 });
    L.push({ fixed: true, p, cell: 'pincer3', size: [size * 1.12, size * 1.12], rot: pose.rot, flip: pose.flip, color: rim, alpha: 0.55 * g, add: 1, intensity: 1.2 });
    L.push({ fixed: true, p, cell: 'pincer3', size: [size * 1.05, size * 1.05], rot: pose.rot, flip: pose.flip, color: [0.05, 0.03, 0.08], alpha: 0.6 * g, add: 0, hot: 0, intensity: 1 });
    L.push({ fixed: true, p, cell: 'pincer3', size: [size, size], rot: pose.rot, flip: pose.flip, color: cfg.a2tint || [0.66, 0.64, 0.78], gmap: 'metal', alpha: g, add: 0, intensity: 1.0 });
    if (open < 0.2 && s.prev >= 0.2 && it.age > 0.2) { const tip = scrOff(c, s.side * h * 0.3, 0); tip[2] += 0.4; d.emit(PS.steelSpark, tip, 6, { scale: 0.8 }); d.addFx('card', { p: tip, cell: 'star4', size0: h * 0.45, size1: h * 0.08, color: [0.85, 0.75, 1], intensity: 1.5, life: 0.1, add: 1 }); }
    s.prev = open; d.light(c, cfg.a2rim || [0.6, 0.4, 1], 1.2 * g, 6, 'a2_jaw');
  }
};
// the cut: a blade of light across the target where the jaws meet, sparks, a refraction shock (bigger on the last bite)
HD.MOVE_FX.a2_cut = (d, e) => { const b = d.tgtB(); if (!present(d, b)) return; const c = nowPos(d, b); const h = hOf(d, b); const k = e.k || 1; const p = [c[0], c[1] + h * 0.04, c[2] + 0.45];
  d.addFx('card', { p, cell: 'chop', size0: h * 1.0 * k, size1: h * 1.9 * k, aspect: 0.3, rot: 0.08, color: e.color || [0.92, 0.82, 1], intensity: 1.7, life: 0.16 + 0.06 * k, add: 1 });
  d.addFx('card', { p, cell: 'impact3', size0: h * 0.3, size1: h * 0.75 * k, color: [0.8, 0.8, 0.8], gmap: e.ramp || 'psychic', intensity: 1, life: 0.12, add: 1 });
  d.emit(PS.steelSpark, p, Math.round(10 * k), { scale: 1 }); d.emit(PS.energy, p, Math.round(8 * k), { ramp: e.eramp || 'dark', speedMul: 1.6 });
  d.addFx('shockd', { p: p.slice(), r0: 0.15 * h, r1: 1.0 * h * k, life: 0.22, strength: 0.8 * k }); d.shake(0.12 * k);
  if (k > 1) { d.addFx('a_stage', { life: 0.5, dark: 0.45 }); d.addFx('lightpulse', { p: p.slice(), color: [0.7, 0.5, 1], intensity: 5, range: 10, life: 0.3 }); }
};

// ------------------------------------------------------------------ wave 2: Crush Grip, a vise of force
// No floating hands: the grip travels from the user as a surge of energy (an open, C-shaped pair of arcs at the head of
// a streak), and while the runtime compresses the target two great arcs of force press on its sides, squeezing in beats
// (implosion distortion, strain lines, grit); the five crush pops are short shaped sparks.
K.a2_grasp = {
  update(d, it, cfg) {
    const b = d.tgtB(); const h = hOf(d, b); const p = it.p.slice(); const L = it.cards; const col = cfg.color || [1, 0.74, 0.38]; const T = nowPos(d, b);
    const th = sAng(d.bpos(d.atkB()), T); const close = clamp(1 - V.dist(p, T) / (h * 2.2), 0, 1); const sz = h * 0.5;
    if (it.hist.length > 1) { const pts = it.hist.slice(-6).concat([p]); L.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 0.55 * Math.pow(i / (pts.length - 1), 1.3)), width: sz * 0.55, cell: 'trail', color: col, intensity: 1.2, alpha: 0.65, add: 1 }); }
    L.push({ fixed: true, p, cell: 'flare', size: [sz * 1.2, sz * 1.2], color: col, alpha: 0.55, add: 1, intensity: 1.1 });
    for (const sd of [-1, 1]) { const q = scrOff(p, Math.cos(th + sd * 1.3) * sz * (0.32 - 0.12 * close), Math.sin(th + sd * 1.3) * sz * (0.32 - 0.12 * close)); const pa = V3.pointAlong(th + sd * (0.9 - 0.5 * close));
      L.push({ fixed: true, p: q, cell: 'swoosh', size: [sz * 0.9, sz * 0.9], rot: pa.rot + (sd > 0 ? 0 : Math.PI), flip: sd > 0 ? 0 : 1, color: col, alpha: 0.95, add: 0.6, intensity: 1.3 }); }
    d.light(p, col, 1.5, 6, 'a2_grasp');
  }
};
HD.MOVE_FX.a2_vise = (d, e) => { const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; d.addFx('a2_vise', { b, life: (e.dur || 90) / FPS, color: e.color || [1, 0.74, 0.38], beat: e.beat || 14 }); };
HD.FX.a2_vise = function (d, f, age, out) {
  const u = age / f.life; if (!(u >= 0 && u <= 1)) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); const k = env01(u, 0.06, 0.12);
  const [gx] = oamScale(d, f.b); const a = d.act[f.b]; const w = gx * (a ? a.sx : 1); const ph = (age * FPS / f.beat) % 1; const sq = ph < 0.25 ? HD.easeOut(ph / 0.25) : 1 - HD.smooth((ph - 0.25) / 0.75);
  for (const sd of [-1, 1]) {
    const x = sd * (h * 0.36 * w + h * 0.3 - h * 0.08 * sq); const p = scrOff([c[0], c[1], c[2] + 0.35], x, 0);
    out.cards.push({ p, cell: 'swoosh', size: [h * 1.15, h * 1.15], rot: sd < 0 ? Math.PI / 2 : -Math.PI / 2, flip: 0, color: f.color, alpha: 0.85 * k, add: 0.55, intensity: 1.3 });
    out.cards.push({ p, cell: 'dot', size: [h * 0.7, h * 1.3], color: f.color, alpha: 0.22 * k, add: 1, intensity: 1 });
    for (let i = 0; i < 3; i++) { const y = (i - 1) * h * 0.3; out.cards.push({ p: scrOff(p, -sd * h * (0.2 + 0.1 * sq), y), cell: 'speed', size: [h * 0.32, h * 0.06], rot: 0, color: f.color, alpha: 0.6 * k * sq, add: 1, intensity: 1.1 }); }
  }
  out.distort.push({ p: c, cell: 'shock', size: [h * 1.4, h * 1.4], strength: -0.6 * k * (0.4 + 0.6 * sq), mode: 0 });
  out.lights.push({ p: c, color: f.color, intensity: 2.2 * k, range: 7 });
};
HD.FX_STEP.a2_vise = function (d, f, age) { if (d.frame % 7) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); for (const sd of [-1, 1]) d.emit(PS.hitStreak, scrOff(c, sd * h * 0.4, d.rng.range(-0.3, 0.3) * h), 2, { ramp: 'gold', scale: 0.6 }); };

// ------------------------------------------------------------------ wave 2: Wring Out, the coils twist in beats
// The coils (wave 1's tightening wrap) now wring: every beat they tighten, the target is twisted one way and the other
// (HD acting: a small rotation and squeeze, within the acting limits) and takes a small hit (a reaction pulse).
HD.MOVE_FX.a2_wring = (d, e) => { const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; d.addFx('a2_wring', { b, life: (e.dur || 160) / FPS, beat: e.beat || 30, color: e.color || [1, 0.74, 0.4] }); };
HD.FX.a2_wring = function (d, f, age, out) {
  const u = age / f.life; if (!(u >= 0 && u <= 1)) return; const ph = (age * FPS / f.beat) % 1; if (ph > 0.35) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); const k = 1 - ph / 0.35;
  for (let i = 0; i < 2; i++) out.cards.push({ p: [c[0], c[1] + (i - 0.5) * h * 0.35, c[2] + 0.4], cell: 'swirl', size: [h * (1.2 - 0.3 * (1 - k)), h * 0.5], rot: (i ? 1 : -1) * age * 8, color: f.color, alpha: 0.45 * k, add: 1, intensity: 1.1 });
};
HD.FX_STEP.a2_wring = function (d, f, age) {
  const a = d.act[f.b]; if (!a) return; const fr = age * FPS; const n = Math.floor(fr / f.beat); const ph = (fr % f.beat) / f.beat; const dir = n % 2 ? 1 : -1;
  const e = ph < 0.2 ? HD.easeOut(ph / 0.2) : 1 - HD.smooth((ph - 0.2) / 0.6); a.fxOff[0] += dir * 3.5 * e; a.sx *= 1 - 0.12 * e; a.sy *= 1 + 0.07 * e;
  if (Math.floor((fr - 1) / f.beat) !== n && fr > 2 && age < f.life - 0.3) { const c = nowPos(d, f.b); d.impact({ b: f.b, pos: c, strength: d.strength * 0.45, minGap: 6, burstScale: 0.5, knock: 0.5 }); }
};

// ------------------------------------------------------------------ wave 2: Helping Hand, a high five and a boost
// The GBA's two hands clap three times between the battlers (fixed screen spots) while the ally shakes, then the ally
// flashes yellow. HD: golden energy hands, each clap a high-five burst (rays, glints, a refraction shock); the boosted
// battler (the ally; the user itself in a singles preview) powers up: a golden column, rising glints, a ground glow.
HD.MOVE_FX.a2_highfive = (d, e) => {
  const hs = [...d.inst.values()].filter((x) => x.tpl === (e.tpl || 'gHelpingHandClapSpriteTemplate') && !x.hidden); if (!hs.length) return;
  const p = hs.reduce((acc, x) => V.add(acc, acc, x.p), [0, 0, 0]); V.scale(p, p, 1 / hs.length); p[2] += 0.3; const h = hOf(d, d.atkB()) * (e.k || 1); const col = e.color || [1, 0.82, 0.4];
  d.addFx('card', { p: p.slice(), cell: 'lightray', size0: h * 0.6, size1: h * 1.3, color: col, intensity: 1.2, life: 0.22, add: 1, rot: 0.3 });
  d.addFx('card', { p: p.slice(), cell: 'star4', size0: h * 0.75, size1: h * 0.12, color: col, intensity: 1.6, life: 0.16, add: 1, rot: 0.2 });
  d.addFx('shockd', { p: p.slice(), r0: 0.1 * h, r1: 0.7 * h, life: 0.18, strength: 0.5 });
  d.emit(PS.glint, p, 12, { ramp: e.ramp || 'gold', radius: h * 0.12, speedMul: 1.8 }); d.emit(PS.hitStreak, p, 8, { ramp: e.ramp || 'gold', scale: 0.7 });
  d.addFx('lightpulse', { p: p.slice(), color: col, intensity: 3, range: 8, life: 0.2 });
};
HD.MOVE_FX.a2_powerup = (d, e) => { const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; d.addFx('a2_powerup', { b, life: (e.dur || 40) / FPS, color: e.color || [1, 0.8, 0.35], ramp: e.ramp || 'gold' }); };
HD.FX.a2_powerup = function (d, f, age, out) {
  const u = age / f.life; if (!(u >= 0 && u <= 1)) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); const ft = d.space.feet[f.b]; const k = env01(u, 0.12, 0.35);
  out.cards.push({ p: behind([c[0], c[1] + h * 0.3, c[2]], 0.2), cell: 'lightray', size: [h * 1.0, h * 2.2 * (0.7 + 0.3 * HD.easeOut(Math.min(1, u * 3)))], rot: 0, color: f.color, alpha: 0.38 * k, add: 1, intensity: 1, back: true });
  out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 1.8, h * 1.1], rot: 0, color: f.color, alpha: 0.45 * k, add: 1, intensity: 1, mode: 2 });
  for (let i = 0; i < 3; i++) { const v = (u * 2.2 + i / 3) % 1; out.cards.push({ p: [c[0] + (i - 1) * h * 0.38, c[1] - h * 0.35 + v * h * 1.2, c[2] + 0.35], cell: 'arrow', size: [h * 0.2, h * 0.2], rot: Math.PI / 2, color: f.color, alpha: 0.7 * k * Math.sin(Math.PI * v), add: 0.6, intensity: 1.3 }); }
  out.lights.push({ p: c, color: f.color, intensity: 3 * k, range: 8 });
};
HD.FX_STEP.a2_powerup = function (d, f) { if (d.frame % 2) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); d.emit(PS.glint, [c[0], c[1] - h * 0.3, c[2]], 2, { ramp: f.ramp, radius: h * 0.4, vel: [0, h * 1.6, 0] }); };
const a2GoldHand = { kit: 'gesture', cell: 'hand', v3size: 0.42, scale: 2.2, v3glow: [1, 0.8, 0.38], v3ramp: 'gold' };

// ------------------------------------------------------------------ wave 2: Metronome / Me First, a wagging finger
// The finger is a large golden energy finger; its wag leaves a fan of light whose colour cycles (any move could come),
// each turn ticks with a glint in the next colour; at the end the pick bursts out in a random type colour.
HD.POST_STEP.push(function a2_wag(d) {
  if (!A2_MOVES.has(d.move.id)) return;
  for (const it of d.inst.values()) {
    if (it.kit !== K.gesture || !it.cfg.a2_fan || it.hidden) continue; const s = it.s; const h = hOf(d, d.atkB());
    const tip = scrOff(it.p, -Math.sin(it.rot) * h * 0.24, Math.cos(it.rot) * h * 0.24); s.a2tips = (s.a2tips || []).concat([tip]).slice(-9);
    if (s.a2tips.length > 2) { const n = s.a2tips.length; const hue = (it.age * 0.6) % 1; const col = HD.hsv(hue, 0.55, 1);
      it.cards.push({ layer: 'ribbons', fixed: true, pts: s.a2tips.map((q) => q.slice()), widths: s.a2tips.map((_, i) => h * 0.16 * Math.pow(i / (n - 1), 1.2)), width: h * 0.16, cell: 'trail', color: col, intensity: 1.2, alpha: 0.65, add: 1 }); }
  }
});
HD.MOVE_FX.a2_pick = (d, e) => {
  const b = d.battlerRef(e.b || 'attacker'); const c = nowPos(d, b); const h = hOf(d, b); const p = [c[0], c[1] + h * 0.45, c[2] + 0.3];
  const cols = [[1, 0.45, 0.2], [0.35, 0.65, 1], [1, 0.88, 0.25], [0.45, 0.95, 0.35], [1, 0.45, 0.85], [0.6, 0.45, 1], [0.6, 0.9, 1]]; const col = cols[Math.floor(d.rng() * cols.length)];
  for (let i = 0; i < 8; i++) { const a = i * Math.PI / 4 + 0.2; const q = scrOff(p, Math.cos(a) * h * 0.1, Math.sin(a) * h * 0.1); d.addFx('card', { p: q, cell: 'star4', size0: h * 0.32, size1: h * 0.05, color: HD.hsv(i / 8, 0.6, 1), intensity: 1.5, life: 0.3, add: 1, spin: 3 }); }
  d.addFx('card', { p: p.slice(), cell: 'impact3', size0: h * 0.3, size1: h * 0.95, color: col, intensity: 1.2, life: 0.18, add: 1 });
  d.emit(PS.glint, p, 18, { ramp: 'rainbow', radius: h * 0.2, speedMul: 2 }); d.addFx('shockd', { p: p.slice(), r0: 0.1 * h, r1: 0.9 * h, life: 0.2, strength: 0.5 });
  d.addFx('a_glow', { b, life: 0.5, color: col, amt: 0.55, in: 0.1, out: 0.5, light: 3 });
};
// Me First: the user cuts in ahead of the target (a quick dash forward and back with afterimages and streaks)
HD.MOVE_FX.a2_cutahead = (d, e) => { const A = d.space.gba[d.atkB()], T = d.space.gba[d.tgtB()]; const L = Math.hypot(T[0] - A[0], T[1] - A[1]) || 1; d.addFx('a2_cutahead', { b: d.atkB(), ux: (T[0] - A[0]) / L, uy: (T[1] - A[1]) / L, amt: e.amt || 26, life: (e.dur || 30) / FPS }); };
function a2DashAt(fr, n) { if (fr < 0) return 0; if (fr < 5) return HD.easeOut(fr / 5); if (fr < n - 12) return 1; return Math.max(0, 1 - HD.smooth((fr - (n - 12)) / 12)); }
HD.FX.a2_cutahead = function (d, f, age, out) {
  const fr = age * FPS; const o = a2DashAt(fr, f.life * FPS); if (fr > 6 || o <= 0) return; const c = nowPos(d, f.b); const h = d.space.battlerHeight(f.b); const ang = Math.atan2(-f.uy, f.ux);
  for (let i = 0; i < 4; i++) out.cards.push({ p: scrOff(c, -Math.cos(ang) * h * (0.5 + 0.2 * i), (i - 1.5) * h * 0.22), cell: 'speed', size: [h * 0.8, h * 0.1], rot: ang, color: [1, 0.95, 0.85], alpha: 0.6 * (1 - fr / 6), add: 1, intensity: 1.1 });
};
HD.FX_STEP.a2_cutahead = function (d, f, age) {
  const a = d.act[f.b]; if (!a) return; const n = f.life * FPS; const fr = age * FPS; const o = a2DashAt(fr, n) * f.amt; a.fxOff[0] += o * f.ux; a.fxOff[1] += o * f.uy;
  a.v3ghosts = fr < 7 ? [1, 2, 3].map((k) => { const ok = a2DashAt(fr - k * 0.8, n) * f.amt; return [ok * f.ux, ok * f.uy, 0.34 - k * 0.09]; }) : null;
  if (Math.abs(fr - 1) < 0.5) { const ft = d.space.feet[f.b]; d.emit(PS.dustPuff, [ft[0], 0.15, ft[2]], 6, { dir: [-f.ux, 0.3, 0], spread: 0.8, scale: 1 }); }
};
// the stolen move: a prismatic energy copy pulled out of the target into the user (the GBA's mimic orb)
K.a2_steal = {
  update(d, it) {
    const h = hOf(d, d.tgtB()); const p = it.p.slice(); const L = it.cards; const hue = (it.age * 0.8) % 1; const col = HD.hsv(hue, 0.5, 1); const sz = h * 0.32;
    if (it.hist.length > 1) { const pts = it.hist.slice(-8).concat([p]); L.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 0.8 * Math.pow(i / (pts.length - 1), 1.2)), width: sz * 0.8, cell: 'energy', color: col, intensity: 1.2, alpha: 0.7, add: 1, scroll: it.age * 3 }); }
    L.push({ fixed: true, p, cell: 'flare', size: [sz * 2.0, sz * 2.0], color: col, alpha: 0.5, add: 1, intensity: 1 });
    L.push({ fixed: true, p, cell: 'star4', size: [sz * 1.3, sz * 1.3], rot: it.age * 4, color: HD.hsv((hue + 0.33) % 1, 0.45, 1), alpha: 0.9, add: 1, intensity: 1.4 });
    L.push({ fixed: true, p, cell: 'core', size: [sz * 0.6, sz * 0.6], color: col, alpha: 0.9, add: 1, intensity: 1.1 });
    const n = every(it, 'g', 24); if (n) d.emit(PS.glint, p, n, { ramp: 'rainbow', radius: sz * 0.4 }); d.light(p, col, 1.5, 6, 'a2_steal');
  }
};

// ================================================================== wave 2 configuration: the D moves
HD.moveFxClear('MOVE_HAMMER_ARM', (e) => e.kind === 'a_press');
HD.moveFxClear('MOVE_CRUSH_GRIP', (e) => e.kind === 'a_press');
HD.moveFxClear('MOVE_WRING_OUT', (e) => e.kind === 'a_press' || e.kind === 'wrap');
HD.moveFxClear('MOVE_HELPING_HAND', (e) => e.kind === 'a_clap' || e.kind === 'motes');
HD.moveFxClear('MOVE_METRONOME', (e) => e.kind === 'a_roulette');
HD.moveFxClear('MOVE_ME_FIRST', (e) => e.kind === 'lines');
const A2_FINGER = { kit: 'gesture', cell: 'finger', v3size: 0.56, scale: 5, v3glow: [1, 0.84, 0.45], v3ramp: 'gold', a_tick: true, a2_fan: true };
HD.moveAdd({
  MOVE_HAMMER_ARM: { tpl: { gIceHammerPunchStompTemplate: FIST({ a2_hammer: true, a_heavy: 1.35, a_el: 'fight', v3size: 0.66 }) },
    fx: [{ at: 1, kind: 'a_glow', b: 'attacker', dur: 22, color: [1, 0.55, 0.25], amt: 0.4, pulse: 14, in: 0.4, out: 0.2 }, { on: 'AnimTask_SquishTarget', nth: 1, kind: 'a_press', style: 'dust', dur: 60 }] },
  MOVE_GUILLOTINE: { tpl: { gGuillotineSpriteTemplate: { kit: 'a2_jaw', v3size: 0.8 }, gBasicHitSplatSpriteTemplate: { kit: 'impact', cell: 'impact3', color: [0.78, 0.6, 1], scale: 0.75, intensity: 1.15, life: 0.2 } }, theme: 'dark', themeMax: 0.5, pal: { dark: 0.4, copy: true },
    fx: [{ on: 'AnimTask_ShakeMon2', nth: 1, kind: 'a2_cut', k: 1 }, { on: 'AnimTask_ShakeMon2', nth: 2, kind: 'a2_cut', k: 1.5 }] },
  MOVE_CRUSH_GRIP: { tpl: { gCrushGripHandTemplate: { kit: 'a2_grasp', color: [1, 0.74, 0.38] }, gCrushGripExplosionTemplate: { kit: 'impact', cell: 'impact3', scale: 0.75, color: [1, 0.78, 0.45], intensity: 1.15, strength: 1.0, life: 0.2 } },
    fx: [{ on: 'AnimTask_CompressTargetHorizontally', nth: 1, kind: 'a2_vise', dur: 92 }] },
  MOVE_WRING_OUT: { fx: [{ on: 'gWringOutHandSpriteTemplate', nth: 1, kind: 'wrap', b: 'target', dur: 170, color: [1, 0.6, 0.26], n: 3, cell: 'trail', add: 0.6, intensity: 1.2, width: 1.35 },
    { on: 'gWringOutHandSpriteTemplate', nth: 1, kind: 'a2_wring', dur: 160, beat: 30 }] },
  MOVE_HELPING_HAND: { tpl: { gHelpingHandClapSpriteTemplate: a2GoldHand },
    fx: [{ on: 'AnimTask_ShakeMon2', nth: 1, kind: 'a2_highfive' }, { on: 'AnimTask_ShakeMon2', nth: 2, kind: 'a2_highfive' }, { on: 'AnimTask_ShakeMon2', nth: 3, kind: 'a2_highfive', k: 1.3 },
      { on: 'AnimTask_BlendMonInAndOut', nth: 1, kind: 'a2_powerup', b: 'target', dur: 46 }] },
  MOVE_METRONOME: { tag: { ANIM_TAG_FINGER: A2_FINGER }, fx: [{ at: 86, kind: 'a_roulette', dur: 29 }, { at: 115, kind: 'a2_pick' }] },
  MOVE_ME_FIRST: { tag: { ANIM_TAG_FINGER: A2_FINGER }, tpl: { gMimicOrbSpriteTemplate: { kit: 'a2_steal' } },
    fx: [{ at: 2, kind: 'a2_cutahead', dur: 34, amt: 26 }, { on: 'AnimTask_BlendColorCycle', nth: 1, kind: 'a_glow', b: 'attacker', dur: 40, color: [0.5, 0.72, 1], amt: 0.4, light: 3 },
      { on: 'AnimTask_BlendColorCycle', nth: 1, kind: 'motes', b: 'attacker', dur: 30, preset: 'glint', rate: 30, ramp: 'rainbow' }] }
});

// ------------------------------------------------------------------ wave 2: strikes that wait for the user
// a2_late: N frames before contact the limb comes in along its strike path (eased in, smear, afterimages); before that
