  dark: { ramp: 'b_darkfang', glow: [0.55, 0.3, 0.9], ink: [0.03, 0.01, 0.05], smoke: true },
  fire: { ramp: 'ivory', glow: [1, 0.45, 0.12], ink: [0.2, 0.05, 0.02], fire: true },
  ice: { ramp: 'glacier', glow: [0.55, 0.88, 1], ink: [0.04, 0.1, 0.2], ice: true },
