  L.push({ p, cell: 'satchel', size: [sz * 1.14, sz * 1.14], rot, color: glow, alpha: 0.42 * alpha, add: 1, intensity: 1 });
  L.push({ p, cell: 'satchel', size: [sz * 1.06, sz * 1.06], rot, color: [0.1, 0.05, 0.03], alpha: 0.6 * alpha, add: 0, hot: 0, intensity: 1 });
