    const t = o / FPS; const vx = f.dir * hf * (f.kv || 1.5), vy = hf * (f.kvy || 1.3), g = hf * 18; let y = a[1] + vy * t - 0.5 * g * t * t; let x = a[0] + vx * t; const ground = 0.15 + hf * 0.08;   // v3.2 (lead): kv / kvy per use
