  const u = clamp((o - rise) / Math.max(1, D - rise), 0, 1); const q = V.lerp([0, 0, 0], [a[0], a[1] + hf * 0.35, a[2] + 0.3], b, smooth(u)); q[1] += Math.sin(Math.PI * u) * hf * 0.25;
