  if (o === 0) { const a = drawnAt(d, f.from); d.emit(PS.glint, a, 10, { ramp: f.ramp, radius: hOf(d, f.from) * 0.3, speedMul: 1.4 }); }
  if (f.mode !== 'knock' && o === D) {   // caught: glints and a ring at the receiver, a little hop
    const c = drawnAt(d, f.to); const h = hOf(d, f.to); d.emit(PS.glint, c, 14, { ramp: f.ramp, radius: h * 0.35, speedMul: 1.5 });
    d.addFx('ring', { p: c.slice(), cell: 'ring', r0: h * 0.15, r1: h * 0.75, width: 0.06, color: f.glow, intensity: 1.1, life: 0.3, add: 1 });
    HD.MOVE_FX.b_move(d, { b: f.to === d.atkB() ? 'attacker' : 'target', rel: true, keys: [[0, 0, 0], [4, 0, 7, 2], [9, 0, 0, 1], [12, 0, 2], [15, 0, 0]] });
  }
