  const ft = d.space.feet[f.b]; const h = hOf(d, f.b); out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'puddle', size: [h * 1.9 * k, h * 1.9 * k], rot: 0.3, color: f.pool, alpha: 0.85 * k, add: 0, intensity: 1, mode: 2 });
