HD.MOVE_FX.b_whirl = (d, e) => { const b = bRef(d, e.b || 'attacker'); if (!present(d, b)) return; d.addFx('b_whirl', { b, to: bRef(d, e.to || 'target'), f0: d.frame, f1: e.f1, go: e.go, hit: e.hit, back: e.back, color: e.color || [1, 1, 1], life: (e.f1 - d.frame + 2) / FPS }); };
function whirlPos(d, f, fr) {
  const A = d.bpos(f.b), T = d.bpos(f.to); const h = hOf(d, f.b); const k = fr < f.go ? 0 : fr < f.hit ? easeIn((fr - f.go) / (f.hit - f.go)) : fr < f.hit + 3 ? 1 : 1 - smooth((fr - f.hit - 3) / Math.max(1, f.back - f.hit - 3));
  const p = V.lerp([0, 0, 0], A, V.lerp([0, 0, 0], A, T, 0.78), k); p[1] += Math.sin(Math.PI * k) * h * 0.25; return { p, k };
}
HD.FX.b_whirl = function (d, f, age, out) {
  const fr = frameAt(f, age); if (fr < f.f0 || fr > f.f1) return; const { p, k } = whirlPos(d, f, fr); const h = hOf(d, f.b) * (1 - 0.25 * k);
  const env = Math.min(1, (fr - f.f0) / 6, (f.f1 - fr) / 8); const cam = HD.GBA_CAM.pos; const front = (q) => (q[0] - p[0]) * (cam[0] - p[0]) + (q[2] - p[2]) * (cam[2] - p[2]) > 0;
  out.cards.push({ p, cell: 'dot', size: [h * 1.5, h * 1.6], color: [0.8, 0.88, 1], alpha: 0.3 * env, add: 1, intensity: 1 });
  out.cards.push({ p, cell: 'swirl', size: [h * 1.15, h * 1.15], rot: -age * 22, color: f.color, alpha: 0.55 * env, add: 1, intensity: 1.1 });
  for (let r = 0; r < 4; r++) {
    const y = p[1] - h * 0.42 + r * h * 0.28; const R = h * (0.5 - 0.06 * Math.abs(r - 1.5)); const pts = [];
    for (let i = 0; i <= 32; i++) { const a = (i / 32) * TAU + age * 24 + r * 0.9; pts.push([p[0] + Math.cos(a) * R, y + Math.sin(a) * h * 0.14 * (r % 2 ? 1 : -1), p[2] + Math.sin(a) * R * 0.6]); }
    for (const run of HD.splitRuns(pts, front, true)) if (run.pts.length > 1) out.ribbons.push({ pts: run.pts, width: h * 0.06, cell: 'trail', color: f.color, intensity: 1.1, alpha: (run.f ? 0.85 : 0.4) * env, add: 1, back: !run.f });
  }
  if (k > 0.05 && k < 0.98) { const B = d.bpos(f.to); const dir = toScr(V.sub([0, 0, 0], B, d.bpos(f.b))); const ang = Math.atan2(dir[1], dir[0]); for (let i = 0; i < 3; i++) out.cards.push({ p: scrOff(p, -Math.cos(ang) * h * (0.6 + i * 0.25), -Math.sin(ang) * h * (0.6 + i * 0.25) + (i - 1) * h * 0.2), cell: 'speed', size: [h * 0.8, h * 0.1], rot: ang, color: [1, 1, 1], alpha: 0.5 * env, add: 1, intensity: 1 }); }
  out.lights.push({ p, color: [0.85, 0.9, 1], intensity: 1.5 * env, range: 6 });
};
HD.FX_STEP.b_whirl = function (d, f) { const { p } = whirlPos(d, f, d.frame); if (d.frame % 3 === 0) { d.emit(PS.dustPuff, [p[0], 0.15, p[2]], 1, { dir: [0, 0.3, 0], scale: 0.9 }); d.emit(PS.windStreak, p, 2, { scale: 0.8 }); } if (d.frame === f.hit) d.emit(PS.hitStreak, d.bpos(f.to), 12, { ramp: 'white' }); };

