HD.MOVE_FX.b_geyser = (d, e) => { const b = bRef(d, e.b || 'target'); if (present(d, b)) d.addFx('b_geyser', { b, life: (e.dur || 30) / FPS, height: e.height || 1.7, width: e.width || 0.6 }); };
HD.FX.b_geyser = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const ft = d.space.feet[f.b]; const h = hOf(d, f.b); const rise = u < 0.35 ? easeOut(u / 0.35) : u < 0.65 ? 1 : 1 - easeIn((u - 0.65) / 0.35);
  const H = h * f.height * rise; const W = h * f.width * (1 - 0.3 * u); const k = Math.min(1, u * 10, (1 - u) * 5); const x = ft[0], z = ft[2] + 0.35;
  for (let s = -1; s <= 1; s++) { const pts = [], ws = []; for (let i = 0; i <= 10; i++) { const t = i / 10; pts.push([x + s * W * 0.22 + Math.sin(t * 7 + age * 20 + s) * W * 0.05, 0.05 + t * H, z]); ws.push(W * (0.75 - 0.25 * t) * (s ? 0.6 : 1)); }
    out.ribbons.push({ pts, widths: ws, width: W, cell: 'water', color: [0.32, 0.6, 1], intensity: 1.05, add: 0.15, alpha: 0.85 * k, scroll: -age * 8, uvRepeat: 2 }); }
  out.ribbons.push({ pts: [[x, 0.05, z + 0.05], [x, H * 0.5, z + 0.05], [x, H, z + 0.05]], width: W * 0.35, cell: 'trail', color: [0.9, 0.97, 1], intensity: 1, add: 0.5, alpha: 0.7 * k, scroll: -age * 10 });
  out.cards.push({ p: [x, H, z + 0.1], cell: 'spray', size: [W * 2.2, W * 1.4], rot: age * 3, color: [0.85, 0.95, 1], alpha: 0.75 * k, add: 0.35, intensity: 1.1 });
  out.decals.push({ p: [x, 0.03, ft[2]], cell: 'ripple', size: [h * 2.2, h * 2.2], rot: age * 2, color: [0.45, 0.7, 1], alpha: 0.6 * k, add: 0.5, intensity: 1, mode: 2 });
  out.lights.push({ p: [x, H * 0.6, z + 0.6], color: [0.45, 0.7, 1], intensity: 2.2 * k, range: 8 });
};
HD.FX_STEP.b_geyser = function (d, f, age) { const u = age / f.life; const ft = d.space.feet[f.b]; const h = hOf(d, f.b); const rise = u < 0.35 ? easeOut(u / 0.35) : u < 0.65 ? 1 : 1 - easeIn((u - 0.65) / 0.35);
  d.emit(PS.droplet, [ft[0], h * f.height * rise, ft[2] + 0.35], 3, { scale: 1.1, speedMul: 1.2 }); if (d.frame % 3 === 0) d.emit(PS.mist, [ft[0], 0.3, ft[2] + 0.3], 1, { scale: 1.3 }); };

// ---- Volt Tackle: the user, wrapped in an electric ball, streaks across the field (the GBA draws its path as rows of
// bolt segments: HD draws a horizontal electric trail with the ball at its head) and crashes into the target
K.b_voltball = {
  update(d, it, cfg) {
    const h = hOf(d, d.atkB()); const s = h * (cfg.v3size || 1.05); const a = it.alpha; const L = it.cards; const p = it.p.slice();
    L.push({ fixed: true, p, cell: 'dot', size: [s * 1.6, s * 1.6], color: [1, 0.85, 0.3], alpha: 0.35 * a, add: 1, intensity: 1 });
    L.push({ fixed: true, p, cell: 'ring', size: [s, s], rot: it.age * 3, color: [1, 0.92, 0.45], alpha: 0.55 * a, add: 1, intensity: 1.1 });
    L.push({ fixed: true, p, cell: 'orb', size: [s * 0.95, s * 0.95], color: [1, 0.85, 0.35], alpha: 0.22 * a, add: 1, intensity: 1 });
    if (Math.floor(it.age * FPS) % 2 === 0 || !it.s.arcs) { const o = { ribbons: [], cards: [] }; for (let k = 0; k < 3; k++) { const dir = d.rng.unit(); dir[2] *= 0.3; HD.boltRibbons(V.madd([0, 0, 0], p, dir, s * 0.15), V.madd([0, 0, 0], p, dir, s * 0.55), Math.floor(d.rng() * 1e9), s * 0.02, [1, 0.92, 0.45], 2.2 * a, 0, o, 0.35); } it.s.arcs = o.ribbons; }
    for (const r of it.s.arcs) L.push(Object.assign({ layer: 'ribbons', fixed: true }, r));
    const n = every(it, 'sp', 26); if (n) d.emit(PS.spark, p, n, { scale: 0.8, radius: s * 0.4 });
    d.light(p, [1, 0.9, 0.45], 3 * a, 9, 'volt');
  }
};
K.b_voltstreak = {
  init(d, it) { const w = d.v3.bVolt || (d.v3.bVolt = {}); const key = Math.round(it.rec.y / 6); const g = w[key] || (w[key] = { head: null, f: -1 }); if (d.frame >= g.f) { g.f = d.frame; g.head = it.uid; } it.s.g = g; },
  update(d, it) {
    const k = d.kpxAt(it.p); const a = it.alpha * Math.max(0, 1 - it.age / 0.2); const L = it.cards; const half = 9 * k; const h = hOf(d, d.atkB());
    const p0 = [it.p[0] - half, it.p[1], it.p[2]], p1 = [it.p[0] + half, it.p[1], it.p[2]];
    if (a > 0.02) {
      L.push({ layer: 'ribbons', fixed: true, pts: [p0, it.p.slice(), p1], width: h * 0.5, cell: 'boltglow', color: [1, 0.85, 0.3], intensity: 0.5 * a, add: 1 });
      L.push({ layer: 'ribbons', fixed: true, pts: [p0, it.p.slice(), p1], width: h * 0.16, cell: 'beam', color: [1, 0.95, 0.6], intensity: 1.1 * a, add: 1 });
      if ((it.uid + Math.floor(it.age * FPS)) % 2 === 0) { const o = { ribbons: [], cards: [] }; HD.boltRibbons([p0[0], p0[1] + d.rng.range(-0.3, 0.3) * h, p0[2]], [p1[0], p1[1] + d.rng.range(-0.3, 0.3) * h, p1[2]], Math.floor(d.rng() * 1e9), 0.03, [1, 0.92, 0.5], 2 * a, 0, o, 0.5); for (const r of o.ribbons) L.push(Object.assign({ layer: 'ribbons', fixed: true }, r)); }
    }
    if (it.s.g.head === it.uid && it.age < 0.06) {   // the newest segment of the row: the electric ball (the user) at the head of its streak
      const s = h * 0.95; L.push({ fixed: true, p: it.p.slice(), cell: 'dot', size: [s * 1.5, s * 1.5], color: [1, 0.85, 0.3], alpha: 0.5, add: 1, intensity: 1.1 }, { fixed: true, p: it.p.slice(), cell: 'core', size: [s * 0.7, s * 0.7], color: [1, 1, 0.85], alpha: 0.9, add: 1, intensity: 1.3 }, { fixed: true, p: it.p.slice(), cell: 'ring', size: [s * 0.9, s * 0.9], rot: it.age * 20, color: [1, 0.9, 0.4], alpha: 0.7, add: 1, intensity: 1.1 });
      d.emit(PS.spark, it.p, 4, { scale: 0.9 }); d.light(it.p, [1, 0.9, 0.45], 4, 10, 'volt');
    }
  }
};
HD.moveAdd({ MOVE_VOLT_TACKLE: { tpl: { gVoltTackleOrbSlideSpriteTemplate: { kit: 'b_voltball', v3size: 1.05 }, gVoltTackleBoltSpriteTemplate: { kit: 'b_voltstreak' } }, fx: [
  on('AnimTask_ShakeMon2', 'b_slam', { nth: 1, b: 'target', strength: 1.2, crack: false, ringColor: [1, 0.9, 0.4], burstScale: 0.6 })
] } });

// ---- Gyro Ball: two steel gyroscope rings spin around the user (faster and faster, throwing sparks) while the GBA gives
