  on('gBasicHitSplatSpriteTemplate', 'b_move', { b: 'attacker', rel: true, rush: true, frac: true, keys: [[-6, 0, 0], [0, 0.34, 0, 1], [10, 0.34, 0], [26, 0, 0]] }),
  on('gBasicHitSplatSpriteTemplate', 'b_grind', { b: 'target', dur: 12 })
