HD.MOVE_FX.b_gyro = (d, e) => { const b = bRef(d, e.b || 'attacker'); if (present(d, b)) d.addFx('b_gyro', { b, f0: d.frame, f1: e.f1, color: e.color, life: (e.f1 - d.frame + 2) / FPS }); };
HD.FX.b_gyro = function (d, f, age, out) {
  const fr = frameAt(f, age); if (fr > f.f1) return; const c = drawnAt(d, f.b); const h = hOf(d, f.b); const env = Math.min(1, (fr - f.f0) / 10, (f.f1 - fr) / 8); const sp = 4 + 18 * smooth((fr - f.f0) / 120);
  const ang = f.spin = (f.spin || 0); const t = age * sp; const cam = HD.GBA_CAM.pos; const front = (q) => (q[0] - c[0]) * (cam[0] - c[0]) + (q[2] - c[2]) * (cam[2] - c[2]) > 0; void ang;
  for (let r = 0; r < 2; r++) {
    const tilt = r ? 1.1 : -0.5; const R = h * (0.62 + r * 0.08); const pts = [];
    for (let i = 0; i <= 40; i++) { const a = (i / 40) * TAU + t * (r ? 1 : -1.3); const x = Math.cos(a) * R, y = Math.sin(a) * R * 0.3; pts.push([c[0] + x * Math.cos(tilt) - y * Math.sin(tilt) * 0.5, c[1] + x * Math.sin(tilt) * 0.35 + y, c[2] + Math.sin(a) * R * 0.75]); }
    for (const run of HD.splitRuns(pts, front, true)) { if (run.pts.length < 2) continue; out.ribbons.push({ pts: run.pts, width: h * 0.075, cell: 'beam', color: f.color, intensity: 1.05, alpha: (run.f ? 0.9 : 0.45) * env, add: 0.8, back: !run.f }); out.ribbons.push({ pts: run.pts, width: h * 0.2, cell: 'boltglow', color: [0.55, 0.7, 1], intensity: 0.4, alpha: (run.f ? 0.7 : 0.3) * env, add: 1, back: !run.f }); }
  }
  out.lights.push({ p: [c[0], c[1], c[2] + 1], color: [0.75, 0.85, 1], intensity: 2 * env, range: 7 });
};
HD.FX_STEP.b_gyro = function (d, f) { const fr = d.frame; if (fr > f.f1) return; const c = drawnAt(d, f.b); const h = hOf(d, f.b); const sp = smooth((fr - f.f0) / 120); if (d.frame % Math.max(1, Math.round(6 - 4 * sp)) === 0) { const a = d.rng() * TAU; d.emit(PS.steelSpark, [c[0] + Math.cos(a) * h * 0.65, c[1] + d.rng.range(-0.3, 0.3) * h, c[2] + Math.sin(a) * h * 0.5], 2, { dir: [-Math.sin(a), 0.2, Math.cos(a)], spread: 0.3, scale: 0.9 }); }
  const a = d.act[f.b]; if (a) { const g = 0.35 * Math.min(1, (fr - f.f0) / 10); if (g > a.glow[3]) a.glow = [0.7, 0.8, 1, g]; } };
HD.MOVE_FX.b_grind = (d, e) => { const b = bRef(d, e.b || 'target'); if (present(d, b)) d.addFx('b_grind', { b, life: (e.dur || 12) / FPS }); };
