HD.moveAdd({ MOVE_NATURAL_GIFT: { tpl: { gDragonDanceOrbSpriteTemplate: { kit: 'orb', color: [0.7, 1, 0.45], scale: 0.55, trail: 12, lightI: 1 } }, fx: [
  at(3, 'b_berry', { b: 'attacker', f1: 80 }),
  at(78, 'b_glow', { b: 'attacker', dur: 82, color: [0.6, 1, 0.4], amt: 0.7, rate: 9, ramp: 'nature', motes: 2 }),
  at(112, 'b_shot', { from: 'attacker', to: 'target', dur: 14, color: [0.7, 1, 0.4], ramp: 'nature' })
] } });
HD.MOVE_FX.b_berry = (d, e) => { const b = bRef(d, e.b || 'attacker'); if (present(d, b)) d.addFx('b_berry', { b, f0: d.frame, f1: e.f1, life: (e.f1 - d.frame + 2) / FPS }); };
HD.FX.b_berry = function (d, f, age, out) {
  const fr = frameAt(f, age); const o = fr - f.f0, D = f.f1 - f.f0; if (o < 0 || o > D) return; const c = drawnAt(d, f.b); const h = hOf(d, f.b);
  const sink = clamp((o - (D - 18)) / 18, 0, 1); const up = smooth(o / 14); const y = c[1] + h * (0.15 + 0.6 * up * (1 - easeIn(sink))) + Math.sin(age * 4) * h * 0.04 * (1 - sink);
  const sz = h * 0.44 * (0.4 + 0.6 * up) * (1 - 0.7 * sink); const p = [c[0], y, c[2] + 0.4]; const a = Math.min(1, o / 6);
  out.cards.push({ p, cell: 'dot', size: [sz * 2.4, sz * 2.4], color: [1, 0.55, 0.65], alpha: 0.35 * a, add: 1, intensity: 1 });
  out.cards.push({ p, cell: 'berry3', size: [sz * 1.08, sz * 1.08], rot: Math.sin(age * 3) * 0.2, color: [0.08, 0.02, 0.03], alpha: 0.55 * a, add: 0, intensity: 1 });
  out.cards.push({ p, cell: 'berry3', size: [sz, sz], rot: Math.sin(age * 3) * 0.2, color: [1, 1, 1], gmap: 'berry', alpha: a, add: 0, intensity: 1 });
  out.lights.push({ p, color: [1, 0.6, 0.7], intensity: 1.5 * a, range: 6 });
};
