HD.FX.b_homing = function (d, f, age, out) {
  const fr = frameAt(f, age); const A = drawnAt(d, d.atkB()), T = d.bpos(d.tgtB()); const ha = hOf(d, d.atkB()), ht = hOf(d, d.tgtB());
  for (let i = 0; i < f.n; i++) {
    const o = fr - f.f0 - i * f.gap * 0.5; if (o < 0) continue; const u = clamp(o / f.dur, 0, 1); const arrive = f.dur + i * f.gap * 0.5; if (fr - f.f0 > arrive + 4) continue;
    const a0 = i * TAU / f.n; const s0 = [A[0] + Math.cos(a0) * ha * 0.6, A[1] + Math.sin(a0) * ha * 0.3, A[2]]; const end = scrOff(T, Math.cos(a0 + 1) * ht * 0.25, Math.sin(a0 + 1) * ht * 0.25);
    const p = V.lerp([0, 0, 0], s0, end, easeIn(u)); p[1] += Math.sin(Math.PI * u) * ht * 0.35; const sz = ht * 0.26;
    out.cards.push({ p, cell: 'ring', size: [sz * 1.8, sz * 1.8], rot: age * 6, color: [0.4, 0.65, 1], alpha: 0.6, add: 1, intensity: 1.2 }, { p, cell: 'b_bomb', size: [sz * 1.08, sz * 1.08], rot: age * 8 + i, color: [0.03, 0.04, 0.08], alpha: 0.6, add: 0, intensity: 1 }, { p, cell: 'b_bomb', size: [sz, sz], rot: age * 8 + i, color: [1, 1, 1], gmap: 'metal', alpha: 1, add: 0, intensity: 1 });
    if (u < 1) { const q = V.lerp([0, 0, 0], s0, end, easeIn(Math.max(0, u - 0.25))); q[1] += Math.sin(Math.PI * Math.max(0, u - 0.25)) * ht * 0.35; out.ribbons.push({ pts: [q, V.lerp([0, 0, 0], q, p, 0.5), p], widths: [0, sz * 0.25, sz * 0.5], width: sz * 0.5, cell: 'trail', color: [0.5, 0.7, 1], intensity: 1.1, alpha: 0.6, add: 1 }); }
  }
};

