HD.MOVE_FX.b_swarm = (d, e) => { const b = bRef(d, e.b || 'target'); if (present(d, b)) d.addFx('b_swarm', { b, n: e.n || 14, life: (e.dur || 120) / FPS }); };
HD.FX.b_swarm = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = drawnAt(d, f.b); const h = hOf(d, f.b); const k = Math.min(1, u * 8, (1 - u) * 6); const cam = HD.GBA_CAM.pos; const r = HD.rng(f.seed);
  for (let i = 0; i < f.n; i++) {
    const sp = r.range(2.2, 4) * r.sign(); const R = h * r.range(0.45, 0.75); const y0 = r.range(-0.45, 0.4) * h; const ph = r() * TAU; const a = age * sp + ph;
    const p = [c[0] + Math.cos(a) * R, c[1] + y0 + Math.sin(age * 5 + ph) * h * 0.08, c[2] + Math.sin(a) * R * 0.6]; const back = (p[2] - c[2]) * (cam[2] - c[2]) < 0;
    const sz = h * r.range(0.2, 0.28); const rot = (sp > 0 ? a + Math.PI : a); const fl = 0.75 + 0.25 * Math.sin(age * 70 + i);
    out.cards.push({ p, back, cell: 'bug3', size: [sz * fl, sz], rot, color: [1, 1, 1], gmap: 'b_beetle', alpha: k, add: 0, intensity: 1 });
  }
};
HD.FX_STEP.b_swarm = function (d, f) { const a = d.act[f.b]; if (a) a.glow = [0.45, 0.6, 0.15, Math.min(a.glow[3], 0.3)]; if (d.frame % 4 === 0) d.emit(PS.b_bug, d.bpos(f.b), 1, { radius: hOf(d, f.b) * 0.5 }); };

// ================================================================== C families: cuts on the script's hits, claw sprites, elemental cloaks
// a cut (claw / blade / tail arc) that finishes exactly on each of the script's hits on the target (scheduled at the
// start; future-dated effects wait for their time). th: one angle or a list cycled per hit; frames: explicit list.
HD.MOVE_FX.b_hitarcs = (d, e) => {
  const b = bRef(d, e.b || 'target'); if (!present(d, b) || !d.plan) return; const hits = e.frames || d.plan.hits.filter((x) => x.f >= (e.from || 1) && x.f <= (e.to || 9999)).map((x) => x.f);
  const ths = Array.isArray(e.th) ? e.th : [e.th != null ? e.th : -2.3]; const sweep = e.sweep || 0.08; const lead = Math.round(sweep * FPS);
  hits.forEach((hf, i) => { const fx = bArcs(d, b, Object.assign({}, e, { th: ths[i % ths.length], hit: false, sweep })); fx.t0 = (hf - lead) / FPS; fx.c = d.bpos(b); });
};
// GBA slash / claw sprites (moves without scripted hits): one arc set per birth frame, along the sprite's own motion
K.b_claw = {
  init(d, it, cfg) {
    const f0 = d.frame; d.v3.bClaw = d.v3.bClaw || []; if (cfg.pair && d.v3.bClaw.some((x) => Math.abs(x - f0) <= 1)) return; d.v3.bClaw.push(f0);
    const ti = trackInfo(d, it.uid); let th = cfg.th != null ? cfg.th : -2.3, cx = it.rec.x, cy = it.rec.y;
    if (ti && ti.travel > 10 && cfg.th == null) { th = Math.atan2(-(ti.y1 - ti.y0), ti.x1 - ti.x0); cx = (ti.x0 + ti.x1) / 2; cy = (ti.y0 + ti.y1) / 2; }
    if (cfg.alt && (d.v3.bClaw.length % 2 === 0)) th = Math.PI - th;
    const b = d.tgtB(); const tg = d.space.gba[b]; if (cfg.onTarget) { cx = tg[0]; cy = tg[1]; }
    const hitNear = d.plan && d.plan.hits.some((x) => x.f >= f0 - 1 && x.f <= f0 + 8);
    bArcs(d, b, Object.assign({}, cfg, { pos: d.space.liftAuto(cx, cy), th, hit: !hitNear && cfg.hit !== false }));
  },
  update() {}
};
// the user wrapped in its element from the wind-up to contact (the v3 rush carries it in): fire wheel, electric arcs,
// a water sheet, dark smoke, a white-gold force aura; it trails behind the user while it moves
HD.MOVE_FX.b_cloak = (d, e) => {
  const b = bRef(d, e.b || 'attacker'); if (!present(d, b)) return; let C = e.until;
  if (C == null) { const h = d.plan && d.plan.hits.find((x) => x.f >= 2); C = h ? h.f : d.frame + (e.dur || 40); }
  const f0 = e.from != null ? e.from : Math.max(d.frame, C - (e.lead || 30)); const f1 = C + (e.after || 5);
  const fx = d.addFx('b_cloak', { b, f0, f1, el: e.el || 'force', size: e.size || 1, life: (f1 - d.frame + 2) / FPS, hist: [] }); fx.t0 = d.t;
};
const CLOAK = { fire: { glow: [1, 0.45, 0.12], ramp: 'fire' }, blue: { glow: [0.4, 0.6, 1], ramp: 'bluefire' }, electric: { glow: [1, 0.88, 0.3], ramp: 'electric' }, water: { glow: [0.35, 0.65, 1], ramp: 'water' }, dark: { glow: [0.5, 0.28, 0.8], ramp: 'dark' }, force: { glow: [1, 0.85, 0.55], ramp: 'gold' }, steel: { glow: [0.75, 0.85, 1], ramp: 'steel' }, psychic: { glow: [1, 0.4, 0.8], ramp: 'psychic' }, ghost: { glow: [0.55, 0.32, 0.95], ramp: 'ghost' }, grass: { glow: [0.45, 0.95, 0.35], ramp: 'nature' } };
HD.FX.b_cloak = function (d, f, age, out) {
  const fr = frameAt(f, age); if (fr < f.f0 || fr > f.f1) return; const c = drawnAt(d, f.b); const h = hOf(d, f.b) * f.size; const st = CLOAK[f.el] || CLOAK.force;
  const env = Math.min(1, (fr - f.f0) / 6, (f.f1 - fr) / 4); const L = out.cards;
  L.push({ p: [c[0], c[1], c[2] - 0.05], back: true, cell: 'dot', size: [h * 1.9, h * 2.1], color: st.glow, alpha: 0.4 * env, add: 1, intensity: 1 });
  if (f.el === 'fire' || f.el === 'blue') {   // a turning wheel of gradient-mapped flames around the body
    for (let i = 0; i < 8; i++) { const a = age * 9 + i * TAU / 8; const p = [c[0] + Math.cos(a) * h * 0.55, c[1] + Math.sin(a) * h * 0.55, c[2] + 0.2]; L.push({ p, cell: 'flame' + ((i + Math.floor(fr / 3)) % 4), size: [h * 0.45, h * 0.6], rot: a + Math.PI, color: [1, 1, 1], gmap: st.ramp, alpha: 0.9 * env, add: 0.45, intensity: 1.15 }); }
    L.push({ p: [c[0], c[1], c[2] + 0.25], cell: 'ring', size: [h * 1.25, h * 1.25], rot: age * 6, color: st.glow, alpha: 0.6 * env, add: 1, intensity: 1.1 });
  } else if (f.el === 'electric') {
    const o = { ribbons: [], cards: [] }; const sd = f.seed + Math.floor(fr / 2) * 7919; const r = HD.rng(sd);
    for (let k = 0; k < 4; k++) { const a = r() * TAU; const a2 = a + r.range(0.8, 1.6); HD.boltRibbons([c[0] + Math.cos(a) * h * 0.5, c[1] + Math.sin(a) * h * 0.55, c[2] + 0.3], [c[0] + Math.cos(a2) * h * 0.6, c[1] + Math.sin(a2) * h * 0.6, c[2] + 0.3], sd + k * 31, 0.045, [1, 0.92, 0.45], 2.4 * env, 0, o, 0.35); }
    for (const rb of o.ribbons) out.ribbons.push(rb);
  } else if (f.el === 'water') {
    const pts = []; for (let i = 0; i <= 30; i++) { const t = i / 30; const a = t * TAU * 1.5 + age * 10; pts.push([c[0] + Math.cos(a) * h * 0.55, c[1] - h * 0.5 + t * h, c[2] + Math.sin(a) * h * 0.4]); }
    out.ribbons.push({ pts, width: h * 0.16, cell: 'water', color: [0.35, 0.62, 1], intensity: 1.05, add: 0.2, alpha: 0.85 * env, scroll: age * 6 });
  } else {   // force / dark / steel / psychic / ghost / grass: a tight aura shell with streaks
    L.push({ p: [c[0], c[1], c[2] + 0.2], cell: 'shock', size: [h * 1.3, h * 1.4], rot: age * 2, color: st.glow, alpha: 0.3 * env, add: 1, intensity: 1 });
    if (f.el === 'dark' || f.el === 'ghost') for (let i = 0; i < 3; i++) L.push({ p: [c[0] + Math.sin(age * 3 + i * 2) * h * 0.3, c[1] - h * 0.2 + i * h * 0.25, c[2] + 0.25], cell: 'smoke' + i, size: [h * 0.8, h * 0.6], rot: age + i, color: [0.08, 0.03, 0.12], alpha: 0.45 * env, add: 0, intensity: 1 });
  }
  if (f.hist.length > 2) out.ribbons.push({ pts: f.hist.slice(), widths: f.hist.map((_, i) => h * (f.el === 'fire' ? 0.7 : 0.5) * (i / (f.hist.length - 1))), width: h * 0.6, cell: f.el === 'fire' || f.el === 'blue' ? 'fire' : f.el === 'water' ? 'water' : 'energy', color: st.glow, intensity: 1.05, alpha: 0.7 * env, add: f.el === 'water' ? 0.2 : 0.8, scroll: age * 5 });
  out.lights.push({ p: [c[0], c[1], c[2] + 1], color: st.glow, intensity: 3 * env, range: 9 });
};
HD.FX_STEP.b_cloak = function (d, f) {
  const fr = d.frame; if (fr < f.f0 || fr > f.f1) return; const c = drawnAt(d, f.b); const h = hOf(d, f.b) * f.size; const st = CLOAK[f.el] || CLOAK.force;
  const last = f.hist[f.hist.length - 1]; if (!last || V.dist(last, c) > 0.05) f.hist.push(c.slice()); else if (f.hist.length > 1) f.hist.shift(); if (f.hist.length > 7) f.hist.shift();
  const a = d.act[f.b]; if (a) { const g = 0.55; if (g > a.glow[3]) a.glow = [st.glow[0], st.glow[1], st.glow[2], g]; }
  if (f.el === 'fire') { d.emit(PS.fireBody, c, 3, { scale: h / 3.2, radius: h * 0.45 }); d.emit(PS.ember, c, 2); } else if (f.el === 'blue') d.emit(PS.fireBody, c, 3, { ramp: 'bluefire', scale: h / 3.2, radius: h * 0.45 });
  else if (f.el === 'electric') d.emit(PS.spark, c, 3, { radius: h * 0.45 }); else if (f.el === 'water') d.emit(PS.droplet, c, 2, { radius: h * 0.4 });
  else if (f.el === 'dark') d.emit(PS.darkSmoke, c, 1, { radius: h * 0.4 }); else if (f.el === 'ghost') d.emit(PS.wisp, c, 1, { radius: h * 0.4 }); else if (fr % 2 === 0) d.emit(PS.energy, c, 2, { ramp: st.ramp, radius: h * 0.45 });
};

