// a beak / stinger / spike jab: a short straight thrust from the user's side that ends in the target, with a pointed tip
HD.MOVE_FX.b_jab = (d, e) => {
  const b = bRef(d, e.b || 'target'); if (!present(d, b)) return; const A = d.space.gba[d.atkB()], T = d.space.gba[b]; const th = Math.atan2(-(T[1] - A[1]), T[0] - A[0]) + (e.dth || 0); const h = hOf(d, b); const L = e.len || 0.9;
  const c = scrOff(d.bpos(b), -Math.cos(th) * L * h * 0.32 + (e.ox || 0) * h, -Math.sin(th) * L * h * 0.32 + (e.oy || 0) * h);
  bArcs(d, b, { pos: c, th, len: L, bend: 0, n: 1, w: e.w || 0.15, sweep: e.sweep || 0.06, life: e.life || 0.24, look: e.look, limb: e.limb || 'horn3', limbSize: e.limbSize || 0.36, hit: e.hit === true });
};
// run another per-move effect later (on an absolute frame, or on the script's first hit)
HD.MOVE_FX.b_later = (d, e) => { let f = e.f; if (e.onHit) { const h = d.plan && d.plan.hits.find((x) => x.f >= 2); f = h ? h.f + (e.delay || 0) : null; } if (f == null) return; d.addFx('b_later', { f, e2: Object.assign({}, e.then, { kind: e.then.kind }), life: (f - d.frame + 2) / FPS }); };
HD.FX.b_later = function () {};
HD.FX_STEP.b_later = function (d, f) { if (f.done || d.frame < f.f) return; f.done = true; const fn = HD.MOVE_FX[f.e2.kind]; if (fn) fn(d, f.e2, []); };
// spikes / needles / stingers: a shaded, glinting spike along its flight with a light trail (v2: 1 px hairlines)
K.b_spike = {
  update(d, it, cfg) {
    const h = hOf(d, d.tgtB()); const sz = h * (cfg.v3size || 0.46); const v = toScr(it.v); const sp = Math.hypot(v[0], v[1]); const rot = sp > 0.3 ? Math.atan2(v[1], v[0]) - Math.PI / 2 : (it.s.rot || it.rot); it.s.rot = rot;
    const L = it.cards; const p = it.p.slice(); const col = cfg.color || [0.92, 0.95, 1]; const glow = cfg.glow || d.style.color;
    if (sp > 1 && it.hist.length > 1) { const pts = it.hist.slice(-5).concat([p]); L.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 0.3 * (i / (pts.length - 1))), width: sz * 0.3, cell: 'trail', color: glow, intensity: 1.1, alpha: 0.6 * it.alpha, add: 1 }); }
    L.push({ fixed: true, p, cell: 'dot', size: [sz * 0.9, sz * 1.3], rot, color: glow, alpha: 0.3 * it.alpha, add: 1, intensity: 1 });
    L.push({ fixed: true, p, cell: 'needle', size: [sz * 0.72, sz * 1.06], rot, color: [0.08, 0.06, 0.1], alpha: 0.6 * it.alpha, add: 0, intensity: 1 });
    L.push({ fixed: true, p, cell: 'needle', size: [sz * 0.64, sz], rot, color: col, alpha: it.alpha, add: 0.15, intensity: 1.25 });
    if ((Math.floor(it.age * FPS) + it.uid) % 9 === 0) d.addFx('card', { p: p.slice(), cell: 'star4', size0: sz * 0.6, size1: sz * 0.1, color: [1, 1, 1], intensity: 1.5, life: 0.15, add: 1 });
  },
  end(d, it, cfg) { const nb = d.space.nearestBattler(it.p); if (nb.b >= 0 && nb.b !== d.atkB() && nb.d < hOf(d, nb.b) && !d.status) d.impact({ b: nb.b, pos: it.p.slice(), strength: d.strength * 0.6, minGap: 5, burstScale: 0.5 }); }
};
