HD.CELL_PAINTERS.b2_spike = { draw(g, R) {   // a bold spike / stinger pointing up: a lit left flank, a shaded right flank, a ridge, a collar
  const L = HD.TEX.lum; const tip = -0.97 * R, base = 0.6 * R, hw = 0.21 * R;
  let gg = g.createLinearGradient(-hw, 0, 0, 0); gg.addColorStop(0, L(165)); gg.addColorStop(0.75, L(248)); gg.addColorStop(1, L(255)); g.fillStyle = gg;
  g.beginPath(); g.moveTo(0, tip); g.quadraticCurveTo(-hw * 0.5, (tip + base) * 0.45, -hw, base); g.quadraticCurveTo(-hw * 0.4, base + 0.12 * R, 0, base + 0.13 * R); g.closePath(); g.fill();
  gg = g.createLinearGradient(0, 0, hw, 0); gg.addColorStop(0, L(185)); gg.addColorStop(1, L(70)); g.fillStyle = gg;
  g.beginPath(); g.moveTo(0, tip); g.quadraticCurveTo(hw * 0.5, (tip + base) * 0.45, hw, base); g.quadraticCurveTo(hw * 0.4, base + 0.12 * R, 0, base + 0.13 * R); g.closePath(); g.fill();
  g.strokeStyle = L(255, 0.9); g.lineWidth = 0.035 * R; g.beginPath(); g.moveTo(-0.02 * R, tip + 0.1 * R); g.lineTo(-hw * 0.32, base - 0.05 * R); g.stroke();
  g.fillStyle = L(95); g.beginPath(); g.ellipse(0, base + 0.06 * R, hw * 1.2, 0.09 * R, 0, 0, TAU); g.fill();
  g.fillStyle = L(205); g.beginPath(); g.ellipse(-0.03 * R, base + 0.035 * R, hw * 0.85, 0.04 * R, 0, 0, TAU); g.fill();
} };
HD.CELL_PAINTERS.b2_ball = { draw(g, R) {   // a solid ball: lit sphere, two curved panel seams, a dark rim (luminance = shading)
  const L = HD.TEX.lum; const r = 0.82 * R;
  const bg = g.createRadialGradient(-0.32 * r, -0.36 * r, 0.04 * r, 0, 0, r); bg.addColorStop(0, L(255)); bg.addColorStop(0.22, L(225)); bg.addColorStop(0.7, L(140)); bg.addColorStop(1, L(62));
  g.fillStyle = bg; g.beginPath(); g.arc(0, 0, r, 0, TAU); g.fill();
  g.save(); g.beginPath(); g.arc(0, 0, r, 0, TAU); g.clip(); g.strokeStyle = L(55, 0.85); g.lineWidth = 0.075 * r;
  g.beginPath(); g.ellipse(-0.55 * r, 0, r * 0.42, r * 1.05, 0.35, 0, TAU); g.stroke(); g.beginPath(); g.ellipse(0.6 * r, 0, r * 0.42, r * 1.05, 0.35, 0, TAU); g.stroke(); g.restore();
  g.fillStyle = L(255, 0.85); g.beginPath(); g.ellipse(-0.34 * r, -0.4 * r, 0.16 * r, 0.09 * r, -0.6, 0, TAU); g.fill();
} };
HD.CELL_PAINTERS.b2_coil = { draw(g, R) {   // a stretch of a coiled body: a capsule lit from above, belly shade, faint scale bands
  const L = HD.TEX.lum; const hh = 0.44 * R, x0 = -0.98 * R, x1 = 0.98 * R;
  const gg = g.createLinearGradient(0, -hh, 0, hh); gg.addColorStop(0, L(140)); gg.addColorStop(0.16, L(252)); gg.addColorStop(0.42, L(210)); gg.addColorStop(0.8, L(110)); gg.addColorStop(1, L(60));
  g.fillStyle = gg; g.beginPath(); g.moveTo(x0 + hh, -hh); g.lineTo(x1 - hh, -hh); g.arc(x1 - hh, 0, hh, -Math.PI / 2, Math.PI / 2); g.lineTo(x0 + hh, hh); g.arc(x0 + hh, 0, hh, Math.PI / 2, Math.PI * 1.5); g.closePath(); g.fill();
  g.save(); g.clip(); g.strokeStyle = L(80, 0.32); g.lineWidth = 0.05 * R; for (let k = -3; k <= 3; k++) { g.beginPath(); g.moveTo(k * 0.3 * R - 0.12 * R, -hh); g.lineTo(k * 0.3 * R + 0.12 * R, hh); g.stroke(); } g.restore();
} };
HD.CELL_PAINTERS.b2_fang = { draw(g, R) {   // an upper jaw read at a glance: a crescent gum (dark) and five big teeth (two canines), luminance = shading
  const L = HD.TEX.lum; const W0 = 0.92 * R; const gum = (x) => -0.1 * R - 0.24 * R * (1 - (x / W0) * (x / W0));
  g.beginPath(); for (let i = 0; i <= 30; i++) { const x = -W0 + 2 * W0 * i / 30; g.lineTo(x, gum(x) + 0.03 * R); }
  for (let i = 30; i >= 0; i--) { const x = -W0 + 2 * W0 * i / 30; g.lineTo(x, gum(x) - 0.22 * R * (0.5 + 0.5 * (1 - Math.abs(x / W0)))); }
  g.closePath(); let gg = g.createLinearGradient(0, -0.62 * R, 0, -0.1 * R); gg.addColorStop(0, L(40)); gg.addColorStop(1, L(105)); g.fillStyle = gg; g.fill();
  for (const [xc, len, hw] of [[-0.64, 0.6, 0.17], [-0.32, 0.36, 0.135], [0, 0.34, 0.135], [0.32, 0.36, 0.135], [0.64, 0.6, 0.17]]) {
    const x = xc * R, y0 = gum(x) - 0.01 * R, w = hw * R; const tx = x - Math.sign(xc) * w * 0.35, ty = y0 + len * R;
    gg = g.createLinearGradient(x - w, 0, x + w, 0); gg.addColorStop(0, L(255)); gg.addColorStop(0.5, L(238)); gg.addColorStop(1, L(150)); g.fillStyle = gg;
    g.beginPath(); g.moveTo(x - w, y0); g.quadraticCurveTo(x - w * 0.7, y0 + len * R * 0.65, tx, ty); g.quadraticCurveTo(x + w * 0.9, y0 + len * R * 0.5, x + w, y0); g.closePath(); g.fill();
  }
} };
