HD.MOVE_FX.b2_berry = (d, e) => { const b = bRef(d, e.b || 'attacker'); if (present(d, b)) d.addFx('b2_berry', { b, f0: d.frame, f1: e.f1, life: (e.f1 - d.frame + 2) / FPS }); };
HD.FX.b2_berry = function (d, f, age, out) {
  const fr = frameAt(f, age); const o = fr - f.f0, D = f.f1 - f.f0; if (o < 0 || o > D) return; const c = drawnAt(d, f.b); const h = hOf(d, f.b);
  const up = smooth(o / 14); const eat = smooth(clamp((o - (D - 16)) / 16, 0, 1)); const y = c[1] + h * (0.2 + 0.62 * up - 0.5 * eat) + Math.sin(age * 4) * h * 0.035 * (1 - eat);
  const sz = h * 0.8 * (0.45 + 0.55 * up) * (1 - 0.85 * eat); const p = [c[0] + h * 0.05 * eat, y, c[2] + 0.4]; const a = Math.min(1, o / 5); const rot = Math.sin(age * 2.5) * 0.18;
  out.cards.push({ p, cell: 'dot', size: [sz * 1.7, sz * 1.7], color: [1, 0.5, 0.6], alpha: 0.16 * a, add: 1, intensity: 1 });
  out.cards.push({ p, cell: 'berry3', size: [sz * 1.13, sz * 1.13], rot, color: DARKC, alpha: 0.88 * a, add: 0, hot: 0, intensity: 1 });
  out.cards.push({ p, cell: 'berry3', size: [sz, sz], rot, color: [1, 1, 1], gmap: 'berry', alpha: a, add: 0, hot: 0, intensity: 1.08 });
  out.lights.push({ p, color: [1, 0.55, 0.6], intensity: 1.2 * a, range: 5 });
};
HD.FX_STEP.b2_berry = function (d, f) { const o = d.frame - f.f0, D = f.f1 - f.f0; const c = drawnAt(d, f.b); const h = hOf(d, f.b);
  if (o % 9 === 4 && o < D - 16) d.addFx('card', { p: [c[0] - h * 0.1, c[1] + h * 0.95, c[2] + 0.5], cell: 'star4', size0: h * 0.32, size1: h * 0.05, color: [1, 0.95, 0.9], intensity: 1.5, life: 0.22, add: 1 });
  if (o === D) { d.emit(PS.glint, [c[0], c[1] + h * 0.2, c[2]], 14, { ramp: 'pink', radius: h * 0.3, speedMul: 1.4 }); d.emit(PS.energy, c, 16, { ramp: 'nature', radius: h * 0.35 }); d.emit(PS.leafBit, c, 6, { scale: 1.1 }); d.addFx('card', { p: [c[0], c[1] + h * 0.2, c[2] + 0.4], cell: 'dot', size0: h * 0.5, size1: h * 1.4, color: [0.55, 1, 0.4], intensity: 1, life: 0.3, add: 1 }); } };
// the berry's energy surging through the user: green-gold flames licking up round it, leaf bits, a soft ground glow
