HD.FX.b2_surge = function (d, f, age, out) { const u = age / f.life; if (u < 0 || u > 1) return; const ft = d.space.feet[f.b]; const h = hOf(d, f.b); const k = Math.min(1, u * 6, (1 - u) * 5);
  out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 1.9, h * 1.9], rot: 0, color: f.color, alpha: 0.4 * k, add: 1, intensity: 1, mode: 2 });
  out.lights.push({ p: [ft[0], h * 0.6, ft[2] + 0.8], color: f.color, intensity: 2.4 * k, range: 8 }); };
HD.FX_STEP.b2_surge = function (d, f, age) { const u = age / f.life; if (u > 0.9) return; const c = drawnAt(d, f.b); const h = hOf(d, f.b);
  for (let i = 0; i < 2; i++) { const a = d.rng() * TAU; d.emit(PS.fireLick, [c[0] + Math.cos(a) * h * 0.42, c[1] - h * 0.35 + d.rng() * h * 0.3, c[2] + Math.sin(a) * h * 0.3], 1, { ramp: f.ramp, scale: h / 3.2 }); }
  if (d.frame % 4 === 0) d.emit(PS.leafBit, [c[0], c[1] - h * 0.2, c[2]], 1, { radius: h * 0.4, vel: [0, h * 1.2, 0] }); };
// a shot of energy from one battler to another: a lit object (a seed of light, a coin...) in a glow with an energy trail,
