  const pl = d.plan; if (!pl) return; const bt = pl.births.find((x) => x.tpl === e.tpl && x.f >= d.frame - 1 && x.f <= d.frame + 1); if (!bt) return; const ti = trackInfo(d, bt.uid); if (!ti || ti.n < 3) return;
