  if ((Math.floor(it.age * FPS) + it.uid) % 6 < 2) { const o = { ribbons: [], cards: [] }; const a = (it.uid * 1.7 + Math.floor(it.age * 20)) % 6.28; HD.boltRibbons(scrOff(p, Math.cos(a) * sz * 0.4, Math.sin(a) * sz * 0.4), scrOff(p, Math.cos(a + 1.2) * sz * 0.75, Math.sin(a + 1.2) * sz * 0.75), it.uid * 31 + Math.floor(it.age * 30), 0.025, [0.5, 0.75, 1], 2 * it.alpha, 0, o, 0.4); for (const r of o.ribbons) L.push(Object.assign({ layer: 'ribbons', fixed: true }, r)); }
