  out.cards.push({ p: [c[0], c[1], c[2] + 0.1], cell: 'frost', size: [h * 1.4 * g, h * 1.4 * g], rot: f.seed % 5, color: [0.7, 0.88, 1], alpha: 0.16 * g * fade, add: 1, intensity: 1 });
