// a crescent wind blade riding a sprite, convex edge leading, with a distortion trail (fadeStill: it fades once it stops)
K.c_blade = {
  update(d, it, cfg) {
    const h = H(d, d.tgtB()); const s = h * (cfg.v3size || 0.55); const vd = toScr(it.v); const sp = Math.hypot(vd[0], vd[1]);
    if (sp > 0.5) it.s.ang = Math.atan2(vd[1], vd[0]); const ang = it.s.ang != null ? it.s.ang : screenAng(cen(d, d.atkB()), cen(d, d.tgtB()));
    it.s.still = sp < 0.5 && it.age > 0.08 ? (it.s.still || 0) + 1 : 0; const a = it.alpha * (cfg.fadeStill ? clamp(1 - it.s.still / 8, 0, 1) : 1); if (a < 0.02) return;
    const col = cfg.color || styOf(d, cfg.style).glow; const rot = ang - Math.PI / 2;
    it.cards.push({ cell: 'slash', size: [s * 1.25, s * 1.25], rot, color: col, alpha: 0.45 * a, add: 1, intensity: 1 });
    it.cards.push({ cell: 'slash', size: [s, s], rot, color: [0.95, 1, 1], alpha: 0.95 * a, add: 1, intensity: 1.3 });
    it.cards.push({ layer: 'distort', cell: 'slash', size: [s * 1.3, s * 1.3], rot, strength: 0.6 * a });
    if (sp > 2 && it.hist.length > 1) { const pts = it.hist.slice(-5).concat([it.p.slice()]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => s * 0.5 * (i / (pts.length - 1))), width: s, cell: 'trail', color: col, intensity: 0.9, alpha: 0.5 * a, add: 1 }); }
    const n = KH.every(it, 'w', 14); if (n && sp > 2) d.emit(PS.windStreak, it.p, n, { scale: s * 0.5, ramp: 'wind' });
  },
  end(d, it, cfg) { if (cfg.hit === false) return; const b = KH.nearTarget(d, it.p, 1.1); if (b >= 0) { d.emit(PS.windStreak, it.p, 6, { scale: 0.8 }); } }
};
// two blade lines crossing on a battler (a cut lands)
HD.MOVE_FX.c_slashx = (d, e) => { const tos = e.b === 'foes' ? foes(d) : [d.battlerRef(e.b || 'target')]; for (const b of tos) { if (!present(d, b)) continue; const c = cen(d, b); const h = H(d, b); const col = e.color || styOf(d, e.style).glow; for (const r of [0.7, -0.6]) d.addFx('card', { p: c.slice(), cell: 'chop', size0: h * 0.7, size1: h * 1.3, aspect: 0.5, rot: r, color: col, intensity: 1.4, life: 0.22, add: 1 }); d.emit(PS.windStreak, c, 8, { scale: 0.9 }); } };
// lightning: jagged branching bolts from the sky (or from the user) onto a battler, every few frames
HD.MOVE_FX.c_bolt = (d, e) => {
  const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; const n = e.n || 1; const f0 = e.start != null ? Math.max(d.frame, e.start) : d.frame;
  for (let i = 0; i < n; i++) { const f = f0 + i * (e.every || 6); const c = cen(d, b); const h = H(d, b); const r = HD.rng(f * 977 + b);
    const a = e.from === 'attacker' ? mouth(d, d.atkB(), b, 0.3) : [c[0] + r.range(-0.4, 0.4) * h, c[1] + h * 3.2, c[2]]; const q = e.from === 'attacker' ? contact(d, b, d.atkB()) : [c[0] + r.range(-0.2, 0.2) * h, c[1] - h * 0.1, c[2]];
    d.addFx('bolt', { t0: tAt(f), a, b: q, width: e.width || 0.13, life: (e.life || 9) / FPS, color: e.color || [1, 0.88, 0.32], intensity: e.intensity || 3.4, branches: e.branches != null ? e.branches : 3, jag: e.jag || 0.16, flicker: true });
    d.addFx('c_later', { t0: tAt(f), life: 0.05, b, style: 'electric', size: 0.5 }); }
};
// a column of water / fire / leaves erupting from the ground under a battler
HD.MOVE_FX.c_geyser = (d, e) => { const tos = e.b === 'foes' ? foes(d) : [d.battlerRef(e.b || 'target')]; const f0 = e.arrive != null ? Math.max(d.frame, frameOfRef(d, e.arrive, d.frame) - (e.lead || 4)) : e.start != null ? Math.max(d.frame, e.start) : d.frame;
  for (const b of tos) if (present(d, b)) d.addFx('c_geyser', { t0: tAt(f0), life: (e.dur || 40) / FPS, b, kindG: e.style || 'water', height: e.height || 2.4, width: e.width || 0.8, base: e.base || null }); };
HD.FX.c_geyser = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const ft = d.space.feet[f.b]; const h = H(d, f.b); const k = env(u, 0.08, 0.3); const grow = HD.easeOut(Math.min(1, u * 5)); const Ht = h * f.height * grow; const W = h * f.width;
  const pts = []; for (let i = 0; i <= 8; i++) { const t = i / 8; pts.push([ft[0] + Math.sin(t * 5 + age * 9) * W * 0.06, Ht * t, ft[2] + 0.3]); }
  if (f.kindG === 'fire') {
    out.ribbons.push({ pts, width: W * 1.9, cell: 'boltglow', color: [1, 0.4, 0.1], intensity: 0.5 * k, add: 1 });
    for (let i = 0; i < 6; i++) { const y = (i + 0.5) / 6 * Ht; const fi = (Math.floor(age * 15) + i) % 4; out.cards.push({ p: [ft[0] + Math.sin(age * 9 + i) * W * 0.08, y, ft[2] + 0.35], cell: 'flame' + fi, size: [W * (1.05 - i * 0.07), Ht / 2.6], color: [1, 1, 1], gmap: 'fire', alpha: 0.7 * k, add: 0.55, intensity: 1.1 }); }
  } else if (f.kindG === 'grass') {
    out.ribbons.push({ pts, width: W * 1.0, cell: 'trail', color: [0.4, 0.95, 0.3], intensity: 0.8 * k, add: 0.6, scroll: -age * 4 });
    const r = HD.rng(f.seed); for (let i = 0; i < 14; i++) { const t = ((i / 14) + age * 0.9) % 1; const a = i * 2.4 + age * 7; out.cards.push({ p: [ft[0] + Math.cos(a) * W * 0.55, Ht * t, ft[2] + Math.sin(a) * W * 0.35 + 0.3], cell: 'leaf' + (i & 1), size: [h * 0.24, h * 0.24], rot: a, color: [0.4 + r() * 0.2, 0.85, 0.3], alpha: 0.95 * k * Math.sin(Math.PI * t), add: 0, intensity: 1.05 }); }
  } else {
    out.ribbons.push({ pts, width: W * 1.15, cell: 'water', color: [0.38, 0.66, 1], intensity: 1.05, add: 0.12, alpha: 0.72 * k, scroll: -age * 6, uvRepeat: 2 });
    out.ribbons.push({ pts, width: W * 0.5, cell: 'trail', color: [0.9, 0.97, 1], intensity: 1, add: 0.5, alpha: 0.75 * k, scroll: -age * 9 });
    out.cards.push({ p: [ft[0], Ht, ft[2] + 0.35], cell: 'spray', size: [W * 2.4, W * 2.0], rot: age * 3, color: [0.88, 0.96, 1], alpha: 0.8 * k, add: 0.4, intensity: 1.15 });
  }
  out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: f.kindG === 'fire' ? 'scorch' : 'ring', size: [W * 3, W * 1.8], rot: 0, color: f.base || (f.kindG === 'fire' ? [1, 0.5, 0.2] : f.kindG === 'grass' ? [0.5, 1, 0.4] : [0.7, 0.9, 1]), alpha: 0.6 * k, add: f.kindG === 'fire' ? 0 : 1, intensity: 1, mode: 2 });
  out.lights.push({ p: [ft[0], Ht * 0.6, ft[2] + 0.6], color: f.kindG === 'fire' ? [1, 0.5, 0.2] : f.kindG === 'grass' ? [0.5, 1, 0.4] : [0.45, 0.7, 1], intensity: 3.5 * k, range: 10 });
};
HD.FX_STEP.c_geyser = function (d, f, age) {
  const u = age / f.life; if (u > 0.85) return; const ft = d.space.feet[f.b]; const h = H(d, f.b); const Ht = h * f.height * HD.easeOut(Math.min(1, u * 5));
  if (f.kindG === 'fire') { d.emit(PS.fireBody, [ft[0], Ht * d.rng(), ft[2] + 0.3], 2, { scale: h * 0.8, vel: [0, h * 2, 0] }); d.emit(PS.ember, [ft[0], Ht, ft[2]], 2); }
  else if (f.kindG === 'grass') d.emit(PS.leafBit, [ft[0], Ht, ft[2]], 1, { scale: 1.2 });
  else { d.emit(PS.droplet, [ft[0], Ht, ft[2] + 0.3], 3, { scale: 1.2, speedMul: 1.2 }); if (d.frame % 3 === 0) d.emit(PS.mist, [ft[0], Ht, ft[2]], 1, { scale: 1.2 }); }
};
// a small glowing symbol over a battler (an eye for foresight / odd power...), held to <= 0.45 target heights
HD.MOVE_FX.c_glyph = (d, e) => { const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; d.addFx('c_glyph', { t0: tAt(e.start != null ? Math.max(d.frame, e.start) : d.frame), life: (e.dur || 30) / FPS, b, cell: e.cell || 'eye3', color: e.color || styOf(d, null).glow, size: Math.min(0.45, e.size || 0.4), up: e.up != null ? e.up : 0.85 }); };
HD.FX.c_glyph = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = cen(d, f.b); const h = H(d, f.b); const k = env(u, 0.2, 0.3); const p = [c[0], c[1] + h * f.up, c[2] + 0.2]; const s = h * f.size * (0.85 + 0.15 * Math.sin(age * 8));
  out.cards.push({ p, cell: 'dot', size: [s * 2, s * 2], color: f.color, alpha: 0.3 * k, add: 1, intensity: 1 });
  out.cards.push({ p, cell: f.cell, size: [s, s], color: [1, 1, 1], alpha: 0.95 * k, add: 0.2, intensity: 1.15 });
  out.cards.push({ p, cell: f.cell, size: [s * 1.12, s * 1.12], color: f.color, alpha: 0.5 * k, add: 1, intensity: 1.1 });
};
// a ground shadow growing where something will fall
HD.MOVE_FX.c_fallshadow = (d, e) => { const b = d.battlerRef(e.b || 'target'); const ft = d.space.feet[b]; d.addFx('c_fallshadow', { life: (e.dur || 30) / FPS, p: [ft[0], 0.03, ft[2] + 0.2], h: H(d, b) }); };
