// Night Shade's mirage: a dark, smoky shadow swelling over the user's enlarged clone, two glowing eyes in it
HD.MOVE_FX.c_mirage = (d, e) => d.addFx('c_mirage', { life: (e.dur || 70) / FPS, b: d.battlerRef(e.b || 'attacker'), color: e.color || [0.85, 0.2, 0.35] });
HD.FX.c_mirage = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = cen(d, f.b); const h = H(d, f.b); const k = env(u, 0.25, 0.2); const r = HD.rng(f.seed); const sw = 0.7 + 0.3 * sm(u * 2);
  for (let i = 0; i < 7; i++) { const a = r() * 6.28; const p = [c[0] + Math.cos(a) * h * 0.45 * sw, c[1] + h * (0.35 + 0.35 * r()) * sw, c[2] + 0.4 + i * 0.02]; out.cards.push({ p, cell: 'smoke' + (i % 3), size: [h * 1.5 * sw, h * 1.5 * sw], rot: r() * 6 + age * (i % 2 ? 0.4 : -0.4), color: [0.07, 0.03, 0.1], alpha: 0.55 * k, add: 0, intensity: 1 }); }
  for (const sx of [-1, 1]) { const p = [c[0] + sx * h * 0.28 * sw, c[1] + h * 0.85 * sw, c[2] + 0.6]; out.cards.push({ p, cell: 'dot', size: [h * 0.45, h * 0.3], color: f.color, alpha: 0.5 * k, add: 1, intensity: 1.2 }); out.cards.push({ p, cell: 'eye', size: [h * 0.32, h * 0.2], flip: sx < 0 ? 1 : 0, color: [1, 0.5, 0.55], alpha: 0.95 * k, add: 0.6, intensity: 1.5 }); }
  out.lights.push({ p: [c[0], c[1] + h * 0.8, c[2] + 0.8], color: f.color, intensity: 2 * k, range: 8 });
};
HD.FX_STEP.c_mirage = function (d, f, age) { if (d.frame % 3) return; const c = cen(d, f.b); const h = H(d, f.b); d.emit(PS.darkSmoke, [c[0], c[1] + h * 0.5, c[2] + 0.3], 2, { radius: h * 0.7, scale: h * 0.9 }); d.emit(PS.wisp, [c[0], c[1] + h * 0.6, c[2] + 0.3], 1, { ramp: 'ghost', radius: h * 0.6 }); };
HD.moveFxClear('MOVE_NIGHT_SHADE', (e) => e.kind === 'c_glyph' || (e.kind === 'motes' && e.preset === 'darkSmoke'));
add({ MOVE_NIGHT_SHADE: { fx: [{ at: 54, kind: 'c_mirage', b: 'attacker', dur: 120 }] } });


