// a sound blast on a battler: shock rings, distortion and dust (Boomburst's blasts, not fire)
K.c_shockburst = {
  init(d, it) { const h = H(d, d.tgtB()); d.emit(PS.dustPuff, it.p, 6, { scale: h * 0.5 }); d.emit(PS.hitStreak, it.p, 8, { scale: 0.8 }); const b = KH.nearTarget(d, it.p, 1.3); if (b >= 0 && !d.status) d.impact({ b, pos: it.p.slice(), strength: d.strength * 0.7, minGap: 6, burstScale: 0.3 }); },
  update(d, it) { const h = H(d, d.tgtB()); const u = clamp(it.age / 0.3, 0, 1); if (u >= 1) return; it.cards.push({ cell: 'shock', size: [h * (0.4 + u), h * (0.4 + u)], color: [1, 0.95, 0.85], alpha: 0.7 * (1 - u), add: 1, intensity: 1.1 }); it.cards.push({ layer: 'distort', cell: 'shock', size: [h * (0.6 + u * 1.2), h * (0.6 + u * 1.2)], strength: 0.9 * (1 - u) }); }
};
// a portal ring: a glowing ring with a dark swirling centre that bends the air (Hyperspace Hole)
HD.MOVE_FX.c_portal = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); d.addFx('c_portal', { t0: tAt(e.start != null ? Math.max(d.frame, e.start) : d.frame), life: (e.dur || 40) / FPS, b, side: e.side || 0, color: e.color || [1, 0.75, 0.35] }); };
HD.FX.c_portal = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = cen(d, f.b); const h = H(d, f.b); const k = env(u, 0.2, 0.25); const p = scrOff(c, f.side * h * 0.75, h * 0.1); const s = h * 1.1 * sm(Math.min(1, u * 4));
  out.cards.push({ p, cell: 'swirl', size: [s * 0.85, s * 0.85], rot: -age * 5, color: [0.1, 0.02, 0.18], alpha: 0.9 * k, add: 0, intensity: 1 });
  out.cards.push({ p, cell: 'swirl', size: [s * 0.75, s * 0.75], rot: -age * 7 + 1, color: [0.8, 0.3, 1], alpha: 0.5 * k, add: 1, intensity: 1 });
  out.cards.push({ p, cell: 'ring', size: [s, s], color: f.color, alpha: k, add: 1, intensity: 1.4 });
  out.distort.push({ p, cell: 'swirl', size: [s * 1.1, s * 1.1], strength: 0.6 * k, mode: 0 }); out.lights.push({ p, color: f.color, intensity: 3 * k, range: 8 });
};
