  const q = [fa[0] + dx * tt, h * 0.3, fa[2] + dz * tt]; out.distort.push({ p: q, cell: 'shock', size: [h * 1.4, h * 1.1], strength: 0.6 * k, mode: 0 }); out.lights.push({ p: [q[0], 1, q[2]], color: f.color, intensity: 4 * k, range: 8 });
