// c2_vortex: a funnel of spiralling strands round a battler (fire / wind / leaves / water): strands split into front and
// back runs so the battler shows between them; optional orbiting leaves and particles drawn up the funnel
HD.MOVE_FX.c2_vortex = (d, e) => { const tos = e.b === 'foes' ? foes(d) : [d.battlerRef(e.b || 'target')]; for (const b of tos) if (present(d, b)) d.addFx('c2_vortex', { t0: tAt(e.start != null ? Math.max(d.frame, e.start) : d.frame), life: (e.dur || 60) / FPS, b, cell: e.cell || 'trail', color: e.color || [0.85, 0.95, 1], height: e.height || 1.5, radius: e.radius || 0.55, strands: e.strands || 3, spin: e.spin || 7, width: e.width || 0.12, alpha: e.alpha != null ? e.alpha : 0.6, add: e.add != null ? e.add : 0.8, ps: e.ps || null, psRamp: e.psRamp, leaves: e.leaves || 0, leafColor: e.leafColor || [0.3, 0.75, 0.2], turns: e.turns || 1.3, flare: e.flare || 0 }); };
HD.FX.c2_vortex = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const ft = d.space.feet[f.b]; const c = cen(d, f.b); const h = H(d, f.b); const k = env(u, 0.12, 0.25); const Ht = h * f.height * (0.55 + 0.45 * sm(Math.min(1, u * 4)));
  for (let s = 0; s < f.strands; s++) {
    let run = [], runW = [], runBack = null;
    const flush = () => { if (run.length > 1) out.ribbons.push({ pts: run, widths: runW, width: 1, cell: f.cell, color: f.color, intensity: 1.05 * k, add: f.add, alpha: f.alpha * k, scroll: age * 4 + s, uvRepeat: 2, back: runBack }); };
    for (let i = 0; i <= 26; i++) { const t = i / 26; const a = s * 6.283 / f.strands + t * 6.283 * f.turns - age * f.spin; const r = h * f.radius * (0.55 + 0.75 * t); const back = Math.sin(a) < 0;
      const p = [c[0] + Math.cos(a) * r, ft[1] + 0.05 + t * Ht, c[2] + Math.sin(a) * r * 0.55]; const w = h * f.width * (0.45 + t) * (0.8 + 0.2 * Math.sin(t * 9 + age * 5 + s));
      run.push(p); runW.push(w); if (runBack !== null && back !== runBack) { flush(); run = [p]; runW = [w]; } runBack = back; }
    flush();
  }
  const r = HD.rng(f.seed);
  for (let i = 0; i < f.leaves; i++) { const t = (r() + age * 0.35) % 1; const a = r() * 6.283 - age * f.spin * 1.1; const rad = h * f.radius * (0.6 + 0.7 * t); const back = Math.sin(a) < 0;
    out.cards.push({ p: [c[0] + Math.cos(a) * rad, ft[1] + t * Ht, c[2] + Math.sin(a) * rad * 0.55], cell: 'leaf' + (i & 1), size: [h * 0.2, h * 0.2], rot: a * 2 + age * 6, color: f.leafColor, alpha: 0.95 * k * Math.sin(Math.PI * t), add: 0, intensity: 1.05, back }); }
  if (f.flare) out.cards.push({ p: [c[0], ft[1] + Ht * 0.35, c[2]], cell: 'dot', size: [h * 1.4, Ht * 0.9], color: f.color, alpha: 0.25 * f.flare * k, add: 1, intensity: 1, back: true });
  out.distort.push({ p: [c[0], ft[1] + Ht * 0.5, c[2]], cell: 'swirl', size: [h * f.radius * 2.6, Ht], strength: 0.4 * k, mode: 0 });
};
HD.FX_STEP.c2_vortex = function (d, f, age) { if (!f.ps || age / f.life > 0.85) return; const ft = d.space.feet[f.b]; const h = H(d, f.b); const a = d.rng() * 6.283; const rad = h * f.radius * 0.8;
  d.emit(PS[f.ps], [ft[0] + Math.cos(a) * rad, h * 0.2, ft[2] + Math.sin(a) * rad * 0.55], 1, { ramp: f.psRamp, vel: [-Math.sin(a) * 2, h * 2.2, Math.cos(a) * 1.2] }); };
// c2_gust: the GBA gust sprite circling the target drawn as a faint translucent streak (the funnel itself is a c2_vortex)
K.c2_gust = { update(d, it, cfg) { const h = H(d, d.tgtB()); if (it.hist.length > 2) { const pts = it.hist.slice(-7).concat([it.p.slice()]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => h * 0.16 * (i / (pts.length - 1))), width: 1, cell: 'trail', color: cfg.color || [0.85, 0.95, 1], intensity: 1, alpha: (cfg.alpha || 0.4) * it.alpha, add: 0.8 }); }
  const n = KH.every(it, 'w', cfg.rate || 14); if (n) d.emit(cfg.ps ? PS[cfg.ps] : PS.windStreak, it.p, n, { scale: 0.8, ramp: cfg.psRamp }); } };
// c2_splash: a water hit splat drawn as a short blue splash crown with droplets (not a pale puff that lingers)
K.c2_splash = {
  init(d, it, cfg) { const h = H(d, d.tgtB()); d.emit(PS.droplet, it.p, cfg.drops || 8, { scale: h * 0.45, speedMul: 1.2 }); },
  update(d, it, cfg) { const h = H(d, d.tgtB()); const u = clamp(it.age / (cfg.life || 0.28), 0, 1); if (u >= 1) return; const s = h * (cfg.v3size || 0.5) * (0.55 + 0.6 * HD.easeOut(u));
    it.cards.push({ cell: 'spray', size: [s, s], rot: it.uid, color: cfg.color || [0.5, 0.76, 1], alpha: 0.9 * (1 - u) * it.alpha, add: 0.3, intensity: 1.1 }); }
};
// c2_shuriken: a spinning star of water (four droplet blades round a blue core) with a spray trail
K.c2_shuriken = {
  update(d, it, cfg) { const h = H(d, d.tgtB()); const s = h * (cfg.v3size || 0.42); const rot = it.age * (cfg.spin || 16) + it.uid; const L = it.cards; const p = it.p.slice(); const a = it.alpha;
    if (it.hist.length > 1) { const pts = it.hist.slice(-6).concat([p]); L.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => s * 0.5 * (i / (pts.length - 1))), width: 1, cell: 'water', color: [0.35, 0.62, 1], intensity: 1.05, alpha: 0.7 * a, add: 0.3 }); }
    L.push({ fixed: true, p, cell: 'dot', size: [s * 1.6, s * 1.6], color: [0.3, 0.6, 1], alpha: 0.3 * a, add: 1, intensity: 1 });
    for (let i = 0; i < 4; i++) { const an = rot + i * Math.PI / 2; L.push({ fixed: true, p: along(p, an, s * 0.3), cell: 'droplet', size: [s * 0.32, s * 0.62], rot: an - Math.PI / 2, color: [0.45, 0.72, 1], alpha: 0.95 * a, add: 0.35, intensity: 1.15 }); }
    L.push({ fixed: true, p, cell: 'orb', size: [s * 0.42, s * 0.42], color: [0.3, 0.58, 1], alpha: 0.9 * a, add: 0.3, intensity: 1.15 }, { fixed: true, p, cell: 'core', size: [s * 0.2, s * 0.2], color: [0.9, 0.97, 1], alpha: 0.8 * a, add: 1, intensity: 1.1 });
    const n = KH.every(it, 'd', 20); if (n) d.emit(PS.droplet, p, n, { scale: s * 0.6, speedMul: 0.5 }); d.light(p, [0.4, 0.7, 1], 1.5 * a, 6, 'c2_shuriken'); }
};
// c2_drop: a ball of energy that falls from the sky onto a battler and lands on a frame (Future Sight's delayed strike)
HD.MOVE_FX.c2_drop = (d, e) => { const T = frameOfRef(d, e.arrive, d.frame + 14); const tr = e.travel || 14; const f0 = Math.max(d.frame, T - tr);
  for (const b of (e.b === 'foes' ? foes(d) : [d.battlerRef(e.b || 'target')])) if (present(d, b)) d.addFx('c2_drop', { t0: tAt(f0), life: (T - f0) / FPS, b, sty: e.style || null, size: e.size || 0.45, burst: e.burst != null ? e.burst : null, burstSize: e.burstSize || 1 }); };
function dropPos(d, f, age) { const c = cen(d, f.b); const h = H(d, f.b); const t = clamp(age / f.life, 0, 1); const e = HD.easeIn(t); return [c[0] + (1 - e) * h * 0.3, c[1] + (1 - e) * h * 3.4, c[2]]; }
HD.FX.c2_drop = function (d, f, age, out) { const u = age / f.life; if (u < 0 || u > 1) return; const S = styOf(d, f.sty); const h = H(d, f.b); const s = h * f.size; const p = dropPos(d, f, age);
  const pts = []; for (let i = 6; i >= 0; i--) pts.push(dropPos(d, f, Math.max(0, age - i * 0.02))); out.ribbons.push({ pts, widths: pts.map((_, i) => s * 0.8 * (i / 6)), width: 1, cell: 'trail', color: S.glow, intensity: 1.1, add: 0.8, alpha: 0.8 });
  drawBall(out.cards, p, s, S, 'orb', age, 3); out.lights.push({ p, color: S.light, intensity: 3, range: 8 }); };
HD.FX_STEP.c2_drop = function (d, f, age) { const S = styOf(d, f.sty); const p = dropPos(d, f, age); ballParticles(d, p, H(d, f.b) * f.size, S, 'orb'); if (age / f.life >= 0.999 && !f.done) { f.done = true; if (f.burst) burstAt(d, f.b, f.burst, { size: f.burstSize, ring: false }); } };
// c2_lightfall: shafts of light that rain down on the field round a battler, each landing with a flash (Judgment)
HD.MOVE_FX.c2_lightfall = (d, e) => { const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; const n = e.n || 10; const f0 = e.start != null ? Math.max(d.frame, e.start) : d.frame; const r = HD.rng(f0 * 13 + 7);
  for (let i = 0; i < n; i++) d.addFx('c2_lightfall', { t0: tAt(f0 + Math.round(i * (e.every || 6) + r() * 3)), life: (e.life || 12) / FPS, b, dx: r.range(-1.6, 1.6), dz: r.range(-0.8, 0.8), color: e.color || [1, 0.85, 0.45], size: e.size || 1 }); };
HD.FX.c2_lightfall = function (d, f, age, out) { const u = age / f.life; if (u < 0 || u > 1) return; const ft = d.space.feet[f.b]; const h = H(d, f.b) * f.size; const g = [ft[0] + f.dx * h, 0, ft[2] + f.dz * h]; const fall = Math.min(1, u * 3); const k = u < 0.33 ? 1 : 1 - (u - 0.33) / 0.67;
  const top = h * 4.2, bot = top * (1 - fall); out.ribbons.push({ pts: [[g[0], top, g[2]], [g[0], bot, g[2]]], width: h * 0.16, cell: 'beam', color: f.color, intensity: 1.2 * k, add: 1, fadeEnds: 2 });
  out.ribbons.push({ pts: [[g[0], top, g[2]], [g[0], bot, g[2]]], width: h * 0.42, cell: 'boltglow', color: f.color, intensity: 0.4 * k, add: 1 });
  if (fall >= 1) { out.cards.push({ p: [g[0], h * 0.12, g[2]], cell: 'star4', size: [h * 0.7 * k, h * 0.7 * k], color: f.color, alpha: k, add: 1, intensity: 1.4 }); out.decals.push({ p: [g[0], 0.03, g[2]], cell: 'dot', size: [h * 1.0, h * 0.6], rot: 0, color: f.color, alpha: 0.7 * k, add: 1, intensity: 1.2, mode: 2 }); }
  out.lights.push({ p: [g[0], h * 0.5, g[2]], color: f.color, intensity: 3 * k, range: 7 }); };
HD.FX_STEP.c2_lightfall = function (d, f, age) { if (f.done || age / f.life < 0.33) return; f.done = true; const ft = d.space.feet[f.b]; const h = H(d, f.b) * f.size; d.emit(PS.glint, [ft[0] + f.dx * h, 0.3, ft[2] + f.dz * h], 5, { ramp: 'gold', speedMul: 1.4 }); };
