// the dirt mound round a dug hole (Dig, Rototiller): the first half draws the pit, each half a ring of soil clods
K.d_mound = {
  init(d, it, cfg) { needMeshes(d); const b = d.space.nearestBattler(it.p).b; it.s.b = b >= 0 ? b : d.atkB(); it.s.first = !d.v3.dMound; d.v3.dMound = true; const r = HD.rng(it.uid * 131 + 5); it.s.side = it.rec.x < d.space.gba[it.s.b][0] ? -1 : 1; it.s.clods = []; for (let i = 0; i < 5; i++) it.s.clods.push({ a: r.range(-1.2, 1.2), rr: r.range(0.75, 1.05), s: r.range(0.1, 0.17), rot: [r() * 6, r() * 6, r() * 6], col: pickCol(r, SOIL) }); },
  update(d, it, cfg) {
    const s = it.s; const ft = feetOf(d, s.b); const h = hOf(d, s.b); const g = HD.smooth(Math.min(1, it.age / 0.25)) * it.alpha; if (g <= 0.01) return;
    if (s.first && cfg.hole !== false) it.cards.push({ layer: 'decals', fixed: true, p: [ft[0], 0.158, ft[2]], cell: 'd_hole', size: [h * 1.25 * g, h * 1.6 * g], color: [0.42, 0.3, 0.2], alpha: 1, add: 0, intensity: 1, mode: 2 });
    it.meshes = s.clods.map((c) => { const a = (s.side > 0 ? 0 : Math.PI) + c.a; return { kind: 'rock', p: [ft[0] + Math.cos(a) * h * 0.46 * c.rr, 0.14 + c.s * h * 0.25 * g, ft[2] + Math.sin(a) * h * 0.4 * c.rr], size: c.s * h * 0.6 * g, scale: [1, 0.7, 1], rot: c.rot, color: c.col }; });
  }
};
// kits that draw several meshes set it.meshes (the director collects it.mesh only): one transient effect per move
// draws them while the move runs
HD.FX.d_meshes = function (d, f, age, out) { for (const it of d.inst.values()) if (!it.hidden && it.meshes) for (const m of it.meshes) out.meshes.push(m); };
function needMeshes(d) { if (d.v3.dMeshFx) return; d.v3.dMeshFx = true; d.addFx('d_meshes', { life: Math.max(1, ((d.plan ? d.plan.frames : 300) - d.frame + 4)) / FPS }); }

// a bone swung as a club (Bone Club, Bone Rush): the runtime slides it onto the target; HD swings it overhead in a
// big arc that lands on the contact frame, with a swoosh behind its far end, then a heavy thud with dust and chips.
// thrown bones (Bonemerang) spin end over end with a circular smear. PROP3 look: ink outline + ivory ramp.
const BONE_AXIS = 0.62;   // the bone3 cell lies about 35 degrees above +x
function drawBone(L, p, rot, sz, alpha, glow) {
  if (glow) L.push({ fixed: true, p, cell: 'dot', size: [sz * 1.6, sz * 1.6], color: glow, alpha: 0.22 * alpha, add: 1, intensity: 1 });
  L.push({ fixed: true, p, cell: 'bone3', size: [sz * 1.08, sz * 1.08], rot, color: [0.07, 0.05, 0.04], alpha: 0.6 * alpha, add: 0, hot: 0, intensity: 1 });
  L.push({ fixed: true, p, cell: 'bone3', size: [sz, sz], rot, color: [0.9, 0.84, 0.72], gmap: 'ivory', alpha, add: 0, intensity: 0.92 });
}
K.d_bone = {
  init(d, it, cfg) {
    const s = it.s; const ti = V3.trackInfo(d, it.uid); s.ti = ti; s.foe = d.tgtB();
    const hit = ti && d.plan ? d.plan.hits.find((x) => x.f >= ti.f0 && x.f <= ti.f1 + 4) : null; s.cf = hit ? hit.f : (ti ? ti.lastMove : d.frame + 12); s.f0 = ti ? ti.f0 : d.frame;
    const turn = d.setup.moveTurn | 0; s.alt = (turn + (d.v3.dBones = (d.v3.dBones || 0) + 1)) & 1;
    s.mode = cfg.mode || 'club';
  },
  update(d, it, cfg) {
    const s = it.s; const h = hOf(d, s.foe); const sz = h * (cfg.v3size || 0.6); const L = it.cards; const a = it.alpha; const f = d.frame;
    if (s.mode === 'spin') {   // thrown: end over end, a circular smear, glints
      const rot = it.age * (cfg.spin || 16) + it.uid; drawBone(L, it.p.slice(), rot, sz, a, null);
      for (let k = 1; k <= 3; k++) L.push({ fixed: true, p: it.p.slice(), cell: 'bone3', size: [sz, sz], rot: rot - k * 0.32, color: [1, 0.95, 0.85], alpha: 0.22 * a / k, add: 1, intensity: 1 });
      L.push({ fixed: true, p: it.p.slice(), cell: 'swirl', size: [sz * 1.25, sz * 1.25], rot: -it.age * 14, color: [1, 0.93, 0.8], alpha: 0.35 * a, add: 1, intensity: 1 });
      if (V.len(it.v) > 2 && it.hist.length > 2) { const pts = it.hist.slice(-6).concat([it.p.slice()]); L.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 0.5 * (i / (pts.length - 1))), width: sz * 0.5, cell: 'trail', color: [1, 0.9, 0.75], intensity: 1, alpha: 0.45, add: 1 }); }
      return;
    }
    // club: the angle sweeps from raised (behind, over the top) down onto the target, accelerating into the contact
    const T = Math.max(2, s.cf - s.f0); const u = clamp((f - s.f0 + (it.age * FPS - Math.floor(it.age * FPS))) / T, 0, 1.25);
    const dirX = d.space.gba[s.foe][0] > d.space.gba[d.atkB()][0] ? 1 : -1;   // swing toward the target's side of the screen
    const A0 = s.alt ? 2.6 : 2.2, A1 = s.alt ? -0.6 : -0.35; const e = u <= 1 ? HD.easeIn(u) : 1 + (u - 1) * 0.6;
    const ang = A0 + (A1 - A0) * Math.min(1, e) - (u > 1 ? 0.12 * Math.sin((u - 1) * 12) : 0);   // screen angle of the bone's head (mirrored for a left swing)
    const scrA = dirX > 0 ? ang : Math.PI - ang; const c = it.p.slice(); const reach = sz * 0.42;
    const piv = V3.scrOff(c, -Math.cos(scrA) * reach, -Math.sin(scrA) * reach);   // the grip: the bone turns round it
    const head = V3.scrOff(piv, Math.cos(scrA) * reach * 2, Math.sin(scrA) * reach * 2); const mid = V3.scrOff(piv, Math.cos(scrA) * reach, Math.sin(scrA) * reach);
    const rot = scrA - BONE_AXIS;
    if (u > 0.25 && u < 1.08) {   // swoosh: the arc swept by the head
      const pts = [], widths = []; const n = 9; for (let i = 0; i < n; i++) { const t = i / (n - 1); const uu = Math.max(0, Math.min(1, e) - 0.45 * (1 - t)); const aa = A0 + (A1 - A0) * uu; const sa = dirX > 0 ? aa : Math.PI - aa; pts.push(V3.scrOff(piv, Math.cos(sa) * reach * 1.9, Math.sin(sa) * reach * 1.9)); widths.push(sz * 0.42 * Math.pow(t, 1.3)); }
      L.push({ layer: 'ribbons', fixed: true, pts, widths, width: sz * 0.5, cell: 'trail', color: [1, 0.9, 0.72], intensity: 1.3, alpha: 0.75 * (u > 1 ? 1 - (u - 1) / 0.08 : 1), add: 1 });
      for (let k = 1; k <= 2; k++) { const uk = Math.max(0, Math.min(1, e) - k * 0.1); const ak = A0 + (A1 - A0) * uk; const sk = dirX > 0 ? ak : Math.PI - ak; drawGhostBone(L, V3.scrOff(piv, Math.cos(sk) * reach, Math.sin(sk) * reach), sk - BONE_AXIS, sz, 0.3 / k * a); }
    }
    const fade = u > 1.08 ? clamp(1 - (u - 1.08) / 0.15, 0, 1) : 1; if (fade <= 0) return;
    drawBone(L, mid, rot, sz, a * fade, d.style.color);
    void head;
  },
  end(d, it, cfg) { if (it.s.mode === 'spin' && cfg.hit) { const nb = d.space.nearestBattler(it.p); if (nb.b >= 0 && nb.b !== d.atkB() && nb.d < hOf(d, nb.b) && !d.status) d.impact({ b: nb.b, pos: it.p.slice(), strength: d.strength * 0.8, minGap: 6 }); } }
};
function drawGhostBone(L, p, rot, sz, al) { L.push({ fixed: true, p, cell: 'bone3', size: [sz, sz], rot, color: [1, 0.94, 0.82], alpha: al, add: 1, intensity: 0.9 }); }
// a heavy blunt hit on the ground type: thud ring, crack under the feet, dust ring, soil chunks and bone / stone chips
HD.MOVE_FX.d_thud = (d, e) => {
  const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; const h = hOf(d, b); const ft = feetOf(d, b); const c = d.bpos(b); const k = e.size || 1;
  if (e.crack !== false) crack(d, ft, h * 0.85 * k, { life: 1.3 });
  dustRing(d, ft, 12, 2.0, 1.3 * k); d.emit(PS.d_plume, [ft[0], 0.3, ft[2]], 5, { scale: h * 0.3 * k });
  if (e.chunks !== false) debris(d, { p: [ft[0], 0.2, ft[2] + 0.3], n: e.n || 5, size: [0.1 * k, 0.22 * k], speed: [1, 3], up: [4, 8], life: 1.1, colors: e.colors || SOIL });
  if (e.chips) d.emit(PS.d_pebble, [c[0], c[1], c[2] + 0.2], e.chips, { ramp: e.chipRamp || 'rock', scale: 1.1 });
  d.addFx('ring', { p: [ft[0], 0.17, ft[2]], cell: 'ring', r0: h * 0.2, r1: h * 1.2 * k, width: 0.08, color: [0.6, 0.48, 0.34], intensity: 0.9, life: 0.35, add: 0, ground: true, distort: 0.8 });
  d.shake(0.22 * k);
};
// the user charges the target (presentation only): the v3 rush (crouch, dash peaking on the contact frame, return) with
// the timing given here instead of the automatic one { C: contact frame, D: dash frames, W: crouch frames, k: share of the distance }
HD.MOVE_FX.d_rush = (d, e) => {
  const b = d.atkB(), t = d.tgtB(); if (b === t) return; const A = d.space.gba[b], T = d.space.gba[t]; const dx = T[0] - A[0], dy = T[1] - A[1]; const dist = Math.hypot(dx, dy) || 1;
  d.v3.rush = true; const C = e.C;
  d.addFx('v3rush', { b, C, D: e.D || 6, W: e.W || 0, amt: dist * (e.k || 0.7), ux: dx / dist, uy: dy / dist, life: (C + 20 - d.frame) / FPS, color: e.color || V3.limbGlow(d, {}, d.style.ramp) });
};


// ------------------------------------------------------------------ more effects
HD.MOVE_FX.d_noquake = (d) => { d.fx = d.fx.filter((f) => f.kind !== 'quake' || f.t0 < d.t - 0.01); };
// a chasm opening under a battler (Fissure): an elongated pit with crack arms, light from the depths, dust columns from
// its edges and stones tumbling in; it closes again at the end
HD.MOVE_FX.d_chasm = (d, e) => { const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; d.addFx('d_chasm', { b, life: (e.dur || 80) / FPS, glow: e.glow || [1, 0.42, 0.12], rot: (d.rng() - 0.5) * 0.4 }); };
HD.FX.d_chasm = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const ft = feetOf(d, f.b); const h = hOf(d, f.b);
  const open = HD.easeOut(Math.min(1, age / 0.28)); const close = 1 - HD.smooth((u - 0.78) / 0.22); const k = open * close;
  out.decals.push({ p: [ft[0], 0.156, ft[2]], cell: 'd_crack', size: [h * 3.6 * (0.45 + 0.55 * open), h * 3.6 * (0.45 + 0.55 * open)], rot: f.rot, color: SOIL_DARK, alpha: close, add: 0, intensity: 1, mode: 2 });
  out.decals.push({ p: [ft[0], 0.16, ft[2] + h * 0.1], cell: 'd_hole', size: [h * 2.3 * k, h * 1.5 * k], rot: f.rot * 0.5, color: [0.48, 0.36, 0.26], alpha: 0.97 * close, add: 0, intensity: 1, mode: 2 });
  const g = k * (0.8 + 0.2 * Math.sin(age * 9)); out.decals.push({ p: [ft[0], 0.164, ft[2] + h * 0.1], cell: 'dot', size: [h * 1.4 * k, h * 0.8 * k], color: f.glow, alpha: 0.55 * g, add: 1, intensity: 1.3, mode: 2 });
  out.lights.push({ p: [ft[0], 0.5, ft[2] + 0.6], color: f.glow, intensity: 4.5 * g, range: 7 });
};
HD.FX_STEP.d_chasm = function (d, f, age) {
  const u = age / f.life; const ft = feetOf(d, f.b); const h = hOf(d, f.b); const r = d.rng; if (u > 0.8) return;
  if (!f.started) { f.started = true; d.shake(0.5); dustRing(d, ft, 16, 2.4, 1.6); debris(d, { p: [ft[0], 0.2, ft[2] + 0.3], n: 9, size: [0.14, 0.32], speed: [1.5, 3.5], up: [5, 9], life: 1.3, jitter: h * 0.4 }); }
  d.cam.trauma = Math.max(d.cam.trauma, 0.32 * (1 - u) * HD.settings.shake);
  if (d.frame % 2 === 0) { const sd = r.sign(); d.emit(PS.d_plume, [ft[0] + sd * r.range(0.45, 0.9) * h, 0.2, ft[2] + r.range(-0.25, 0.25) * h], 1, { vel: [sd * 0.3, h * r.range(1.4, 2.4), 0], scale: h * 0.36 }); }
  if (d.frame % 3 === 0) { d.emit(PS.d_pebble, [ft[0] + r.range(-0.8, 0.8) * h, 0.4, ft[2] + 0.3], 2, { scale: 1.2 }); d.emit(PS.d_ember, [ft[0] + r.range(-0.5, 0.5) * h, 0.1, ft[2]], 1, { vel: [0, h * 0.8, 0] }); }
};
// rolling: the user curled into a ball spinning on the spot or charging (a spinning blur round it, dust and grit kicked
// up behind, scuff marks on the ground) { b, dur, speed }
HD.MOVE_FX.d_roll = (d, e) => d.addFx('d_roll', { b: d.battlerRef(e.b || 'attacker'), life: (e.dur || 40) / FPS, color: e.color || [0.72, 0.6, 0.45], ice: !!e.ice });
HD.FX.d_roll = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hOf(d, f.b);
  const p = V3.scrOff(f.pos || bNow(d, f.b), 0, -h * 0.12); const env = Math.min(1, u * 6, (1 - u) * 6);
  for (let i = 0; i < 2; i++) out.cards.push({ p: [p[0], p[1], p[2] + 0.05], cell: 'swirl', size: [h * (1.05 - i * 0.22), h * (1.05 - i * 0.22)], rot: -age * (16 + i * 5) * ((f.b & 1) ? -1 : 1), color: f.color, alpha: (0.62 - i * 0.2) * env, add: f.ice ? 0.8 : 0.25, intensity: 1.05 });
  out.cards.push({ p: [p[0], p[1], p[2] - 0.05], cell: 'dot', size: [h * 1.3, h * 1.3], color: f.ice ? [0.6, 0.85, 1] : [0.85, 0.75, 0.6], alpha: 0.16 * env, add: 1, intensity: 1, back: true });
};
HD.FX_STEP.d_roll = function (d, f, age) {
  f.pos = bNow(d, f.b); const p = [f.pos[0], 0.15, f.pos[2] + 0.2];
  const dir = (f.b & 1) ? 1 : -1; d.emit(f.ice ? PS.snowPuff || PS.d_dust : PS.d_dust, p, 1, { dir: [dir * 0.8, 0.4, 0], spread: 0.5, scale: 1.1 }); if (d.frame % 2 === 0) d.emit(f.ice ? PS.iceChip : PS.d_grit, [p[0], 0.3, p[2]], 2, { dir: [dir, 0.8, 0], spread: 0.4 });
  if (d.frame % 4 === 0) d.addFx('decal', { p: [p[0], gy(d, p), p[2]], cell: 'scorch', size: hOf(d, f.b) * 0.5, life: 1.2, alpha: f.ice ? 0.25 : 0.4, color: f.ice ? [0.8, 0.92, 1] : [0.45, 0.35, 0.25], rot: d.rng() * 6 });
};

