// ------------------------------------------------------------------ dragon energy
// a battler wrapped in blue-violet dragon energy: draconic flames licking up its body, motes, a glow behind it
HD.MOVE_FX.d_aura = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); if (!present(d, b)) return; d.addFx('d_aura', { b, life: (e.dur || 30) / FPS, ramp: e.ramp || 'd_dragon', color: e.color || [0.38, 0.26, 1], rate: e.rate || 1, glow: e.glow != null ? e.glow : 0.5 }); };
HD.FX.d_aura = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const p = bNow(d, f.b); const h = hOf(d, f.b); const env = Math.min(1, u * 5, (1 - u) * 4);
  out.cards.push({ p: [p[0], p[1] - h * 0.05, p[2] - 0.1], back: true, cell: 'dot', size: [h * 1.7, h * 2.0], color: f.color, alpha: 0.45 * env, add: 1, intensity: 1.1 });
  out.cards.push({ p: [p[0], p[1] - h * 0.1, p[2] - 0.05], back: true, cell: 'flame' + (Math.floor(age * 15) % 4), size: [h * 1.3, h * 1.7], color: [1, 1, 1], gmap: f.ramp, alpha: 0.55 * env, add: 0.6, intensity: 1.1 });
  out.lights.push({ p: [p[0], p[1], p[2] + 1], color: f.color, intensity: 3.5 * env, range: 8 });
};
HD.FX_STEP.d_aura = function (d, f, age) {
  const u = age / f.life; if (u > 1) return; const p = bNow(d, f.b); const h = hOf(d, f.b); const a = d.act[f.b]; const env = Math.min(1, u * 5, (1 - u) * 4);
  if (a && f.glow * env > a.glow[3]) a.glow = [f.color[0], f.color[1], f.color[2], f.glow * env];
  const nf = Math.floor(3 * f.rate + d.rng()), ne = Math.floor(2 * f.rate + d.rng());   // fractional rates: sparse
  if (nf) d.emit(PS.fireBody, [p[0], p[1] - h * 0.3, p[2]], nf, { ramp: f.ramp, scale: h * 0.32, radius: h * 0.32 });
  if (ne) d.emit(PS.energy, p, ne, { ramp: f.ramp, radius: h * 0.4, vel: [0, h * 0.6, 0] });
};
// a shockwave of dragon energy on a battler (the impact of a dragon move): ring, flare, sparks, light
