  d.addFx('ring', { p: c.slice(), cell: 'ring', r0: h * 0.15, r1: h * 0.9 * k, width: 0.08, color: col, intensity: 1.0, life: 0.26, add: 0.6, distort: 1.0 });
  d.addFx('ring', { p: [c[0], 0.17, c[2]], cell: 'ring', r0: h * 0.2, r1: h * 1.3 * k, width: 0.08, color: col, intensity: 0.9, life: 0.32, add: 0.6, ground: true, distort: 0.6 });
  d.addFx('card', { p: c.slice(), cell: 'flare', size0: h * 0.4 * k, size1: h * 1.0 * k, color: col, intensity: 1.0, life: 0.2, add: 1 });
  d.emit(PS.d_spark, c, 18, { scale: 1.2 * k }); d.emit(PS.fireBody, c, 8, { ramp: 'd_dragon', scale: h * 0.3 * k, speedMul: 2 });
  d.addFx('lightpulse', { p: c.slice(), color: col, intensity: 8 * k, range: 10, life: 0.3 });
