// a twisting funnel (Twister, Sand Tomb...): helical bands round a battler, narrow at the ground and wide at the top,
// the bands behind the battler drawn behind it; debris and streaks are the script's own sprites
// { b, dur, color, color2, height, r0, r1, n, spin, cell, alpha, add, release (frame the funnel bursts outward) }
HD.MOVE_FX.d_funnel = (d, e) => { const b = d.battlerRef(e.b || 'target'); if (!present(d, b)) return; d.addFx('d_funnel', { b, life: (e.dur || 100) / FPS, color: e.color || [0.6, 0.5, 1], color2: e.color2 || [0.35, 0.3, 0.7], height: e.height || 1.9, r0: e.r0 || 0.25, r1: e.r1 || 0.85, n: e.n || 4, spin: e.spin || 7, cell: e.cell || 'trail', alpha: e.alpha || 0.7, add: e.add != null ? e.add : 1, body: e.body || null, burst: e.burst || 0 }); };
HD.FX.d_funnel = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const ft = feetOf(d, f.b); const h = hOf(d, f.b); const env = Math.min(1, u * 6, (1 - u) * 5);
  const burst = f.burst ? HD.smooth((age - (f.life - f.burst)) / f.burst) : 0; const cam = HD.GBA_CAM.pos; const towardCam = (q) => (q[0] - ft[0]) * (cam[0] - ft[0]) + (q[2] - ft[2]) * (cam[2] - ft[2]) > 0;
  for (let k = 0; k < f.n; k++) {
    const pts = []; const widths = []; const ph = k / f.n * TAU;
    for (let i = 0; i <= 26; i++) { const t = i / 26; const r = h * (f.r0 + (f.r1 - f.r0) * Math.pow(t, 1.15)) * (1 + burst * 0.8); const a = ph + age * f.spin + t * 5.5 * Math.sign(f.spin); pts.push([ft[0] + Math.cos(a) * r, 0.2 + t * h * f.height, ft[2] + Math.sin(a) * r * 0.75]); widths.push(h * (0.05 + 0.12 * t)); }
    for (const run of HD.splitRuns(pts, towardCam, false)) { if (run.pts.length < 2) continue; const w = run.pts.map((q) => h * (0.07 + 0.16 * ((q[1] - 0.2) / (h * f.height)))); out.ribbons.push({ pts: run.pts, widths: w, width: h * 0.15, cell: f.cell, color: run.f ? f.color : f.color2, intensity: 1.05, alpha: f.alpha * env * (1 - burst) * (run.f ? 1 : 0.8), add: f.add, back: !run.f, scroll: age * 3 }); }
  }
  if (f.body) out.cards.push({ p: [ft[0], h * f.height * 0.45, ft[2] - 0.2], back: true, cell: 'smoke1', size: [h * (f.r1 + 0.3) * 2, h * f.height * 1.1], rot: age * 2, color: f.body, alpha: 0.32 * env * (1 - burst), add: 0, intensity: 1 });
};
HD.FX_STEP.d_funnel = function (d, f, age) {
  const u = age / f.life; if (u > 1) return; const ft = feetOf(d, f.b); const h = hOf(d, f.b); const r = d.rng;
  if (d.frame % 2 === 0) { const a = r() * TAU; const t = r(); const rr = h * (f.r0 + (f.r1 - f.r0) * t); d.emit(PS.windStreak, [ft[0] + Math.cos(a) * rr, 0.3 + t * h * f.height, ft[2] + Math.sin(a) * rr * 0.7], 1, { dir: [-Math.sin(a), 0.3, Math.cos(a) * 0.7], spread: 0.1, ramp: f.ramp || 'wind', scale: 1.2 }); }
  if (d.frame % 3 === 0) d.emit(PS.d_dust, [ft[0] + r.range(-0.4, 0.4) * h, 0.2, ft[2]], 1, { dir: [r.range(-1, 1), 0.3, 0], spread: 0.4, scale: 1.2 });
};

