// ------------------------------------------------------------------ ancient power: rune-lit stones that rise round the user, then fly at the target
// each stone the runtime raises (fewer are drawn) launches when its sprite goes, on an arc that lands on the script's hit
K.d_ancient = {
  init(d, it, cfg) { K.d_rock.init(d, it, cfg); it.s.show = it.uid % 3 !== 0; },
  update(d, it, cfg) {
    if (!it.s.show) return; K.d_rock.update(d, it, cfg); const h = hOf(d, d.atkB()); const sz = h * (cfg.v3size || 0.13) * it.s.k;
    it.cards.push({ fixed: true, p: it.p.slice(), cell: 'dot', size: [sz * 4, sz * 4], color: cfg.glowColor || [1, 0.62, 0.25], alpha: 0.4 * it.alpha * (0.8 + 0.2 * Math.sin(it.age * 9 + it.uid)), add: 1, intensity: 1.1 });
    const n = KH.every(it, 'am', 6); if (n) d.emit(PS.d_ember, it.p, n, { scale: 0.8 });
  },
  end(d, it, cfg) {
    if (!it.s.show) return; const hit = d.plan ? d.plan.hits.find((x) => x.f > d.frame + 2) : null; if (!hit) return;
    const h = hOf(d, d.atkB()); const r = HD.rng(it.uid * 17 + 3); const tgt = d.bpos(d.tgtB()); const ht = hOf(d, d.tgtB());
    d.addFx('d_hurl', { from: it.p.slice(), to: [tgt[0] + r.range(-0.3, 0.3) * ht, tgt[1] + r.range(-0.25, 0.2) * ht, tgt[2] + 0.2], f0: d.frame, f1: hit.f + Math.round(r.range(-2, 1)), size: h * (cfg.v3size || 0.13) * it.s.k, col: it.s.col, rot0: it.s.rot0.slice(), spin: it.s.spin.map((x) => x * 2.5), arc: ht * r.range(0.5, 0.9), glow: cfg.glowColor || [1, 0.62, 0.25], life: (hit.f + 4 - d.frame) / FPS });
  }
};
HD.FX.d_hurl = function (d, f, age, out) {
  const fr = f.f0 + age * FPS; const u = (fr - f.f0) / Math.max(1, f.f1 - f.f0); if (u < 0 || u > 1) return; const e = u * u * (0.35 + 0.65 * u);
  const p = V.lerp([0, 0, 0], f.from, f.to, e); p[1] += Math.sin(Math.PI * e) * f.arc; f.hist = f.hist || []; 
  out.meshes.push({ kind: 'rock', p, size: f.size, rot: [f.rot0[0] + age * f.spin[0], f.rot0[1] + age * f.spin[1], f.rot0[2] + age * f.spin[2]], color: f.col });
  out.cards.push({ p, cell: 'dot', size: [f.size * 4, f.size * 4], color: f.glow, alpha: 0.45, add: 1, intensity: 1.1 });
  const back = []; for (let k = 4; k >= 0; k--) { const ek = Math.max(0, e - k * 0.06); const q = V.lerp([0, 0, 0], f.from, f.to, ek); q[1] += Math.sin(Math.PI * ek) * f.arc; back.push(q); }
  out.ribbons.push({ pts: back, widths: back.map((_, i) => f.size * 1.6 * (i / (back.length - 1))), width: f.size * 1.6, cell: 'trail', color: f.glow, intensity: 1.1, alpha: 0.6, add: 1 });
};
HD.FX_STEP.d_hurl = function (d, f, age) { if (!f.done && d.frame >= f.f1) { f.done = true; d.emit(PS.d_pebble, f.to, 6, { scale: 1.3 }); d.emit(PS.d_dust, f.to, 2, { scale: 1.2 }); d.emit(PS.d_ember, f.to, 6, { scale: 1.2, speedMul: 2 }); } };
// a glyph ring glowing on the ground under a battler { b, dur, color, size }
HD.MOVE_FX.d_glyph = (d, e) => { const b = d.battlerRef(e.b || 'attacker'); if (!present(d, b)) return; d.addFx('d_glyph', { b, life: (e.dur || 60) / FPS, color: e.color || [1, 0.62, 0.25], size: e.size || 1.5 }); };
HD.FX.d_glyph = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const ft = feetOf(d, f.b); const h = hOf(d, f.b); const env = Math.min(1, u * 5, (1 - u) * 4); const s = h * f.size * (0.85 + 0.15 * HD.easeOut(Math.min(1, u * 4)));
  out.decals.push({ p: [ft[0], 0.16, ft[2]], cell: 'd_rune', size: [s, s], rot: age * 0.6, color: f.color, alpha: 0.85 * env, add: 1, intensity: 1.3, mode: 2 });
  out.decals.push({ p: [ft[0], 0.158, ft[2]], cell: 'dot', size: [s * 1.1, s * 1.1], color: f.color, alpha: 0.3 * env, add: 1, intensity: 1, mode: 2 });
  out.lights.push({ p: [ft[0], 0.8, ft[2] + 0.6], color: f.color, intensity: 3 * env, range: 7 });
};
