  if (d.frame % 3 === 0) { const t = h * (0.55 + 1.5 * Math.min(1, u * 2)); const side = r.range(-0.6, 0.6) * h; const p = [A[0] + dir[0] * t - dir[2] * side, 0.25, A[2] + dir[2] * t + dir[0] * side]; d.emit(PS.d_clod, p, 2, { scale: 1.2 }); d.emit(PS.d_dust, p, 1, { scale: 1 }); }
