HD.FX.d_sandspray = function () {};
HD.FX_STEP.d_sandspray = function (d, f, age) {
  const u = age / f.life; if (u > 1) return; const A = d.atkB(), T = d.tgtB(); if (!present(d, A) || !present(d, T) || A === T) return; const r = d.rng;
  const a = bNow(d, A), t = bNow(d, T); const ht = hOf(d, T); const p0 = V.lerp([0, 0, 0], a, t, 0.08); const p1 = [t[0], t[1] + ht * 0.15, t[2]]; const tf = 0.3;
  const v0 = [(p1[0] - p0[0]) / tf, (p1[1] - p0[1]) / tf + 2, (p1[2] - p0[2]) / tf];
  for (let i = 0; i < 6; i++) d.emit(PS.d_grit, [p0[0] + r.range(-0.2, 0.2), p0[1] + r.range(-0.15, 0.2), p0[2]], 1, { vel: [v0[0] * r.range(0.85, 1.1), v0[1] + r.range(-1, 1.5), v0[2] * r.range(0.85, 1.1)], scale: 2.6 });
  d.emit(PS.d_sandstreak, p0, 1, { vel: v0, scale: 2.4 });
  if (d.frame % 2 === 0) { const q = V.lerp([0, 0, 0], p0, p1, r.range(0.2, 0.8)); d.emit(PS.d_dust, q, 1, { vel: [v0[0] * 0.25, 0.4, v0[2] * 0.25], scale: 0.9, ramp: 'd_grit' }); }
};
// a sandstorm sweeping the field: streaks of driven sand, grit and dust banks all blowing one way { dur, dir }
