    it.mesh = { kind: 'ice', p, size: sz, scale: [1.7, 0.95, 1.8], rot: [it.s.rot0[0] + a * 9, it.s.rot0[1] + a * 2, it.s.rot0[2] + a * 6], color: [0.88, 0.96, 1] };
    it.cards.push({ fixed: true, p, cell: 'dot', size: [sz * 3.4, sz * 3.4], color: [0.55, 0.82, 1], alpha: 0.22 * it.alpha, add: 1, intensity: 1 });
    if (V.len(it.v) > 1.5) { const n = KH.every(it, 's', 30); if (n) d.emit(PS.snowFlake, p, n, { vel: V.scale([0, 0, 0], it.v, -0.1) }); const m = KH.every(it, 'm', 10); if (m) d.emit(PS.snowPuff, p, m, { scale: sz * 1.2, vel: V.scale([0, 0, 0], it.v, -0.05) }); if (it.hist.length > 2) { const pts = it.hist.slice(-6).concat([p]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 1.4 * (i / (pts.length - 1))), width: sz * 1.4, cell: 'trail', color: [0.75, 0.9, 1], intensity: 0.9, alpha: 0.45, add: 1 }); } }
    if (Math.floor(a * FPS + it.uid) % 14 === 0) d.addFx('card', { p: V.add([0, 0, 0], p, [0, sz * 0.6, 0.2]), cell: 'star4', size0: sz * 1.8, size1: sz * 0.3, color: [0.9, 0.97, 1], intensity: 1.8, life: 0.22, add: 1 });
    d.light(p, [0.6, 0.85, 1], 0.9, 6, 'ice');
