    it.cards.push({ fixed: true, p: [c[0], c[1], c[2] + 0.35], cell: 'frost', size: [h * 1.2, h * 1.2], rot: it.uid, color: [0.85, 0.95, 1], alpha: 0.3 * g, add: 1, intensity: 1 });
