HD.FX.d_coldbeam = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const A = bNow(d, d.atkB()), T = bNow(d, d.tgtB()); const head = Math.min(1, u * 2.2); const tail = Math.max(0, (u - 0.6) / 0.4); const pts = [];
  for (let i = 0; i <= 10; i++) { const t = tail + (head - tail) * i / 10; const q = V.lerp([0, 0, 0], A, T, t); q[1] += Math.sin(t * Math.PI) * 0.6 + Math.sin(t * 9 + age * 12) * 0.12; pts.push(q); }
  out.ribbons.push({ pts, width: hOf(d, d.tgtB()) * 0.32, cell: 'smoke', color: [0.85, 0.94, 1], intensity: 1.05, alpha: 0.8, add: 0.2, scroll: age * 4 });
  out.ribbons.push({ pts, width: hOf(d, d.tgtB()) * 0.12, cell: 'energy', color: f.color, intensity: 1.1, alpha: 0.8, add: 1, scroll: age * 6 });
};
HD.FX_STEP.d_coldbeam = function (d, f, age) { const u = age / f.life; if (u > 1) return; const A = bNow(d, d.atkB()), T = bNow(d, d.tgtB()); const t = Math.min(1, u * 2.2) * d.rng(); d.emit(PS.frost, V.lerp([0, 0, 0], A, T, t), 3, { scale: 1.2 }); };

