    if (V.len(it.v) > 2 && it.hist.length > 2) { const pts = it.hist.slice(-4).concat([p]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 0.9 * (i / (pts.length - 1))), width: sz, cell: 'trail', color: col, intensity: 1.1, alpha: 0.5, add: 1 }); }
