    debris(d, { p: c, n: 9, size: [h * 0.04, h * 0.07], speed: [2, 4], up: [3, 6], life: 1, kind: 'd_gem', colors: [f.color, [0.95, 0.9, 1]], dust: false }); d.emit(PS.glint, c, 20, { ramp: 'pink', radius: h * 0.3, speedMul: 2 });
