// stone panels raised across the ally side (Wide Guard): each runtime tile raises one slab in a low wall in front of the
// user (the user stays visible behind it); amber seams; the wall shimmers when it locks in
K.d_panel = {
  init(d, it) { const s = it.s; needMeshes(d); const k = (d.v3.dPanel = (d.v3.dPanel || 0) + 1) - 1; const A = feetOf(d, d.atkB()), T = feetOf(d, d.tgtB() === d.atkB() ? d.atkB() ^ 1 : d.tgtB()); const h = hOf(d, d.atkB()); const r = HD.rng(it.uid * 389 + 5);
    // a wide wall across the user's side, facing the camera, a little beyond the user toward the foes (the user stands in front of it)
    // 4 slabs each side of the user (it stays clear in the middle, where the wall is a translucent amber sheet)
    const j = k % 8; const sx = (j < 4 ? -1 : 1) * (0.86 + (j < 4 ? 3 - j : j - 4) * 0.27); const row = Math.floor(k / 8) % 2; const c = V.lerp([0, 0, 0], A, T, 0.12); s.c = c; s.p = [c[0] + sx * h, 0, c[2] + r.range(-0.05, 0.05)]; s.row = row; s.h = h; s.t0 = d.t; s.first = k === 0;
    s.rot = [r.range(-0.08, 0.08), r.range(-0.18, 0.18), r.range(-0.07, 0.07)]; s.k = r.range(0.92, 1.1); s.col = pickCol(r, [[0.3, 0.24, 0.17], [0.26, 0.21, 0.16], [0.33, 0.26, 0.18]], 0.04);
    d.emit(PS.d_dust, [s.p[0], 0.2, s.p[2]], 3, { scale: 1 }); d.emit(PS.d_pebble, [s.p[0], 0.2, s.p[2]], 2); },
  update(d, it) { const s = it.s; const g = HD.easeOut(Math.min(1, (d.t - s.t0) / 0.25)); const hh = s.h * 0.27 * s.k; const y = hh * 0.66 * (1 + s.row * 2) * g - (1 - g) * hh;
    it.mesh = { kind: 'boulder', p: [s.p[0], 0.1 + y, s.p[2]], size: hh, scale: [0.95, 1.3, 0.4], rot: s.rot, color: s.col };
    if (s.first) { const k2 = HD.smooth(Math.min(1, (d.t - s.t0) / 1.2)); const lk = d.v3.dPanelLock ? Math.max(0, 1 - (d.t - d.v3.dPanelLock) / 0.6) : 0;   // the sheet across the middle
      for (let rr = 0; rr < 2; rr++) for (let cc = -2; cc <= 2; cc++) it.cards.push({ fixed: true, p: [s.c[0] + cc * s.h * 0.29, 0.1 + s.h * (0.19 + rr * 0.36), s.c[2]], cell: 'hex', size: [s.h * 0.36, s.h * 0.36], color: [1, 0.72, 0.36], alpha: (0.16 + 0.1 * Math.sin(d.t * 5 + cc + rr * 2) + 0.4 * lk) * k2, add: 0.7, intensity: 1 }); }
    const lock = d.v3.dPanelLock ? Math.max(0, 1 - (d.t - d.v3.dPanelLock) / 0.5) : 0; const pul = 0.5 + 0.5 * Math.sin(d.t * 6 + s.p[0]);
    it.cards.push({ fixed: true, p: [s.p[0], 0.1 + y, s.p[2] - 0.15], cell: 'dot', size: [hh * 3.4, hh * 3], color: [1, 0.68, 0.3], alpha: (0.22 + 0.15 * pul + 0.5 * lock) * g, add: 1, intensity: 1, back: true }); }
};
HD.MOVE_FX.d_panellock = (d) => { d.v3.dPanelLock = d.t; const A = feetOf(d, d.atkB()); d.addFx('lightpulse', { p: [A[0], 1.5, A[2] + 1], color: [1, 0.7, 0.35], intensity: 6, range: 10, life: 0.5 }); d.emit(PS.glint, [A[0], 1, A[2] + 1], 16, { ramp: 'gold', radius: 2 }); };


