    for (let i = 0; i <= 8; i++) { const t = i / 8; const q = V.lerp([0, 0, 0], a0, b, t); q[1] -= Math.sin(Math.PI * t) * h * 0.12; pts.push(q); }
    it.cards.push({ layer: 'ribbons', fixed: true, pts, width: h * 0.025, cell: 'beam', color: [0.95, 0.97, 1], intensity: 1.1, alpha: 0.85 * it.alpha, add: 0.6 });
