// ------------------------------------------------------------------ Zygarde moves (Thousand Arrows, Thousand Waves, Land's Wrath): green earth energy, arrowheads, a rolling wave of earth
// an energy arrowhead riding the runtime's sprite, pointing along its motion; the falling ones strike the ground (green burst,
// dust, a crack) and hit a foe they land on. cfg: fall (strikes on landing), foeSideOnly, color
// a rain of energy arrows diving onto the foe side (Thousand Arrows), filling in between the runtime's own arrows
// { dur, every (frames), spread (battler heights round each foe) }
HD.MOVE_FX.d_arrowrain = (d, e) => d.addFx('d_arrowrain', { life: (e.dur || 160) / FPS, every: e.every || 3, spread: e.spread || 1.4, arrows: [] });
HD.FX.d_arrowrain = function (d, f, age, out) {
  const pose = V3.pointAlong(-Math.PI / 2);
  for (const a of f.arrows) { const u = (age - a.t0) / a.dur; if (u < 0 || u > 1) continue; const y = 0.25 + (a.y0 - 0.25) * (1 - u * u); const p = [a.p[0], y, a.p[2]];
    out.cards.push({ p, cell: 'd_arrow', size: [a.sz, a.sz], rot: pose.rot, flip: pose.flip, color: [0.75, 1, 0.75], alpha: 1, add: 0.6, intensity: 1.3 });
    out.ribbons.push({ pts: [[p[0], y + a.sz * 0.3, p[2]], [p[0], y + a.sz * 2.6, p[2]]], width: a.sz * 0.28, cell: 'trail', color: [0.45, 1, 0.5], intensity: 1.1, alpha: 0.7, add: 1 }); }
};
HD.FX_STEP.d_arrowrain = function (d, f, age) {
  const u = age / f.life; const r = d.rng;
  if (u < 0.92 && d.frame % f.every === 0) { const fs = foes(d); if (fs.length) { const b = fs[Math.floor(r() * fs.length)]; const ft = feetOf(d, b); const h = hOf(d, b);
    f.arrows.push({ t0: age, dur: 0.17, p: [ft[0] + r.range(-1, 1) * h * f.spread, 0, ft[2] + r.range(-0.6, 0.5) * h], y0: h * 3.2, sz: h * r.range(0.26, 0.34), b, landed: false }); } }
  for (const a of f.arrows) { if (a.landed || age - a.t0 < a.dur) continue; a.landed = true; const p = a.p; const h = hOf(d, a.b);
    d.emit(PS.energy, [p[0], 0.3, p[2]], 5, { ramp: 'nature', speedMul: 1.4 }); d.emit(PS.d_dust, [p[0], 0.2, p[2]], 2, { scale: 0.9 });
    d.addFx('ring', { p: [p[0], gy(d, p, 0.01), p[2]], cell: 'ring', r0: h * 0.08, r1: h * 0.45, width: 0.05, color: [0.45, 1, 0.5], intensity: 1, life: 0.22, add: 1, ground: true }); }
  if (f.arrows.length > 40) f.arrows = f.arrows.filter((a) => !a.landed || age - a.t0 < a.dur);
};
K.d_arrowkit = {
  init(d, it, cfg) { if (!HD.onScreen(it.rec)) { it.s.skip = true; return; } if (cfg.foeSideOnly) { const ti = V3.trackInfo(d, it.uid); if (ti) { const A = d.space.gba[d.atkB()], T = d.space.gba[d.tgtB()]; if (Math.abs(ti.x1 - A[0]) < Math.abs(ti.x1 - T[0])) it.s.skip = true; } } },
  update(d, it, cfg) {
    if (it.s.skip) return; const h = hOf(d, d.tgtB()); const sz = h * (cfg.v3size || 0.32); const col = cfg.color || [0.45, 1, 0.5]; const vd = V3.toScr(it.v); const ang = Math.hypot(vd[0], vd[1]) > 0.5 ? Math.atan2(vd[1], vd[0]) : (cfg.fall ? -Math.PI / 2 : Math.PI / 2); const pose = V3.pointAlong(ang);
    it.cards.push({ fixed: true, p: it.p.slice(), cell: 'd_arrow', size: [sz * 1.25, sz * 1.25], rot: pose.rot, flip: pose.flip, color: col, alpha: 0.4 * it.alpha, add: 1, intensity: 1 });
    it.cards.push({ fixed: true, p: it.p.slice(), cell: 'd_arrow', size: [sz, sz], rot: pose.rot, flip: pose.flip, color: [0.75, 1, 0.75], alpha: it.alpha, add: 0.6, intensity: 1.3 });
    if (it.hist.length > 2) { const pts = it.hist.slice(-5).concat([it.p.slice()]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 0.3 * (i / (pts.length - 1))), width: sz * 0.3, cell: 'trail', color: col, intensity: 1.2, alpha: 0.7, add: 1 }); }
  },
  end(d, it, cfg) {
    if (it.s.skip || !cfg.fall) return; const p = [it.p[0], 0, it.p[2]]; const h = hOf(d, d.tgtB());
    d.emit(PS.energy, [p[0], 0.3, p[2]], 8, { ramp: 'nature', speedMul: 1.6 }); d.emit(PS.d_dust, [p[0], 0.2, p[2]], 3, { scale: 1.1 }); d.emit(PS.d_pebble, [p[0], 0.2, p[2]], 3);
    d.addFx('ring', { p: [p[0], gy(d, p, 0.01), p[2]], cell: 'ring', r0: h * 0.1, r1: h * 0.6, width: 0.06, color: [0.45, 1, 0.5], intensity: 1.1, life: 0.25, add: 1, ground: true });
    if (d.rng() < 0.5) crack(d, p, h * 0.8, { life: 1.2 });
    const nb = d.space.nearestBattler([it.p[0], h * 0.5, it.p[2]]); if (nb.b >= 0 && (nb.b & 1) !== (d.atkB() & 1) && nb.d < h * 1.2 && !d.status) { d.impact({ b: nb.b, strength: d.strength * 0.7, minGap: 10, burstScale: 0.5 }); d.synthDone = true; }
  }
};
// a rolling wave of earth crawling along the ground from the user to the target (Thousand Waves) { dur, travel }
HD.MOVE_FX.d_earthwave = (d, e) => d.addFx('d_earthwave', { life: (e.dur || 60) / FPS, travel: e.travel || 30, color: e.color || [0.45, 1, 0.5] });
HD.FX.d_earthwave = function (d, f, age, out) {
  const fr = age * FPS; const A = feetOf(d, d.atkB()), T = feetOf(d, d.tgtB()); const t = Math.min(1, fr / f.travel); if (t >= 1 && fr > f.travel + 12) return; const h = hOf(d, d.tgtB());
  const c = V.lerp([0, 0, 0], A, T, t); const dir = V.norm([0, 0, 0], V.sub([0, 0, 0], T, A)); const side = [-dir[2], 0, dir[0]]; const pts = [];
  for (let i = -4; i <= 4; i++) pts.push([c[0] + side[0] * i * h * 0.22, h * (0.3 - 0.02 * i * i) * (t < 1 ? 1 : 1 - (fr - f.travel) / 12), c[2] + side[2] * i * h * 0.22]);
  out.ribbons.push({ pts, width: h * 0.45, cell: 'smoke', color: [0.55, 0.42, 0.3], intensity: 1, alpha: 0.85, add: 0 });
  out.ribbons.push({ pts: pts.map((q) => [q[0], q[1] + h * 0.15, q[2]]), width: h * 0.12, cell: 'energy', color: f.color, intensity: 1.1, alpha: 0.7, add: 1, scroll: age * 4 });
};
HD.FX_STEP.d_earthwave = function (d, f, age) {
  const fr = age * FPS; if (fr > f.travel) { if (!f.hit) { f.hit = true; const ft = feetOf(d, d.tgtB()); dustRing(d, ft, 14, 2.2, 1.4); debris(d, { p: [ft[0], 0.2, ft[2] + 0.3], n: 7, size: [0.12, 0.26], speed: [1, 3], up: [5, 9], life: 1.2 }); d.shake(0.4); } return; }
  const A = feetOf(d, d.atkB()), T = feetOf(d, d.tgtB()); const c = V.lerp([0, 0, 0], A, T, fr / f.travel); const h = hOf(d, d.tgtB());
  d.emit(PS.d_plume, [c[0], 0.3, c[2]], 2, { scale: h * 0.32, radius: h * 0.4, vel: [0, h * 1.2, 0] }); d.emit(PS.d_clod, [c[0], 0.3, c[2]], 3, { scale: 1.3 }); if (d.frame % 3 === 0) crack(d, c, h * 1.1, { life: 1.6, open: 0.1 });
};

