function d2lob(d, o) { const r = d.rng; return d.addFx('d2_lob', Object.assign({ life: (o.f1 - o.f0 + 3) / FPS, rot0: [r() * 6, r() * 6, r() * 6], spin: [r.range(3, 6), r.range(1, 3), r.range(2, 5)] }, o)); }
HD.d2_lob = d2lob;

// Rock Throw: each rock the runtime drops on the target is thrown by the user instead: it leaves the user's side on the
