    const h = hOf(d, d.atkB()); const r = HD.rng(it.uid * 17 + 3); const tgt = d.bpos(d.tgtB()); const ht = hOf(d, d.tgtB());
    d2lob(d, { from: it.p.slice(), to: [tgt[0] + r.range(-0.3, 0.3) * ht, tgt[1] + r.range(-0.2, 0.15) * ht, tgt[2] + 0.35], f0: d.frame, f1: hit.f + Math.round(r.range(-2, 1)), size: h * (cfg.v3size || 0.17) * it.s.k, col: it.s.col,
      rot0: it.s.rot0.slice(), spin: it.s.spin.map((x) => x * 2.5), arc: ht * r.range(0.35, 0.65), trail: 'amber', ribbon: [0.66, 0.48, 0.3], ribbonAlpha: 0.4, ease: 'in', land: 'shatter', shadow: false });
