    if (d.frame < s.landF) { const a = it.age; it.mesh = { kind: 'd2_stone', p: it.p.slice(), size: sz * 0.8, scale: [0.7, 1.25, 0.7], rot: [s.rot0[0] + a * s.spin[0], s.rot0[1] + a * s.spin[1], s.rot0[2] + a * s.spin[2]], color: s.col };
      if (it.hist.length > 2 && V.len(it.v) > 2) { const pts = it.hist.slice(-5).concat([it.p.slice()]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 0.9 * (i / (pts.length - 1))), width: sz, cell: 'smoke', color: [0.66, 0.54, 0.4], intensity: 1, alpha: 0.45, add: 0 }); }
      return; }
