  const p = scrOff(c, -face(d, f.b) * h * 0.12, h * (f.y + 0.06 * HD.smooth(u) + 0.02 * Math.sin(age * 3))); p[2] -= 0.8; drawFace(out.cards, p, h * f.size * (0.9 + 0.1 * HD.smooth(u * 3)), k, f.color);
