function fieldSpots(d, f, n) {   // seeded points over the field, ordered outward from the user (the terrain spreads from it)
  if (f.spots) return f.spots; const r = HD.rng(f.seed); const o = d.space.feet[f.from]; const s = [];
  for (let i = 0; i < n; i++) { const p = [r.range(-12, 14), 0, r.range(-15, 7)]; s.push({ p, d: Math.hypot(p[0] - o[0], p[2] - o[2]), r: r(), q: r() }); }
  for (let b = 0; b < 4; b++) if (here(d, b)) { const ft = d.space.feet[b]; for (let j = 0; j < 3; j++) { const p = [ft[0] + r.range(-1.6, 1.6), 0, ft[2] + r.range(-0.8, 1.0)]; s.push({ p, d: Math.hypot(p[0] - o[0], p[2] - o[2]), r: r(), q: r() }); } }
  s.sort((a, b) => a.d - b.d); f.spots = s; f.maxD = s[s.length - 1].d || 1; return s;
}
HD.FX.e_field = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.08, 0.2); const o = d.space.feet[f.from]; const spread = HD.easeOut(Math.min(1, u * 2.2));
  if (f.field === 'grass') {
    const S = fieldSpots(d, f, 34);
    out.decals.push({ p: [o[0] + (1 - o[0]) * spread * 0.6, 0.025, o[2] * (1 - spread * 0.6)], cell: 'dot', size: [6 + 34 * spread, 4 + 24 * spread], color: [0.45, 1, 0.3], alpha: 0.4 * k, add: 1, intensity: 0.9, mode: 2 });
    for (const sp of S) { const g = HD.easeOut(clamp((spread * f.maxD - sp.d) / 2.5, 0, 1)) * k; if (g <= 0.01) continue; const s = 1.5 + sp.r * 1.4; const sway = Math.sin(age * 2.2 + sp.r * 6) * 0.08;
      out.cards.push({ p: [sp.p[0], s * 0.42 * g, sp.p[2]], cell: 'e_grass', size: [s, s * g], rot: sway, color: [0.3 + sp.q * 0.15, 0.78 + sp.r * 0.15, 0.25], alpha: g, add: 0, intensity: 1 });
      if (sp.q > 0.5) out.cards.push({ p: [sp.p[0] + 0.15, s * 0.78 * g, sp.p[2] + 0.05], cell: 'star5', size: [0.62 * g, 0.62 * g], rot: sp.r * 3, color: sp.r > 0.5 ? [1, 0.6, 0.8] : [1, 0.92, 0.45], alpha: g, add: 0.15, intensity: 1.1 }); }
  } else if (f.field === 'misty') {
    const S = fieldSpots(d, f, 16);
    for (const sp of S) { const g = HD.smooth(clamp((spread * f.maxD - sp.d) / 4, 0, 1)) * k; if (g <= 0.01) continue; const x = sp.p[0] + Math.sin(age * 0.4 + sp.r * 6) * 0.8;
      out.cards.push({ p: [x, 0.5 + sp.q * 0.6, sp.p[2]], cell: 'cloud', size: [3.2 + sp.r * 2.4, 1.3 + sp.q * 0.7], rot: sp.r * 0.3 - 0.15, color: [1, 0.5, 0.8], alpha: 0.55 * g, add: 0.15, intensity: 1.05 }); }
    out.decals.push({ p: [1, 0.025, -4], cell: 'dot', size: [36 * spread, 26 * spread], color: [1, 0.7, 0.9], alpha: 0.28 * k, add: 1, intensity: 0.9, mode: 2 });
  } else if (f.field === 'electric') {
    const S = fieldSpots(d, f, 18); const fr = Math.floor(age * FPS / 2);
    out.decals.push({ p: [1, 0.025, -4], cell: 'dot', size: [34 * spread, 24 * spread], color: [1, 0.88, 0.3], alpha: 0.26 * k * (0.85 + 0.15 * Math.sin(age * 17)), add: 1, intensity: 1, mode: 2 });
    for (let i = 0; i < S.length; i++) { const sp = S[i]; if (sp.d > spread * f.maxD) continue; if ((fr + i) % 3) continue; const a = sp.r * 6.283 + fr * 0.7; const L = 1.4 + sp.q * 1.8;
      const p0 = [sp.p[0], 0.08, sp.p[2]], p1 = [sp.p[0] + Math.cos(a) * L, 0.08, sp.p[2] + Math.sin(a) * L * 0.6]; HD.boltRibbons(p0, p1, (f.seed + i * 977 + fr * 131) | 0, 0.05, [1, 0.9, 0.35], 2.2 * k, 1, out, 0.3); }
  }
};
HD.FX_STEP.e_field = function (d, f, age) {
  const u = age / f.life; if (u > 0.9) return; const r = d.rng;
  if (f.field === 'grass') { if (d.frame % 3 === 0) d.emit(PS.leafBit, [r.range(-10, 12), 0.3, r.range(-13, 5)], 1, { vel: [0, 1.5, 0], scale: 1.3 }); if (d.frame % 4 === 0) for (let b = 0; b < 4; b++) if (here(d, b)) { const ft = d.space.feet[b]; d.emit(PS.e_mote, [ft[0], 0.2, ft[2]], 1, { ramp: 'heal', radius: hgt(d, b) * 0.6, vel: [0, 1.2, 0], scale: 1.1 }); } }
  else if (f.field === 'misty') { if (d.frame % 3 === 0) d.emit(PS.e_sparkle, [r.range(-10, 12), r.range(0.3, 1.5), r.range(-13, 5)], 1, { ramp: 'fairy', scale: 1.2 }); }
  else if (f.field === 'electric') { if (d.frame % 2 === 0) for (let b = 0; b < 4; b++) if (here(d, b)) { const ft = d.space.feet[b]; d.emit(PS.spark, [ft[0] + r.range(-1, 1), 0.15, ft[2] + r.range(-0.6, 0.6)], 2, { scale: 1.0 }); } }
};

// ================================================================== Gravity: the field's weight slams down on every battler
// flat indigo pressure rings drop from above each battler and slam into the ground (accelerating, not rain-like streaks),
// the ground dents and cracks under the feet, the battlers are squashed down and dust is pushed out sideways
HD.MOVE_FX.e_grav = (d, e) => d.addFx('e_grav', { life: (e.dur || 60) / FPS, color: e.color || [0.62, 0.45, 1] });
HD.FX.e_grav = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.1, 0.25); const cr = HD.easeOut(Math.min(1, u * 2.2));
  for (let b = 0; b < 4; b++) {
    if (!here(d, b)) continue; const ft = d.space.feet[b]; const h = hgt(d, b); const front = camSide(bnow(d, b));
    for (let i = 0; i < 3; i++) { const ph = (age * 1.5 + i / 3) % 1; const y = h * 1.45 * (1 - ph * ph); const R = h * (0.5 + 0.3 * ph); const w = Math.sin(Math.PI * Math.min(1, ph * 1.15)) * k; const pts = [];
      for (let j = 0; j <= 28; j++) { const a = j / 28 * Math.PI * 2; pts.push([ft[0] + Math.cos(a) * R, y, ft[2] + Math.sin(a) * R * 0.55]); }
      for (const run of HD.splitRuns(pts, front, true)) { if (run.pts.length < 2) continue;
        out.ribbons.push({ pts: run.pts, width: h * 0.12, cell: 'boltglow', color: f.color, intensity: 0.5 * w, add: 1, back: !run.f });
        out.ribbons.push({ pts: run.pts, width: h * 0.035, cell: 'beam', color: [0.86, 0.8, 1], intensity: 0.9 * w, add: 1, back: !run.f }); } }
    out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 2.2, h * 1.3], color: [0.06, 0.02, 0.12], alpha: 0.55 * k, add: 0, intensity: 1, mode: 2 });
    out.decals.push({ p: [ft[0], 0.035, ft[2]], cell: 'crack', size: [h * 2.0 * cr, h * 1.25 * cr], rot: b * 1.3, color: [0.12, 0.06, 0.2], alpha: 0.85 * k, add: 0, intensity: 1, mode: 2 });
    out.decals.push({ p: [ft[0], 0.04, ft[2]], cell: 'ring', size: [h * 2.4 * (1.1 - 0.3 * cr), h * 1.45 * (1.1 - 0.3 * cr)], color: f.color, alpha: 0.5 * k, add: 1, intensity: 1.1, mode: 2 });
  }
};
HD.FX_STEP.e_grav = function (d, f, age) {
  const u = age / f.life; const k = env01(u, 0.1, 0.25); const slam = Math.pow(Math.max(0, Math.sin(age * Math.PI * 4.5)), 6);   // pressure pulses
  for (let b = 0; b < 4; b++) {
    if (!here(d, b)) continue; const a = d.act[b]; if (a) { const q = (0.07 + 0.06 * slam) * k; a.sy *= 1 - q; a.sx *= 1 + q * 0.7; }
    if (d.frame % 5 === b && u < 0.85) { const ft = d.space.feet[b]; const h = hgt(d, b); for (const s of [-1, 1]) d.emit(PS.dustPuff, [ft[0] + s * h * 0.45, 0.1, ft[2] - 0.3], 1, { dir: [s * 0.5, 0.05, 0], spread: 0.3, scale: 1.0, ramp: 'dust' }); }
  }
  if (slam > 0.9 && d.frame % 3 === 0) d.shake(0.04 * k);
};

// ================================================================== Acid Armor: the body melts into a glossy violet acid pool and re-forms
// a translucent acid coat sags over the battler and drips into a bubbling pool with specular glints; the pool draws back up
HD.MOVE_FX.e_acid = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e_acid', { b, life: (e.dur || 100) / FPS }); };
HD.FX.e_acid = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const c = bnow(d, f.b); const ft = d.space.feet[f.b];
  const melt = HD.smooth(clamp(u / 0.45, 0, 1)) * (1 - HD.smooth(clamp((u - 0.72) / 0.22, 0, 1))); const pool = HD.easeOut(clamp(u / 0.35, 0, 1)) * (1 - HD.smooth(clamp((u - 0.8) / 0.2, 0, 1)));
  const coat = Math.min(1, u * 6) * (1 - HD.smooth(clamp((u - 0.85) / 0.15, 0, 1)));
  const ch = h * (1 - 0.55 * melt); const cp = [c[0], ft[1] + ch * 0.5 + h * 0.02, c[2] + 0.35];
  out.cards.push({ p: cp, cell: 'goo', size: [h * (0.95 + 0.25 * melt), ch * 1.05], color: [0.55, 0.2, 0.85], alpha: 0.5 * coat, add: 0.15, intensity: 1.05 });
  out.cards.push({ p: scrOff(cp, -h * 0.2, ch * 0.22), cell: 'dot', size: [h * 0.16, h * 0.1], color: [1, 0.92, 1], alpha: 0.75 * coat, add: 1, intensity: 1.3 });
  const R = h * (0.6 + 0.9 * pool); const gp = [ft[0], 0.03, ft[2]];
  out.decals.push({ p: gp, cell: 'puddle', size: [R * 2, R * 1.2], color: [0.5, 0.16, 0.75], alpha: 0.8 * pool, add: 0.1, intensity: 1.05, mode: 2 });
  out.decals.push({ p: [gp[0] - R * 0.3, 0.035, gp[2] - R * 0.1], cell: 'dot', size: [R * 0.5, R * 0.18], color: [1, 0.85, 1], alpha: 0.45 * pool * (0.7 + 0.3 * Math.sin(age * 5)), add: 1, intensity: 1.2, mode: 2 });
  out.lights.push({ p: [ft[0], h * 0.4, ft[2] + 1], color: [0.7, 0.35, 1], intensity: 2.4 * Math.max(pool, coat), range: 7 });
};
HD.FX_STEP.e_acid = function (d, f, age) {
  const u = age / f.life; const h = hgt(d, f.b); const c = bnow(d, f.b); const ft = d.space.feet[f.b]; const r = d.rng;
  if (u < 0.5 && d.frame % 3 === 0) d.emit(PS.gooDrop, scrOff(c, r.range(-0.35, 0.35) * h, r.range(-0.1, 0.3) * h), 1, { ramp: 'sludgewave', scale: h / 3.5, vel: [0, -1, 0] });
  if (u > 0.15 && u < 0.85 && d.frame % 3 === 0) d.emit(PS.poisonBub, [ft[0] + r.range(-1, 1) * h * 0.8, 0.12, ft[2] + r.range(-0.5, 0.5) * h * 0.5], 1, { ramp: 'poison', scale: h / 3 });
};

// ================================================================== Defog: a fog bank over the foe's side is blown away by a gust from the user
HD.MOVE_FX.e_defog = (d, e) => d.addFx('e_defog', { life: (e.dur || 150) / FPS, a: d.atkB(), b: d.tgtB() });
HD.FX.e_defog = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const A = d.space.feet[f.a], B = d.space.feet[f.b]; const h = hgt(d, f.b); const r = HD.rng(f.seed);
  const blow = HD.easeIn(clamp((u - 0.25) / 0.5, 0, 1)); const kin = Math.min(1, u * 5);
  const dir = V.norm([0, 0, 0], [B[0] - A[0], 0, B[2] - A[2]]);
  for (let i = 0; i < 9; i++) { const ox = r.range(-1.6, 1.6) * h, oy = r.range(0.1, 0.9) * h, oz = r.range(-0.8, 0.6) * h; const push = blow * (6 + r() * 8);
    const p = [B[0] + ox + dir[0] * push, oy + blow * 1.5, B[2] + oz + dir[2] * push]; const a = 0.5 * kin * (1 - blow);
    if (a > 0.01) out.cards.push({ p, cell: 'cloud', size: [h * (1.0 + r() * 0.6) * (1 + blow), h * (0.55 + r() * 0.3)], rot: r.range(-0.2, 0.2), color: [0.86, 0.88, 0.9], alpha: a, add: 0, intensity: 1 }); }
  const gust = clamp((u - 0.2) / 0.55, 0, 1); if (gust > 0 && gust < 1) {
    for (let i = 0; i < 6; i++) { const t0 = (gust * 2.2 + i / 6) % 1; const y = h * (0.25 + 0.15 * i); const s0 = lerp3([A[0], y, A[2]], [B[0], y + h * 0.1, B[2]], Math.max(0, t0 - 0.25)), s1 = lerp3([A[0], y, A[2]], [B[0], y + h * 0.1, B[2]], t0);
      const mid = lerp3(s0, s1, 0.5); mid[1] += Math.sin(i * 2 + age * 6) * h * 0.08; const k = Math.sin(Math.PI * t0) * Math.sin(Math.PI * gust);
      out.ribbons.push(tapered([s0, mid, s1], h * 0.12, { cell: 'trail', color: [0.85, 0.95, 1], intensity: 0.9 * k, alpha: 0.8, add: 1 })); } }
};
HD.FX_STEP.e_defog = function (d, f, age) {
  const u = age / f.life; if (f.done || u < 0.72) return; f.done = true; const c = bnow(d, f.b); const h = hgt(d, f.b);   // the foe's barriers break: a glassy flicker and shards
  d.addFx('ring', { p: c.slice(), cell: 'hex', r0: h * 0.5, r1: h * 1.1, width: 0.2, color: [0.6, 0.85, 1], intensity: 1.2, life: 0.3, add: 1 });
  d.emit(PS.iceChip, c, 12, { radius: h * 0.4, scale: h / 3.5, speedMul: 1.6 }); d.addFx('e_shiver', { b: f.b, life: 0.3, amp: 2, freq: 40 });
};

// ================================================================== a rhythmic sway (Entrainment: the foe catches the user's dance)
HD.MOVE_FX.e_sway = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('e_sway', { b, life: (e.dur || 60) / FPS, amp: e.amp || 5, bpm: e.bpm || 150 }); };
HD.FX_STEP.e_sway = function (d, f, age) {
  const u = age / f.life; if (u < 0 || u > 1) return; const a = d.act[f.b]; if (!a) return; const k = Math.min(1, u * 5, (1 - u) * 4); const ph = age * f.bpm / 60 * Math.PI;
  a.fxOff[0] += Math.sin(ph) * f.amp * k; const bob = Math.abs(Math.cos(ph)); a.fxOff[1] -= bob * f.amp * 0.4 * k; a.sy *= 1 - 0.04 * (1 - bob) * k; a.sx *= 1 + 0.03 * (1 - bob) * k;
};

// ================================================================== rooms: three distinct enclosures (Trick Room twists, Wonder Room ripples, Magic Room seals the items' magic)
HD.MOVE_FX.e_room = (d, e) => d.addFx('e_room', { life: (e.dur || 130) / FPS, room: e.room || 'trick', color: e.color || [1, 0.45, 0.85] });
HD.FX.e_room = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = Math.min(1, u * 4, (1 - u) * 3); const g = HD.smooth(Math.min(1, u * 2.4)); const col = f.color;
  const cx = 1, cz = -4, hw = 12, hd = 10, H = 9 * g; const base = [[-hw, -hd], [hw, -hd], [hw, hd], [-hw, hd]];
  const tw = f.room === 'trick' ? (0.55 * (1 - g) + 0.12 * Math.sin(age * 1.5)) : 0;   // Trick Room: the ceiling turns against the floor (a twisted, bizarre box)
  const corner = (i, top) => { const [x, z] = base[i]; const a = top ? tw : -tw * 0.3; const ca = Math.cos(a), sa = Math.sin(a); return [cx + x * ca - z * sa, top ? H : 0.05, cz + x * sa + z * ca]; };
  const wave = f.room === 'wonder';
  const edge = (p, q, w) => { let pts = [p, q]; if (wave) { pts = []; for (let i = 0; i <= 12; i++) { const t = i / 12; const s = lerp3(p, q, t); s[1] += Math.sin(t * Math.PI * 3 + age * 5) * 0.25 * Math.sin(Math.PI * t); pts.push(s); } }
    out.ribbons.push({ pts, width: w * 3, cell: 'boltglow', color: col, intensity: 0.55 * k, add: 1 }); out.ribbons.push({ pts, width: w, cell: 'beam', color: [Math.min(1, col[0] + 0.3), Math.min(1, col[1] + 0.3), Math.min(1, col[2] + 0.3)], intensity: 0.85 * k, add: 1 }); };
  for (let i = 0; i < 4; i++) { const j = (i + 1) % 4; edge(corner(i, false), corner(j, false), 0.12); edge(corner(i, true), corner(j, true), 0.12); edge(corner(i, false), corner(i, true), 0.12); }
  if (f.room === 'trick') {   // a diamond lattice on the floor, turning
    for (let i = -4; i <= 4; i++) { for (const s of [1, -1]) { const a = Math.PI / 4 * s + age * 0.25; const L = 14; const c0 = [cx + i * 2.6 * Math.cos(a + Math.PI / 2), 0.04, cz + i * 2.6 * Math.sin(a + Math.PI / 2)];
      out.ribbons.push({ pts: [[c0[0] - Math.cos(a) * L, 0.04, c0[2] - Math.sin(a) * L], [c0[0] + Math.cos(a) * L, 0.04, c0[2] + Math.sin(a) * L]], width: 0.07, cell: 'beam', color: col, intensity: 0.45 * k, add: 1, back: true }); } }
    out.distort.push({ p: [cx, 3, cz], cell: 'swirl', size: [20, 20], strength: 0.18 * k, mode: 0 });
  } else if (f.room === 'wonder') {   // ripples spreading over the floor, two guard sigils trading places
    for (let i = 0; i < 3; i++) { const ph = (age * 0.45 + i / 3) % 1; out.decals.push({ p: [cx, 0.035, cz], cell: 'ring', size: [4 + ph * 26, 3 + ph * 19], color: col, alpha: 0.55 * k * (1 - ph), add: 1, intensity: 1.1, mode: 2 }); }
    const sw = HD.smooth(clamp((u - 0.3) / 0.4, 0, 1)); for (const s of [0, 1]) { const t = s ? sw : 1 - sw; const p = [cx - 5 + 10 * t, 4.2 + Math.sin(Math.PI * sw) * (s ? 1.5 : -1.5), cz + 2];
      obj(out.cards, p, { cell: 'e_kshield', ramp: s ? 'glass' : 'nacre', size: 2.2, alpha: k * 0.85, glow: col, glowA: 0.35 }); }
  } else {   // Magic Room: a rune circle on the floor; sparkles of held-item magic dim out
    out.decals.push({ p: [cx, 0.035, cz], cell: 'ring', size: [22 * g, 16 * g], rot: age * 0.2, color: col, alpha: 0.6 * k, add: 1, intensity: 1.1, mode: 2 });
    out.decals.push({ p: [cx, 0.03, cz], cell: 'hex', size: [18 * g, 13 * g], rot: -age * 0.15, color: col, alpha: 0.22 * k, add: 1, intensity: 1, mode: 2 });
    out.decals.push({ p: [cx, 0.034, cz], cell: 'reticle', size: [12 * g, 9 * g], rot: age * 0.35, color: col, alpha: 0.35 * k, add: 1, intensity: 1, mode: 2 });
  }
  out.lights.push({ p: [cx, H * 0.8, cz], color: col, intensity: 3 * k, range: 22 });
};
HD.FX_STEP.e_room = function (d, f, age) { if (f.room !== 'magic' || d.frame % 3) return; const r = d.rng; const u = age / f.life; d.emit(PS.e_sparkle, [r.range(-9, 11), r.range(0.5, 5), r.range(-12, 4)], 1, { ramp: 'gold', scale: 1.6 * (1 - u), vel: [0, -0.4, 0] }); };

// ================================================================== an eye of light opens above a battler (Mind Reader, Miracle Eye): opens, holds, blinks
HD.MOVE_FX.e_eyeopen = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e_eyeopen', { b, life: (e.dur || 60) / FPS, color: e.color || [1, 0.55, 0.95], size: e.size || 0.55, y: e.y != null ? e.y : 0.95 }); };
HD.FX.e_eyeopen = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const p = scrOff(bnow(d, f.b), 0, h * (f.y + 0.03 * Math.sin(age * 3))); p[2] += 0.4;
  const open = Math.min(HD.easeOut(clamp(age / 0.2, 0, 1)), u > 0.85 ? 1 - HD.smooth((u - 0.85) / 0.15) : 1); const s = h * f.size; const k = Math.min(1, age / 0.1);
  out.cards.push({ p, cell: 'flare', size: [s * 2.2, s * 1.6], color: f.color, alpha: 0.45 * k, add: 1, intensity: 1.1 });
  out.cards.push({ p, cell: 'eye3', size: [s * 1.06, s * 0.56 * Math.max(0.06, open)], color: [0.08, 0.03, 0.1], alpha: 0.6 * k, add: 0, hot: 0 });
  out.cards.push({ p, cell: 'eye3', size: [s, s * 0.52 * Math.max(0.06, open)], color: [Math.min(1, f.color[0] + 0.35), Math.min(1, f.color[1] + 0.35), Math.min(1, f.color[2] + 0.35)], alpha: k, add: 0.45, intensity: 1.35 });
  const ph = (age * 1.6) % 1; out.cards.push({ p, cell: 'ring', size: [s * (0.9 + ph * 1.2), s * (0.6 + ph * 0.8)], color: f.color, alpha: 0.5 * (1 - ph) * open, add: 1, intensity: 1.1 });
  out.lights.push({ p, color: f.color, intensity: 2.5 * open, range: 7 });
};
// a scanning cone of light from a battler's eye (or a sprite such as Foresight's lens) sweeping over the target
HD.MOVE_FX.e_scan = (d, e) => { const a = ref(d, e.from || 'attacker'), b = ref(d, e.to || 'target'); if (!here(d, a) || !here(d, b)) return; d.addFx('e_scan', { a, b, life: (e.dur || 40) / FPS, color: e.color || [0.6, 0.95, 1], tpl: e.tpl || null, y: e.y != null ? e.y : 0.95, w: e.width || 1 }); };
HD.FX.e_scan = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.15, 0.25); const hb = hgt(d, f.b); let A = null;
  if (f.tpl) for (const it of d.inst.values()) if (it.tpl === f.tpl && !it.hidden) { A = it.p; break; }
  if (!A) { if (f.tpl) return; A = scrOff(bnow(d, f.a), 0, hgt(d, f.a) * f.y); }
  const sw = Math.sin(age * 4.2) * 0.35; const B = scrOff(bnow(d, f.b), hb * sw, hb * (0.05 + 0.25 * Math.cos(age * 2.7)));
  out.ribbons.push({ pts: [A, lerp3(A, B, 0.5), B], widths: [hb * 0.04, hb * 0.35 * f.w, hb * 0.8 * f.w], width: 1, cell: 'boltglow', color: f.color, intensity: 0.38 * k, add: 1 });
  out.ribbons.push({ pts: [A, B], widths: [hb * 0.01, hb * 0.06], width: 1, cell: 'beam', color: [1, 1, 1], intensity: 0.6 * k, add: 1 });
  out.cards.push({ p: B, cell: 'flare', size: [hb * 0.9, hb * 0.9], color: f.color, alpha: 0.5 * k, add: 1, intensity: 1.1 });
};

// ================================================================== Recycle: a used pouch re-forms inside a turning loop of arrows above the user, then pops
HD.MOVE_FX.e_recycle = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e_recycle', { b, life: (e.dur || 130) / FPS, color: e.color || [0.45, 1, 0.55] }); };
HD.FX.e_recycle = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const p = scrOff(bnow(d, f.b), 0, h * 0.95); p[2] += 0.4; const k = env01(u, 0.12, 0.12); const form = HD.smooth(clamp((u - 0.15) / 0.55, 0, 1));
  for (let i = 0; i < 3; i++) { const a = age * 2.6 + i * Math.PI * 2 / 3; const q = scrOff(p, Math.cos(a) * h * 0.4, Math.sin(a) * h * 0.4);
    obj(out.cards, q, { cell: 'arrow', size: h * 0.26, rot: a, color: f.color, alpha: k, glow: f.color, glowA: 0.25, add: 0.25, intensity: 1.2 }); }
  out.cards.push({ p, cell: 'ring', size: [h * 0.85, h * 0.85], color: f.color, alpha: 0.35 * k, add: 1, intensity: 1 });
  if (form > 0.02) obj(out.cards, p, { cell: 'satchel', ramp: 'cloth', size: h * 0.46 * form, alpha: k * Math.min(1, form * 2), glow: [1, 0.9, 0.6], glowA: 0.3 * form });
  out.lights.push({ p, color: f.color, intensity: 1.8 * k, range: 6 });
};
HD.FX_STEP.e_recycle = function (d, f, age) {
  const u = age / f.life; const h = hgt(d, f.b); const p = scrOff(bnow(d, f.b), 0, h * 0.95);
  if (u > 0.12 && u < 0.7 && d.frame % 2 === 0) { const dir = d.rng.unit(); d.emit(Object.assign({}, PS.glint, { speed: [0, 0], life: [0.3, 0.4] }), V.madd([0, 0, 0], p, dir, h * 0.6), 1, { vel: V.scale([0, 0, 0], dir, -h * 1.6), ramp: 'gold' }); }
  if (!f.pop && u > 0.88) { f.pop = true; d.addFx('ring', { p: p.slice(), cell: 'ring', r0: h * 0.1, r1: h * 0.6, width: 0.05, color: f.color, intensity: 1.2, life: 0.25, add: 1 }); d.emit(PS.e_sparkle, p, 10, { ramp: 'gold', speedMul: 2.2, scale: h / 4 }); }
};

// ================================================================== King's Shield: a steel kite shield with a gold rim materialises in front of the user, locks with a clang
HD.MOVE_FX.e_kshield = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e_kshield', { b, life: (e.dur || 100) / FPS }); };
HD.FX.e_kshield = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const F = wallFrame(d, f.b, 1, false); const h = F.h; const g = HD.easeOut(clamp(age / 0.16, 0, 1)); const k = u > 0.85 ? 1 - (u - 0.85) / 0.15 : 1;
  const p = [F.c0[0], h * 0.62, F.c0[2]]; const back = d.space.depthOf(p) > d.space.depth[f.b]; const s = h * 1.15 * (0.7 + 0.3 * g);
  out.cards.push({ p, back, cell: 'dot', size: [s * 1.7, s * 1.7], color: [1, 0.82, 0.4], alpha: 0.32 * k, add: 1, intensity: 1 });
  out.cards.push({ p, back, cell: 'e_kshield', size: [s * 1.1, s * 1.1], color: [0.05, 0.04, 0.02], alpha: 0.6 * k * g, add: 0, hot: 0 });
  out.cards.push({ p, back, cell: 'e_kshield', size: [s * 1.04, s * 1.04], color: [1, 1, 1], gmap: 'brass', alpha: k * g, add: 0, intensity: 1 });
  out.cards.push({ p, back, cell: 'e_kshield', size: [s * 0.9, s * 0.9], color: [1, 1, 1], gmap: 'metal', alpha: k * g, add: 0, intensity: 1 });
  const sw = (age * 0.8) % 1.5; if (sw < 1) out.cards.push({ p: scrOff(p, (sw - 0.5) * s * 0.6, (0.5 - sw) * s * 0.6), back, cell: 'star4', size: [s * 0.35, s * 0.35], rot: age * 2, color: [1, 0.97, 0.85], alpha: 0.9 * Math.sin(Math.PI * sw) * k, add: 1, intensity: 1.6 });
  if (age > 0.16 && age < 0.45) { const v = (age - 0.16) / 0.29; out.cards.push({ p, back, cell: 'flare', size: [s * (1 + v), s * (1 + v)], color: [1, 0.9, 0.6], alpha: 0.6 * (1 - v), add: 1, intensity: 1.3 }); }
  out.lights.push({ p, color: [1, 0.85, 0.55], intensity: 2.6 * k, range: 8 });
};
HD.FX_STEP.e_kshield = function (d, f, age) { if (f.clang || age < 0.16) return; f.clang = true; const F = wallFrame(d, f.b, 1, false); const p = [F.c0[0], F.h * 0.62, F.c0[2]]; d.emit(PS.steelSpark, p, 16, { scale: 1.2 }); d.shake(0.1); };

// ================================================================== Tail Whip: bold wag arcs swishing behind the user, left and right in rhythm
HD.MOVE_FX.e_wag = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e_wag', { b, life: (e.dur || 50) / FPS, n: e.n || 3, color: e.color || [1, 0.95, 0.85] }); };
HD.FX.e_wag = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const fx = face(d, f.b); const base = scrOff(bnow(d, f.b), -fx * h * 0.38, -h * 0.28); base[2] += 0.3;
  const per = 1 / f.n; const i = Math.min(f.n - 1, Math.floor(u / per)); const v = (u - i * per) / per; const dir = i % 2 ? 1 : -1;
  const a0 = Math.PI / 2 + dir * 1.1, a1 = Math.PI / 2 - dir * 1.1; const head = HD.easeOut(Math.min(1, v / 0.6)), tail = HD.easeIn(clamp((v - 0.25) / 0.75, 0, 1)); if (head - tail < 0.02) return;
  const pts = arcPts(base, h * 0.42, a0 + (a1 - a0) * tail, a0 + (a1 - a0) * head, 12);
  out.ribbons.push(tapered(pts, h * 0.16, { cell: 'boltglow', color: f.color, intensity: 0.45, add: 1 })); out.ribbons.push(tapered(pts, h * 0.06, { cell: 'beam', color: f.color, intensity: 1.1, add: 1 }));
};

// ================================================================== small helpers: a specular sweep, hovering, rim glow, weather strength, no giant sky eyes
