HD.MOVE_FX.e_hover = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e_hover', { b, life: (e.dur || 60) / FPS, height: e.height || 10 }); };
HD.FX.e_hover = function (d, f, age, out) { const u = age / f.life; if (u < 0 || u > 1) return; const ft = d.space.feet[f.b]; const h = hgt(d, f.b); const k = env01(u, 0.25, 0.25); out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 1.2 * (1 - 0.3 * k), h * 0.6 * (1 - 0.3 * k)], color: [0, 0, 0], alpha: 0.4 * k, add: 0, intensity: 1, mode: 2 }); };
HD.FX_STEP.e_hover = function (d, f, age) { const a = d.act[f.b]; if (!a) return; const k = env01(age / f.life, 0.25, 0.25); a.fxOff[1] -= f.height * k + Math.sin(age * 4) * 1.5 * k; };
HD.MOVE_FX.e_glowon = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e_glowon', { b, life: (e.dur || 30) / FPS, color: e.color || [1, 1, 1], glow: e.glow || 0.35 }); };
HD.FX.e_glowon = function () {};
HD.FX_STEP.e_glowon = function (d, f, age) { glowOn(d, f.b, f.color, f.glow * env01(age / f.life, 0.2, 0.3)); };
