// =====================================================================================================================
// WAVE 2 (group E, prefix e2_): the moves the pass-2 review graded D / C, reworked. Nothing above is reassigned: the e_
// kits and effects keep their behaviour for every move that still uses them (group H's moves too); new looks get new
// e2_ names. Timing stays the runtime's: every effect starts on a script event or a fixed frame of the move.
// =====================================================================================================================
const E2 = {};
// the frame of a battler's defences: its feet, the direction to the other side, the side axis, its height
function e2Frame(d, b) {
  const A = d.space.feet[b]; let o = b ^ 1; if (!here(d, o)) o = b ^ 3;
  const T = here(d, o) ? d.space.feet[o] : [A[0] + 6, 0, A[2] - 12 * ((b & 1) ? -1 : 1)];
  const dir = V.norm([0, 0, 0], [T[0] - A[0], 0, T[2] - A[2]]); return { A, dir, side: [-dir[2], 0, dir[0]], h: hgt(d, b) };
}
const e2At = (F, fwd, sd, y) => [F.A[0] + F.dir[0] * fwd + F.side[0] * sd, y, F.A[2] + F.dir[2] * fwd + F.side[2] * sd];
const e2Mix = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
const e2Lite = (c, k) => [Math.min(1, c[0] + (1 - c[0]) * k), Math.min(1, c[1] + (1 - c[1]) * k), Math.min(1, c[2] + (1 - c[2]) * k)];
E2.frame = e2Frame;

// ---- ramps and cells
HD.addRamp('e2_mat', [[0, 0.64, 0.52, 0.26, 1], [0.2, 0.54, 0.42, 0.2, 1], [0.38, 0.38, 0.29, 0.13, 1], [0.5, 0.14, 0.12, 0.1, 1], [0.6, 0.04, 0.05, 0.11, 1], [0.8, 0.02, 0.03, 0.07, 1], [1, 0.01, 0.01, 0.02, 1]]);
HD.addRamp('e2_mirror', [[0, 0.92, 1, 1, 1], [0.12, 0.62, 0.9, 1, 1], [0.35, 0.3, 0.62, 0.95, 1], [0.6, 0.14, 0.34, 0.66, 1], [1, 0.03, 0.08, 0.2, 1]]);
HD.addCells(['e2_mat', 'e2_hex']);
HD.CELL_PAINTERS.e2_mat = { draw(g, R) {   // a tatami mat face-on: woven rush face, wide cloth borders (heri) on the long sides, dark rim
  const L = HD.TEX.lum; const w = R * 0.97, h = R * 0.97, bw = R * 0.2;
  g.fillStyle = L(22); HD.TEX.rrPath(g, -w, -h, w * 2, h * 2, R * 0.04); g.fill();
  const sg = g.createLinearGradient(-w, -h, w * 0.6, h); sg.addColorStop(0, L(252)); sg.addColorStop(0.55, L(222)); sg.addColorStop(1, L(190));
  g.fillStyle = sg; g.fillRect(-w + bw, -h + R * 0.035, (w - bw) * 2, (h - R * 0.035) * 2);
  for (let y = -h + R * 0.05; y < h - R * 0.04; y += R * 0.052) { g.fillStyle = L(150, 0.6); g.fillRect(-w + bw, y, (w - bw) * 2, R * 0.014); }   // weave rows
  for (let x = -w + bw + R * 0.16; x < w - bw - R * 0.08; x += R * 0.3) { g.fillStyle = L(255, 0.25); g.fillRect(x, -h + R * 0.04, R * 0.03, (h - R * 0.04) * 2); }   // warp ridges
  for (const s of [-1, 1]) { const x0 = s < 0 ? -w + R * 0.025 : w - bw; g.fillStyle = L(92); g.fillRect(x0, -h + R * 0.025, bw - R * 0.025, (h - R * 0.025) * 2);   // heri
    g.fillStyle = L(70); g.fillRect(x0 + bw * 0.42, -h + R * 0.025, bw * 0.16, (h - R * 0.025) * 2); }
} };
HD.CELL_PAINTERS.e2_hex = { draw(g, R) {   // a bevelled hexagonal mirror tile (pointy top): dark rim, lit upper bevel, mirror face with a diagonal sheen
  const L = HD.TEX.lum; const hexP = (r) => { g.beginPath(); for (let i = 0; i < 6; i++) { const a = Math.PI / 6 + i * Math.PI / 3; const x = Math.cos(a) * r, y = Math.sin(a) * r; if (i) g.lineTo(x, y); else g.moveTo(x, y); } g.closePath(); };
  g.fillStyle = L(40); hexP(R * 0.97); g.fill();
  const bg = g.createLinearGradient(-R * 0.6, -R * 0.8, R * 0.6, R * 0.8); bg.addColorStop(0, L(255)); bg.addColorStop(0.5, L(170)); bg.addColorStop(1, L(95)); g.fillStyle = bg; hexP(R * 0.86); g.fill();
  const fg = g.createLinearGradient(-R * 0.7, -R * 0.7, R * 0.7, R * 0.7); fg.addColorStop(0, L(215)); fg.addColorStop(0.42, L(160)); fg.addColorStop(0.5, L(235)); fg.addColorStop(0.58, L(150)); fg.addColorStop(1, L(120));
  g.fillStyle = fg; hexP(R * 0.7); g.fill();
} };

// ---- screens: three distinct walls in front of the user (toward the foes), drawn big enough to read behind it
// style 'light' (Light Screen): a curved curtain of golden light rays rising from a glowing base line round the user's front
// style 'mirror' (Reflect): a flat pane of bevelled hexagonal mirror tiles that flip in from the centre, a reflection sweeps it
// style 'crystal' (Barrier): a palisade of violet crystal columns bursting up out of the ground, a faint film between them
// style 'fairy' (Crafty Shield): a curved pink veil woven from a diamond lattice of light with twinkling stars at its nodes
HD.MOVE_FX.e2_screen = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_screen', { b, life: (e.dur || 64) / FPS, style: e.style || 'light', color: e.color || [1, 0.78, 0.3], size: e.size || 1, build: (e.build || 10) / FPS, pulseAt: e.pulseAt != null ? e.pulseAt / FPS : -1 }); };
function e2Arc(F, R, th, y) { const c = Math.cos(th), s = Math.sin(th); return [F.A[0] + (F.dir[0] * c + F.side[0] * s) * R, y, F.A[2] + (F.dir[2] * c + F.side[2] * s) * R]; }
HD.FX.e2_screen = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const F = e2Frame(d, f.b); const h = F.h; const col = f.color; const k = Math.min(1, (1 - u) / 0.14);
  const pulse = f.pulseAt >= 0 && age > f.pulseAt ? Math.max(0, 1 - (age - f.pulseAt) / 0.35) : 0;
  if (f.style === 'light' || f.style === 'fairy') {
    const R = h * 1.12 * f.size, H = h * 1.62 * f.size, N = 17, A0 = -1.38, A1 = 1.38, step = (A1 - A0) / (N - 1); const fairy = f.style === 'fairy';
    const tops = [];
    for (let i = 0; i < N; i++) {
      const th = A0 + step * i; const dl = Math.abs(th) / A1 * (fairy ? f.build * 0.8 : 0.22); const g = HD.easeOut((age - dl) / (fairy ? f.build * 0.5 : 0.3)); if (g <= 0) { tops.push(null); continue; }
      const top = H * g * (0.94 + 0.06 * Math.sin(i * 1.9)) * (1 - 0.12 * Math.pow(Math.abs(th) / A1, 2)); const sh = 0.62 + 0.38 * Math.sin(age * 3.6 - i * 0.75);
      const p0 = e2Arc(F, R, th, 0.03), p1 = e2Arc(F, R, th, top * 0.5), p2 = e2Arc(F, R, th, top); tops.push(p2);
      const w = R * step * 1.75;
      if (!fairy) {
        out.ribbons.push({ pts: [p0, p1, p2], width: w, cell: 'boltglow', color: col, intensity: 0.5 * sh + 0.5 * pulse, alpha: k, add: 0.5, back: true, fadeEnds: 5 });
        if (i % 2 === 0) out.ribbons.push({ pts: [p0, p1, p2], width: w * 0.22, cell: 'beam', color: e2Lite(col, 0.35), intensity: 0.55 * sh * k, add: 1, back: true, fadeEnds: 4 });
      } else out.ribbons.push({ pts: [p0, p1, p2], width: w, cell: 'boltglow', color: col, intensity: 0.42 + 0.5 * pulse, alpha: g * k * (0.75 + 0.25 * sh), add: 0.55, back: true, fadeEnds: 4 });
    }
    // the glowing base line and the bright top edge
    const base = [], top = []; for (let i = 0; i < N; i++) { const th = A0 + step * i; if (tops[i]) { base.push(e2Arc(F, R, th, 0.05)); top.push(tops[i]); } }
    if (base.length > 1) { out.ribbons.push({ pts: base, width: h * 0.28, cell: 'boltglow', color: col, intensity: 0.5 * k, add: 1, back: true }); out.ribbons.push({ pts: base, width: h * 0.06, cell: 'beam', color: e2Lite(col, 0.4), intensity: 1.0 * k, add: 1, back: true }); }
    if (top.length > 1 && !fairy) out.ribbons.push({ pts: top, width: h * 0.05, cell: 'beam', color: e2Lite(col, 0.3), intensity: 0.75 * k, add: 1, back: true });
    if (fairy) {   // the diamond lattice: helices of light on the veil crossing each other, a twinkling star on every node
      const bt = HD.easeOut(age / f.build); const NL = 7;
      for (const s of [-1, 1]) for (let j = 0; j < NL; j++) { const pts = []; const th0 = A0 + (A1 - A0) * (j - 1) / (NL - 3);
        for (let q = 0; q <= 8; q++) { const v = q / 8; const th = th0 + s * v * (A1 - A0) * 0.45; if (th < A0 - 0.01 || th > A1 + 0.01) continue; pts.push(e2Arc(F, R, th, v * H * 0.98)); }
        if (pts.length > 1) { out.ribbons.push({ pts, width: h * 0.16, cell: 'boltglow', color: col, intensity: (0.35 + 0.4 * pulse) * bt * k, add: 1, back: true, fadeEnds: 6 }); out.ribbons.push({ pts, width: h * 0.05, cell: 'beam', color: col, intensity: (0.55 + 0.6 * pulse) * bt * k, add: 1, back: true, fadeEnds: 6 }); } }
      const nodes = Math.round(bt * 30); const r = HD.rng(f.seed);
      for (let n = 0; n < nodes; n++) { const th = A0 + (A1 - A0) * r(); const y = H * r.range(0.1, 0.92); const tw = 0.55 + 0.45 * Math.sin(age * 7 + n * 2.3);
        out.cards.push({ p: e2Arc(F, R, th, y), back: true, cell: 'star4', size: [h * 0.26 * tw, h * 0.26 * tw], rot: n, color: e2Lite(col, 0.1), alpha: k, add: 1, intensity: 1.35 }); }
    }
    out.decals.push({ p: e2Arc(F, R * 0.85, 0, 0.03), cell: 'dot', size: [R * 2.6, R * 1.4], rot: Math.atan2(-F.dir[0], -F.dir[2]), color: col, alpha: 0.35 * k, add: 1, intensity: 1, mode: 2 });
    out.lights.push({ p: e2Arc(F, R, 0, H * 0.5), color: col, intensity: (2.6 + 3 * pulse) * k, range: 9 });
    if (age < 0.3) { const v = age / 0.3; out.cards.push({ p: e2Arc(F, R, 0, H * 0.4), back: true, cell: 'flare', size: [h * (1 + v * 1.4), h * (0.6 + v)], color: col, alpha: 0.45 * (1 - v), add: 1, intensity: 1.1 }); }
  } else if (f.style === 'mirror') {
    const W = h * 1.75 * f.size, H = h * 1.6 * f.size; const fwd = h * 1.0; const r = h * 0.16 * f.size; const cw = Math.sqrt(3) * r, rh = 1.5 * r;
    const cols = Math.ceil(W / cw) + 1, rows = Math.floor((H - r) / rh) + 1; const sw = ((age * 0.85) % 1.5) - 0.25;   // the reflection band's position along the pane's diagonal
    for (let j = 0; j < rows; j++) for (let i = 0; i < cols; i++) {
      const x = (i - (cols - 1) / 2 + (j % 2 ? 0.5 : 0)) * cw; if (Math.abs(x) > W / 2) continue; const y = r * 0.9 + j * rh;
      const dist = Math.hypot(x / (W / 2), (y - H / 2) / (H / 2)); const v = clamp((age - dist * 0.2) / 0.1, 0, 1); if (v <= 0) continue;
      const p = e2At(F, fwd, x, y); const fl = Math.sin(v * Math.PI / 2); const q = (x / W + 0.5) * 0.6 + (y / H) * 0.4; const band = Math.exp(-Math.pow((q - sw) / 0.09, 2));
      out.cards.push({ p, back: true, cell: 'e2_hex', size: [r * 2.12 * fl, r * 2.12], color: [0.02, 0.05, 0.1], alpha: 0.5 * k, add: 0, hot: 0 });
      out.cards.push({ p, back: true, cell: 'e2_hex', size: [r * 2 * fl, r * 2], color: [1, 1, 1], gmap: 'e2_mirror', alpha: 0.85 * k, add: 0.1 + 0.5 * band, intensity: 0.92 + 0.9 * band + (1 - v) * 1.2 });
      if (band > 0.6 && (i + j) % 3 === 0) out.cards.push({ p: [p[0], p[1], p[2] + 0.05], back: true, cell: 'star4', size: [r * 1.6, r * 1.6], rot: 0.3, color: [0.85, 0.97, 1], alpha: (band - 0.6) * 2.5 * k, add: 1, intensity: 1.6 });
    }
    const c = e2At(F, fwd, 0, H * 0.5); out.cards.push({ p: [c[0], c[1], c[2] - 0.3], back: true, cell: 'dot', size: [W * 1.5, H * 1.4], color: col, alpha: 0.28 * k, add: 1, intensity: 1 });
        out.decals.push({ p: e2At(F, fwd, 0, 0.03), cell: 'dot', size: [W * 1.3, h * 0.8], rot: Math.atan2(-F.side[2], F.side[0]), color: col, alpha: 0.4 * k, add: 1, intensity: 1, mode: 2 });
    out.lights.push({ p: c, color: col, intensity: 2.8 * k, range: 9 });
  } else if (f.style === 'crystal') {
    const n = 7; const r = HD.rng(f.seed); const fwd = h * 0.95; const sink = HD.smooth((age - (f.life - 0.28)) / 0.28);
    const film = []; for (let i = 0; i < n; i++) {
      const o = i - (n - 1) / 2; const x = o * h * 0.27 * f.size + r.range(-0.04, 0.04) * h; const hc = h * f.size * (1.5 - 0.12 * Math.abs(o)) * r.range(0.9, 1.08); const z = r.range(-0.12, 0.12) * h;
      const v = HD.easeOut((age - Math.abs(o) * 0.035) / 0.2); if (v <= 0) { r(); r(); continue; }
      const size = hc / 2.25; const yc = hc - 1.35 * size - hc * (1 - v) * 1.15 - hc * 1.2 * sink; const bp = e2At(F, fwd + z, x, 0);
      const glint = Math.max(0, Math.sin(age * 2.2 - i * 0.9)); const cc = e2Lite(col, 0.25 * Math.pow(glint, 8));
      out.meshes.push({ kind: 'crystal', p: [bp[0], yc, bp[2]], size, scale: [0.8, 1, 0.8], rot: [r.range(-0.12, 0.12), r() * 3, o * -0.07], color: cc });
      film.push(e2At(F, fwd + z, x, hc * 0.45 * v * (1 - sink)));
      if (Math.pow(glint, 8) > 0.5) out.cards.push({ p: e2At(F, fwd + z - 0.3, x, Math.max(0.2, yc + 1.25 * size)), cell: 'star4', size: [h * 0.32, h * 0.32], rot: age * 2, color: [0.95, 0.9, 1], alpha: (Math.pow(glint, 8) - 0.5) * 2 * k, add: 1, intensity: 1.7 });
    }
    if (film.length > 1) { out.ribbons.push({ pts: film, width: h * 1.25 * f.size, cell: 'boltglow', color: col, intensity: 0.55, alpha: k * (1 - sink), add: 0.7, back: true });
      out.ribbons.push({ pts: film.map((p) => [p[0], p[1] * 1.6, p[2]]), width: h * 0.05, cell: 'beam', color: e2Lite(col, 0.4), intensity: 0.5 * k * (1 - sink), add: 1, back: true }); }
    out.decals.push({ p: e2At(F, fwd, 0, 0.03), cell: 'dot', size: [h * 2.6 * f.size, h * 0.9], rot: Math.atan2(-F.side[2], F.side[0]), color: col, alpha: 0.42 * k, add: 1, intensity: 1, mode: 2 });
    out.lights.push({ p: e2At(F, fwd, 0, h * 0.8), color: col, intensity: 3 * k, range: 9 });
  }
};
HD.FX_STEP.e2_screen = function (d, f, age) {
  const F = e2Frame(d, f.b); const h = F.h; const r = d.rng; const u = age / f.life;
  if (f.style === 'crystal') {
    if (!f.burst) { f.burst = true; const p = e2At(F, h * 0.95, 0, 0.2); d.emit(PS.dustPuff, p, 12, { dir: [0, 0.6, 0], spread: 1, scale: 1.3, radius: h * 0.7 }); d.emit(PS.iceChip, e2At(F, h * 0.95, 0, h * 0.4), 14, { ramp: 'psychic', scale: 1.2, radius: h * 0.6 }); d.shake(0.1); }
    if (d.frame % 4 === 0 && u < 0.85) d.emit(PS.glint, e2At(F, h * 0.9, r.range(-1, 1) * h * 0.8, r.range(0.2, 1.4) * h), 1, { ramp: 'psychic', scale: 1.1 });
    if (!f.sunk && age > f.life - 0.28) { f.sunk = true; d.emit(PS.glint, e2At(F, h * 0.95, 0, h * 0.6), 16, { ramp: 'psychic', radius: h * 0.8, speedMul: 1.4 }); }
  } else if (f.style === 'mirror') {
    if (d.frame % 6 === 0 && u < 0.85) d.emit(PS.glint, e2At(F, h, r.range(-0.8, 0.8) * h, r.range(0.2, 1.5) * h), 1, { ramp: 'ice', scale: 1.2 });
  } else {
    const R = h * 1.12 * f.size; if (d.frame % 2 === 0 && u < 0.85) { const th = r.range(-1.3, 1.3); d.emit(PS.e_mote, e2Arc(F, R, th, r.range(0.05, 0.5) * h), 1, { ramp: f.style === 'fairy' ? 'pink' : 'gold', vel: [0, h * 0.5, 0], scale: h / 3.4 }); }
  }
};

// ---- Mat Block: a tatami mat lies on the ground in front of the user, flips up with a slap, holds as a shield, falls back
HD.MOVE_FX.e2_mat = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_mat', { b, life: (e.dur || 98) / FPS, lie: (e.lie || 4) / FPS, up: (e.up || 6) / FPS }); };
function e2MatPose(f, age) {   // 0 = flat on the ground, 1 = standing; the wobble after the slap
  const t1 = f.lie, t2 = f.lie + f.up, t3 = f.life - 0.3;
  if (age < t1) return { st: 0, wob: 0, flat: Math.min(1, age / Math.max(0.01, t1)) };
  if (age < t2) return { st: HD.easeIn((age - t1) / f.up), wob: 0, flat: 1 };
  if (age < t3) { const w = age - t2; return { st: 1, wob: Math.sin(w * 34) * 0.06 * Math.exp(-w * 7), flat: 1 }; }
  return { st: 1 - HD.easeIn((age - t3) / 0.3), wob: 0, flat: 1, falling: true };
}
HD.FX.e2_mat = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const F = e2Frame(d, f.b); const h = F.h; const Wm = h * 1.0, Hm = h * 1.62; const P = e2MatPose(f, age);
  const B = e2At(F, h * 0.5, h * 0.12, 0); const ang = Math.atan2(-F.dir[0], -F.dir[2]);
  if (P.st < 0.98) {   // the part of the mat still lying on the ground (foreshortened: a thin strip toward the foe)
    const L = Hm * Math.cos(P.st * Math.PI / 2); const c = e2At(F, h * 0.5 + L / 2, h * 0.12, 0.04);
    out.decals.push({ p: c, cell: 'e2_mat', size: [Wm, Math.max(0.05, L)], rot: ang, color: [1, 1, 1], gmap: 'e2_mat', alpha: P.flat, add: 0, intensity: 1, mode: 2 });
  }
  if (P.st > 0.02) {
    const Hs = Hm * Math.sin(P.st * Math.PI / 2) * (1 + P.wob * 0.5); const p = [B[0], Hs / 2, B[2]]; const rot = P.wob * 0.25;
    if (!P.falling && P.st < 1) for (let j = 1; j <= 2; j++) { const s2 = Math.max(0, P.st - j * 0.22); const H2 = Hm * Math.sin(s2 * Math.PI / 2); out.cards.push({ p: [B[0], H2 / 2, B[2] - 0.05], back: true, cell: 'e2_mat', size: [Wm, H2], color: [1, 0.85, 0.6], alpha: 0.28 / j, add: 1, intensity: 0.8 }); }
    out.cards.push({ p: [p[0], p[1], p[2] - 0.02], back: true, cell: 'e2_mat', size: [Wm * 1.06, Hs * 1.035], rot, color: [0.03, 0.04, 0.02], alpha: 0.65, add: 0, hot: 0 });
    const edge = scrOff(p, Wm * 0.53, -Hs * 0.012); out.cards.push({ p: [edge[0], edge[1], edge[2] - 0.01], back: true, cell: 'dot', size: [Wm * 0.09, Hs * 1.0], rot, color: [0.35, 0.33, 0.18], alpha: 0.95, add: 0, hot: 0 });   // the mat's thickness
    out.cards.push({ p, back: true, cell: 'e2_mat', size: [Wm, Hs], rot, color: [1, 1, 1], gmap: 'e2_mat', alpha: 1, add: 0, intensity: 1.02 });
    const t2 = f.lie + f.up; const sl = age - t2;
    if (sl > 0 && sl < 0.3) { const v = sl / 0.3; out.cards.push({ p, back: true, cell: 'e2_mat', size: [Wm, Hs], rot, color: [1, 0.78, 0.45], alpha: (1 - v) * 0.8, add: 1, intensity: 1.2 });
      out.cards.push({ p, back: true, cell: 'flare', size: [Wm * (1.6 + v * 1.4), Hs * (1.1 + v)], color: [1, 0.7, 0.35], alpha: 0.4 * (1 - v), add: 1, intensity: 1.1 }); }
    if (sl > 0 && !P.falling) {   // a guarding glow along the mat's edges, breathing while it holds; a glint crosses its face now and then
      const br = 0.55 + 0.45 * Math.sin(sl * 4.5);
      out.cards.push({ p: [p[0], p[1], p[2] - 0.04], back: true, cell: 'e2_mat', size: [Wm * 1.16, Hs * 1.08], rot, color: [1, 0.55, 0.2], alpha: 0.5 * br, add: 1, intensity: 1.1 });
      const gl = (sl * 0.7) % 1.6; if (gl < 1) out.cards.push({ p: scrOff(p, (gl - 0.5) * Wm * 0.8, (0.5 - gl) * Hs * 0.8), back: true, cell: 'star4', size: [h * 0.34, h * 0.34], rot: sl * 2, color: [1, 0.92, 0.7], alpha: Math.sin(Math.PI * gl), add: 1, intensity: 1.5 });
    }
  }
  out.decals.push({ p: [B[0], 0.03, B[2]], cell: 'dot', size: [Wm * 1.5, h * 0.55], rot: Math.atan2(-F.side[2], F.side[0]), color: [0, 0, 0], alpha: 0.4 * P.st, add: 0, intensity: 1, mode: 2 });
};
HD.FX_STEP.e2_mat = function (d, f, age) {
  const F = e2Frame(d, f.b); const h = F.h; const B = e2At(F, h * 0.5, h * 0.12, 0.2); const t2 = f.lie + f.up;
  if (!f.slap && age >= t2) { f.slap = true; for (const s of [-1, 1]) d.emit(PS.dustPuff, scrOff(B, s * h * 0.55, 0), 9, { dir: [s * 0.8, 0.35, 0], spread: 0.7, scale: 1.4 }); d.shake(0.16);
    d.addFx('ring', { p: [B[0], 0.06, B[2]], cell: 'ring', r0: 0.3, r1: h * 1.3, width: 0.08, color: [0.9, 0.78, 0.55], intensity: 0.8, life: 0.3, add: 0.3, ground: true, distort: 0.5 }); }
  const a = d.act[f.b]; if (a && age > t2 && age < f.life - 0.3) { const k = Math.min(1, (age - t2) / 0.12); a.sy *= 1 - 0.04 * k; a.sx *= 1 + 0.025 * k; }   // the user braces behind its mat
  if (!f.fall && age >= f.life - 0.06) { f.fall = true; d.emit(PS.dustPuff, e2At(F, h * 1.2, h * 0.12, 0.2), 12, { dir: [0, 0.3, 0], spread: 1, scale: 1.3, radius: h * 0.5 }); }
};

// ---- King's Shield: a steel kite shield rises at the user's front side spinning into place, locks with a clang and a
// royal glow, holds while a sheen crosses it; the user sets its stance
HD.MOVE_FX.e2_kshield = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_kshield', { b, life: (e.dur || 108) / FPS, rise: (e.rise || 9) / FPS }); };
HD.FX.e2_kshield = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const F = e2Frame(d, f.b); const h = F.h; const v = HD.easeOut(age / f.rise); const k = Math.min(1, (1 - u) / 0.12);
  const s = h * 1.3; const p = e2At(F, h * 0.55, h * 0.5, s * 0.5 - s * 0.45 * (1 - v) + 0.04 * h * Math.sin(age * 2.4)); const sx = Math.max(0.08, Math.abs(Math.sin(v * Math.PI * 1.5)));
  const lock = age - f.rise;
  out.cards.push({ p: [p[0], p[1], p[2] - 0.3], back: true, cell: 'dot', size: [s * 1.6, s * 1.7], color: [0.7, 0.4, 1], alpha: 0.42 * k * v, add: 1, intensity: 1 });
  if (v < 1) for (let j = 1; j <= 2; j++) { const q = [p[0], p[1] - s * 0.12 * j * (1 - v), p[2] - 0.05]; out.cards.push({ p: q, back: true, cell: 'e_kshield', size: [s * sx, s], color: [1, 0.85, 0.5], alpha: 0.25 / j, add: 1, intensity: 0.9 }); }
  out.cards.push({ p, back: true, cell: 'e_kshield', size: [s * 1.07 * sx, s * 1.07], color: [0.04, 0.03, 0.05], alpha: 0.7 * k, add: 0, hot: 0 });
  out.cards.push({ p, back: true, cell: 'e_kshield', size: [s * 1.02 * sx, s * 1.02], color: [1, 0.86, 0.5], gmap: 'brass', alpha: k, add: 0, intensity: 1 });
  out.cards.push({ p, back: true, cell: 'e_kshield', size: [s * 0.88 * sx, s * 0.88], color: [0.62, 0.68, 0.82], gmap: 'metal', alpha: k, add: 0, intensity: 1 });
  if (lock > 0) {
    const sw = (lock * 0.75) % 1.4; if (sw < 1) { const q = scrOff(p, (sw - 0.5) * s * 0.5, (0.5 - sw) * s * 0.55); out.cards.push({ p: q, back: true, cell: 'star4', size: [s * 0.32, s * 0.32], rot: lock * 2, color: [1, 0.97, 0.85], alpha: Math.sin(Math.PI * sw) * k, add: 1, intensity: 1.7 }); }
    if (lock < 0.3) { const w = lock / 0.3; out.cards.push({ p, back: true, cell: 'e_kshield', size: [s * 0.9, s * 0.9], color: [1, 0.8, 0.45], alpha: (1 - w) * 0.5, add: 1, intensity: 1.1 }); out.cards.push({ p: scrOff(p, 0, s * 0.28), back: true, cell: 'star4', size: [s * (0.5 + w * 0.9), s * (0.5 + w * 0.9)], rot: 0.4, color: [1, 0.85, 0.5], alpha: 1 - w, add: 1, intensity: 1.5 }); }
    const br = 0.6 + 0.4 * Math.sin(lock * 3.5); const ft = e2At(F, h * 0.55, h * 0.5, 0.03); out.decals.push({ p: ft, cell: 'dot', size: [s * 1.3, s * 0.6], color: [1, 0.78, 0.4], alpha: 0.35 * br * k, add: 1, intensity: 1, mode: 2 });
  }
  out.lights.push({ p, color: [1, 0.85, 0.6], intensity: 2.8 * k * v, range: 8 });
};
HD.FX_STEP.e2_kshield = function (d, f, age) {
  const F = e2Frame(d, f.b); const h = F.h;
  if (!f.clang && age >= f.rise) { f.clang = true; const p = e2At(F, h * 0.55, h * 0.5, h * 0.65); d.emit(PS.steelSpark, p, 18, { scale: 1.3 }); d.emit(PS.glint, p, 8, { ramp: 'gold', radius: h * 0.4 }); d.shake(0.12); }
  const a = d.act[f.b]; if (a) { const w = age - f.rise; const k = w < 0 ? 0 : Math.min(1, w / 0.15) * Math.min(1, (f.life - age) / 0.2); a.sy *= 1 - 0.045 * k; a.sx *= 1 + 0.03 * k; a.fxOff[0] -= face(d, f.b) * 2 * k; }   // the stance: set low behind the shield
};

// ---- Detect: the world dims (time slows), a sharp glint flashes in the user's eye, it slips aside leaving afterimages
HD.MOVE_FX.e2_dodge = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_dodge', { b, life: (e.dur || 26) / FPS, amt: e.amt || 16, color: e.color || [1, 0.7, 0.35] }); };
function e2DodgeAt(f, fr) { const t = fr - f.f0; const n = f.life * FPS; if (t <= 0 || t >= n) return 0; if (t < 4) return HD.easeOut(t / 4); if (t < n - 10) return 1; return 1 - HD.smooth((t - (n - 10)) / 10); }
HD.FX.e2_dodge = function (d, f, age, out) {   // speed streaks while it slips aside
  const fr = f.f0 + age * FPS; const o = e2DodgeAt(f, fr), pr = e2DodgeAt(f, fr - 1); if (Math.abs(o - pr) < 0.08) return; const c = bnow(d, f.b); const h = hgt(d, f.b); const dir = -face(d, f.b); const r = HD.rng(Math.floor(fr) * 17 + 3);
  for (let i = 0; i < 5; i++) out.cards.push({ p: scrOff(c, -dir * h * r.range(0.35, 0.9), r.range(-0.45, 0.4) * h), cell: 'speed', size: [h * 1.0, h * 0.13], rot: 0, color: f.color, alpha: 0.75, add: 1, intensity: 1.2 });
};
HD.FX_STEP.e2_dodge = function (d, f, age) {
  if (f.f0 == null) f.f0 = d.frame; const a = d.act[f.b]; if (!a) return; const dir = -face(d, f.b); const o = e2DodgeAt(f, d.frame) * f.amt * dir;
  a.fxOff[0] += o; const r0 = a.v3rushNext || [0, 0]; a.v3rushNext = [r0[0] + o, r0[1]];
  const sp = Math.abs(e2DodgeAt(f, d.frame) - e2DodgeAt(f, d.frame - 1)); a.v3ghosts = [];
  if (sp > 0.02 || (d.frame - f.f0 >= 3 && d.frame - f.f0 < 12)) for (let k = 1; k <= 3; k++) { const q = e2DodgeAt(f, d.frame - k * 2.2) * f.amt * dir; a.v3ghosts.push([a.dx + (q - o), a.dy, 0.55 - k * 0.13]); }
};

// ---- Endure: rising streaks of red-orange power (no flame shapes), the user braced low with a steady glow
K.e2_rise = {
  update(d, it, cfg) {
    const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.atkB()); const s = h * (cfg.v3size || 0.3); const a = it.alpha; const col = cfg.color || [1, 0.42, 0.2];
    const top = it.p.slice(); const bot = [top[0], top[1] - s * 1.5, top[2]]; const pts = [bot, e2Mix(bot, top, 0.5), top];   // a rising tongue of power: wide at its head, thin tail below
    it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: [s * 0.08, s * 0.32, s * 0.5], width: s * 0.5, cell: 'boltglow', color: col, intensity: 0.9 * a, add: 1 });
    it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: [s * 0.03, s * 0.12, s * 0.2], width: s * 0.2, cell: 'beam', color: e2Lite(col, 0.3), intensity: 1.0 * a, add: 1 });
    it.cards.push({ cell: 'dot', size: [s * 1.1, s * 1.1], color: col, alpha: 0.45 * a, add: 1, intensity: 1 });
  }
};
HD.MOVE_FX.e2_brace = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_brace', { b, life: (e.dur || 110) / FPS, color: e.color || [1, 0.38, 0.18], strainAt: e.strainAt != null ? e.strainAt / FPS : -1 }); };
HD.FX.e2_brace = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.08, 0.15); const ft = d.space.feet[f.b]; const h = hgt(d, f.b); const br = 0.75 + 0.25 * Math.sin(age * 6);
  out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 1.9, h * 1.15], color: f.color, alpha: 0.42 * k * br, add: 1, intensity: 1, mode: 2 });
  out.decals.push({ p: [ft[0], 0.035, ft[2]], cell: 'crack', size: [h * 1.5, h * 0.95], rot: 0.6, color: [0.2, 0.08, 0.04], alpha: 0.55 * k * Math.min(1, age / 0.3), add: 0, intensity: 1, mode: 2 });
  const c = bnow(d, f.b); out.cards.push({ p: [c[0], c[1] - h * 0.05, c[2] - 0.3], back: true, cell: 'dot', size: [h * 1.7, h * 1.9], color: f.color, alpha: 0.32 * k * br, add: 1, intensity: 1 });
  if (f.strainAt >= 0 && age > f.strainAt && age < f.strainAt + 0.5) { const v = (age - f.strainAt) / 0.5; for (let i = 0; i < 8; i++) { const a = i * Math.PI / 4 + 0.3; out.cards.push({ p: scrOff(c, Math.cos(a) * h * (0.5 + v * 0.55), Math.sin(a) * h * (0.5 + v * 0.55)), cell: 'speed', size: [h * 0.8, h * 0.14], rot: a, color: e2Lite(f.color, 0.15), alpha: 1 - v, add: 1, intensity: 1.4 }); } }
  out.lights.push({ p: [c[0], c[1], c[2] + 0.8], color: f.color, intensity: 2.6 * k * br, range: 7 });
};
HD.FX_STEP.e2_brace = function (d, f, age) {
  const u = age / f.life; const k = env01(u, 0.08, 0.15); const a = d.act[f.b]; const h = hgt(d, f.b); const ft = d.space.feet[f.b];
  if (a) { a.sy *= 1 - 0.06 * k; a.sx *= 1 + 0.04 * k; }
  glowOn(d, f.b, f.color, 0.36 * k * (0.8 + 0.2 * Math.sin(age * 6)));
  if (!f.dust) { f.dust = true; for (const s of [-1, 1]) d.emit(PS.dustPuff, [ft[0] + s * h * 0.4, 0.15, ft[2]], 6, { dir: [s * 0.8, 0.2, 0], spread: 0.6, scale: 1.1 }); }
  if (f.strainAt >= 0 && !f.strained && age >= f.strainAt) { f.strained = true; d.emit(PS.ember, bnow(d, f.b), 18, { ramp: 'e_rage', radius: h * 0.4, speedMul: 1.5 }); d.emit(PS.dustPuff, [ft[0], 0.15, ft[2]], 8, { dir: [0, 0.3, 0], spread: 1, scale: 1.2 }); }
  if (d.frame % 3 === 0 && u < 0.85) d.emit(PS.e_mote, [ft[0], h * 0.1, ft[2]], 1, { ramp: 'e_rage', radius: h * 0.45, vel: [0, h * 0.8, 0], scale: h / 3.5 });
};

// a battler's rim glow set to the move's colour while it lasts (replaces the white rim a GBA white palette blend leaves)
HD.MOVE_FX.e2_rim = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_rim', { b, life: (e.dur || 60) / FPS, color: e.color || [1, 0.8, 0.4], amt: e.amt != null ? e.amt : 0.2 }); };
HD.FX.e2_rim = function () {};
HD.FX_STEP.e2_rim = function (d, f, age) { const a = d.act[f.b]; if (!a) return; const k = env01(age / f.life, 0.1, 0.2); a.glow = [f.color[0], f.color[1], f.color[2], Math.max(f.amt * k, a.glow[3] * (1 - k) * 0.5)]; };

