// ---- rooms: enclosures built from translucent panes (no wireframe): back and side walls of glowing panes that pop in from
// the user outward, a floor of tiles; Trick Room twists (magenta diamonds spinning into place, a swirl warp), Wonder Room
// ripples (teal hex cells with waves running through them, two guard lights trading places), Magic Room seals the items'
// power (violet-gold panes, a bold rune circle, item pouches over the battlers dimming to grey)
HD.addCells(['e2_pane']);
HD.CELL_PAINTERS.e2_pane = { draw(g, R) {   // a square glass pane: bright bevelled frame, faint glassy fill, a diagonal sheen
  const L = HD.TEX.lum; const s = R * 0.9;
  g.fillStyle = L(150, 0.3); g.fillRect(-s, -s, s * 2, s * 2);
  g.strokeStyle = L(255); g.lineWidth = R * 0.13; g.strokeRect(-s + R * 0.06, -s + R * 0.06, s * 2 - R * 0.12, s * 2 - R * 0.12);
  g.strokeStyle = L(200, 0.7); g.lineWidth = R * 0.05; g.strokeRect(-s + R * 0.2, -s + R * 0.2, s * 2 - R * 0.4, s * 2 - R * 0.4);
  g.save(); g.beginPath(); g.rect(-s, -s, s * 2, s * 2); g.clip(); g.fillStyle = L(255, 0.35); g.beginPath(); g.moveTo(-s, -s * 0.2); g.lineTo(-s * 0.2, -s); g.lineTo(s * 0.15, -s); g.lineTo(-s, s * 0.15); g.closePath(); g.fill(); g.restore();
} };
const E2ROOM = { cx: 1, cz: -4, hw: 12, hd: 10, H: 9 };
function e2RoomTiles(f) {   // every pane of the room: wall ('b' back, 'l' / 'r' sides) or floor ('f'), world position, distance from the user
  if (f.tiles) return f.tiles; const R = E2ROOM; const T = []; const o = f.o;
  const push = (w, p, i, j) => T.push({ w, p, i, j, dist: Math.hypot(p[0] - o[0], p[1] * 0.5, p[2] - o[2]) });
  for (let i = 0; i < 10; i++) for (let j = 0; j < 4; j++) push('b', [R.cx - R.hw + (i + 0.5) * 2.4, (j + 0.5) * 2.25, R.cz - R.hd], i, j);
  for (const s of [-1, 1]) for (let i = 0; i < 6; i++) for (let j = 0; j < 4; j++) push(s < 0 ? 'l' : 'r', [R.cx + s * R.hw, (j + 0.5) * 2.25, R.cz - R.hd + (i + 0.5) * 2.6], i, j);
  for (let i = 0; i < 10; i++) for (let j = 0; j < 7; j++) push('f', [R.cx - R.hw + (i + 0.5) * 2.4, 0.03, R.cz - R.hd + (j + 0.5) * 2.6], i, j);
  T.sort((a, b) => a.dist - b.dist); f.maxD = T[T.length - 1].dist; f.tiles = T; return T;
}
HD.MOVE_FX.e2_room = (d, e) => d.addFx('e2_room', { life: (e.dur || 140) / FPS, room: e.room || 'trick', color: e.color || [1, 0.35, 0.8], o: d.space.feet[d.atkB()].slice() });
HD.FX.e2_room = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = Math.min(1, (1 - u) / 0.16); const col = f.color; const T = e2RoomTiles(f); const R = E2ROOM;
  const wave = age * 26;   // the build front (world units from the user)
  for (const t of T) {
    const v = clamp((wave - t.dist) / 4, 0, 1); if (v <= 0) continue; const pop = v < 1 ? HD.easeOut(v) * (1 + 0.25 * Math.sin(v * Math.PI)) : 1; const fl = (1 - v);
    const chk = (t.i + t.j) % 2;
    if (f.room === 'trick') {
      const rot = Math.PI / 4 + (1 - HD.easeOut(v)) * Math.PI * 1.5 + (t.w === 'f' ? age * 0.25 : Math.sin(age * 1.4 + t.i * 0.5) * 0.08);
      const a = (chk ? 0.55 : 0.95) * k; const s = (t.w === 'f' ? 2.3 : 2.2) * pop;
      if (t.w === 'f') out.decals.push({ p: t.p, cell: 'e2_pane', size: [s, s], rot, color: chk ? [0.35, 0.08, 0.3] : col, alpha: a * 0.55, add: chk ? 0 : 0.8, intensity: 1, mode: 2 });
      else out.cards.push({ p: t.p, back: true, cell: 'e2_pane', size: [s * 1.08, s * 1.08], rot, color: col, alpha: a * 0.7, add: 0.7, intensity: 1 + fl * 1.5 });
    } else if (f.room === 'wonder') {
      const rp = 0.55 + 0.45 * Math.sin(t.dist * 0.9 - age * 5.5); const s = (t.w === 'f' ? 2.6 : 2.5) * pop;
      if (t.w === 'f') out.decals.push({ p: t.p, cell: 'e2_hex', size: [s, s], rot: 0, color: col, alpha: 0.4 * k * rp, add: 0.9, intensity: 1, mode: 2 });
      else out.cards.push({ p: t.p, back: true, cell: 'e2_hex', size: [s, s], color: e2Mix(col, [0.85, 1, 1], 0.3 * rp), alpha: (0.38 + 0.4 * rp) * k, add: 0.8, intensity: 0.9 + fl * 1.5 });
    } else {
      const sh = Math.max(0, Math.sin(age * 2.2 - t.i * 0.6 - t.j * 0.4)); const s = (t.w === 'f' ? 2.3 : 2.2) * pop;
      if (t.w !== 'f') out.cards.push({ p: t.p, back: true, cell: 'e2_pane', size: [s, s], color: e2Mix(col, [1, 0.85, 0.4], Math.pow(sh, 6)), alpha: 0.6 * k, add: 0.7, intensity: 0.95 + fl * 1.5 + 0.5 * Math.pow(sh, 6) });
    }
  }
  if (f.room === 'magic') {   // the rune circle: bold gold rings and turning star marks round the field's centre
    const g = HD.easeOut(age / 0.7); const c = [R.cx, 0.035, R.cz];
    out.decals.push({ p: c, cell: 'dot', size: [24 * g, 17 * g], color: [0.35, 0.12, 0.55], alpha: 0.45 * k, add: 0, intensity: 1, mode: 2 });
    out.decals.push({ p: c, cell: 'ring', size: [22 * g, 16 * g], rot: age * 0.2, color: [1, 0.8, 0.35], alpha: 0.95 * k, add: 1, intensity: 1.2, mode: 2 });
    out.decals.push({ p: c, cell: 'ring', size: [16 * g, 11.6 * g], rot: -age * 0.3, color: [0.85, 0.45, 1], alpha: 0.8 * k, add: 1, intensity: 1.1, mode: 2 });
    for (let i = 0; i < 8; i++) { const a = i * Math.PI / 4 + age * 0.35; out.decals.push({ p: [c[0] + Math.cos(a) * 9.5 * g, 0.04, c[2] + Math.sin(a) * 6.9 * g], cell: 'star4', size: [2.2 * g, 2.2 * g], rot: a, color: [1, 0.85, 0.45], alpha: k, add: 1, intensity: 1.4, mode: 2 }); }
    for (let b = 0; b < 4; b++) {   // the held items' power fades: a pouch over each battler loses its glow and greys
      if (!here(d, b)) continue; const h = hgt(d, b); const p = scrOff(bnow(d, b), 0, h * 0.95 + 0.05 * h * Math.sin(age * 2 + b)); const dim = HD.smooth((u - 0.3) / 0.35); const a = HD.easeOut((u - 0.12) / 0.12) * k; if (a <= 0) continue;
      obj(out.cards, p, { cell: 'satchel', ramp: 'cloth', size: h * 0.5, alpha: a, glow: e2Mix([1, 0.85, 0.4], [0.3, 0.3, 0.35], dim), glowA: 0.6 * (1 - dim) + 0.1, color: e2Mix([1, 1, 1], [0.42, 0.42, 0.48], dim) });
    }
  }
  if (f.room === 'wonder') {   // two guard lights (Defense blue, Sp. Def pink) cross the room and trade places
    const sw = HD.smooth(clamp((u - 0.3) / 0.4, 0, 1)); for (const s of [0, 1]) { const t = s ? sw : 1 - sw; const p = [R.cx - 6 + 12 * t, 4.4 + Math.sin(Math.PI * sw) * (s ? 1.6 : -1.6), R.cz + 3]; const c = s ? [0.45, 0.75, 1] : [1, 0.5, 0.85];
      const pts = []; for (let j = 0; j <= 6; j++) { const sj = HD.smooth(clamp((u - 0.3 - j * 0.02) / 0.4, 0, 1)); const tj = s ? sj : 1 - sj; pts.push([R.cx - 6 + 12 * tj, 4.4 + Math.sin(Math.PI * sj) * (s ? 1.6 : -1.6), R.cz + 3]); }
      if (sw > 0.01 && sw < 0.99) out.ribbons.push({ pts, width: 0.8, cell: 'trail', color: c, intensity: 1.1 * k, alpha: 0.8, add: 1, taper: 0.8 });
      out.cards.push({ p, cell: 'dot', size: [3.2, 3.2], color: c, alpha: 0.5 * k, add: 1, intensity: 1 }); out.cards.push({ p, cell: 'core', size: [1.3, 1.3], color: e2Lite(c, 0.4), alpha: k, add: 1, intensity: 1.4 }); out.lights.push({ p, color: c, intensity: 3 * k, range: 8 }); }
  }
  if (age < 0.6) { const v = age / 0.6; out.distort.push({ p: [R.cx, 3, R.cz], cell: f.room === 'trick' ? 'swirl' : 'shock', size: [26 * (0.4 + v), 26 * (0.4 + v)], strength: 0.55 * (1 - v), mode: 0 }); }
  out.lights.push({ p: [R.cx, 5, R.cz], color: col, intensity: 3 * k, range: 24 });
};
HD.FX_STEP.e2_room = function (d, f, age) {
  const u = age / f.life; const g = d.env.grade; const k = env01(u, 0.1, 0.16);
  g.tint = f.color; g.amt = Math.max(g.amt, 0.12 * k);
  if (f.room === 'magic' && d.frame % 3 === 0 && u > 0.3 && u < 0.75) for (let b = 0; b < 4; b++) if (here(d, b)) { const h = hgt(d, b); d.emit(PS.darkSmoke, scrOff(bnow(d, b), 0, h * 0.95), 1, { radius: h * 0.15, scale: 0.8 }); }
  if (f.room === 'trick' && d.frame % 2 === 0 && u < 0.8) d.emit(PS.glint, [d.rng.range(-10, 12), d.rng.range(0.5, 7), d.rng.range(-13, 4)], 1, { ramp: 'pink', scale: 1.4 });
  if (f.room === 'wonder' && d.frame % 2 === 0 && u < 0.8) d.emit(PS.e_bubble, [d.rng.range(-10, 12), d.rng.range(0.2, 2), d.rng.range(-13, 4)], 1, { ramp: 'spray', scale: 1.3 });
};

// ---- Gravity: violet pressure waves slam down on every battler with motion echoes, warp and dust; streaks of matter fall
HD.MOVE_FX.e2_grav = (d, e) => d.addFx('e2_grav', { life: (e.dur || 66) / FPS, color: e.color || [0.6, 0.4, 1] });
HD.FX.e2_grav = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.08, 0.2); const cr = HD.easeOut(Math.min(1, u * 2.2));
  for (let b = 0; b < 4; b++) {
    if (!here(d, b)) continue; const ft = d.space.feet[b]; const h = hgt(d, b); const front = camSide(bnow(d, b));
    for (let i = 0; i < 2; i++) { const ph = (age * 1.3 + i * 0.5) % 1; const w0 = Math.sin(Math.PI * Math.min(1, ph * 1.1)) * k;
      for (let e = 0; e < 3; e++) { const pe = Math.max(0, ph - e * 0.06); const y = h * 1.7 * (1 - pe * pe); const R = h * (0.62 + 0.25 * pe); const w = w0 * (1 - e * 0.32); const pts = [];
        for (let j = 0; j <= 28; j++) { const a = j / 28 * Math.PI * 2; pts.push([ft[0] + Math.cos(a) * R, y, ft[2] + Math.sin(a) * R * 0.5]); }
        for (const run of HD.splitRuns(pts, front, true)) { if (run.pts.length < 2) continue;
          out.ribbons.push({ pts: run.pts, width: h * (e ? 0.2 : 0.32), cell: 'boltglow', color: f.color, intensity: 0.6 * w, add: 1, back: !run.f });
          if (!e) out.ribbons.push({ pts: run.pts, width: h * 0.08, cell: 'energy', color: e2Lite(f.color, 0.12), intensity: 0.75 * w, add: 1, back: !run.f, scroll: age * 3 }); } }
      if (ph > 0.85) out.distort.push({ p: [ft[0], 0.1, ft[2]], cell: 'shock', size: [h * 3, h * 3], strength: 0.5 * (1 - (ph - 0.85) / 0.15) * k, mode: 2 }); }
    out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 2.3, h * 1.35], color: [0.12, 0.04, 0.22], alpha: 0.6 * k, add: 0, intensity: 1, mode: 2 });
    out.decals.push({ p: [ft[0], 0.035, ft[2]], cell: 'crack', size: [h * 2.1 * cr, h * 1.3 * cr], rot: b * 1.3, color: [0.16, 0.06, 0.26], alpha: 0.9 * k, add: 0, intensity: 1, mode: 2 });
  }
};
HD.FX_STEP.e2_grav = function (d, f, age) {
  const u = age / f.life; const k = env01(u, 0.08, 0.2);
  for (let b = 0; b < 4; b++) {
    if (!here(d, b)) continue; const a = d.act[b]; const h = hgt(d, b); const ft = d.space.feet[b];
    let slam = 0; for (let i = 0; i < 2; i++) { const ph = (age * 1.3 + i * 0.5) % 1; if (ph > 0.85) slam = Math.max(slam, 1 - (ph - 0.85) / 0.15); }
    if (a) { const q = (0.07 + 0.08 * slam) * k; a.sy *= 1 - q; a.sx *= 1 + q * 0.7; }
    if (slam > 0.9) for (const s of [-1, 1]) d.emit(PS.dustPuff, [ft[0] + s * h * 0.45, 0.1, ft[2] - 0.2], 2, { dir: [s * 0.8, 0.05, 0], spread: 0.3, scale: 1.1, ramp: 'dust' });
    if (d.frame % 2 === b % 2 && u < 0.85) d.emit(PS.windStreak, [ft[0] + d.rng.range(-0.8, 0.8) * h, h * d.rng.range(1.2, 2.2), ft[2] + d.rng.range(-0.3, 0.3) * h], 1, { dir: [0, -1, 0], spread: 0.05, ramp: 'psychic', scale: 1.2 });
  }
};

// ---- Calm Mind: soft violet halos converge on the user with gathering motes; while the world is hidden the empty places
// sink into darkness; a calm aura breathes out at the end
HD.MOVE_FX.e2_converge = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_converge', { b, life: (e.dur || 24) / FPS, color: e.color || [0.7, 0.55, 1] }); };
HD.FX.e2_converge = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = bnow(d, f.b); const h = hgt(d, f.b); const R = h * (1.5 - 1.1 * HD.easeIn(u)); const k = Math.min(1, u * 5) * (1 - HD.smooth((u - 0.7) / 0.3));
  const pts = []; for (let j = 0; j <= 32; j++) { const a = j / 32 * Math.PI * 2; pts.push(scrOff(c, Math.cos(a) * R, Math.sin(a) * R * 0.92)); }
  out.ribbons.push({ pts, width: h * 0.42 * (1 - 0.5 * u), cell: 'boltglow', color: f.color, intensity: 0.42 * k, add: 1 });
  out.cards.push({ p: [c[0], c[1], c[2] - 0.2], back: true, cell: 'dot', size: [h * 1.6, h * 1.7], color: f.color, alpha: 0.35 * k * u, add: 1, intensity: 1 });
  out.distort.push({ p: c, cell: 'shock', size: [R * 2.3, R * 2.3], strength: 0.25 * k, mode: 0 });
};
HD.FX_STEP.e2_converge = function (d, f, age) { const c = bnow(d, f.b); const h = hgt(d, f.b); if (d.frame % 2) return; for (let i = 0; i < 3; i++) { const dir = d.rng.unit(); dir[2] *= 0.3; d.emit(Object.assign({}, PS.glint, { speed: [0, 0], life: [0.35, 0.45] }), V.madd([0, 0, 0], c, dir, h * 1.3), 1, { vel: V.scale([0, 0, 0], dir, -h * 2.8), ramp: 'psychic' }); } };
HD.MOVE_FX.e2_hush = (d, e) => d.addFx('e2_hush', { life: (e.dur || 64) / FPS });
HD.FX.e2_hush = function (d, f, age, out) {   // the hidden battlers' places sink into darkness (no bare platforms)
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.12, 0.2);
  for (let b = 0; b < 4; b++) { if (b === d.atkB() || !here(d, b)) continue; const ft = d.space.feet[b]; const h = hgt(d, b); for (let i = 0; i < 3; i++) out.cards.push({ p: [ft[0] + (i - 1) * h * 0.35, h * (0.12 + 0.1 * (i % 2)), ft[2] + 0.3 + i * 0.1], cell: 'smoke' + i, size: [h * 1.7, h * 1.2], rot: i * 1.9 + age * 0.2 * (i % 2 ? 1 : -1), color: [0.1, 0.06, 0.2], alpha: 0.85 * k, add: 0, hot: 0, intensity: 1 }); }
  const c = bnow(d, d.atkB()); const h = hgt(d, d.atkB()); const ft = d.space.feet[d.atkB()];
  out.decals.push({ p: [ft[0], 0.035, ft[2]], cell: 'dot', size: [h * 2.4, h * 1.4], color: [0.72, 0.6, 1], alpha: 0.4 * k, add: 1, intensity: 1, mode: 2 });
  out.lights.push({ p: [c[0], c[1] + h, c[2] + 1], color: [0.75, 0.65, 1], intensity: 3 * k, range: 7 });
};

// ---- chimes: golden sound fronts ring out from a point to both sides (a bell's chime: '(( ))'), not ring outlines
HD.MOVE_FX.e2_chime = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_chime', { b, life: (e.dur || 26) / FPS, color: e.color || [1, 0.85, 0.4], y: e.y != null ? e.y : 0.85 }); };
HD.FX.e2_chime = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const c = scrOff(bnow(d, f.b), 0, h * f.y); c[2] += 0.4;
  for (let i = 0; i < 3; i++) { const v = u * 1.4 - i * 0.2; if (v <= 0 || v >= 1) continue; const R = h * (0.3 + v * 1.2); const kk = Math.sin(Math.PI * v);
    for (const s of [-1, 1]) { const a0 = s > 0 ? -0.75 : Math.PI - 0.75, a1 = s > 0 ? 0.75 : Math.PI + 0.75; const pts = arcPts(c, R, a0, a1, 12);
      out.ribbons.push(tapered(pts, h * 0.22, { cell: 'boltglow', color: f.color, intensity: 0.5 * kk, add: 1 })); out.ribbons.push(tapered(pts, h * 0.07, { cell: 'beam', color: e2Lite(f.color, 0.3), intensity: 1.1 * kk, add: 1 })); } }
};
HD.FX_STEP.e2_chime = function (d, f) { if (f.done) return; f.done = true; const h = hgt(d, f.b); d.emit(PS.e_sparkle, scrOff(bnow(d, f.b), 0, h * f.y), 6, { ramp: 'gold', radius: h * 0.2, speedMul: 1.8, scale: h / 4 }); };

// ---- Healing Wish: the wish rises: a pink-gold star of light lifts from the user into the sky with a long trail
HD.MOVE_FX.e2_ascend = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('e2_ascend', { b, life: (e.dur || 50) / FPS, color: e.color || [1, 0.6, 0.85] }); };
HD.FX.e2_ascend = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const c = bnow(d, f.b); const at = (t) => scrOff(c, Math.sin(t * 5) * h * 0.15 * t, h * (0.1 + 3.6 * HD.easeIn(t)));
  const p = at(u); const pts = []; for (let j = 8; j >= 0; j--) pts.push(at(Math.max(0, u - j * 0.035))); const k = Math.min(1, u * 6) * (1 - HD.smooth((u - 0.85) / 0.15));
  out.ribbons.push({ pts, width: h * 0.32, cell: 'trail', color: f.color, intensity: 1.1 * k, alpha: 0.85, add: 1, taper: 0.85 });
  out.cards.push({ p, cell: 'dot', size: [h * 0.9, h * 0.9], color: f.color, alpha: 0.45 * k, add: 1, intensity: 1 });
  out.cards.push({ p, cell: 'star5', size: [h * 0.34, h * 0.34], rot: age * 3, color: [1, 0.85, 0.6], alpha: k, add: 0.6, intensity: 1.5 });
  out.lights.push({ p, color: f.color, intensity: 3 * k, range: 7 });
};
HD.FX_STEP.e2_ascend = function (d, f, age) { const h = hgt(d, f.b); const u = age / f.life; if (d.frame % 2 === 0 && u < 0.85) { const c = bnow(d, f.b); d.emit(PS.e_sparkle, scrOff(c, 0, h * (0.1 + 3.6 * HD.easeIn(u))), 1, { ramp: 'pink', radius: h * 0.12, scale: h / 4 }); } };

