function battlerNow(d, b) { const r = (d.oam || []).find((x) => x.kind === 'battler' && x.id === b); return r ? d.space.lift(r.x, r.y, d.space.depth[b] || 30) : d.bpos(b); }
function nearestB(d, p) { const nb = d.space.nearestBattler(p); return nb.b >= 0 ? nb.b : d.atkB(); }
