// colour, a tint of the picture toward a colour (linear light, kept partial so pixel art stays readable)
function glowB(d, b, col, g) { const a = d.act[b]; if (a && g > a.glow[3]) a.glow = [col[0], col[1], col[2], g]; }
function tintB(d, b, col, amt) { const a = d.act[b]; if (a && amt > a.flash[3]) a.flash = [col[0], col[1], col[2], amt]; }
