    g.beginPath(); g.moveTo(-R * 0.82, R * 0.12);
    g.bezierCurveTo(-R * 0.86, -R * 0.62, -R * 0.36, -R * 0.9, 0, -R * 0.88); g.bezierCurveTo(R * 0.4, -R * 0.9, R * 0.88, -R * 0.6, R * 0.82, R * 0.12);
