HD.CELL_PAINTERS.f_sigil = { draw(g, R) {   // a generic sigil ring: double ring, rune ticks, four diamond notches (bright lines; no letter, no logo)
  const { lum } = TX(); g.lineCap = 'round';
  const fg = g.createRadialGradient(0, 0, R * 0.2, 0, 0, R * 0.9); fg.addColorStop(0, lum(120, 0.05)); fg.addColorStop(1, lum(160, 0.3)); g.fillStyle = fg; g.beginPath(); g.arc(0, 0, R * 0.88, 0, Math.PI * 2); g.fill();
  g.strokeStyle = lum(250); g.lineWidth = R * 0.07; g.beginPath(); g.arc(0, 0, R * 0.86, 0, Math.PI * 2); g.stroke();
  g.strokeStyle = lum(215); g.lineWidth = R * 0.03; g.beginPath(); g.arc(0, 0, R * 0.7, 0, Math.PI * 2); g.stroke();
  g.strokeStyle = lum(235); g.lineWidth = R * 0.03; for (let i = 0; i < 24; i++) { const a = i / 24 * Math.PI * 2; const r0 = i % 2 ? R * 0.72 : R * 0.74, r1 = i % 2 ? R * 0.78 : R * 0.84; g.beginPath(); g.moveTo(Math.cos(a) * r0, Math.sin(a) * r0); g.lineTo(Math.cos(a) * r1, Math.sin(a) * r1); g.stroke(); }
  g.fillStyle = lum(255); for (let i = 0; i < 4; i++) { const a = i * Math.PI / 2; const x = Math.cos(a) * R * 0.86, y = Math.sin(a) * R * 0.86; g.beginPath(); g.moveTo(x + Math.cos(a) * R * 0.12, y + Math.sin(a) * R * 0.12); g.lineTo(x - Math.sin(a) * R * 0.07, y + Math.cos(a) * R * 0.07); g.lineTo(x - Math.cos(a) * R * 0.12, y - Math.sin(a) * R * 0.12); g.lineTo(x + Math.sin(a) * R * 0.07, y - Math.cos(a) * R * 0.07); g.closePath(); g.fill(); }
} };
HD.CELL_PAINTERS.f_hexcell = { draw(g, R) {   // one glowing hexagonal cell: bright rim, darker body, a bright nucleus
  const { lum } = TX(); const hex = (r) => { g.beginPath(); for (let i = 0; i < 6; i++) { const a = i / 6 * Math.PI * 2 + Math.PI / 6; g.lineTo(Math.cos(a) * r, Math.sin(a) * r); } g.closePath(); };
  const bg = g.createRadialGradient(0, 0, 0, 0, 0, R * 0.8); bg.addColorStop(0, lum(200)); bg.addColorStop(0.5, lum(120)); bg.addColorStop(1, lum(170)); g.fillStyle = bg; hex(R * 0.78); g.fill();
  g.strokeStyle = lum(255); g.lineWidth = R * 0.1; hex(R * 0.78); g.stroke();
  const ng = g.createRadialGradient(0, 0, 0, 0, 0, R * 0.26); ng.addColorStop(0, lum(255)); ng.addColorStop(1, lum(200, 0)); g.fillStyle = ng; g.beginPath(); g.arc(0, 0, R * 0.26, 0, Math.PI * 2); g.fill();
} };
HD.addRamp('f_wraith', [[0, 1, 0.38, 0.55, 1], [0.1, 0.92, 0.3, 0.72, 1], [0.28, 0.56, 0.3, 0.98, 1], [0.55, 0.2, 0.08, 0.38, 1], [1, 0.035, 0.01, 0.06, 1]]);
HD.addRamp('f_syrup', [[0, 1, 0.9, 0.75, 1], [0.12, 0.98, 0.5, 0.18, 1], [0.32, 0.82, 0.16, 0.05, 1], [0.58, 0.5, 0.04, 0.03, 1], [1, 0.18, 0.01, 0.01, 1]]);
HD.addRamp('f_syrupgold', [[0, 1, 0.98, 0.86, 1], [0.15, 1, 0.84, 0.32, 1], [0.4, 0.95, 0.56, 0.07, 1], [0.7, 0.6, 0.28, 0.03, 1], [1, 0.28, 0.12, 0.02, 1]]);

// ================================================================== Nightmare: a shadow wraith rises out of the sleeper
// GBA: the devil sprite starts on the battler's body and drifts up past its head with a sine sway, fading in and out
// (AnimGhostStatusSprite); the battler shakes. HD: inside the body the sprite is only dark smoke seeping out; above
// the head it takes shape as a horned wraith with glowing slit eyes, tethered to the head by a wisp of shadow. The
// sleeper darkens toward violet and shudders while it hovers.
K.f_wraith = {
  init(d, it) { it.s.b = d.atkB(); },
  update(d, it, cfg) {
    const b = it.s.b; const g = d.space.gba[b]; const h = d.space.battlerHeight(b); const a = clamp(it.alpha * 1.7, 0, 1);
    const up = g[1] - it.rec.y; const em = sm01((up + 4) / 26);   // 0 while on the body, 1 once above the head
    const sz = h * (0.4 + 0.42 * em); const L = it.cards;
    const p = scrOff(it.p, 0, sz * 0.42 * em); p[2] += 0.25;   // the wraith hangs from the runtime's point by its tail
    const head = headOf(d, b); head[2] += 0.2;
    if (em > 0.05) {   // the shadow tether from the sleeper's head to the wraith's tail
      const tail = scrOff(p, 0, -sz * 0.36); const mid = V.lerp([0, 0, 0], head, tail, 0.5); mid[0] += Math.sin(it.age * 7) * h * 0.08;
      L.push({ layer: 'ribbons', fixed: true, pts: [head, mid, tail], widths: [h * 0.2, h * 0.13, h * 0.06], width: h * 0.2, cell: 'beam', color: [0.08, 0.02, 0.14], alpha: 0.75 * a * em, add: 0, intensity: 1 });
      L.push({ layer: 'ribbons', fixed: true, pts: [head, mid, tail], widths: [h * 0.34, h * 0.24, h * 0.1], width: h * 0.34, cell: 'boltglow', color: [0.5, 0.22, 0.9], alpha: 0.35 * a * em, add: 1, intensity: 0.9 });
    }
    const k = a * em;
    L.push({ fixed: true, p, cell: 'dot', size: [sz * 2.1, sz * 2.1], color: cfg.halo || [0.5, 0.22, 0.9], alpha: 0.3 * k, add: 1, intensity: 1 });
    L.push({ fixed: true, p, cell: 'f_wraith', size: [sz * 1.14, sz * 1.14], rot: Math.sin(it.age * 3) * 0.08, color: [0.55, 0.3, 1], alpha: 0.35 * k, add: 1, intensity: 1 });
    L.push({ fixed: true, p, cell: 'f_wraith', size: [sz * 1.05, sz * 1.05], rot: Math.sin(it.age * 3) * 0.08, color: [0.02, 0, 0.04], alpha: 0.55 * k, add: 0, hot: 0, intensity: 1 });
    L.push({ fixed: true, p, cell: 'f_wraith', size: [sz, sz], rot: Math.sin(it.age * 3) * 0.08, color: [1, 1, 1], gmap: cfg.ramp || 'f_wraith', alpha: 0.95 * k, add: 0.04, intensity: 1.1 });
    const fl = 0.75 + 0.25 * Math.sin(it.age * 23 + it.uid);   // the eyes flicker
    for (const s of [-1, 1]) L.push({ fixed: true, p: scrOff(p, s * sz * 0.075, sz * 0.17), cell: 'dot', size: [sz * 0.2, sz * 0.2], color: cfg.eye || [1, 0.25, 0.45], alpha: 0.8 * k * fl, add: 1, intensity: 1.6 });
    const n = every(it, 'w', 10); if (n) d.emit(PS.wisp, em > 0.3 ? scrOff(p, 0, -sz * 0.3) : p, n, { ramp: 'ghost', scale: 1.3, radius: sz * 0.25, vel: [0, 0.5, 0] });
    const m = every(it, 'g', 12 * em); if (m) d.emit(PS.wisp, p, m, { ramp: 'ghost', scale: 0.9, radius: sz * 0.3 });
    d.light(p, [0.55, 0.28, 0.95], 1.4 * k, 6, 'wraith');
  }
};
// the sleeper's side: a violet darkening that pulses, a violet rim, shadow seeping from the head, a pained shudder
HD.MOVE_FX.f_dread = (d, e) => d.addFx('f_dread', { b: d.battlerRef(e.b || 'attacker'), life: (e.dur || 40) / FPS, color: e.color || [0.13, 0.04, 0.24], rim: e.rim || [0.42, 0.16, 0.85], rate: e.rate || 8 });
HD.FX.f_dread = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); const k = env01(u, 0.15, 0.3);
  out.cards.push({ p: [c[0], c[1] + h * 0.1, c[2] - 0.1], back: true, cell: 'smoke2', size: [h * 2.2, h * 1.9], rot: age * 0.4, color: [0.1, 0.03, 0.16], alpha: 0.5 * k, add: 0, intensity: 1 });
  out.lights.push({ p: [c[0], c[1] + h * 0.4, c[2] + 0.6], color: f.rim, intensity: 1.6 * k, range: 7 });
};
HD.FX_STEP.f_dread = function (d, f, age) {
  const u = age / f.life; const k = env01(u, 0.15, 0.3); const pul = 0.75 + 0.25 * Math.sin(age * 9);
  tintB(d, f.b, f.color, 0.42 * k * pul); glowB(d, f.b, f.rim, 0.24 * k);
  const a = d.act[f.b]; if (a && u < 0.6) { const sh = Math.sin(age * 55) * (1 - u / 0.6); a.sx *= 1 + 0.02 * sh; a.sy *= 1 - 0.025 * sh; }
  f.acc = (f.acc || 0) + f.rate / FPS; const n = Math.floor(f.acc); f.acc -= n;
  if (n) { const hd = headOf(d, f.b); const h = d.space.battlerHeight(f.b); d.emit(PS.wisp, hd, n, { ramp: 'ghost', radius: h * 0.25, vel: [0, 0.9, 0], scale: 1.4 }); }
};

// ================================================================== held items: knocked off, stolen
// The pouch is the generic held-item picture (the Lab does not know the battlers' items; v3.js satchel, cloth ramp).
function drawPouch(L, p, sz, rot, a, glow) {
  L.push({ fixed: true, p, cell: 'dot', size: [sz * 1.8, sz * 1.8], color: glow, alpha: 0.26 * a, add: 1, intensity: 1 });
  L.push({ fixed: true, p, cell: 'satchel', size: [sz * 1.14, sz * 1.14], rot, color: glow, alpha: 0.4 * a, add: 1, intensity: 1 });
  L.push({ fixed: true, p, cell: 'satchel', size: [sz * 1.06, sz * 1.06], rot, color: [0.1, 0.05, 0.03], alpha: 0.6 * a, add: 0, hot: 0, intensity: 1 });
  L.push({ fixed: true, p, cell: 'satchel', size: [sz, sz], rot, color: [1, 1, 1], gmap: 'cloth', alpha: a, add: 0, intensity: 1 });
}
// cfg.mode 'knock': swatted off its holder and sent tumbling away; 'steal': pulled across by a shadow tendril into
// the thief, where it vanishes with a glint as it lands (the GBA leaves the icon sitting on the thief: not drawn).
K.f_pouch = {
  init(d, it, cfg) {
    const s = it.s; const ti = V3.trackInfo(d, it.uid); s.ti = ti; s.f0 = d.frame;
    s.holder = nearestB(d, d.space.liftAuto(ti ? ti.x0 : it.rec.x, ti ? ti.y0 : it.rec.y));
    s.thief = ti ? nearestB(d, d.space.liftAuto(ti.x1, ti.y1)) : d.atkB();
    s.arrive = ti ? ti.lastMove : d.frame + 60; s.glow = cfg.glow || [0.62, 0.4, 0.95];
    s.spinDir = ti && ti.x1 < ti.x0 ? 1 : -1;
    if (cfg.mode === 'knock') {   // the swat that knocks it loose
      const h = d.space.battlerHeight(s.holder); const p = it.p.slice(); p[2] += 0.3;
      const ang = ti ? Math.atan2(-(ti.tr.y[Math.min(6, ti.n - 1)] - ti.y0), ti.tr.x[Math.min(6, ti.n - 1)] - ti.x0) : 0.6;
      d.addFx('card', { p: scrOff(p, -Math.cos(ang) * h * 0.25, -Math.sin(ang) * h * 0.25), cell: 'swoosh', size0: h * 0.7, size1: h * 1.15, rot: ang, color: [0.75, 0.55, 1], gmap: 'dark', intensity: 1.5, life: 0.16, add: 1 });
      d.addFx('card', { p, cell: 'impact3', size0: h * 0.25, size1: h * 0.6, rot: ang, color: [0.85, 0.7, 1], gmap: 'psychic', intensity: 1.2, life: 0.12, add: 1 });
      d.impact({ b: s.holder, pos: p, strength: 0.55, minGap: 1, burstScale: 0.45, knock: 0.7, force: true });
      d.emit(PS.energy, p, 10, { ramp: 'dark', scale: 1.1 }); d.emit(PS.hitStreak, p, 6, { ramp: 'white', dir: [Math.cos(ang), Math.sin(ang), 0], spread: 0.5 });
      d.addFx('card', { p: toward(p, 0.3), cell: 'swoosh', size0: h * 1.0, size1: h * 1.7, rot: ang, color: [0.6, 0.35, 1], gmap: 'dark', intensity: 1.6, life: 0.2, add: 1 });   // wave 2: a bigger swat
      d.addFx('card', { p: toward(p, 0.35), cell: 'flare', size0: h * 0.9, size1: h * 0.3, color: [1, 0.85, 0.5], intensity: 1.2, life: 0.14, add: 1 });
    }
    if (cfg.mode === 'steal') {   // wave 2: plucked off its holder with a pop
      const h = d.space.battlerHeight(s.holder); const p = toward(it.p, 0.3); d.addFx('card', { p, cell: 'flare', size0: h * 0.8, size1: h * 0.25, color: [0.75, 0.5, 1], intensity: 1.2, life: 0.18, add: 1 });
      d.emit(PS.glint, p, 10, { ramp: 'gold', radius: h * 0.15, speedMul: 1.5 }); d.emit(PS.darkSmoke, p, 4, { scale: 1 }); const a = d.act[s.holder]; if (a) a.kick.push({ t0: d.t, life: 0.25, amp: 3.5, dir: (s.holder & 1) ? 1 : -1, squash: 0.06 });
    }
  },
  update(d, it, cfg) {
    const s = it.s; const h = d.space.battlerHeight(s.holder); let sz = h * (cfg.v3size || 0.4); const f = d.frame; const L = it.cards; const p = it.p.slice(); p[2] += 0.25;
    if (cfg.mode === 'steal') {
      if (f >= s.arrive) { if (!s.done) { s.done = true; d.addFx('f_pocket', { to: s.thief, life: 0.55, size: sz, color: s.glow }); } return; }
      const em = sm01((f - s.f0) / 10); sz *= 0.6 + 0.4 * em;
      const tc = d.bpos(s.thief); tc[2] += 0.2; const hT = d.space.battlerHeight(s.thief); const near = clamp(V.dist(tc, p) / (hT * 0.7), 0, 1);
      const grip = scrOff(p, 0, sz * 0.32); const mid = V.lerp([0, 0, 0], tc, grip, 0.5); mid[1] += hT * 0.3 + Math.sin(it.age * 9) * hT * 0.06;   // a shadow tendril from the thief, gripping the pouch's neck
      const ka = em * near;
      if (ka > 0.02 && cfg.tendril) {   // wave 2: off by default (the reviewers read it as a tentacle); the pouch flies on its own
        const pts = []; for (let i = 0; i <= 8; i++) { const t = i / 8; const q = V.lerp([0, 0, 0], V.lerp([0, 0, 0], tc, mid, t), V.lerp([0, 0, 0], mid, grip, t), t); q[0] += Math.sin(t * 9 - it.age * 12) * hT * 0.035 * Math.sin(Math.PI * t); pts.push(q); }
        L.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => hT * (0.36 - 0.18 * i / 8)), width: hT * 0.36, cell: 'boltglow', color: [0.5, 0.25, 0.9], alpha: 0.5 * ka, add: 1, intensity: 0.9 });
        L.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => hT * (0.13 - 0.06 * i / 8)), width: hT * 0.13, cell: 'beam', color: [0.07, 0.02, 0.12], alpha: 0.92 * ka, add: 0, intensity: 1 });
        const hc = [grip[0], grip[1], grip[2] + 0.05]; const hs = hT * 0.34;   // the tendril's shadow hand closed on the drawstring
        L.push({ fixed: true, p: hc, cell: 'fist3', size: [hs * 1.12, hs * 1.12], color: [0.5, 0.25, 0.9], alpha: 0.5 * ka, add: 1, intensity: 1 });
        L.push({ fixed: true, p: hc, cell: 'fist3', size: [hs, hs], color: [0.16, 0.07, 0.26], alpha: 0.95 * ka, add: 0, hot: 0.2, intensity: 1 });
      }
    }
    const rot = cfg.mode === 'knock' ? s.spinDir * it.age * 9 : Math.sin(it.age * 6 + it.uid) * 0.25;
    if (V.len(it.v) > 2 && it.hist.length > 2) { const pts = it.hist.slice(-5).concat([p]); L.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => sz * 0.5 * (i / (pts.length - 1))), width: sz * 0.5, cell: 'trail', color: s.glow, intensity: 1, alpha: 0.5, add: 1 }); }
    drawPouch(L, p, sz, rot, it.alpha, s.glow);
    const n = every(it, 'g', 8); if (n) d.emit(PS.glint, p, n, { ramp: 'gold', scale: sz / 2.2, radius: sz * 0.4 });
    d.light(p, s.glow, 0.7 * it.alpha, 6, 'item');
  }
};

// the stolen pouch pockets into the thief: it shrinks into the chest with a small dark puff and a glint (no ring)
HD.FX.f_pocket = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.to); const h = d.space.battlerHeight(f.to); const k = 1 - u;
  if (u < 0.6) { const s = f.size * (1 - u / 0.6); out.cards.push({ p: [c[0], c[1] + h * 0.15 * (1 - u), c[2] + 0.3], cell: 'satchel', size: [s, s], color: [1, 1, 1], gmap: 'cloth', alpha: 1, add: 0, intensity: 1 }); }
  out.cards.push({ p: [c[0], c[1] + h * 0.1, c[2] + 0.35], cell: 'star4', size: [h * (0.2 + 0.45 * Math.sin(Math.PI * u)), h * (0.2 + 0.45 * Math.sin(Math.PI * u))], rot: age * 3, color: [1, 0.9, 0.6], alpha: k, add: 1, intensity: 1.5 });
  out.lights.push({ p: c, color: f.color, intensity: 3 * k, range: 7 });
};
HD.FX_STEP.f_pocket = function (d, f, age) { const ac = d.act[f.to]; if (ac && age < 0.4) ac.fxOff[1] -= Math.max(0, Math.sin(age / 0.4 * Math.PI)) * 5; if (f.done) return; f.done = true; const c = d.bpos(f.to); const h = d.space.battlerHeight(f.to); d.emit(PS.glint, c, 10, { ramp: 'gold', radius: h * 0.3 }); d.emit(PS.energy, c, 8, { ramp: 'dark', radius: h * 0.25 }); glowB(d, f.to, f.color, 0.3); };

// ================================================================== Shell Trap set up: a ring of fire round the user, then a red-hot shell glow
// GBA: seven embers spread from the user's lower body (AnimFireSpread), then four hit splats on it. HD: each ember is a
// flame rooted on the ground where its spread puts it (the ring round the user's feet), rising and dying down; the
// splats become the shell heating up (a contained orange glow behind the user, a hot rim, embers), not a white blob.
K.f_groundflame = {
  init(d, it, cfg) { const ti = V3.trackInfo(d, it.uid); it.s.o = ti ? [ti.x0, ti.y0] : [it.rec.x, it.rec.y]; it.s.b = d.atkB(); it.s.fr = it.uid % 4; it.s.life = ti ? (ti.f1 - ti.f0) / FPS : 0.7; },
  update(d, it, cfg) {
    const s = it.s; const b = s.b; const ft = d.space.feet[b]; const h = d.space.battlerHeight(b); const k = d.space.kpx(d.space.depth[b]); const ramp = cfg.ramp || 'fire';
    const dx = (it.rec.x - s.o[0]) * k * 1.2, dz = (it.rec.y - s.o[1]) * k * 0.75;
    const u = it.age / Math.max(0.2, s.life); const grow = sm01(u / 0.3) * (1 - sm01((u - 0.72) / 0.28) * 0.8);
    const H = h * (0.3 + 0.62 * grow) * (0.88 + 0.12 * Math.sin(it.age * 14 + it.uid * 2));
    const p = [ft[0] + dx, H * 0.46, ft[2] + dz]; const back = dz < -0.1; const fr = (s.fr + Math.floor(it.age * 14)) % 4; const a = it.alpha;
    it.cards.push({ fixed: true, back, p, cell: 'flame' + fr, size: [H * 0.62, H], color: [1, 1, 1], gmap: ramp, alpha: 0.95 * a, add: 0.35, intensity: 1.2 });
    it.cards.push({ fixed: true, back, p: [p[0], H * 0.36, p[2] + 0.02], cell: 'flame' + ((fr + 2) % 4), size: [H * 0.4, H * 0.66], color: [1, 1, 1], gmap: ramp, alpha: 0.75 * a, add: 0.75, intensity: 0.95 });
    it.cards.push({ fixed: true, p: [p[0], 0.04, p[2]], cell: 'dot', size: [H * 1.1, H * 0.6], color: [1, 0.45, 0.12], alpha: 0.5 * a, add: 1, intensity: 1, mode: 2 });
    const n = every(it, 'f', 10); if (n) d.emit(PS.fireLick, [p[0], H * 0.3, p[2]], n, { ramp, scale: H / 2.2 });
    const e = every(it, 'e', 10); if (e) d.emit(PS.ember, [p[0], H * 0.6, p[2]], e, { scale: 0.9 });
    d.light([p[0], 1, p[2] + 0.3], [1, 0.55, 0.2], 1.6 * a, 6, 'fire');
  },
  end(d, it) { const h = d.space.battlerHeight(it.s.b); d.emit(PS.smoke, it.p, 2, { scale: h / 3.5 }); }
};
HD.MOVE_FX.f_hotshell = (d, e) => d.addFx('f_hotshell', { b: d.battlerRef(e.b || 'attacker'), life: (e.dur || 16) / FPS });
HD.FX.f_hotshell = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); const k = env01(u, 0.2, 0.45); const pul = 0.8 + 0.2 * Math.sin(age * 22);
  out.cards.push({ p: [c[0], c[1] + h * 0.08, c[2] - 0.15], back: true, cell: 'shell3', size: [h * 1.45, h * 1.25], color: [1, 0.5, 0.28], gmap: 'fire', alpha: 0.42 * k * pul, add: 0.25, intensity: 1.0 });
  out.cards.push({ p: [c[0], c[1], c[2] - 0.2], back: true, cell: 'flare', size: [h * 1.5, h * 1.5], color: [1, 0.3, 0.06], alpha: 0.4 * k * pul, add: 1, intensity: 1.0 });
  out.distort.push({ p: [c[0], c[1] + h * 0.85, c[2]], cell: 'smoke1', size: [h * 1.4, h * 0.9], strength: 0.25 * k, mode: 1 });
  out.lights.push({ p: [c[0], c[1], c[2] + 0.8], color: [1, 0.5, 0.18], intensity: 4 * k * pul, range: 8 });
};
HD.FX_STEP.f_hotshell = function (d, f, age) {
  const u = age / f.life; const k = env01(u, 0.2, 0.45); tintB(d, f.b, [1, 0.32, 0.08], 0.22 * k); glowB(d, f.b, [1, 0.45, 0.12], 0.6 * k);
  const c = d.bpos(f.b); const h = d.space.battlerHeight(f.b); d.emit(PS.ember, c, 2, { radius: h * 0.45, vel: [0, 1.6, 0], scale: 1.1 });
};

