  ULTRA: [[44, 44, 52], [245, 245, 245], [250, 210, 40]], MASTER: [[130, 50, 180], [245, 245, 245], [245, 110, 200]], PREMIER: [[245, 245, 245], [245, 245, 245], [220, 50, 40]],
  HEAL: [[245, 140, 195], [250, 250, 250], [120, 200, 240]], NET: [[40, 150, 200], [245, 245, 245], [30, 40, 60]], NEST: [[120, 190, 60], [225, 205, 150], [70, 120, 30]],
  DIVE: [[40, 120, 235], [245, 245, 245], [140, 220, 255]], DUSK: [[40, 90, 60], [60, 60, 66], [250, 140, 40]], TIMER: [[245, 245, 245], [245, 245, 245], [220, 50, 40]],
  QUICK: [[60, 120, 235], [245, 245, 245], [250, 220, 60]], REPEAT: [[240, 120, 40], [245, 245, 245], [250, 220, 60]], LUXURY: [[36, 36, 42], [50, 50, 56], [225, 60, 40]],
  LEVEL: [[200, 45, 45], [245, 245, 245], [250, 210, 40]], LURE: [[40, 110, 220], [245, 245, 245], [60, 190, 120]], MOON: [[50, 70, 150], [245, 245, 245], [250, 225, 90]],
  FRIEND: [[70, 170, 70], [245, 245, 245], [230, 60, 50]], LOVE: [[245, 120, 180], [245, 245, 245], [235, 60, 120]], FAST: [[250, 210, 50], [245, 245, 245], [230, 60, 50]],
  HEAVY: [[110, 120, 135], [245, 245, 245], [60, 110, 200]], DREAM: [[240, 140, 210], [250, 235, 245], [150, 90, 210]], SAFARI: [[120, 145, 60], [225, 210, 160], [90, 100, 40]],
  SPORT: [[240, 150, 40], [245, 245, 245], [200, 60, 40]], PARK: [[250, 210, 60], [245, 245, 245], [60, 110, 220]], BEAST: [[40, 60, 170], [70, 80, 160], [250, 220, 60]],
