      L.push({ fixed: true, back: true, p: [p[0], p[1], p[2] - 0.1], cell: 'dot', size: [sz * 3 * br, sz * 3 * br], color: [1, 0.75, 0.3], alpha: 0.35 * a, add: 1, intensity: 1 });
