function crustPieces(f, h) { const r = HD.rng(f.seed); const out = []; for (let i = 0; i < f.n; i++) { const side = i % 2 ? 1 : -1; const lvl = i / (f.n - 1); const front = i % 3 !== 1;
  out.push({ x: side * h * r.range(0.3, 0.5) * (1 - 0.3 * lvl), y: h * (0.06 + 0.66 * lvl) + r.range(-0.05, 0.05) * h, z: front ? r.range(0.2, 0.4) : -0.35, s: h * r.range(0.13, 0.2) * (1 - 0.25 * lvl), t0: 0.04 + lvl * 0.3, rot: [r() * 6, r() * 6, r() * 6] }); } return out; }
