  out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'frost', size: [h * 2.4 * sm01(age / 0.4), h * 2.4 * sm01(age / 0.4)], rot: 1, color: [0.85, 0.95, 1], alpha: 0.75 * k, add: 0, intensity: 1, mode: 2 });
