      if (prog > 0.25) L.push({ fixed: true, back: true, p: [c[0], c[1], c[2] - 0.25], cell: 'lightray', size: [R * (1.6 + 1.6 * prog), R * (1.6 + 1.6 * prog)], rot: it.age * 0.4, color: morphCol(S, 2, it.age), alpha: 0.4 * prog * a, add: 1, intensity: 1.1 });
