HD.FX.f_afterglow = function () {};
HD.FX_STEP.f_afterglow = function (d, f, age) { const u = age / f.life; const S = styleOf(d, f.style); glowB(d, f.b, morphCol(S, 0, age), 0.6 * (1 - u)); };
// a crown jewel over the Terastallized battler's head (a generic faceted gem, lit)
