HD.FX.f_sun = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.15, 0.25); const sun = [-13, 13, -22]; const r = HD.rng(f.seed);
  out.cards.push({ p: sun, cell: 'flare', size: [9, 9], color: [1, 0.85, 0.5], alpha: 0.75 * k, add: 1, intensity: 1.3 });
  out.cards.push({ p: sun, cell: 'lightray', size: [16, 16], rot: age * 0.08, color: [1, 0.82, 0.45], alpha: 0.4 * k, add: 1, intensity: 1 });
  for (let i = 0; i < 7; i++) { const x = r.range(-12, 14), z = r.range(-12, 6); const sway = Math.sin(age * 0.8 + i) * 0.6; const w = 1.2 + r() * 1.6; const fl = 0.6 + 0.4 * Math.sin(age * 1.5 + i * 2);
    out.ribbons.push({ pts: [[x - 9 + sway, 14, z - 4], [x + sway * 0.3, 0, z]], width: w, cell: 'boltglow', color: [1, 0.8, 0.45], intensity: 0.32 * k * fl, add: 1, alpha: 0.55, back: true }); }
  // wave 2: lens ghosts along the line from the sun across the frame (a camera glare instead of lighting the battlers white)
  for (let i = 0; i < 4; i++) { const t = 0.28 + i * 0.2; const p = [sun[0] + (8 - sun[0]) * t, sun[1] + (3 - sun[1]) * t, sun[2] + (4 - sun[2]) * t];
    out.cards.push({ p, cell: i % 2 ? 'ring' : 'dot', size: [1.2 + i * 0.7, 1.2 + i * 0.7], color: [[1, 0.6, 0.3], [1, 0.85, 0.4], [0.9, 0.6, 1], [1, 0.75, 0.4]][i], alpha: (i % 2 ? 0.16 : 0.22) * k, add: 1, intensity: 1 }); }
  out.lights.push({ p: [0, 12, -6], color: [1, 0.78, 0.5], intensity: 1.0 * k, range: 18 });
};
