  for (let i = 0; i < 26; i++) { const ph = (age * (0.9 + r() * 0.8) + r()) % 1; const y = 0.3 + r() * 5.5, z = r.range(-9, 6); const x = -14 + 30 * ph; const len = 2.5 + r() * 3.5;
    out.ribbons.push({ pts: [[x - len, y + 0.25, z], [x - len * 0.5, y + 0.1 + Math.sin(ph * 9 + i) * 0.15, z], [x, y, z]], width: 0.2 + r() * 0.3, cell: 'trail', color: [0.9, 0.68, 0.38], intensity: 0.95, alpha: 0.7 * k * Math.sin(Math.PI * ph), add: 0.35, taper: 0.6 }); }
