HD.FX.f_windcalm = function (d, f, age, out) { const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.1, 0.2); const r = HD.rng(f.seed);
  for (let i = 0; i < 18; i++) { const sp = 0.6 + r() * 0.9; const gust = 1 + 0.6 * Math.max(0, Math.sin(age * 1.7 + i)); const ph = (age * sp * gust * 0.7 + r()) % 1; const y = 0.5 + r() * 7, z = r.range(-11, 6); const x = -16 + 34 * ph; const len = 3 + r() * 4; const cy = Math.sin(ph * 6 + i) * 0.4;
    out.ribbons.push({ pts: [[x - len, y - 0.2, z], [x - len * 0.5, y + cy, z], [x, y + 0.15, z]], width: 0.18 + r() * 0.22, cell: 'trail', color: [0.82, 0.94, 1], intensity: 0.9, alpha: 0.6 * k * Math.sin(Math.PI * ph), add: 1, taper: 0.6 }); } };
