  for (let i = 0; i < 8; i++) { const a = age * 0.7 + i / 8 * Math.PI * 2; const p = [c[0] + Math.cos(a) * h * 0.6, c[1] + Math.sin(a * 1.3) * h * 0.3, c[2] + Math.sin(a) * h * 0.35]; out.cards.push({ p, back: !front(p), cell: 'smoke2', size: [h * 0.9, h * 0.9], rot: a, color: [0.12, 0.04, 0.2], alpha: 0.6 * k * pul, add: 0, intensity: 1 }); }
