  const n = e.puffs || 14; for (let i = 0; i < n; i++) { const a = (i / n) * TAU + d.rng() * 0.3; const dir = [Math.cos(a), 0.12, Math.sin(a) * 0.7]; d.emit(PS.dustPuff, [ft[0] + dir[0] * h * 0.35, 0.18, ft[2] + dir[2] * h * 0.35], 1, { dir, spread: 0.15, scale: 1.5 * (e.dustScale || 1), speedMul: 1.6 }); }
  d.emit(PS.dustPuff, [ft[0], 0.2, ft[2]], e.dust || 8, { dir: [0, 0.5, 0], spread: 1, scale: 1.6 * (e.dustScale || 1) });
  if (e.chips !== 0) d.emit(PS.chip, [ft[0], 0.3, ft[2]], e.chips || 8, { scale: 1.2 });
  if (e.crack !== false) d.addFx('decal', { p: [ft[0], 0.02, ft[2]], cell: 'crack', size: h * (e.crackSize || 0.95), life: 1.6, alpha: 0.85, rot: d.rng() * 6 });
