// ---- a battler's squash softened: the runtime flattens a battler (SquishTarget...) for a second or more; HD lets it pop
// back after `hold` frames (dur: frames to restore), keeping its bottom edge on the ground (act scale on top of the
// picture's own squash, gpu.squashPolicy)
HD.MOVE_FX.g2_unsquash = (d, e) => { const b = bRef(d, e.b || 'target'); if (!present(d, b)) return; d.addFx('g2_unsquash', { b, f0: d.frame + (e.hold || 6), dur: e.dur || 10, keep: e.keep != null ? e.keep : 0, life: lifeTo(d, e.until || 9999) }); };
HD.FX_STEP.g2_unsquash = function (d, f) {
  const a = d.act[f.b]; if (!a || !HD.GPU || !HD.GPU.squashPolicy) return; const rec = (d.oam || []).find((x) => x.kind === 'battler' && x.id === f.b); if (!rec || !(rec.affine & 1) || !rec.mat) return;
  const M = HD.GPU.squashPolicy(rec).mat; if (Math.abs(M.b) > 2 || Math.abs(M.c) > 2 || !M.a || !M.d) return;
  const sxp = 256 / Math.abs(M.a), syp = 256 / Math.abs(M.d); const k = smooth((d.frame - f.f0) / f.dur) * (1 - f.keep); if (k <= 0) return;
  const kx = (sxp + (1 - sxp) * k) / sxp, ky = (syp + (1 - syp) * k) / syp; a.sx *= kx; a.sy *= ky; a.dy += (1 - ky) * (32 * syp - 28.8);
};

// ================================================================== Seismic Toss: grab, launch, spin in the sky, slam
// The user dashes in and grabs; both leap up (the GBA scrolls the sky behind them) and whirl round in a loop high above
// the field with air rushing past; at the end of the scroll they plummet and the target is slammed into its pad (dust
// thrown along the ground, a crack, shake; the GBA's rock scatter and extra bounces follow), the user springs back home.
// Stays in frame; the GBA's own hits (variants) land on the slam.
