  const u = fr < f.cf ? easeIn(clamp((fr - f.f0) / Math.max(1, f.cf - f.f0), 0, 1)) : 1; const lift = fr > f.f1 - 6 ? easeIn((fr - (f.f1 - 6)) / 6) : 0;
  // raised high above-left of the target pointing up, driven down so the claw bites onto its head, lifted away
