  if (f.broke || d.frame < f.f1) return; f.broke = true; const c = drawnAt(d, f.b); const h = hOf(d, f.b); const p = scrOff(c, -h * 0.15, h * 0.02);
  d.emit(PS.g2_glass, p, 26, { radius: h * 0.45, scale: 1.2, speedMul: 1.3 }); d.emit(PS.glint, p, 10, { ramp: 'heal', radius: h * 0.5 });
