PS.g2_glass = { sys: 'add', cell: 'shard', life: [0.35, 0.7], size: [0.26, 0.12], speed: [2.5, 5], up: [0.3, 1.2], gravity: 5, drag: 1.2, ramp: 'heal', intensity: 1.6, spin: 9 };
