  const grow = smooth((fr - f.f0) / 100); const pul = 0.75 + 0.25 * Math.sin(age * 8);
  out.cards.push({ p, cell: 'dot', size: [h * (0.7 + 0.5 * grow), h * (0.55 + 0.4 * grow)], color: f.color, alpha: 0.5 * env * pul, add: 1, intensity: 1 });
  out.cards.push({ p, cell: 'swirl', size: [h * (0.5 + 0.3 * grow), h * (0.5 + 0.3 * grow)], rot: -age * 5, color: [1, 1, 1], gmap: 'g2_psy', alpha: 0.75 * env, add: 1, intensity: 1.0 });
  out.cards.push({ p, cell: 'flare', size: [h * 0.45 * (0.6 + grow), h * 0.45 * (0.6 + grow)], rot: age * 2, color: f.color, alpha: 0.5 * env * pul, add: 1, intensity: 1.0 });
  out.distort.push({ p, cell: 'swirl', size: [h * 0.9, h * 0.9], strength: 0.25 * env, mode: 0 });
