  const a = d.act[f.b]; if (!a) return; const u = clamp((d.frame - f.f0) / f.dur, 0, 1);
  if (u < 1) { a.dy -= Math.sin(Math.PI * u) * f.H; a.dx -= Math.sin(Math.PI * u) * f.H * 0.25 * (1 - u); regMove(a, -Math.sin(Math.PI * u) * f.H * 0.25 * (1 - u), -Math.sin(Math.PI * u) * f.H, d); if (u > 0.5) { a.sy *= 1.06; a.sx *= 0.95; } f.hist.push(drawnAt(d, f.b)); if (f.hist.length > 8) f.hist.shift(); }
