HD.moveAdd({ MOVE_WOOD_HAMMER: { impactStyle: G2S.g2_wood, fx: [
  at(1, 'g2_move', { b: 'attacker', keys: [[69, 0, 0, 0], [77, 0, 0, 24, 2], [82, 0, 0, 0, 1]] }),
  on('AnimTask_SquishTarget', 'g2_unsquash', { b: 'target', hold: 7, dur: 12 })
] } });

// ================================================================== hit splats (all group G moves)
// The GBA hit splat sprites (basic / flashing / random-position...) drew v2's white comic starburst for their whole life on
// top of the hit's own type-coloured spark: they keep their hit and kit (K.impact: reaction, burst, shake; the v3 contact
// rush keys off 'impact' marks) and draw only a brief soft glow in the move's colour.
const SPLATS = ['gBasicHitSplatSpriteTemplate', 'gFlashingHitSplatSpriteTemplate', 'gRandomPosHitSplatSpriteTemplate', 'gMonEdgeHitSplatSpriteTemplate', 'gPersistHitSplatSpriteTemplate', 'gSlamHitSpriteTemplate', 'gAquaTailHitSpriteTemplate', 'gWaterHitSplatSpriteTemplate'];
HD.v3.g2Splats = function (list) {
  for (const [id, type] of list) { const m = HD.MOVES[id] || (HD.MOVES[id] = {}); const tpl = m.tpl || {}; const add = {}; const lk = LOOK[String(type).toLowerCase()] || LOOK.normal;
    for (const t of SPLATS) if (!tpl[t]) add[t] = { kit: 'impact', cell: 'dot', color: lk.glow, intensity: 1, life: 0.14, scale: 1.0, add: 1 };
    HD.moveAdd({ [id]: { tpl: add } }); }
};

// ================================================================== C moves: shared building blocks
G2S.g2_normal = g2Style({ ramp: 'g2_warm', glow: [1, 0.72, 0.38], debris: (d, p, st) => { d.emit(PS.dustPuff, p, 2 + st * 2, { scale: 1 }); } });
// a dash in for each hit: the user arrives on each of the given frames (default: the script's hits) and leaves after the
// last one; hits closer together than the trip there and back keep it at the target in between; k: fraction of the
// distance; hop: GBA px it bounds up on the way in
HD.MOVE_FX.g2_multirush = (d, e) => {
  if (!d.plan) return; const hits = (e.frames || d.plan.hits.filter((x) => x.f >= (e.from || 3)).map((x) => x.f)).filter((f, i, a) => i === 0 || f - a[i - 1] > 2); if (!hits.length) return;
  const D = e.D || 6, R = e.R || 9, k = e.k || 0.6, hop = e.hop || 0; const keys = [[Math.max(1, hits[0] - D - 1), 0, 0, 0]];
  hits.forEach((h, i) => { const nx = hits[i + 1]; const last = keys[keys.length - 1];
    if (last[1] === 0) { keys.push([Math.max(last[0] + 1, h - D), -0.04, 0, 0]); if (hop) keys.push([h - D / 2, k * 0.5, 0, hop, 2]); keys.push([h, k, 0, 0, 1]); } else keys.push([h, k, 0, 0]);
    keys.push([h + 2, k, 0, 0]); if (!nx || nx - h > D + R + 4) keys.push([h + 2 + R, 0, 0, 0]); });
  HD.MOVE_FX.g2_move(d, { b: 'attacker', rush: true, frac: true, keys, dustAt: Math.max(1, hits[0] - D), streak: e.streak || lookOf(d).glow });
};
// a recoil: shortly after the hit the user is thrown back a little, flashes in the colour and sheds a few sparks
HD.MOVE_FX.g2_recoil = (d, e) => { const b = d.atkB(); if (!present(d, b)) return; let f = e.f; if (f == null) { const h = d.plan && d.plan.hits.find((x) => x.f >= 2); f = h ? h.f + (e.delay || 5) : d.frame; } d.addFx('g2_recoil', { b, f0: f, color: e.color || [1, 0.42, 0.25], life: lifeTo(d, f + 18) }); };
HD.FX_STEP.g2_recoil = function (d, f) {
  const a = d.act[f.b]; if (!a) return; const o = d.frame - f.f0; if (o < 0 || o > 16) return; const t = dirTo(d, f.b, d.tgtB()); const k = o < 3 ? easeOut(o / 3) : 1 - smooth((o - 3) / 13);
  a.dx -= t.ux * 9 * k; a.dy -= t.uy * 9 * k - 3 * k; regMove(a, -t.ux * 9 * k, -(t.uy * 9 * k - 3 * k), d);
  const fl = 0.14 * (o < 2 ? 1 : 1 - (o - 2) / 14); if (fl > a.flash[3]) a.flash = [f.color[0], f.color[1], f.color[2], fl]; if (0.3 * k > a.glow[3]) a.glow = [f.color[0], f.color[1], f.color[2], 0.3 * k];
  if (o === 0) { const c = drawnAt(d, f.b); d.emit(PS.hitStreak, c, 8, { ramp: 'g2_warm', scale: 0.8 }); d.emit(PS.dustPuff, [c[0], 0.2, c[2]], 4, { scale: 1 }); }
};
// two energy palms clap together in front of a battler on frame cf (Fake Out): a shock and a burst of air
HD.MOVE_FX.g2_clap = (d, e) => { const b = bRef(d, e.b || 'target'); if (present(d, b)) d.addFx('g2_clap', { b, f0: d.frame, cf: e.cf, lk: lookOf(d, e.look), life: lifeTo(d, e.cf + 10), done: false }); };
HD.FX.g2_clap = function (d, f, age, out) {
  const fr = frameAt(f, age); const c = drawnAt(d, f.b); const h = hOf(d, f.b); const A = drawnAt(d, d.atkB()); const p0 = V.lerp([0, 0, 0], c, A, 0.22); p0[1] += h * 0.15;
  const u = fr < f.cf ? easeIn(clamp((fr - f.f0) / Math.max(1, f.cf - f.f0), 0, 1)) : 1; const after = fr - f.cf; const fade = after < 2 ? 1 : 1 - smooth((after - 2) / 6); if (fade <= 0.01) return;
  for (const sd of [1, -1]) { const p = scrOff(p0, 0, sd * h * (0.6 * (1 - u) + 0.13)); const pose = { rot: sd > 0 ? -Math.PI / 2 : Math.PI / 2, flip: 0 }; V3.drawLimb(out.cards, p, 'palm3', pose, h * 0.62, f.lk.ramp, f.lk.glow, fade); }
  if (after >= 0 && after < 7) { const v = after / 7; out.cards.push({ p: p0, cell: 'impact3', size: [h * (0.35 + 0.6 * v), h * (0.35 + 0.6 * v)], rot: 0.4, color: [1, 1, 1], gmap: 'g2_warm', alpha: 0.85 * (1 - v), add: 1, intensity: 1.0 }); out.distort.push({ p: p0, cell: 'shock', size: [h * (0.6 + 2 * v), h * (0.6 + 2 * v)], strength: 0.7 * (1 - v), mode: 0 }); }
};
