// ================================================================== C batch 2
G2S.g2_steel = g2Style({ ramp: 'steel', glow: [0.7, 0.82, 1], debris: (d, p, st) => { d.emit(PS.steelSpark, p, 14 + st * 10, { scale: 1.1 }); } });
