HD.FX_STEP.h2_drop = function (d, f, age) { const u = clamp(age / f.life, 0, 1); glowOn(d, f.b, f.color, 0.18 * env01(u, 0.15, 0.35)); const a = d.act[f.b]; if (a) { const k = Math.sin(Math.PI * u); if (f.up) { a.fxOff[1] -= 1.5 * k; a.sy *= 1 + 0.04 * k; } else { a.fxOff[1] += 2.5 * k; a.sy *= 1 - 0.05 * k; } } };

