  const tight = HD.easeIn(clamp(u / f.snap, 0, 1)); const ft = d.space.feet[f.b]; const locked = u >= f.snap; const lv = locked ? clamp((u - f.snap) / 0.12, 0, 1) : 0; const flashK = locked ? 1 - lv : 0;
