HD.FX_STEP.h2_comet = function (d, f, age) {
  const u = age / f.life; const p = cometPos(d, f, u); const H = hgt(d, f.a); if (d.frame % 2 === 0 && u < 0.95) d.emit(PS.glint, p, 1, { ramp: f.ramp, scale: H / 3, radius: H * 0.08 });
  if (f.done || u < 0.95 || !f.recv) return; f.done = true; const c = bdraw(d, f.b); const h = hgt(d, f.b);
  d.emit(PS.glint, c, 14, { ramp: f.ramp, radius: h * 0.35, speedMul: 1.6, scale: 1.1 }); d.addFx('shockd', { p: c.slice(), r0: h * 0.15, r1: h * 0.8, strength: 0.45, life: 0.22 });
  d.addFx('h2_glowpulse', { b: f.b, life: 0.4, color: f.color, amt: 0.45 }); if (f.react) d.addFx('h2_react', { b: f.b, kind: f.react, life: 0.4, amt: 0.7 });
};
HD.MOVE_FX.h2_glowpulse = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_glowpulse', { b, life: (e.dur || 24) / FPS, color: e.color || [1, 1, 1], amt: e.amt || 0.4 }); };
HD.FX.h2_glowpulse = function () {};
HD.FX_STEP.h2_glowpulse = function (d, f, age) { const u = clamp(age / f.life, 0, 1); glowOn(d, f.b, f.color, f.amt * (u < 0.2 ? u / 0.2 : 1 - HD.smooth((u - 0.2) / 0.8))); };

// ================================================================== environment helpers: cap a GBA scene darkening / screen flash for this move
HD.MOVE_FX.h2_dimcap = (d, e) => d.addFx('h2_dimcap', { life: (e.dur || 60) / FPS, cap: e.cap != null ? e.cap : 0.3, flash: e.flash != null ? e.flash : 1 });
HD.FX.h2_dimcap = function () {};
HD.FX_STEP.h2_dimcap = function (d, f) { d.env.darken = Math.min(d.env.darken, f.cap); d.env.flash = Math.min(d.env.flash, f.flash); };
HD.MOVE_FX.h2_noeyes = (d, e) => d.addFx('h2_noeyes', { life: (e.dur || 200) / FPS });
HD.FX.h2_noeyes = function () {};
HD.FX_STEP.h2_noeyes = function (d) { for (const x of d.fx) if (x.kind === 'eyesbg') x.life = 1e-4; };   // (not 0: age / 0 is NaN on its first frame)

// ================================================================== kits for restyled GBA sprites
// a music note: coloured, glowing, an ink rim, a short sparkle wake; up to 0.36 target heights
const NOTE_COLS = [[1, 0.5, 0.6], [1, 0.82, 0.3], [0.45, 0.82, 1], [0.55, 1, 0.5], [0.85, 0.55, 1]];
K.h2_note = { update(d, it, cfg) {
  const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.atkB()); const s = h * (cfg.v3size || 0.42) * (0.9 + 0.1 * Math.sin(it.age * 10 + it.uid)); const col = cfg.color || NOTE_COLS[it.uid % NOTE_COLS.length];
  const rot = Math.sin(it.age * 5 + it.uid) * 0.28; const a = it.alpha;
  if (it.hist.length > 2) { const pts = it.hist.slice(-6).concat([it.p.slice()]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => s * 0.35 * (i / (pts.length - 1))), width: s * 0.35, cell: 'trail', color: col, intensity: 0.9, alpha: 0.5 * a, add: 1 }); }
  it.cards.push({ cell: 'dot', size: [s * 1.9, s * 1.9], color: col, alpha: 0.32 * a, add: 1, intensity: 1 });
  it.cards.push({ cell: 'note', size: [s * 1.12, s * 1.12], rot, color: [col[0] * 0.12, col[1] * 0.12, col[2] * 0.18], alpha: 0.75 * a, add: 0, hot: 0 });
  it.cards.push({ cell: 'note', size: [s, s], rot, color: col, alpha: a, add: 0.25, hot: 0.4, intensity: 1.3 });
  const n = KH.every(it, 'g', 7); if (n) d.emit(PS.glint, it.p, n, { ramp: cfg.ramp || 'gold', scale: s / 1.6 });
} };

// ================================================================== scheduling: run fx entries `wait` frames after a script event (keeps variant-specific triggers)
HD.MOVE_FX.h2_later = (d, e) => d.addFx('h2_later', { life: (e.wait || 1) / FPS + 0.3, wait: (e.wait || 1) / FPS, then: e.then });
HD.FX.h2_later = function () {};
HD.FX_STEP.h2_later = function (d, f, age) { if (f.done || age < f.wait - 1e-6) return; f.done = true; for (const e of (Array.isArray(f.then) ? f.then : [f.then])) { const fn = HD.MOVE_FX[e.kind]; if (fn && (e.needs == null || d.space.present[d.battlerRef(e.needs)])) fn(d, e, []); } };
// caps the rim glow GBA palette blends put on battlers (white / coloured flashes that read as a wash-out); effects added later still glow
HD.MOVE_FX.h2_glowcap = (d, e) => d.addFx('h2_glowcap', { life: (e.dur || 60) / FPS, cap: e.cap != null ? e.cap : 0.18 });
HD.FX.h2_glowcap = function () {};
HD.FX_STEP.h2_glowcap = function (d, f) { for (let b = 0; b < 4; b++) { const a = d.act[b]; if (a && a.glow[3] > f.cap) a.glow[3] = f.cap; } };
// the GBA dips a squashing battler (AnimTask_Splash): cancel most of the downward offset so it does not sink through its platform
HD.MOVE_FX.h2_plant = (d, e) => d.addFx('h2_plant', { life: (e.dur || 120) / FPS, k: e.k != null ? e.k : 0.85 });
HD.FX.h2_plant = function () {};
HD.FX_STEP.h2_plant = function (d, f) { const o = d.plan && d.plan.atkOff ? d.plan.atkOff[d.frame + 1] : null; const a = d.act[d.atkB()]; if (o && a && o[1] > 0) a.fxOff[1] -= o[1] * f.k; };
// a small coloured hit spark on a battler (pain, a jab of pressure, a crackle): an impact shape and a star, brief
HD.MOVE_FX.h2_spark = (d, e) => { const tg = [ref(d, e.b || 'target')]; if (e.both) tg.push(e.both === 'pair' ? d.atkB() : tg[0] ^ 2); for (const b of tg) { if (!here(d, b)) continue; const h = hgt(d, b); const c = scrOff(bdraw(d, b), (e.dx || 0) * h, (e.dy || 0.05) * h); c[2] += 0.4; const s = e.size || 0.6; const col = e.color || [1, 0.5, 0.4];
  d.addFx('card', { p: c.slice(), cell: 'impact3', size0: h * 0.25 * s, size1: h * 0.85 * s, color: col, intensity: 1.2, life: 0.16, add: 1, rot: d.rng() * 6 });
  d.addFx('card', { p: c.slice(), cell: 'star4', size0: h * 0.9 * s, size1: h * 0.2 * s, color: [1, 0.95, 0.9], intensity: 1.5, life: 0.14, add: 1, rot: 0.4 });
  d.emit(PS.glint, c, 6, { ramp: e.ramp || 'fire', radius: h * 0.15, speedMul: 1.8, scale: 1.1 }); if (e.react) d.addFx('h2_react', { b, kind: e.react, life: 0.35, amt: e.amt || 0.6 }); } };

// ================================================================== Snatch: a shadow arm darts out of the lunging user, closes on the target's power and drags it back
HD.MOVE_FX.h2_snatch = (d, e) => { const a = d.atkB(), b = foeOf(d); if (!here(d, a) || !here(d, b) || a === b) return; d.addFx('h2_snatch', { a, b, life: (e.dur || 24) / FPS, reach: (e.reach || 8) / FPS, grab: (e.grab || 10) / FPS, back: (e.back || 20) / FPS, color: e.color || [0.6, 0.32, 0.95], loot: e.loot || [1, 0.82, 0.32] }); };
function snPath(d, f, t) { const ha = hgt(d, f.a); const A = scrOff(bdraw(d, f.a), face(d, f.a) * ha * 0.15, ha * 0.12), B = scrOff(bdraw(d, f.b), 0, hgt(d, f.b) * 0.05); const p = lerp3(A, B, t); p[1] += Math.sin(Math.PI * t) * ha * 0.3; return p; }
function snExt(f, age) { return age < f.reach ? HD.easeOut(age / f.reach) : age < f.grab ? 1 : 1 - HD.smooth(clamp((age - f.grab) / (f.back - f.grab), 0, 1)); }
HD.FX.h2_snatch = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const ha = hgt(d, f.a), hb = hgt(d, f.b); const ext = snExt(f, age); const k = Math.min(1, age / 0.05) * (age > f.back ? 1 - clamp((age - f.back) / 0.08, 0, 1) : 1);
  if (ext > 0.02 && k > 0.01) {
    const n = 10; const pts = [], wd = []; for (let i = 0; i <= n; i++) { pts.push(snPath(d, f, ext * i / n)); wd.push(ha * (0.3 - 0.17 * (i / n))); }
    out.ribbons.push({ pts, widths: wd.map((w) => w * 0.7), width: 1, cell: 'water', color: [0.06, 0.02, 0.1], alpha: 0.95 * k, add: 0, intensity: 1, scroll: age * 3 });
    out.ribbons.push({ pts, widths: wd.map((w) => w * 1.6), width: 1, cell: 'smoke', color: [0.1, 0.03, 0.15], alpha: 0.9 * k, add: 0, intensity: 1, scroll: age * 4 });
    out.ribbons.push({ pts, widths: wd.map((w) => w * 0.5), width: 1, cell: 'beam', color: f.color, intensity: 1.2 * k, add: 1 });
    const H = pts[n]; const sd = toScr(V.sub([0, 0, 0], H, pts[n - 1])); const th = ext < 0.999 && age > f.grab ? Math.atan2(-sd[1], -sd[0]) : Math.atan2(sd[1], sd[0]); const open = age < f.grab - 0.02 ? 1 : 0.2;
    if (age <= f.grab + 0.02) for (const s of [-1, 0, 1]) {   // the claws: three shadow fingers, open while reaching, snapping shut
      const ang = th + s * 0.62 * open; const tip = scrOff(H, Math.cos(ang) * ha * 0.5, Math.sin(ang) * ha * 0.5); const mid = scrOff(lerp3(H, tip, 0.55), -Math.sin(ang) * ha * 0.08 * (s || 1), Math.cos(ang) * ha * 0.08 * (s || 1));
      out.ribbons.push({ pts: [H, mid, tip], widths: [ha * 0.2, ha * 0.15, ha * 0.03], width: 1, cell: 'water', color: [0.06, 0.02, 0.1], alpha: 0.95 * k, add: 0, intensity: 1 });
      out.ribbons.push({ pts: [H, mid, tip], widths: [ha * 0.1, ha * 0.08, ha * 0.02], width: 1, cell: 'beam', color: f.color, intensity: 1.4 * k, add: 1 }); }
    if (age >= f.grab - 0.02) {   // the loot: a golden orb of stolen power riding the claw back
      const g = HD.easeOut(clamp((age - f.grab + 0.02) / 0.08, 0, 1)); const s = hb * 0.34 * g; const p = H.slice(); p[2] += 0.3;
      out.cards.push({ p, cell: 'dot', size: [s * 2.2, s * 2.2], color: f.loot, alpha: 0.35 * k, add: 1, intensity: 1 });
      out.cards.push({ p, cell: 'orb', size: [s * 1.06, s * 1.06], color: [0.25, 0.12, 0.02], alpha: 0.6 * k, add: 0, hot: 0 });
      out.cards.push({ p, cell: 'orb', size: [s, s], color: [1, 0.9, 0.6], gmap: 'gold', alpha: k, add: 0.3, intensity: 1.05 });
      out.cards.push({ p, cell: 'star4', size: [s * 1.3, s * 1.3], rot: age * 5, color: f.loot, alpha: 0.9 * k, add: 1, intensity: 1.3 });
      out.lights.push({ p, color: f.loot, intensity: 3 * k, range: 7 }); }
  }
};
HD.FX_STEP.h2_snatch = function (d, f, age) {
  if (age < f.grab && d.frame % 2 === 0) d.emit(PS.h2_shadow, snPath(d, f, snExt(f, age)), 1, { scale: hgt(d, f.a) / 3 });
  if (!f.g && age >= f.grab) { f.g = true; const c = bdraw(d, f.b); const h = hgt(d, f.b); d.emit(PS.glint, c, 14, { ramp: 'gold', radius: h * 0.3, speedMul: 2, scale: 1.2 }); d.addFx('h2_react', { b: f.b, kind: 'flinch', life: 0.4, amt: 0.8 }); d.addFx('shockd', { p: c.slice(), r0: h * 0.2, r1: h * 0.9, strength: 0.5, life: 0.2 }); }
  if (age < f.grab) glowOn(d, f.a, f.color, 0.3);
  if (!f.r && age >= f.back) { f.r = true; const c = bdraw(d, f.a); const h = hgt(d, f.a); d.emit(PS.glint, c, 16, { ramp: 'gold', radius: h * 0.35, speedMul: 1.6, scale: 1.2 }); d.addFx('h2_glowpulse', { b: f.a, life: 0.3, color: f.loot, amt: 0.55 }); }
};

// ================================================================== Assist: wisps of the party's power fly in from behind the user, one after another
HD.MOVE_FX.h2_gather = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('h2_gather', { b, life: (e.dur || 44) / FPS, n: e.n || 3, cols: e.cols || [[1, 0.55, 0.3], [0.4, 0.72, 1], [0.5, 1, 0.45]], ramps: e.ramps || ['fire', 'water', 'nature'], stagger: (e.stagger || 7) / FPS, travel: (e.travel || 20) / FPS, size: e.size || 0.34 }); };
function gatherPos(d, f, i, t) { const c = bdraw(d, f.b); const h = hgt(d, f.b); const fx = face(d, f.b); const S = scrOff(c, -fx * h * (1.4 + 0.25 * i), h * (1.1 - 0.55 * i)); const s = HD.easeIn(clamp(t, 0, 1)); const p = lerp3(S, scrOff(c, 0, h * 0.05), s); return scrOff(p, Math.sin(Math.PI * s) * h * 0.25 * fx, Math.sin(Math.PI * s) * h * 0.2); }
HD.FX.h2_gather = function (d, f, age, out) {
  for (let i = 0; i < f.n; i++) { const ai = age - i * f.stagger; if (ai < 0 || ai > f.travel) continue; const t = ai / f.travel; const p = gatherPos(d, f, i, t); const h = hgt(d, f.b); const s = h * f.size * (1 - 0.3 * t); const col = f.cols[i % f.cols.length]; const k = Math.min(1, t * 6);
    const pts = []; for (let j = 7; j >= 0; j--) pts.push(gatherPos(d, f, i, t - j * 0.05));
    out.ribbons.push({ pts, width: s * 0.8, cell: 'trail', color: col, intensity: 1.1 * k, alpha: 0.8, add: 1, taper: 0.9 });
    out.cards.push({ p, cell: 'dot', size: [s * 2.2, s * 2.2], color: col, alpha: 0.4 * k, add: 1, intensity: 1 });
    const fr = Math.floor(age * 16 + i) % 4; const sd = toScr(V.sub([0, 0, 0], p, pts[pts.length - 2])); const ang = Math.atan2(sd[1], sd[0]);
    out.cards.push({ p: scrOff(p, -Math.cos(ang) * s * 0.25, -Math.sin(ang) * s * 0.25), cell: 'flame' + fr, size: [s, s * 1.5], rot: ang + Math.PI / 2, color: [1, 1, 1], gmap: f.ramps[i % f.ramps.length], alpha: 0.9 * k, add: 0.5, intensity: 1.1 });
    out.cards.push({ p, cell: 'core', size: [s * 0.4, s * 0.4], color: [1, 1, 1], alpha: k, add: 1, intensity: 1.2 }); }
};
HD.FX_STEP.h2_gather = function (d, f, age) { f.got = f.got || 0; while (f.got < f.n && age - f.got * f.stagger >= f.travel) { const i = f.got++; const c = bdraw(d, f.b); const h = hgt(d, f.b); d.emit(PS.glint, c, 9, { ramp: f.ramps[i % f.ramps.length], radius: h * 0.3, speedMul: 1.6, scale: 1.1 }); d.addFx('h2_glowpulse', { b: f.b, life: 0.3, color: f.cols[i % f.cols.length], amt: 0.4 }); } };

// ================================================================== Odor Sleuth: wavering scent trails drawn from the target to the user's nose
HD.MOVE_FX.h2_scent = (d, e) => { const a = ref(d, e.to || 'attacker'), b = ref(d, e.from || 'target'); if (!here(d, a) || !here(d, b) || a === b) return; d.addFx('h2_scent', { a, b, life: (e.dur || 60) / FPS, color: e.color || [1, 0.85, 0.45], n: e.n || 3 }); };
HD.FX.h2_scent = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.15, 0.25); const N = mouthAt(d, f.a); const hb = hgt(d, f.b), ha = hgt(d, f.a); const B = bdraw(d, f.b); const grow = HD.easeOut(Math.min(1, u * 3));
  for (let i = 0; i < f.n; i++) { const S = scrOff(B, (i - 1) * hb * 0.24, hb * (0.05 + 0.14 * i)); const pts = []; const n = 14;
    for (let j = 0; j <= n; j++) { const t = j / n * grow; const p = lerp3(S, N, t); const w = Math.sin(t * 10 - age * 7 + i * 2) * ha * 0.1 * Math.sin(Math.PI * t); pts.push(scrOff(p, 0, w + Math.sin(Math.PI * t) * ha * 0.32)); }
    out.ribbons.push(tapered(pts, hb * 0.22, { cell: 'smoke', color: f.color, alpha: 0.5 * k, add: 0.35, intensity: 1.15, scroll: -age * 3 }));
    out.ribbons.push(tapered(pts, hb * 0.05, { cell: 'beam', color: f.color, intensity: 0.8 * k, add: 1 }));
    for (let m = 0; m < 3; m++) { const t = (age * 0.9 + m / 3 + i * 0.17) % 1; const q = pts[Math.min(n, Math.round(t * n))]; out.cards.push({ p: q, cell: 'dot', size: [hb * 0.13, hb * 0.13], color: f.color, alpha: 0.85 * k * Math.sin(Math.PI * t), add: 1, intensity: 1.4 }); } }
};
// a reveal: a sweep of light crosses the battler, its outline flashes and a shimmer peels off it (Foresight, Odor Sleuth, Miracle Eye)
HD.MOVE_FX.h2_reveal = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_reveal', { b, life: (e.dur || 30) / FPS, color: e.color || [0.6, 1, 0.95], ramp: e.ramp || 'ice' }); };
HD.FX.h2_reveal = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = bdraw(d, f.b); const h = hgt(d, f.b); const sw = HD.smooth(Math.min(1, u * 1.6)); const k = 1 - HD.smooth(Math.max(0, (u - 0.5) / 0.5));
  const x = (sw - 0.5) * h * 1.2; const q0 = scrOff(c, x - h * 0.12, -h * 0.55), q1 = scrOff(c, x + h * 0.12, h * 0.6); q0[2] += 0.4; q1[2] += 0.4; const ks = k * Math.sin(Math.PI * sw);
  out.ribbons.push({ pts: [q0, q1], width: h * 0.35, cell: 'boltglow', color: f.color, intensity: 0.7 * ks, add: 1 }); out.ribbons.push({ pts: [q0, q1], width: h * 0.08, cell: 'beam', color: f.color, intensity: 1.3 * ks, add: 1 });
  out.distort.push({ p: c, cell: 'shock', size: [h * (0.8 + u * 1.2), h * (0.8 + u * 1.2)], strength: 0.3 * k, mode: 0 }); out.lights.push({ p: c, color: f.color, intensity: 3 * k, range: 7 });
};
HD.FX_STEP.h2_reveal = function (d, f, age) { const u = clamp(age / f.life, 0, 1); glowOn(d, f.b, f.color, 0.42 * (u < 0.15 ? u / 0.15 : 1 - HD.smooth((u - 0.15) / 0.85)));
  if (f.done) return; f.done = true; const c = bdraw(d, f.b); const h = hgt(d, f.b); for (let i = 0; i < 16; i++) { const a = i / 16 * Math.PI * 2; const q = scrOff(c, Math.cos(a) * h * 0.38, Math.sin(a) * h * 0.44); d.emit(PS.glint, q, 1, { ramp: f.ramp, vel: V.scale([0, 0, 0], V.sub([0, 0, 0], q, c), 2.4), scale: 1.3 }); } };
// a mirror flash (Copycat, Role Play): v3's glass pane on the battler with prismatic sparkles
HD.MOVE_FX.h2_mirror = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('v3mirror', { b, life: (e.dur || 20) / FPS }); const h = hgt(d, b); d.emit(PS.glint, bdraw(d, b), 14, { ramp: e.ramp || 'rainbow', radius: h * 0.4, speedMul: 1.4, scale: 1.2 }); };

// ================================================================== small status cues (bold enough for the battle camera)
HD.MOVE_FX.h2_sweat = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_sweat', { b, life: (e.dur || 40) / FPS, n: e.n || 4 }); };
HD.FX.h2_sweat = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const c = bdraw(d, f.b);
  for (let i = 0; i < f.n; i++) { const v = (u - i * (0.6 / f.n)) / 0.45; if (v < 0 || v > 1) continue; const side = i % 2 ? 1 : -1;
    const p = scrOff(c, side * h * (0.3 + 0.16 * v), h * (0.38 + 0.12 * v - 0.5 * v * v)); p[2] += 0.4; const s = h * 0.16; const a = Math.min(1, v * 5) * (1 - HD.smooth((v - 0.7) / 0.3));
    out.cards.push({ p, cell: 'droplet', size: [s * 1.14, s * 1.3], rot: side * 0.6, color: [0.04, 0.1, 0.22], alpha: 0.6 * a, add: 0, hot: 0 });
    out.cards.push({ p, cell: 'droplet', size: [s, s * 1.16], rot: side * 0.6, color: [0.6, 0.86, 1], alpha: a, add: 0.35, intensity: 1.3 }); }
};
HD.MOVE_FX.h2_dizzy = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_dizzy', { b, life: (e.dur || 50) / FPS, color: e.color || [1, 0.88, 0.35], n: e.n || 3, cell: e.cell || 'star5' }); };
HD.FX.h2_dizzy = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const top = scrOff(bdraw(d, f.b), 0, h * 0.56); const k = env01(u, 0.12, 0.2);
  for (let i = 0; i < f.n; i++) { const a = age * 5.5 + i * Math.PI * 2 / f.n; const p = scrOff(top, Math.cos(a) * h * 0.34, Math.sin(a) * h * 0.09); p[2] += Math.sin(a) * 0.6; const s = h * 0.21; const back = Math.sin(a) < 0;
    out.cards.push({ p, back, cell: 'dot', size: [s * 1.8, s * 1.8], color: f.color, alpha: 0.3 * k, add: 1, intensity: 1 });
    out.cards.push({ p, back, cell: f.cell, size: [s * 1.14, s * 1.14], rot: age * 4 + i, color: [0.22, 0.12, 0.02], alpha: 0.6 * k, add: 0, hot: 0 });
    out.cards.push({ p, back, cell: f.cell, size: [s, s], rot: age * 4 + i, color: f.color, alpha: k, add: 0.4, intensity: 1.4 }); }
};
// a creeping miasma round a battler: dark smoke curling up out of a stain on the ground, a violet underglow
HD.MOVE_FX.h2_miasma = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('h2_miasma', { b, life: (e.dur || 60) / FPS, color: e.color || [0.5, 0.22, 0.7], dark: e.dark || [0.07, 0.03, 0.09], size: e.size || 1 }); };
HD.FX.h2_miasma = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.2, 0.25); const c = bdraw(d, f.b); const h = hgt(d, f.b) * f.size; const ft = d.space.feet[f.b];
  out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 2.0, h * 1.25], color: [0, 0, 0], alpha: 0.55 * k, add: 0, intensity: 1, mode: 2 });
  out.decals.push({ p: [ft[0], 0.034, ft[2]], cell: 'dot', size: [h * 2.4, h * 1.5], color: f.color, alpha: 0.3 * k, add: 1, intensity: 1, mode: 2 });
  for (let i = 0; i < 9; i++) { const ph = (age * 0.55 + i / 9) % 1; const a = i * 0.7 + age * 0.5; const R = h * (0.42 + 0.08 * Math.sin(i * 3)); const back = Math.sin(a) < 0;
    const p = [c[0] + Math.cos(a) * R, ft[1] + h * (0.02 + ph * 0.75), c[2] + Math.sin(a) * R * 0.6]; const s = h * (0.34 + 0.18 * (1 - ph)); const fa = k * Math.sin(Math.PI * Math.min(1, ph * 1.3));
    out.cards.push({ p, back, cell: 'flame' + ((i + Math.floor(age * 12)) % 4), size: [s * 0.8, s * 1.3], color: [0.55, 0.32, 0.8], gmap: 'purplefire', alpha: 0.85 * fa, add: 0.15, intensity: 0.9 });
    out.cards.push({ p: [p[0], p[1] + s * 0.4, p[2]], back, cell: 'smoke' + (i % 3), size: [s, s], rot: a, color: f.dark, alpha: 0.75 * fa, add: 0, hot: 0, intensity: 1 }); }
  out.lights.push({ p: [c[0], h * 0.3, c[2] + 0.6], color: f.color, intensity: 2 * k, range: 7 });
};
HD.FX_STEP.h2_miasma = function (d, f, age) { glowOn(d, f.b, f.color, 0.25 * env01(age / f.life, 0.2, 0.25)); };

// ================================================================== kits: a speech bubble (whispers, sleep talk), a glossy heart
K.h2_bubble = { update(d, it, cfg) {
  const b = cfg.who === 'target' ? d.tgtB() : d.atkB(); const h = hgt(d, b); const s = h * (cfg.v3size || 0.4) * (0.94 + 0.06 * Math.sin(it.age * 6)); const a = it.alpha * Math.min(1, it.age / 0.15);
  const p = cfg.anchor ? scrOff(bdraw(d, b), face(d, b) * h * 0.42, h * 0.55) : it.p.slice(); p[2] += 0.3; const col = cfg.color || [1, 0.82, 0.93];
  it.cards.push({ fixed: true, p, cell: 'dot', size: [s * 1.9, s * 1.6], color: col, alpha: 0.3 * a, add: 1, intensity: 1 });
  it.cards.push({ fixed: true, p, cell: 'cloud', size: [s * 1.1, s * 0.9], color: [0.12, 0.05, 0.12], alpha: 0.55 * a, add: 0, hot: 0 });
  it.cards.push({ fixed: true, p, cell: 'cloud', size: [s, s * 0.82], color: col, alpha: a, add: 0.1, intensity: 1.1 });
  for (let i = 0; i < 3; i++) { const on = ((it.age * 2.5 - i * 0.33) % 1.2) < 0.8 ? 1 : 0.3; it.cards.push({ fixed: true, p: scrOff(p, (i - 1) * s * 0.2, -s * 0.03), cell: 'dot', size: [s * 0.15, s * 0.15], color: cfg.dots || [0.5, 0.18, 0.42], alpha: a * on, add: 0, hot: 0 }); }
} };
K.h2_heart = { update(d, it, cfg) {
  const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.tgtB()); const s = h * (cfg.v3size || 0.34) * (1 + 0.08 * Math.sin(it.age * 12 + it.uid)); const col = cfg.color || [1, 0.32, 0.55]; const a = it.alpha;
  if (V.len(it.v) > 2 && it.hist.length > 2) { const pts = it.hist.slice(-5).concat([it.p.slice()]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => s * 0.45 * (i / (pts.length - 1))), width: s * 0.45, cell: 'trail', color: col, intensity: 1, alpha: 0.5 * a, add: 1 }); }
  it.cards.push({ cell: 'dot', size: [s * 2, s * 2], color: col, alpha: 0.32 * a, add: 1, intensity: 1 });
  it.cards.push({ cell: 'heart', size: [s * 1.12, s * 1.12], rot: it.rot, color: [col[0] * 0.25, col[1] * 0.06, col[2] * 0.12], alpha: 0.75 * a, add: 0, hot: 0 });
  it.cards.push({ cell: 'heart', size: [s, s], rot: it.rot, color: col, alpha: a, add: 0.2, hot: 0.3, intensity: 1.2 });
  it.cards.push({ cell: 'dot', size: [s * 0.28, s * 0.2], off: scrOff([0, 0, 0.02], -s * 0.18, s * 0.15), color: [1, 1, 1], alpha: 0.8 * a, add: 1, intensity: 1.4 });
} };
// a sprouting seed on landing: a burst of leaves and green light (Worry Seed, Leech Seed)
HD.MOVE_FX.h2_sprout = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; const h = hgt(d, b); const c = scrOff(bdraw(d, b), 0, (e.dy || 0.1) * h); c[2] += 0.4;
  d.emit(PS.leafBit, c, 12, { scale: 1.6, speedMul: 1.3 }); d.emit(PS.glint, c, 10, { ramp: 'nature', radius: h * 0.2, speedMul: 1.6, scale: 1.2 });
  d.addFx('card', { p: c.slice(), cell: 'burst', size0: h * 0.3, size1: h * 0.9, color: [0.55, 1, 0.4], intensity: 1.2, life: 0.18, add: 1, rot: 0.3 }); d.addFx('h2_glowpulse', { b, life: 0.35, color: [0.5, 1, 0.4], amt: 0.4 }); };

// ================================================================== Whirlwind: a translucent funnel of wind streaks round the target, debris and a dust ring at its base
HD.MOVE_FX.h2_twister = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_twister', { b, life: (e.dur || 60) / FPS, color: e.color || [0.88, 0.94, 1] }); };
HD.FX.h2_twister = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.12, 0.12); const c = bdraw(d, f.b); const h = hgt(d, f.b); const ft = d.space.feet[f.b]; const front = camSide(c);
  for (let r = 0; r < 7; r++) { const t = r / 6; const y = 0.15 + t * h * 1.55; const R = h * (0.34 + 0.6 * t) * (0.9 + 0.1 * Math.sin(age * 5 + r)); const a0 = age * (10 - t * 4) + r * 1.3; const sway = Math.sin(age * 3 + t * 2.5) * h * 0.1; const pts = [];
    for (let i = 0; i <= 20; i++) { const a = a0 + (i / 20) * Math.PI * 1.35; pts.push([c[0] + Math.cos(a) * R + sway, y + Math.sin(a) * R * 0.1, c[2] + Math.sin(a) * R * 0.55]); }   // open arcs: streaks of a funnel, not closed rings
    for (const run of HD.splitRuns(pts, front, false)) { if (run.pts.length < 2) continue;
      out.ribbons.push({ pts: run.pts, width: h * 0.16, cell: 'trail', color: f.color, intensity: (run.f ? 0.75 : 0.45) * k, alpha: 0.8, add: 0.55, back: !run.f, taper: 0.45, scroll: age * 5 }); } }
  out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'dot', size: [h * 2.4, h * 1.4], color: [0.5, 0.42, 0.3], alpha: 0.4 * k, add: 0, intensity: 1, mode: 2 });
  out.distort.push({ p: [c[0], h * 0.8, c[2]], cell: 'swirl', size: [h * 2, h * 2.4], strength: 0.4 * k, mode: 0 });
};
HD.FX_STEP.h2_twister = function (d, f, age) { const h = hgt(d, f.b); const ft = d.space.feet[f.b]; const r = d.rng; if (age / f.life > 0.9) return;
  if (d.frame % 2 === 0) { d.emit(PS.leafBit, [ft[0] + r.range(-0.6, 0.6) * h, 0.3, ft[2] + r.range(-0.3, 0.3) * h], 1, { vel: [r.range(-2, 2), h * 1.3, r.range(-1, 1)], scale: 1.5 }); d.emit(PS.dustPuff, [ft[0] + r.range(-0.5, 0.5) * h, 0.15, ft[2]], 1, { dir: [0, 0.4, 0], spread: 1, scale: 1.4 }); } };
// a gust from the user that whips toward the target (the wind's source)
HD.MOVE_FX.h2_gust = (d, e) => { const a = ref(d, e.from || 'attacker'), b = ref(d, e.to || 'target'); if (!here(d, a) || !here(d, b) || a === b) return; d.addFx('h2_gust', { a, b, life: (e.dur || 24) / FPS, color: e.color || [0.88, 0.95, 1], n: e.n || 5 }); };
HD.FX.h2_gust = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const A = bdraw(d, f.a), B = bdraw(d, f.b); const ha = hgt(d, f.a), hb = hgt(d, f.b); const r = HD.rng(f.seed);
  for (let i = 0; i < f.n; i++) { const o = r.range(-0.4, 0.5); const t0 = r() * 0.3; const v = clamp((u - t0) / 0.6, 0, 1); if (v <= 0 || v >= 1) continue; const head = HD.easeOut(v), tail = HD.easeIn(v);
    const P = (t) => { const p = lerp3(scrOff(A, 0, ha * o), scrOff(B, 0, hb * o * 0.8), t); p[1] += Math.sin(Math.PI * t) * ha * 0.25 + Math.sin(t * 9 + i) * ha * 0.06; return p; };
    const pts = []; for (let j = 0; j <= 8; j++) pts.push(P(tail + (head - tail) * j / 8));
    out.ribbons.push(tapered(pts, ha * 0.2, { cell: 'trail', color: f.color, intensity: 0.85 * Math.sin(Math.PI * v), alpha: 0.85, add: 0.7 })); }
};

// ================================================================== Leech Seed: vines spiral up round the target from where the seeds landed, leaves along them
HD.MOVE_FX.h2_vines = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_vines', { b, life: (e.dur || 80) / FPS, grow: (e.grow || 26) / FPS, n: e.n || 3 }); };
HD.FX.h2_vines = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.04, 0.15); const c = bdraw(d, f.b); const h = hgt(d, f.b); const g = HD.easeOut(clamp(age / f.grow, 0, 1)); const front = camSide(c); const top = c[1] + h * 0.3; const pul = (age * 1.4) % 1;
  for (let i = 0; i < f.n; i++) { const pts = []; const n = 24; for (let j = 0; j <= n; j++) { const t = j / n * g; const a = i * 2.1 + t * 5.2 + Math.sin(age * 2 + i) * 0.06; const R = h * (0.5 - 0.14 * t); pts.push([c[0] + Math.cos(a) * R, 0.04 + t * top, c[2] + Math.sin(a) * R * 0.6]); }
    for (const run of HD.splitRuns(pts, front, false)) { if (run.pts.length < 2) continue; const bk = !run.f;
      out.ribbons.push({ pts: run.pts, width: h * 0.13, cell: 'water', color: [0.05, 0.13, 0.03], alpha: 0.9 * k, add: 0, intensity: 1, back: bk });
      out.ribbons.push({ pts: run.pts, width: h * 0.08, cell: 'fire', color: run.f ? [0.38, 0.8, 0.22] : [0.22, 0.48, 0.12], alpha: k, add: 0.1, intensity: 1.1, back: bk }); }
    for (let j = 3; j <= Math.floor(n * g); j += 4) { const q = pts[j]; const bk = !front(q); obj(out.cards, q, { cell: j % 8 === 3 ? 'leaf0' : 'leaf1', size: h * 0.24, rot: i * 1.7 + j * 0.9 + Math.sin(age * 3 + j) * 0.2, color: [0.55, 1, 0.38], alpha: k, back: bk, add: 0.1, intensity: 1.1 }); }
    if (g >= 1) { const q = pts[Math.min(n, Math.floor(pul * n))]; out.cards.push({ p: q, back: !front(q), cell: 'dot', size: [h * 0.3, h * 0.3], color: [0.6, 1, 0.45], alpha: 0.8 * k, add: 1, intensity: 1.3 }); }   // sap pulses climbing
  }
};

// ================================================================== kits: toxic goo, an eye of energy, a ghostly flame, a water droplet, an acid glob
K.h2_goo = { update(d, it, cfg) {
  const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.tgtB()); const s = h * (cfg.v3size || 0.3) * (0.92 + 0.08 * Math.sin(it.age * 8 + it.uid)); const a = it.alpha; const col = cfg.color || [0.72, 0.3, 0.95];
  it.cards.push({ cell: 'dot', size: [s * 1.9, s * 1.9], color: col, alpha: 0.28 * a, add: 1, intensity: 1 });
  it.cards.push({ cell: 'goo', size: [s * 1.25, s * 1.25], rot: Math.sin(it.age * 4 + it.uid) * 0.2, color: [0.1, 0.02, 0.14], alpha: 0.75 * a, add: 0, hot: 0 });
  it.cards.push({ cell: 'goo', size: [s * 1.15, s * 1.15], rot: Math.sin(it.age * 4 + it.uid) * 0.2, color: [1, 1, 1], gmap: cfg.ramp || 'poison', alpha: 0.95 * a, add: 0.1, intensity: 1.05 });
  it.cards.push({ cell: 'swirl', size: [s * 0.8, s * 0.8], rot: -it.age * 3 + it.uid, color: [0.25, 0.05, 0.35], alpha: 0.55 * a, add: 0, hot: 0 });
  it.cards.push({ cell: 'dot', size: [s * 0.3, s * 0.2], off: scrOff([0, 0, 0.02], -s * 0.2, s * 0.2), color: [1, 0.95, 1], alpha: 0.8 * a, add: 1, intensity: 1.4 });
  const n = KH.every(it, 'b', cfg.rate || 6); if (n) d.emit(PS.poisonBub, it.p, n, { ramp: cfg.ramp || 'poison', scale: s / 2.2 });
  const m = KH.every(it, 'g', cfg.drip || 4); if (m) d.emit(PS.gooDrop, it.p, m, { ramp: cfg.ramp || 'poison', scale: s / 1.8 });
}, end(d, it, cfg) { const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.tgtB()); const s = h * (cfg.v3size || 0.3);   // it splats on the target
  d.emit(PS.gooDrop, it.p, 9, { ramp: cfg.ramp || 'poison', scale: s / 1.4, speedMul: 1.3 }); d.emit(PS.poisonBub, it.p, 5, { ramp: cfg.ramp || 'poison', scale: s / 1.6 });
  d.addFx('card', { p: it.p.slice(), cell: 'goo', size0: s * 0.8, size1: s * 1.8, color: [0.75, 0.35, 1], intensity: 1, life: 0.2, add: 0.3 }); if (nb.b >= 0 && nb.b !== d.atkB()) d.addFx('h2_glowpulse', { b: nb.b, life: 0.3, color: [0.7, 0.3, 0.95], amt: 0.35 }); } };
K.h2_eye = { update(d, it, cfg) {
  const b = cfg.who === 'attacker' ? d.atkB() : d.tgtB(); const h = hgt(d, b); const s = h * (cfg.v3size || 0.9); const open = HD.easeOut(clamp((it.age - (cfg.delay || 0)) / 0.35, 0, 1)); const a = it.alpha * Math.min(1, it.age / 0.15);
  const p = it.p.slice(); p[1] += h * (cfg.dy || 0); p[2] += 0.5; const col = cfg.color || [1, 0.2, 0.25]; const L = it.cards;
  if (cfg.smoke !== false) for (let i = 0; i < 3; i++) L.push({ fixed: true, p: scrOff(p, (i - 1) * s * 0.28, Math.sin(it.age * 2 + i) * s * 0.04), cell: 'smoke' + i, size: [s * 0.8, s * 0.6], rot: it.age * 0.5 + i, color: cfg.smokeColor || [0.06, 0.02, 0.08], alpha: 0.85 * a, add: 0, hot: 0 });
  L.push({ fixed: true, p, cell: 'dot', size: [s * 1.4, s * 0.8], color: col, alpha: 0.45 * a * open, add: 1, intensity: 1 });
  L.push({ fixed: true, p, cell: 'eye3', size: [s * 1.05, s * 0.56 * Math.max(0.06, open)], color: [0.04, 0.02, 0.05], alpha: 0.75 * a, add: 0, hot: 0 });
  L.push({ fixed: true, p, cell: 'eye3', size: [s, s * 0.52 * Math.max(0.06, open)], color: col, alpha: a, add: 0.5, intensity: 1.45 });
  L.push({ fixed: true, p, cell: 'core', size: [s * 0.09, s * 0.36 * open], color: [1, 0.95, 0.8], alpha: a * open, add: 1, intensity: 1.5 });
  d.light(p, col, 2 * a * open, 7, 'eye');
} };
K.h2_wisp = { update(d, it, cfg) {
  const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.tgtB()); const s = h * (cfg.v3size || 0.4); const a = it.alpha; const fr = Math.floor(it.age * 14 + it.uid) % 4; const fl = 1 + 0.1 * Math.sin(it.age * 19 + it.uid * 2);
  if (it.hist.length > 2 && V.len(it.v) > 1) { const pts = it.hist.slice(-7).concat([it.p.slice()]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => s * 0.75 * (i / (pts.length - 1))), width: s * 0.75, cell: 'fire', color: [0.55, 0.65, 1], intensity: 1.0, alpha: 0.75 * a, add: 0.8 }); }
  it.cards.push({ cell: 'dot', size: [s * 2.4, s * 2.4], color: [0.4, 0.5, 1], alpha: 0.35 * a, add: 1, intensity: 1 });
  it.cards.push({ cell: 'flame' + fr, size: [s * 1.0 * fl, s * 1.5 * fl], off: [0, s * 0.24, 0.01], color: [1, 1, 1], gmap: cfg.ramp || 'bluefire', alpha: 0.95 * a, add: 0.55, intensity: 1.1 });
  it.cards.push({ cell: 'core', size: [s * 0.42, s * 0.42], color: [0.85, 0.9, 1], alpha: 0.95 * a, add: 1, intensity: 1.25 });
  const n = KH.every(it, 'w', cfg.rate || 12); if (n) d.emit(PS.wisp, it.p, n, { ramp: 'ghost', scale: s / 2.2 });
  d.light(it.p, [0.5, 0.6, 1], 1.4 * a, 6, 'wisp');
} };
K.h2_droplet = {
  update(d, it, cfg) { const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.atkB()); const s = h * (cfg.v3size || 0.13); const a = it.alpha; const vd = KH.velDir(it); const rot = vd ? HD.alignRot(V.scale([0, 0, 0], vd, -1)) : 0; const st = vd ? 1.4 : 1;
    it.cards.push({ cell: 'droplet', size: [s * 1.15, s * 1.4 * st], rot, color: [0.03, 0.12, 0.3], alpha: 0.6 * a, add: 0, hot: 0 });
    it.cards.push({ cell: 'droplet', size: [s, s * 1.25 * st], rot, color: [1, 1, 1], gmap: 'water', alpha: 0.95 * a, add: 0.2, intensity: 1.15 });
    it.cards.push({ cell: 'dot', size: [s * 0.25, s * 0.2], off: scrOff([0, 0, 0.02], -s * 0.12, s * 0.05), color: [1, 1, 1], alpha: 0.8 * a, add: 1, intensity: 1.4 }); },
  end(d, it) { const p = it.p; d.emit(PS.droplet, p, 3, { scale: 0.9 }); if (p[1] < 1.2 && (it.uid % 3 === 0)) d.addFx('ring', { p: [p[0], 0.05, p[2]], cell: 'ring', r0: 0.1, r1: 0.9, width: 0.05, color: [0.6, 0.85, 1], intensity: 0.9, life: 0.35, add: 0.6, ground: true }); }
};
K.h2_acid = {
  update(d, it, cfg) { const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.tgtB()); const s = h * (cfg.v3size || 0.24); const a = it.alpha; const vd = KH.velDir(it); const rot = vd ? HD.alignRot(V.scale([0, 0, 0], vd, -1)) : 0; const st = vd ? 1.25 : 1; const wob = 1 + 0.07 * Math.sin(it.age * 14 + it.uid);
    if (it.hist.length > 2 && V.len(it.v) > 1) { const pts = it.hist.slice(-5).concat([it.p.slice()]); it.cards.push({ layer: 'ribbons', fixed: true, pts, widths: pts.map((_, i) => s * 0.5 * (i / (pts.length - 1))), width: s * 0.5, cell: 'water', color: [0.55, 0.9, 0.2], intensity: 1, alpha: 0.6 * a, add: 0.2 }); }
    it.cards.push({ cell: 'dot', size: [s * 1.8, s * 1.8], color: [0.5, 0.95, 0.2], alpha: 0.25 * a, add: 1, intensity: 1 });
    it.cards.push({ cell: 'droplet', size: [s * 1.6 * wob, s * 2.0 * st], rot, color: [0.05, 0.12, 0.02], alpha: 0.7 * a, add: 0, hot: 0 });
    it.cards.push({ cell: 'droplet', size: [s * 1.45 * wob, s * 1.85 * st], rot, color: [1, 1, 1], gmap: cfg.ramp || 'toxic', alpha: a, add: 0.1, intensity: 1.05 });
    it.cards.push({ cell: 'dot', size: [s * 0.24, s * 0.18], off: scrOff([0, 0, 0.02], -s * 0.12, s * 0.06), color: [1, 1, 0.9], alpha: 0.85 * a, add: 1, intensity: 1.4 });
    const n = KH.every(it, 'b', 5); if (n) d.emit(PS.poisonBub, it.p, n, { ramp: cfg.ramp || 'toxic', scale: s / 2 }); },
  end(d, it, cfg) { const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.tgtB()); d.emit(PS.gooDrop, it.p, 6, { ramp: cfg.ramp || 'toxic', scale: h / 4.5 }); d.emit(PS.poisonBub, it.p, 4, { ramp: cfg.ramp || 'toxic', scale: h / 4 }); }
};

// ================================================================== Haze: a dark haze rolls evenly across the field, then clears off both battlers
HD.MOVE_FX.h2_haze = (d, e) => d.addFx('h2_haze', { life: (e.dur || 150) / FPS, color: e.color || [0.3, 0.33, 0.44], a: d.atkB(), b: foeOf(d) });
HD.FX.h2_haze = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.2, 0.3); const A = d.space.feet[f.a], B = d.space.feet[f.b]; const r = HD.rng(f.seed); const h = (hgt(d, f.a) + hgt(d, f.b)) / 2;
  for (let i = 0; i < 14; i++) { const t0 = r(); const sp = r.range(0.05, 0.09); const t = (t0 + age * sp) % 1; const lane = r.range(-1, 1); const p = lerp3([A[0] - h * 2.5, 0, A[2] + h * 0.6], [B[0] + h * 2.5, 0, B[2] - h * 0.6], t);
    p[2] += lane * h * 1.1; p[1] = h * r.range(0.12, 0.55); const s = h * r.range(1.1, 1.8);
    out.cards.push({ p, back: i % 3 === 0, cell: i % 2 ? 'cloud' : 'smoke' + (i % 3), size: [s * 1.5, s * 0.75], rot: r.range(-0.2, 0.2), color: f.color, alpha: 0.42 * k * Math.sin(Math.PI * t), add: 0, hot: 0, intensity: 1 }); }
};

// ================================================================== Will-O-Wisp: ghostly blue flames engulf the target (burn)
HD.MOVE_FX.h2_engulf = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_engulf', { b, life: (e.dur || 30) / FPS, ramp: e.ramp || 'bluefire', color: e.color || [0.5, 0.6, 1] }); if (e.react !== false) d.addFx('h2_react', { b, kind: 'flinch', life: 0.6, amt: 1 }); };
HD.FX.h2_engulf = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.08, 0.35); const c = bdraw(d, f.b); const h = hgt(d, f.b); const ft = d.space.feet[f.b];
  for (let i = 0; i < 9; i++) { const a = i * 0.7 + age * 1.5; const R = h * 0.4; const ph = (age * 1.6 + i / 9) % 1; const back = Math.sin(a) < 0; const p = [c[0] + Math.cos(a) * R, ft[1] + h * (0.1 + ph * 0.85), c[2] + Math.sin(a) * R * 0.6]; const s = h * (0.62 - 0.3 * ph);
    out.cards.push({ p, back, cell: 'flame' + ((i + Math.floor(age * 14)) % 4), size: [s * 0.75, s * 1.25], color: [1, 1, 1], gmap: f.ramp, alpha: 0.95 * k * Math.sin(Math.PI * Math.min(1, ph * 1.2)), add: 0.6, intensity: 1.05 }); }
  out.lights.push({ p: c, color: f.color, intensity: 3.5 * k, range: 8 });
};
HD.FX_STEP.h2_engulf = function (d, f, age) { const u = age / f.life; glowOn(d, f.b, f.color, 0.4 * env01(u, 0.08, 0.35)); if (u < 0.8 && d.frame % 2 === 0) { const c = bdraw(d, f.b); const h = hgt(d, f.b); d.emit(PS.fireBody, [c[0], c[1] - h * 0.3, c[2]], 2, { ramp: f.ramp, radius: h * 0.45, scale: 1.3 }); } };

// ================================================================== Recycle: fragments of a used item spiral together into a pouch above the user, which drops into it
HD.MOVE_FX.h2_reform = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('h2_reform', { b, life: (e.dur || 130) / FPS, color: e.color || [0.45, 1, 0.55] }); };
HD.FX.h2_reform = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const c = bdraw(d, f.b); const P = scrOff(c, 0, h * 0.95); P[2] += 0.4; const form = HD.smooth(clamp((u - 0.08) / 0.6, 0, 1)); const drop = HD.easeIn(clamp((u - 0.84) / 0.13, 0, 1));
  const k = Math.min(1, u * 10) * (u > 0.97 ? (1 - u) / 0.03 : 1); const Q = lerp3(P, scrOff(c, 0, h * 0.1), drop); const R = h * 0.55 * (1 - 0.35 * form);
  if (drop < 0.5) { const pts = []; for (let i = 0; i <= 30; i++) { const a = age * 3 + (i / 30) * Math.PI * 1.7; pts.push(scrOff(Q, Math.cos(a) * R, Math.sin(a) * R * 0.85)); }   // a green loop of recycling energy turning round it
    out.ribbons.push({ pts, width: h * 0.16, cell: 'boltglow', color: f.color, intensity: 0.45 * k * (1 - drop * 2), add: 1, taper: 0.5 });
    out.ribbons.push({ pts, width: h * 0.05, cell: 'energy', color: f.color, intensity: 1.0 * k * (1 - drop * 2), add: 1, taper: 0.5, scroll: age * 3 }); }
  for (let i = 0; i < 10; i++) { const a = i * 0.63 + age * (2.5 + i * 0.1); const rr = R * (1 - form) * (0.9 + 0.3 * ((i * 7) % 3) / 2); if (rr < h * 0.02) continue; const q = scrOff(Q, Math.cos(a) * rr, Math.sin(a) * rr * 0.85);   // fragments spiralling in
    out.cards.push({ p: q, cell: 'triangle', size: [h * 0.13, h * 0.13], rot: a * 2, color: [1, 1, 1], gmap: 'cloth', alpha: k * (1 - form * 0.8), add: 0.1, intensity: 1.1 }); }
  if (form > 0.02) obj(out.cards, Q, { cell: 'satchel', ramp: 'cloth', size: h * 0.5 * form * (1 - 0.4 * drop), alpha: k * Math.min(1, form * 2), glow: [1, 0.9, 0.6], glowA: 0.3 * form });
  out.lights.push({ p: Q, color: f.color, intensity: 1.8 * k, range: 6 });
};
HD.FX_STEP.h2_reform = function (d, f, age) { const u = age / f.life; if (f.done || u < 0.97) return; f.done = true; const c = bdraw(d, f.b); const h = hgt(d, f.b); d.emit(PS.glint, c, 14, { ramp: 'gold', radius: h * 0.35, speedMul: 1.6, scale: 1.2 }); d.addFx('h2_glowpulse', { b: f.b, life: 0.3, color: f.color, amt: 0.35 }); };

// ================================================================== Tickle: feathers brush back and forth over the target with motion trails
HD.MOVE_FX.h2_feathers = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_feathers', { b, life: (e.dur || 90) / FPS, n: e.n || 3, size: e.size || 0.55 }); };
function featherPos(d, f, i, age) { const c = bdraw(d, f.b); const h = hgt(d, f.b); const a = age * 4.2 + i * Math.PI * 2 / f.n; const p = scrOff(c, Math.cos(a) * h * 0.5, Math.sin(a * 1.5 + i) * h * 0.3 + h * 0.05); p[2] += Math.sin(a) * 0.6; return { p, a, h }; }
HD.FX.h2_feathers = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.1, 0.15);
  for (let i = 0; i < f.n; i++) { const o = featherPos(d, f, i, age); const back = Math.sin(o.a) < -0.2; const pts = []; for (let j = 5; j >= 0; j--) pts.push(featherPos(d, f, i, Math.max(0, age - j * 0.03)).p);
    out.ribbons.push({ pts, width: o.h * 0.22, cell: 'trail', color: [1, 0.96, 0.85], intensity: 0.8 * k, alpha: 0.7, add: 0.8, taper: 0.9, back });
    obj(out.cards, o.p, { cell: 'feather', ramp: 'ivory', size: o.h * f.size, rot: Math.sin(age * 13 + i * 2) * 0.7 + i * 1.2, alpha: k, back, glow: [1, 0.95, 0.8], glowA: 0.2 }); }
};

// ================================================================== Defog: a glassy barrier round the target cracks and is blown away in shards
HD.MOVE_FX.h2_barrier = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_barrier', { b, life: (e.dur || 60) / FPS, brk: e.brk || 0.5, color: e.color || [0.55, 0.85, 1], away: -face(d, b) }); };
HD.FX.h2_barrier = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = bdraw(d, f.b); const h = hgt(d, f.b); const p = [c[0], c[1], c[2] + 0.5];
  if (u < f.brk) { const g = HD.easeOut(Math.min(1, u / 0.15)); const cr = clamp((u - f.brk + 0.18) / 0.18, 0, 1);
    out.cards.push({ p, cell: 'bubble', size: [h * 1.8 * g, h * 1.8 * g], color: f.color, alpha: 0.55, add: 0.6, intensity: 1.05 });
    out.cards.push({ p, cell: 'hex', size: [h * 1.6 * g, h * 1.6 * g], rot: 0.2, color: f.color, alpha: 0.22, add: 1, intensity: 1 });
    if (cr > 0) out.cards.push({ p, cell: 'crack', size: [h * 1.5, h * 1.5], rot: 0.7, color: [1, 1, 1], alpha: cr, add: 1, intensity: 1.3 }); }
  else { const v = (u - f.brk) / (1 - f.brk); const r = HD.rng(f.seed); for (let i = 0; i < 12; i++) { const a = r() * Math.PI * 2; const sp = r.range(0.8, 1.6); const q = scrOff(p, Math.cos(a) * h * 0.8 + f.away * v * sp * h * 2.2, Math.sin(a) * h * 0.8 + v * h * 0.4 * r.range(-1, 1));
      out.cards.push({ p: q, cell: 'triangle', size: [h * 0.24, h * 0.24], rot: a + v * 8 * r.sign(), color: f.color, alpha: 0.9 * (1 - v), add: 0.6, intensity: 1.2 }); } }
};
HD.FX_STEP.h2_barrier = function (d, f, age) { if (f.done || age / f.life < f.brk) return; f.done = true; const c = bdraw(d, f.b); const h = hgt(d, f.b); d.emit(PS.iceChip, c, 14, { radius: h * 0.6, scale: h / 3.5, speedMul: 1.6 }); d.addFx('shockd', { p: c.slice(), r0: h * 0.4, r1: h * 1.2, strength: 0.5, life: 0.25 }); d.addFx('h2_react', { b: f.b, kind: 'flinch', life: 0.4, amt: 0.6 }); };

// ================================================================== Dark Void: while the GBA hides the target, a black void with a violet rim swirls in its place; Zs drift out of it
HD.MOVE_FX.h2_void = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_void', { b, life: (e.dur || 160) / FPS, vis: 0 }); if (e.both && here(d, b ^ 2)) d.addFx('h2_void', { b: b ^ 2, life: (e.dur || 160) / FPS, vis: 0 }); };
HD.FX.h2_void = function (d, f, age, out) {
  const k = f.vis || 0; if (k <= 0.01) return; const c = d.bpos(f.b); const h = hgt(d, f.b); const p = [c[0], c[1] - h * 0.02, c[2] + 0.3]; const pul = 1 + 0.05 * Math.sin(age * 4);
  out.cards.push({ p: [p[0], p[1], p[2] - 0.4], back: true, cell: 'dot', size: [h * 2.2, h * 2.2], color: [0.35, 0.12, 0.6], alpha: 0.5 * k, add: 1, intensity: 1 });
  for (let i = 0; i < 4; i++) out.cards.push({ p: scrOff(p, Math.cos(age + i * 1.6) * h * 0.12, Math.sin(age + i * 1.6) * h * 0.1), cell: 'smoke' + (i % 3), size: [h * 1.35 * pul, h * 1.35 * pul], rot: age * 0.8 + i, color: [0.03, 0.01, 0.05], alpha: 0.85 * k, add: 0, hot: 0 });
  out.cards.push({ p, cell: 'dot', size: [h * 1.1 * pul, h * 1.1 * pul], color: [0.01, 0, 0.02], alpha: 0.95 * k, add: 0, hot: 0 });
  out.cards.push({ p, cell: 'swirl', size: [h * 1.5, h * 1.5], rot: -age * 3, color: [0.6, 0.3, 1], alpha: 0.55 * k, add: 1, intensity: 1.05 });
  out.distort.push({ p, cell: 'swirl', size: [h * 1.9, h * 1.9], strength: 0.5 * k, mode: 0 }); out.lights.push({ p, color: [0.5, 0.25, 1], intensity: 1.8 * k, range: 7 });
  for (let i = 0; i < 3; i++) { const v = ((age * 0.55) + i / 3) % 1; const s = h * (0.2 + 0.12 * v); const q = scrOff(p, h * (0.25 + 0.35 * v), h * (0.35 + 0.6 * v)); q[2] += 0.3; const a = k * Math.sin(Math.PI * v);   // sleep, drifting out of the dark
    out.cards.push({ p: q, cell: 'zzz', size: [s * 1.12, s * 1.12], rot: -0.25, color: [0.05, 0.02, 0.12], alpha: 0.7 * a, add: 0, hot: 0 });
    out.cards.push({ p: q, cell: 'zzz', size: [s, s], rot: -0.25, color: [0.78, 0.6, 1], alpha: a, add: 0.35, intensity: 1.35 }); }
};
HD.FX_STEP.h2_void = function (d, f, age) { const s = d.W && d.W.sprites ? d.W.sprites[f.b] : null; const hidden = !!(s && s.invisible); f.vis = clamp((f.vis || 0) + (hidden ? 0.2 : -0.12), 0, 1); if (hidden && d.frame % 3 === 0) { const h = hgt(d, f.b); d.emit(PS.darkSmoke, d.bpos(f.b), 1, { radius: h * 0.6, scale: 1.2 }); } };

// ================================================================== Trick-or-Treat: a ghost-sheet costume drops over the target, candy pops out
HD.MOVE_FX.h2_sheet = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_sheet', { b, life: (e.dur || 50) / FPS }); };
HD.FX.h2_sheet = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = bdraw(d, f.b); const h = hgt(d, f.b); const drop = HD.easeOut(clamp(u / 0.18, 0, 1)); const k = u > 0.75 ? 1 - (u - 0.75) / 0.25 : 1; const sway = Math.sin(age * 5) * 0.06;
  const p = scrOff(c, 0, h * (0.9 - 0.85 * drop)); p[2] += 0.5;
  out.cards.push({ p, cell: 'dot', size: [h * 1.8, h * 1.8], color: [0.6, 0.35, 1], alpha: 0.3 * k, add: 1, intensity: 1 });
  out.cards.push({ p, cell: 'ghost', size: [h * 1.32, h * 1.4], rot: sway, color: [0.12, 0.05, 0.2], alpha: 0.55 * k, add: 0, hot: 0 });
  out.cards.push({ p, cell: 'ghost', size: [h * 1.25, h * 1.32], rot: sway, color: [0.93, 0.9, 1], alpha: 0.72 * k, add: 0.15, intensity: 1.05 });
};
HD.FX_STEP.h2_sheet = function (d, f, age) { if (f.done || age / f.life < 0.18) return; f.done = true; const c = bdraw(d, f.b); const h = hgt(d, f.b); d.emit(PS.confettiBig || PS.confetti, scrOff(c, 0, h * 0.4), 18, { speedMul: 1.6, scale: 1.1 }); d.addFx('h2_react', { b: f.b, kind: 'flinch', life: 0.35, amt: 0.5 }); };

// ================================================================== Acupressure: pressure points light up on the body one after another, then flare together
HD.MOVE_FX.h2_points = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('h2_points', { b, life: (e.dur || 100) / FPS, at: (e.at || [18, 40, 62, 84]).map((x) => x / FPS), pts: e.pts || [[-0.16, 0.12], [0.17, -0.1], [-0.04, 0.3], [0.1, 0.02]], color: e.color || [1, 0.62, 0.3], flare: (e.flare || 98) / FPS }); };
HD.FX.h2_points = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const c = bdraw(d, f.b); const h = hgt(d, f.b); const fl = age > f.flare ? Math.max(0, 1 - (age - f.flare) / 0.25) : 0; const end = u > 0.9 ? 1 - (u - 0.9) / 0.1 : 1;
  f.at.forEach((t0, i) => { const v = age - t0; if (v < 0) return; const q = scrOff(c, f.pts[i % f.pts.length][0] * h, f.pts[i % f.pts.length][1] * h); q[2] += 0.45; const pop = v < 0.12 ? HD.easeOut(v / 0.12) : 1; const pul = 0.85 + 0.15 * Math.sin(age * 8 + i);
    const s = h * 0.16 * pop * pul * (1 + fl * 0.8); out.cards.push({ p: q, cell: 'dot', size: [s * 3, s * 3], color: f.color, alpha: 0.45 * end, add: 1, intensity: 1 }); out.cards.push({ p: q, cell: 'core', size: [s, s], color: [1, 0.85, 0.6], alpha: end, add: 1, intensity: 1.4 });
    if (v < 0.25) out.cards.push({ p: q, cell: 'star4', size: [h * 0.55 * (1 - v / 0.25), h * 0.55 * (1 - v / 0.25)], rot: 0.4, color: f.color, alpha: 1, add: 1, intensity: 1.6 }); });
};
HD.FX_STEP.h2_points = function (d, f, age) { f.n = f.n || 0; while (f.n < f.at.length && age >= f.at[f.n]) { f.n++; d.addFx('h2_react', { b: f.b, kind: 'jolt', life: 0.15, amt: 0.6 }); } };

// ================================================================== Magnetic Flux: dipole field loops round the user (red pole up, blue pole down), current flowing along them
HD.MOVE_FX.h2_field = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('h2_field', { b, life: (e.dur || 80) / FPS }); };
HD.FX.h2_field = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const k = env01(u, 0.15, 0.2); const c = bdraw(d, f.b); const h = hgt(d, f.b); const N = scrOff(c, 0, h * 0.62), S = scrOff(c, 0, -h * 0.5); const g = HD.easeOut(Math.min(1, u * 3));
  for (const sd of [-1, 1]) for (let j = 0; j < 3; j++) { const R = h * (0.55 + 0.28 * j) * g; const pts = []; for (let i = 0; i <= 18; i++) { const t = i / 18; const q = lerp3(S, N, t); pts.push(scrOff(q, sd * R * Math.sin(Math.PI * t), 0)); }
    const hi = pts.slice(9), lo = pts.slice(0, 10);
    out.ribbons.push({ pts: lo, width: h * 0.16, cell: 'boltglow', color: [0.35, 0.55, 1], intensity: 0.35 * k, add: 1 }); out.ribbons.push({ pts: hi, width: h * 0.16, cell: 'boltglow', color: [1, 0.35, 0.3], intensity: 0.35 * k, add: 1 });
    out.ribbons.push({ pts: lo, width: h * 0.045, cell: 'energy', color: [0.5, 0.7, 1], intensity: 1.1 * k, add: 1, scroll: -age * 4 * sd }); out.ribbons.push({ pts: hi, width: h * 0.045, cell: 'energy', color: [1, 0.5, 0.42], intensity: 1.1 * k, add: 1, scroll: -age * 4 * sd });
    const t = (age * 0.9 + j * 0.31 + (sd > 0 ? 0.5 : 0)) % 1; const q = pts[Math.round(t * 18)]; out.cards.push({ p: q, cell: 'core', size: [h * 0.14, h * 0.14], color: t > 0.5 ? [1, 0.7, 0.6] : [0.7, 0.85, 1], alpha: k, add: 1, intensity: 1.5 }); }
  out.cards.push({ p: N, cell: 'dot', size: [h * 0.4, h * 0.4], color: [1, 0.35, 0.3], alpha: 0.6 * k, add: 1, intensity: 1.2 }); out.cards.push({ p: S, cell: 'dot', size: [h * 0.4, h * 0.4], color: [0.35, 0.55, 1], alpha: 0.6 * k, add: 1, intensity: 1.2 });
};

// ================================================================== a lifted battler: counter part of the GBA's vertical sway so it stays in frame (Telekinesis)
HD.MOVE_FX.h2_unlift = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_unlift', { b, life: (e.dur || 200) / FPS, k: e.k != null ? e.k : 0.45 }); };
HD.FX.h2_unlift = function () {};
HD.FX_STEP.h2_unlift = function (d, f) { const s = d.W && d.W.sprites ? d.W.sprites[f.b] : null; if (!s) return; if (!f.base) f.base = [s.x + (s.x2 || 0), s.y + (s.y2 || 0)]; const dy = (s.y + (s.y2 || 0)) - f.base[1]; if (dy < 0) d.act[f.b].fxOff[1] -= dy * f.k; };

// ================================================================== more small helpers: paralysis crackle, a pop-up bubble, quake / weather caps, a puddle, a fog bank
HD.MOVE_FX.h2_para = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_para', { b, life: (e.dur || 40) / FPS, color: e.color || [1, 0.92, 0.4] }); };
HD.FX.h2_para = function () {};
HD.FX_STEP.h2_para = function (d, f, age) {
  const u = age / f.life; const c = bdraw(d, f.b); const h = hgt(d, f.b); const k = env01(u, 0.05, 0.25); glowOn(d, f.b, f.color, 0.4 * k); const a = d.act[f.b];
  if (d.frame % 2 === 0) d.emit(PS.spark, c, 3, { radius: h * 0.45, scale: 1.1 });
  if (d.frame % 6 === 0 && u < 0.85) { const r = d.rng; const p0 = scrOff(c, r.range(-0.5, -0.2) * h, r.range(-0.3, 0.4) * h), p1 = scrOff(c, r.range(0.2, 0.5) * h, r.range(-0.4, 0.3) * h); p0[2] += 0.4; p1[2] += 0.4;
    d.addFx('bolt', { a: p0, b: p1, width: 0.06, life: 0.12, color: f.color, branches: 1, intensity: 2.2, light: false }); if (a) a.fxOff[0] += (d.frame % 12 ? 2.5 : -2.5); }
};
HD.MOVE_FX.h2_pop = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('h2_pop', { b, life: (e.dur || 30) / FPS, cell: e.cell || 'cloud', color: e.color || [1, 1, 1], size: e.size || 0.36, dx: e.dx != null ? e.dx : 0.42, dy: e.dy != null ? e.dy : 0.55, dots: e.dots !== false }); };
HD.FX.h2_pop = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const h = hgt(d, f.b); const p = scrOff(bdraw(d, f.b), face(d, f.b) * h * f.dx, h * (f.dy + 0.06 * u)); p[2] += 0.5;
  const sp = u < 0.2 ? HD.easeOut(u / 0.2) * (1.15 - 0.15 * (u / 0.2)) : 1; const k = u > 0.75 ? 1 - (u - 0.75) / 0.25 : 1; const s = h * f.size * sp;
  obj(out.cards, p, { cell: f.cell, size: s, color: f.color, alpha: k, glow: f.color, glowA: 0.3, add: 0.08, intensity: 1.1, rot: Math.sin(age * 5) * 0.08 });
  if (f.dots) for (let i = 0; i < 3; i++) { const on = (age * 4 - i * 0.5) % 2 < 1.4 ? 1 : 0.35; out.cards.push({ p: scrOff(p, (i - 1) * s * 0.22, -s * 0.03), cell: 'dot', size: [s * 0.16, s * 0.16], color: [0.25, 0.25, 0.45], alpha: k * on, add: 0, hot: 0 }); }
};
HD.MOVE_FX.h2_noquake = (d, e) => d.addFx('h2_noquake', { life: (e.dur || 4) / FPS });
HD.FX.h2_noquake = function () {};
HD.FX_STEP.h2_noquake = function (d) { for (const x of d.fx) if (x.kind === 'quake' || (x.kind === 'decal' && x.cell === 'crack')) x.life = 1e-4; };
HD.MOVE_FX.h2_wamt = (d, e) => d.addFx('h2_wamt', { life: (e.dur || 120) / FPS, amt: e.amt != null ? e.amt : 0.4 });
HD.FX.h2_wamt = function () {};
HD.FX_STEP.h2_wamt = function (d, f) { if (d.env.weather) d.env.weatherAmt = Math.min(d.env.weatherAmt || 1, f.amt); };
HD.MOVE_FX.h2_puddle = (d, e) => { const b = ref(d, e.b || 'attacker'); if (!here(d, b)) return; d.addFx('h2_puddle', { b, life: (e.dur || 120) / FPS, color: e.color || [0.5, 0.75, 1] }); };
HD.FX.h2_puddle = function (d, f, age, out) { const u = age / f.life; if (u < 0 || u > 1) return; const ft = d.space.feet[f.b]; const h = hgt(d, f.b); const g = HD.easeOut(Math.min(1, u * 2.5)); const k = u > 0.85 ? 1 - (u - 0.85) / 0.15 : 1;
  out.decals.push({ p: [ft[0], 0.03, ft[2]], cell: 'puddle', size: [h * 2.0 * g, h * 1.3 * g], color: f.color, alpha: 0.75 * k, add: 0.3, intensity: 1.1, mode: 2 });
  const ph = (age * 1.2) % 1; out.decals.push({ p: [ft[0], 0.035, ft[2]], cell: 'ring', size: [h * (0.6 + ph * 1.4), h * (0.4 + ph * 0.9)], color: f.color, alpha: 0.5 * k * (1 - ph), add: 1, intensity: 1, mode: 2 }); };
// a fog bank over a battler's side; once the gust comes (blow) it is pushed away from the user and thins out
HD.MOVE_FX.h2_fogbank = (d, e) => { const b = ref(d, e.b || 'target'); if (!here(d, b)) return; d.addFx('h2_fogbank', { b, a: d.atkB(), life: (e.dur || 150) / FPS, blow: (e.blow || 60) / FPS, color: e.color || [0.82, 0.86, 0.92] }); };
HD.FX.h2_fogbank = function (d, f, age, out) {
  const u = age / f.life; if (u < 0 || u > 1) return; const B = d.space.feet[f.b], A = d.space.feet[f.a]; const h = hgt(d, f.b); const r = HD.rng(f.seed); const dir = V.norm([0, 0, 0], [B[0] - A[0], 0, B[2] - A[2]]);
  const bl = clamp((age - f.blow) / 0.9, 0, 1); const kin = Math.min(1, age / 0.5);
  for (let i = 0; i < 12; i++) { const ox = r.range(-1.7, 1.7) * h, oy = r.range(0.05, 0.85) * h, oz = r.range(-0.9, 0.7) * h; const push = HD.easeIn(bl) * h * (3 + r() * 4); const drift = Math.sin(age * 0.6 + i) * h * 0.1;
    const p = [B[0] + ox + dir[0] * push + drift, oy + bl * h * 0.6, B[2] + oz + dir[2] * push]; const a = 0.5 * kin * (1 - bl);
    if (a > 0.01) out.cards.push({ p, back: i % 3 === 0, cell: i % 2 ? 'cloud' : 'smoke' + (i % 3), size: [h * (1.1 + r() * 0.6) * (1 + bl * 0.8), h * (0.6 + r() * 0.3)], rot: r.range(-0.2, 0.2), color: f.color, alpha: a, add: 0, hot: 0, intensity: 1.05 }); }
};
// a small seal glyph orb (Imprison's orbs): a spinning rune disc of light with a soft glow
K.h2_rune = { update(d, it, cfg) { const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.atkB()); const s = h * (cfg.v3size || 0.26); const col = cfg.color || [1, 0.5, 0.92]; const a = it.alpha;
  it.cards.push({ cell: 'dot', size: [s * 2, s * 2], color: col, alpha: 0.35 * a, add: 1, intensity: 1 }); it.cards.push({ cell: 'h2_sigil', size: [s * 1.06, s * 1.06], rot: it.age * 2 + it.uid, color: [0.08, 0.02, 0.08], alpha: 0.5 * a, add: 0, hot: 0 });
  it.cards.push({ cell: 'h2_sigil', size: [s, s], rot: it.age * 2 + it.uid, color: col, alpha: a, add: 1, intensity: 1.3 }); } };
// a cotton tuft (Cotton Spore's GBA spores): fibrous white puff, a faint shadow side, drifting spin
K.h2_cotton = { update(d, it, cfg) { const nb = d.space.nearestBattler(it.p); const h = hgt(d, nb.b >= 0 ? nb.b : d.tgtB()); const s = h * (cfg.v3size || 0.32); const rot = it.age * 0.8 + it.uid; const a = it.alpha;
  it.cards.push({ cell: 'h2_tuft', size: [s * 1.1, s * 1.1], rot, color: [0.3, 0.32, 0.4], alpha: 0.45 * a, add: 0, hot: 0 }); it.cards.push({ cell: 'h2_tuft', size: [s, s], rot, color: [1, 1, 1], alpha: a, add: 0.05, intensity: 1.08 });
  it.cards.push({ cell: 'dot', size: [s * 1.5, s * 1.5], color: [1, 0.98, 0.94], alpha: 0.15 * a, add: 1, intensity: 1 }); } };

