    const env = Math.pow(Math.max(0, Math.sin(Math.PI * clamp(v * 0.8 + 0.16, 0, 1))), 0.7) * (1 - 0.7 * v);
    const xx = x + (n - 0.5) * 0.6 * v + Math.sin(v * 5 + seed) * 0.06 * v;
