    const tip = y > -0.25 ? Math.abs(x) / Math.max(0.001, 0.48 * (1 - (y + 0.25) / 1.1)) : 9;
    const d = Math.min(body, y > -0.25 ? Math.max(tip, (y - 0.85) * 9 + 1) : 9);
