      g.lineWidth = R * 0.05; for (const f of [0.38, 0.62]) { g.beginPath(); g.moveTo(0, -R * f); g.lineTo(-R * 0.2, -R * (f + 0.17)); g.moveTo(0, -R * f); g.lineTo(R * 0.2, -R * (f + 0.17)); g.stroke(); }
