    g.save(); g.rotate(Math.PI / 4); g.globalAlpha = 0.5; for (const [sx, sy] of [[0.06, 0.5], [0.5, 0.06]]) { g.beginPath(); g.moveTo(0, -R * sy); g.lineTo(R * sx, 0); g.lineTo(0, R * sy); g.lineTo(-R * sx, 0); g.closePath(); g.fill(); } g.restore();
