  bone: draw((g) => { white(g, 1); g.fillRect(-R * 0.12, -R * 0.62, R * 0.24, R * 1.24); for (const s of [-1, 1]) for (const o of [-0.16, 0.16]) { g.beginPath(); g.arc(R * o, s * R * 0.68, R * 0.2, 0, Math.PI * 2); g.fill(); } }),
  needle: px((x, y) => { const w = 0.11 * Math.max(0, (1 - y) / 2) + 0.012; const a = sm(w, w * 0.5, Math.abs(x)) * sm(1.0, 0.9, Math.abs(y)); return [clamp(0.8 + (x < 0 ? 0.2 : 0), 0, 1), a]; }),
