    g.save(); path(); g.clip(); g.strokeStyle = L(128, 0.55); g.lineWidth = R * 0.035; for (let i = 0; i < 5; i++) { const x = -R * 0.6 + i * R * 0.24; g.beginPath(); g.moveTo(x, R * 0.6); g.quadraticCurveTo(x + R * 0.1, 0, x + R * 0.04, -R * 0.5); g.stroke(); } g.restore();
