    g.fillStyle = eg; g.beginPath(); g.moveTo(0, -R * 0.88); g.bezierCurveTo(R * 0.5, -R * 0.88, R * 0.72, R * 0.2, R * 0.66, R * 0.42); g.bezierCurveTo(R * 0.55, R * 0.9, -R * 0.55, R * 0.9, -R * 0.66, R * 0.42); g.bezierCurveTo(-R * 0.72, R * 0.2, -R * 0.5, -R * 0.88, 0, -R * 0.88); g.fill();
