    const tg = g.createRadialGradient(-R * 0.3, -R * 0.45, R * 0.05, 0, -R * 0.2, R * 0.9); tg.addColorStop(0, L(178)); tg.addColorStop(1, L(102)); g.fillStyle = tg; g.fillRect(-R, -R, R * 2, R);
    const bg = g.createRadialGradient(-R * 0.3, R * 0.2, R * 0.05, 0, R * 0.3, R * 0.9); bg.addColorStop(0, L(255)); bg.addColorStop(1, L(216)); g.fillStyle = bg; g.fillRect(-R, 0, R * 2, R);
